def md5(path):
    return hashlib.md5(open(path, 'rb').read()).hexdigest()[:8]


def setup():
    """base/ = c/SWOS minus exes, saves and backups (once)."""
    base = os.path.join(WORK, 'base')
    if os.path.isdir(base):
        return base
    src = os.path.join(MAIN, 'c', 'SWOS')
    shutil.copytree(src, base, ignore=shutil.ignore_patterns('*.CAR', '*.EXE', '*.BAK', '*.SEA', 'desktop.ini'))
    for f in ('DOS4GW.EXE', 'SETUP.EXE'):
        shutil.copy(os.path.join(src, f), base)
    return base


BUILD_KEEP_DAYS = 3        # build() / unique_out(): <name>-<key> dirs unused this long are removed (other names untouched)
_ENV_RE = re.compile(r"""(?:environ(?:\.get)?\s*[\[(]\s*|getenv\(\s*)['"]([A-Z][A-Z0-9_]*)['"]""")


def _build_vars():
    """The environment variables the build code reads (tools/*.py but this harness), scanned once."""
    if not hasattr(_build_vars, 'v'):
        names = set()
        for f in glob.glob(os.path.join(ROOT, 'tools', '*.py')):
            if os.path.basename(f) != 'swostest.py':
                names |= set(_ENV_RE.findall(open(f, errors='replace').read()))
        _build_vars.v = names
    return _build_vars.v


def build_key(src, env=None, extra=b''):
    """A build's identity (12 hex digits): the source tree (HEAD, its uncommitted changes, untracked files under
    tools/), the build-affecting environment (the variables the build code reads, every *_FORCE / *_TEST / *_DATA /
    *_PACKS / *_HOOK one and env's own, values merged as the build sees them; SEASON_PACKS' packs with their files'
    times) and extra. Two sessions get one dir only for the same build."""
    git = lambda *a: subprocess.run(['git', '-C', src] + list(a), capture_output=True).stdout
    h = hashlib.sha256(git('rev-parse', 'HEAD'))
    h.update(git('diff', 'HEAD', '--binary'))
    for f in sorted(git('ls-files', '--others', '--exclude-standard', 'tools').decode(errors='replace').split()):
        try:
            h.update(f.encode() + open(os.path.join(src, f), 'rb').read())
        except OSError:
            pass
    full = dict(os.environ, **(env or {}))
    keys = _build_vars() | set(env or {}) | {k for k in full if re.search(r'_(FORCE|TEST|DATA|PACKS|HOOK)$', k)}
    for k in sorted(keys):
        if k in full:
            h.update(f'{k}={full[k]}\0'.encode())
    for d in (full.get('SEASON_PACKS') or '').split(','):
        for f in ('pack.json', 'clubs.csv', 'players.csv'):
            q = os.path.join(d, f)
            if os.sep in d and os.path.exists(q):
                h.update(f'{q}:{os.path.getmtime(q)}\0'.encode())
    h.update(extra)
    return h.hexdigest()[:12]


def build_cleanup():
    """<name>-<12 hex> build dirs and branch worktrees unused for BUILD_KEEP_DAYS (a reuse touches its dir)."""
    cut = time.time() - BUILD_KEEP_DAYS * 86400
    for kind in ('builds', 'src'):
        for d in glob.glob(os.path.join(WORK, kind, '*-' + '[0-9a-f]' * 12)):
            try:
                if os.path.getmtime(d) >= cut:
                    continue
                if kind == 'src':
                    subprocess.run(['git', '-C', MAIN, 'worktree', 'remove', '--force', d], capture_output=True)
                shutil.rmtree(d, ignore_errors=True)
            except OSError:
                pass


def unique_out(name, key):
    """builds/<name>-<key>, and whether it is complete (ITALIAN.EXE there: reused, its time touched). A build whose
    INPUTS.txt (build_inputs) no longer matches the files - or a build without one - is not reused: the key moves on
    to one derived from the inputs' current contents (the same for every session with the same files)."""
    for _ in range(8):
        out = os.path.join(WORK, 'builds', f'{name}-{key}')
        if not os.path.exists(os.path.join(out, 'ITALIAN.EXE')):
            return out, False
        now = inputs_now(os.path.join(out, 'INPUTS.txt'))
        if now is None:
            os.utime(out)
            return out, True
        key = hashlib.sha256(f'{key}:{now}'.encode()).hexdigest()[:12]
    return out, False


INPUT_ROOTS = ('internal', 'c', 'orig', 'ref')        # MAIN's ignored dirs: the build reads them live, git doesn't see them
INPUTS_HOOK = r"""
import sys, os, hashlib, atexit
_main, _inp = os.path.realpath(sys.argv[2]), sys.argv[1] + '/INPUTS.txt'
_roots = tuple(os.path.join(_main, d) + os.sep for d in %r)
_skip = (os.path.join(_main, 'internal', 'swostest') + os.sep, os.path.realpath(sys.argv[1]) + os.sep)
_files, _dirs = set(), set()
def _keep(p):
    try:
        p = os.path.realpath(os.fsdecode(p))
    except (TypeError, ValueError):
        return None
    return p if p.startswith(_roots) and not p.startswith(_skip) and '__pycache__' not in p else None
def _hook(ev, a):
    if ev == 'open' and isinstance(a[0], (str, bytes)) and not set(str(a[1] or 'r')) & set('wax+'):
        p = _keep(a[0])
        if p: _files.add(p)
    elif ev in ('os.listdir', 'os.scandir') and isinstance(a[0], (str, bytes)):
        p = _keep(a[0])
        if p: _dirs.add(p)
sys.addaudithook(_hook)
def _write():
    for m in list(sys.modules.values()):
        p = _keep(getattr(m, '__file__', None) or '') if getattr(m, '__file__', None) else None
        if p: _files.add(p)
    rows = []
    for p in sorted(_files):
        if os.path.isfile(p):
            st = os.stat(p)
            rows.append(f'f {hashlib.sha1(open(p, "rb").read()).hexdigest()} {st.st_size} {st.st_mtime_ns} {os.path.relpath(p, _main)}')
    for p in sorted(_dirs):
        if os.path.isdir(p):
            rows.append(f'd {hashlib.sha1(chr(0).join(sorted(os.listdir(p))).encode()).hexdigest()} 0 0 {os.path.relpath(p, _main)}')
    open(_inp, 'w').write(chr(10).join(rows) + chr(10))
atexit.register(_write)
""" % (INPUT_ROOTS,)


def inputs_now(path):
    """None if every input in the build's INPUTS.txt (MAIN-relative: f sha1 size mtime path / d sha1 0 0 dir) is
    unchanged, else a digest of the inputs' current state (missing file: stale)."""
    try:
        rows = [ln.split(' ', 4) for ln in open(path).read().splitlines() if ln]
    except OSError:
        return 'no INPUTS.txt'
    h, stale = hashlib.sha256(), False
    for kind, sha, size, mt, rel in rows:
        p = os.path.join(MAIN, rel)
        try:
            if kind == 'd':
                cur = hashlib.sha1('\0'.join(sorted(os.listdir(p))).encode()).hexdigest()
            else:
                st = os.stat(p)
                cur = sha if (st.st_size, st.st_mtime_ns) == (int(size), int(mt)) else \
                    hashlib.sha1(open(p, 'rb').read()).hexdigest()
        except OSError:
            cur = 'missing'
        stale |= cur != sha
        h.update(f'{rel}:{cur}\0'.encode())
    return h.hexdigest() if stale else None


def mkseason_now():
    """tools/mkseason for the SEASON_PACKS set now: it reads SEASON_PACKS once, at its import, and caches packs(), so a
    scenario run before in the same process (a serial 'run a b c') would leave its own world - world_dplay_c after
    world_gplay_cupd read the club words in cd_strengths' world (global None)"""
    import importlib
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import mkseason
    return importlib.reload(mkseason)


def build(name, env=None, branch=None, lang='it'):
    """Build the IT exe + team files into internal/swostest/builds/<name>-<key> (build_key: from this checkout or a
    git branch, with the build-affecting environment) - its own dir per build, so sessions never overwrite each
    other's exes; an existing dir of the same key is reused. Built in <dir>.tmp<pid>, then renamed into place."""
    src = ROOT
    if branch:                                       # a throw-away worktree of that commit, links to the ignored dirs
        sha = subprocess.run(['git', '-C', MAIN, 'rev-parse', branch + '^{commit}'], capture_output=True, text=True,
                             check=True).stdout.strip()
        src = os.path.join(WORK, 'src', f'{name}-{sha[:12]}')
        if not os.path.isdir(src):
            subprocess.run(['git', '-C', MAIN, 'worktree', 'add', '--detach', src, sha], check=True)
        os.utime(src)
        for d in ('orig', 'ref', 'c', 'internal'):
            if not os.path.exists(os.path.join(src, d)):
                os.symlink(os.path.join(MAIN, d), os.path.join(src, d))
    out, done = unique_out(name, build_key(src, env, b'' if lang == 'it' else lang.encode()))   # (4.0.6: the
    # language in the key - an FR world_vc5 reused the IT exe of the same name and env, typing AZERTY into it)
    if os.environ.get('SWOSTEST_BUILT_LOG'):         # (remote_run.sh's local pre-build: the dirs whose inputs to sync)
        open(os.environ['SWOSTEST_BUILT_LOG'], 'a').write(out + '\n')
    if done:
        return out
    tmp = f'{out}.tmp{os.getpid()}'
    shutil.rmtree(tmp, ignore_errors=True)
    os.makedirs(os.path.join(tmp, 'DATA'))
    code = INPUTS_HOOK + ("import sys,io,contextlib; sys.path.insert(0,'tools'); import patch\n"
            "out=sys.argv[1]\n"
            "with contextlib.redirect_stdout(io.StringIO()):\n"
            "    r=patch.patch_teams('orig/DATA/TEAM.020',out+'/DATA/TEAM.020'); patch.write_new_teams('orig/DATA',out+'/DATA')\n"
            f"    patch.patch_exe('orig/{UI_ORIG_OF[lang]}',out+'/ITALIAN.EXE',r,'{lang}')\n")   # (lang: run as ITALIAN.EXE)
    miss = os.path.join(tmp, 'COBJ_MISSING.txt')   # (cobj.compile_c: C objects not from the reference Mac)
    try:
        subprocess.run([sys.executable, '-c', code, tmp, MAIN], cwd=src, check=True,
                       env=dict(os.environ, **(env or {}), COBJ_MISS_LOG=miss))
        if os.path.exists(miss):                     # not a reference build: never reused, rebuilt next time
            print(f'BUILD WARNING {name}: C objects compiled here, not the reference Mac\'s: {open(miss).read().strip()}',
                  flush=True)
            out = os.path.join(WORK, 'builds', f'{name}-nonref-{os.path.basename(out)[-12:]}')
            shutil.rmtree(out, ignore_errors=True)
        try:
            os.rename(tmp, out)
        except OSError:                              # (another session built the same key meanwhile: its dir stays)
            shutil.rmtree(tmp, ignore_errors=True)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    build_cleanup()
    return out


def prepare(name, exe_dir, cars, steps, match=False, timer=False):
    """runs/<name>/SWOS = base + exe_dir (ITALIAN.EXE + DATA, or an .EXE file) + saves {dos name: source path}."""
    if os.environ.get('SWOSTEST_BUILD_ONLY'):
        raise BuildOnly()
    run = os.path.join(RUNS, name)
    if os.path.isdir(run):
        shutil.rmtree(run)
    game = os.path.join(run, 'SWOS')
    shutil.copytree(setup(), game)
    if os.path.isfile(exe_dir):
        shutil.copytree(os.path.join(MAIN, 'c', 'SWOS', 'DATA'), os.path.join(game, 'DATA'), dirs_exist_ok=True)
        shutil.copy(exe_dir, os.path.join(game, 'ITALIAN.EXE'))
    else:
        shutil.copytree(exe_dir, game, dirs_exist_ok=True, ignore=shutil.ignore_patterns('log.txt', 'INPUTS.txt', 'COBJ_MISSING.txt'))
    for dos, src in cars.items():
        shutil.copy(src, os.path.join(game, dos))
    if not os.path.exists(os.path.join(game, 'ITALIAN.EXE')):      # e.g. an English SWOS++ bundle
        shutil.copy(os.path.join(game, 'ENGLISH.EXE'), os.path.join(game, 'ITALIAN.EXE'))
    return run, test_exe(os.path.join(game, 'ITALIAN.EXE'), steps, match, timer)


SCAN = {'fire': 0x1D, 'up': 0x48, 'down': 0x50, 'left': 0x4B, 'right': 0x4D, 'esc': 0x01, 'enter': 0x1C,
        'space': 0x39, 'bspace': 0x0E, 'semicolon': 0x27, 'pgup': 0x49, 'pgdn': 0x51, 'lshift': 0x2A, 'dump': 0xFF}
SCAN.update({ch: sc for row, base in (('1234567890', 0x02), ('qwertyuiop', 0x10), ('asdfghjkl', 0x1E),
                                      ('zxcvbnm', 0x2C)) for sc, ch in enumerate(row, base)})
SCRIPT_MAX = 200                                       # steps a pause can write
TICKS = 70                                             # timer ticks per s (-timer mode)
HOLD = 1                                               # GetKey calls a typed key stays held (more = menu auto-repeat)
SPP_STEP = False                                        # bench_world BENCH_SPP: spp_go() instead of press() (Panchina's
                                                        # sppmatch flow: the only one that starts PLAY MATCH under SWOS++)


def spp_go(s, target, w=3):
    """Under SWOS++'s timer feed: select target one key at a time, re-planning after each (key:0.3, a pause), then a
    plain fire - Panchina's sppmatch.py flow, which starts PLAY MATCH 5/5 where press()'s whole path + 'fire up:0.05'
    never did. Returns True, or None when target is not on the screen / not reached."""
    for _ in range(30):
        sc = s.screen()
        i = sc.find(target, exact=True)
        if i is None:
            return None
        if sc.selected == i:
            s.send(f'fire dump:{w}')
            return True
        st = sc.path(i, set(), steps=True)
        if not st:
            return None
        s.send(st[0][0] + ':0.3 dump:0.5')
    return None


PRESS_FIRE = 'fire'                                    # press()'s fire ('fire up:0.05' under SWOS++'s timer feed: the
                                                       # menus read the latched last key, a fire would be read again)
RATE = 30                                              # GetKey calls per second in the menus (calibrated)


def steps_of(text, rate=None):
    """'fire down:2 down fire:10' -> [(scan code, GetKey calls to wait before it)]; ':s' = seconds before the key
    (default 0.5), counted only while the game polls the keyboard (not while it loads or simulates)."""
    out = []
    for tok in text.split():
        k, _, t = tok.partition(':')
        codes = [SCAN[x] for x in k.lower().split('+')]          # 'fire+right': both held, fire typed
        assert len(codes) <= 2, tok
        out.append((codes[0] | (codes[1] << 8 if len(codes) > 1 else 0), max(1, round(float(t or 0.5) * (rate or RATE)))))
    return out


def test_exe(exe, steps, match=False, timer=False):
    """Test builds only (the exe under test is patched in its run copy):
    - intro skipped (skipIntro test -> jmp);
    - menus also read the latched last key (MenuCheckControls' 'two joypads' branch, normally only for
      g_inputControls == 5), so one typed key = one menu action however briefly it is held;
    - key feeder: the `call GetKey` of MenuCheckControls and InputTextKeyLoop (the last 2 of 12) go to a stub on a new obj1 page that, when the key buffer is empty, puts the
      script's next scan code into keyBuffer after its wait (counted in GetKey calls, so the script follows the game,
      not the wall clock: loading and simulating do not consume it). Text input (save names) reads GetKey too."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    from le import LE
    from lepatch import LEPatch, add_object_page
    import nasmcave
    data = open(exe, 'rb').read()
    le = LE(data)
    c = le.obj_bytes(1)
    fx = {soff: (tobj, toff) for sobj, soff, _, tobj, toff, *_ in le.fixups() if sobj == 1}
    one = lambda pat: (lambda m: (m[0].start() if len(m) == 1 else sys.exit(f'{exe}: {pat!r} x{len(m)}')))(
        list(re.finditer(pat, c, re.S)))
    i9 = one(rb'\x66\x83\x3d....\x09\x74.\xa0....\x0f\xb7\x1d....\x88\x83')   # Int9KeyboardHandler
    keycount, keybuf = fx[i9 + 3], fx[c.index(b'\x88\x83', i9) + 2]
    k = one(rb'\xe4\x60\x66\x0f\xb6\xc0\x66\x8b\x1d....\x66\x89\x1d....\x66\xa3')   # in al, 60h ...
    scancode, prevscan = fx[k + 9], fx[k + 16]
    e8 = c.index(b'\x66\x83\x05', i9) + 8                  # add keyCount, 1; call SetKeyboardControlFlags
    assert c[e8] == 0xE8
    setkbd = e8 + 5 + struct.unpack_from('<i', c, e8 + 1)[0]
    getkey = [s for s, t in fx.items() if t == keycount and c[s - 2:s] == b'\x66\xa1']
    assert len(getkey) == 1
    gk = c.rindex(b'\xff\x35', 0, getkey[0]) - 14 * 6     # 15 pushes before the body
    assert all(c[gk + 6 * k:gk + 6 * k + 2] == b'\xff\x35' for k in range(15)), hex(gk)
    calls = [i for i in range(len(c) - 5) if c[i] == 0xE8 and i + 5 + struct.unpack_from('<i', c, i + 1)[0] == gk]
    assert len(calls) == 12, len(calls)
    if not match:
        calls = calls[-2:]      # MenuCheckControls, InputTextKeyLoop (the others: match, replays, highlights)
    if timer:                   # SWOS++ re-patches the menu input code: feed from TimerProc (70 Hz) instead
        t = one(rb'\x66\xff\x05....\x66\xff\x05....\x66\xa1....\x66\x0b\xc0\x75.\x66\xff\x05....\x66\x83\x05....'
                rb'\x01\x66\x83\x25....\x01\x75.\x66\xc7\x05....\xff\xff\xe8') + 59   # call BumpIntroTimers
        assert c[t] == 0xE8
        calls, gk = [t], t + 5 + struct.unpack_from('<i', c, t + 1)[0]
    mcc = one(rb'\x66\x83\x3d....\x05\x0f\x85....\x66\x83\x3d....\xff\x0f\x84')
    intro = one(rb'\x66\x83\x3d....\x00\x75.\xe8....\x75')
    mp = one(rb'\x66\x83\x3d....\x01\x74.\x66\x83\x3d....\xff\x75.\xe8....\x66\xa9\x00\x02\x75.'
             rb'\xe8....\xe8....\xe8....\xc7\x05')              # MenuProc: mov A6, offset g_currentMenu
    curmenu = fx[c.index(b'\xc7\x05', mp + 20) + 6]

    o1 = le.obj(1)
    page = o1.npages * le.page_size
    data = add_object_page(data, 1)
    tmp = exe + '.tmp'
    open(tmp, 'wb').write(data)
    p = LEPatch(tmp)
    os.remove(tmp)
    p.set_vsize(1, page + le.page_size)
    if not os.environ.get('SWOSTEST_INTRO'):            # (SWOSTEST_INTRO=1: the intro plays, as on a real start)
        p.put(1, intro + 8, b'\xEB')
    p.put(1, mcc + 8, b'\x90' * 6)
    src = """
stub:   pushad
        inc dword [calls]
        cmp word [hold], 0
        je .idle
        dec word [hold]
        jnz .go
        movzx eax, byte [cur]           ; release after HOLD calls (screens that read the held state)
        or al, 0x80
        call emu
        movzx eax, byte [cur+1]         ; second key of a combination (fire+right)
        or eax, eax
        jz .go
        or al, 0x80
        call emu
        jmp .go
.idle:  cmp word [KEYCOUNT], 0
        jne .go
        mov esi, [ptr]
        movzx eax, word [esi]
        or eax, eax
        jz .go
        dec word [esi+2]
        jnz .go
        add esi, 4
        mov [ptr], esi
        cmp al, 0xFF
        jne .key
        mov dword [ptr], script         ; the runner writes the next steps from the start of the script area
        int 3                           ; 'dump' step: the runner's BPINT 3 stops here (EIP in this page); to go
        jmp .go                         ; on, the runner sets EIP past it (and may write new steps)
.key:   mov [KEYBUF], al                ; latched (menus' last key, text input) ...
        mov word [KEYCOUNT], 1
        mov [cur], ax                   ; al = key, ah = second key held with it (0 = none)
        push eax
        movzx eax, al
        call emu                        ; ... and held, like Int9KeyboardHandler
        pop eax
        movzx eax, ah
        or eax, eax
        jz .held
        call emu
.held:
        mov ax, [holdn]                 ; (HOLD, or a scenario's poke: kbd2's player 2 keys held longer)
        mov [hold], ax
.go:    popad
        jmp GETKEY
emu:    mov bx, [SCANCODE]
        mov [PREVSCAN], bx
        mov [SCANCODE], ax
        call SETKBD
        ret
ptr:    dd script
calls:  dd 0                            ; GetKey calls (read from the dump)
hold:   dw 0
holdn:  dw HOLD
cur:    db 0, 0
script:
""" + ''.join(f'        dw {k:#x}, {w}\n' for k, w in steps) + '        dw 0, 0\n' + f'        times {4 * SCRIPT_MAX} db 0\n'
    sym = {'KEYCOUNT': keycount, 'KEYBUF': keybuf, 'GETKEY': (1, gk), 'SCANCODE': scancode, 'PREVSCAN': prevscan,
           'SETKBD': (1, setkbd), 'HOLD': (0, HOLD)}
    code, fix = nasmcave.assemble(src, page, sym)
    assert len(code) <= le.page_size, 'script too long'
    p.put(1, page, code)
    for off, tobj, toff in fix:
        p.add_ptr(1, page + off, tobj, toff)
    for i in calls:
        p.put(1, i + 1, struct.pack('<i', page - (i + 5)))
    p.save(exe)
    d2 = le.obj_bytes(2)
    anchor = d2.find(b'SERIE A\0') - 32                # constant strings: finds obj2 in a memory dump
    fixed = next(o for o in range(0x1000, len(c), 16)            # 48 code bytes with no fixup: finds obj1 in a dump
                 if not any(o - 3 <= f < o + 48 for f in range(o - 3, o + 48) if f in fx) and len(set(c[o:o + 48])) > 8)
    lab = nasmcave.labels(src, 0, sym)
    # g_workingPalette (obj2): ShowStadiumInit's `add esi, 64000 / mov edi, g_workingPalette / mov ecx, 768 / rep movsb`;
    # the menus' palette as the DAC has it once faded in (frames are rebuilt from memory, no screencapture)
    st = re.search(rb'\x81\xC6\x00\xFA\x00\x00\xBF....\xB9\x00\x03\x00\x00\xF3\xA4', c, re.S).start()
    assert fx[st + 7][0] == 2, 'g_workingPalette'
    return {'pal': fx[st + 7][1], 'page': page, 'size2': min(le.obj(2).vsize, le.obj(2).npages * le.page_size), 'calls': page + lab['calls'], 'holdn': page + lab['holdn'], 'code': (fixed, c[fixed:fixed + 48]), 'menu': curmenu[1],
            'brk': page + code.index(b'\xcd\x03'), 'ptr': page + lab['ptr'], 'script': page + lab['script'],
            'anchor': (anchor, d2[anchor:anchor + 64]),
            'p3': next(((soff, toff) for sobj, soff, t, tobj, toff, *_ in le.fixups() if sobj == 1 and t == 7 and tobj == 3),
                       None)}             # (4.0.6) an obj1 pointer into obj3: its value in memory gives obj3's base


def bp_str(r):
    """SWOSTEST_BP_STR = obj2 offset of a pointer (e.g. the A0 pseudo register): the string it points to;
    SWOSTEST_BP_HEX = obj2 offset:bytes,...: those bytes."""
    out = ''
    for a in filter(None, os.environ.get('SWOSTEST_BP_HEX', '').split(',')):   # obj2 offset:bytes, logged in hex
        o, n = a.split(':')
        out += f' {o}:{r.obj2(int(o, 16), int(n)).hex()}'
    for a in filter(None, os.environ.get('SWOSTEST_BP_HEX1', '').split(',')):  # obj1 offset:bytes (glue variables)
        o, n = a.split(':')
        out += f' obj1+{o}:{r.obj1(int(o, 16), int(n)).hex()}'
    off = os.environ.get('SWOSTEST_BP_STR')
    if not off:
        return out
    p = struct.unpack('<I', r.obj2(int(off, 16), 4))[0]
    return out + ' ' + r.read(p, 24).split(b'\0')[0].decode('latin-1')


def dosbox_cpu(pid):
    """The process's CPU seconds so far (ps), None if unreadable."""
    try:
        v = subprocess.run(['ps', '-o', 'time=', '-p', str(pid)], capture_output=True, text=True, timeout=5).stdout.strip()
        p = [float(x) for x in v.replace('-', ':').split(':')]
        return sum(x * 60 ** k for k, x in enumerate(reversed(p)))
    except Exception:
        return None


ANSI = re.compile(rb'\x1b\[[0-9;?]*[a-zA-Z]|\x1b\(B')
MEMSIZE = 0x2000000                                   # memsize=32: linear 0..32 MB


class BuildOnly(BaseException):
    """SWOSTEST_BUILD_ONLY=1 (remote_run.sh's local pre-build): a scenario stops at its first game start, its builds
    done. A BaseException, so the scenarios' own 'except Exception' don't catch it."""


class Dosbox:
    """DOSBox-X under a pty: debugger reachable, int 3 traps caught."""

    def __init__(self, run, timeout, shots=0, exe='ITALIAN.EXE'):
        if os.environ.get('SWOSTEST_BUILD_ONLY'):
            raise BuildOnly()
        self.run, self.timeout, self.shots = run, timeout, shots
        conf = CONF if not os.environ.get('SWOSTEST_NOEXIT') else CONF.replace('{exe}\nexit\n', '{exe}\n')
        if os.environ.get('SWOSTEST_MEMSIZE'):         # (experiments: DOSBox-X memory in MB; dumps still read 32 MB)
            conf = conf.replace('memsize=32', 'memsize=' + os.environ['SWOSTEST_MEMSIZE'])
        if os.environ.get('SWOSTEST_DIRTY'):           # (4.0.6) free conventional + XMS memory filled with that byte before
            shutil.copy(os.path.join(ROOT, 'tools', 'dirty', 'DIRTY.COM'), run)   # the game starts (tools/dirty:
            conf = conf.replace('c:\ncd \\SWOS\n', 'c:\nDIRTY.COM ' + os.environ['SWOSTEST_DIRTY'] + ' > DIRTY.TXT\ncd \\SWOS\n')
            assert 'DIRTY.COM' in conf                 # real hardware's RAM is not zero: DOSBox-X's is)
            if os.environ.get('SWOSTEST_DIRTY_EMS') != '1':   # (no EMS: DOS/4GW then takes XMS - the filled pages -
                conf = conf.replace('[mixer]', '[dos]\nems=false\n[mixer]')   # instead of VCPI's)
        exe = exe + (' ' + os.environ['SWOSTEST_EXEARGS'] if os.environ.get('SWOSTEST_EXEARGS') else '')   # (e.g. /H)
        conf = conf.format(cputype=os.environ.get('SWOSTEST_CPUTYPE', 'pentium'), cycles=os.environ.get('CYCLES', 'max'), core=os.environ.get('CORE', 'dynamic'), iso=ISO,
                           exe=exe, turbo='false' if os.environ.get('TURBO') == '0' else 'true',
                           joy=f"[joystick]\njoysticktype={os.environ['SWOSTEST_JOY']}\n" if os.environ.get('SWOSTEST_JOY') else '')   # (none / auto / 2axis ...)
        open(os.path.join(run, 'test.conf'), 'w').write(conf)
        self.screen, self.eip, self.t0, self.watch = b'', None, time.time(), set()
        self.stats = {}                                # wall time per phase (s), shown in the session log
        self.pid, self.fd = pty.fork()
        if self.pid == 0:
            os.chdir(run)
            os.environ['TERM'] = 'xterm'
            os.execv(DOSBOX, [DOSBOX, '-conf', 'test.conf', '-fastlaunch', '-break-start',
                              '-time-limit', '100000000'])  # the runner kills it; the limit counts EMULATED
                                                        # seconds: 14400 ended turbo runs after ~4.5 real minutes

    def pump(self, t, until=None, start=None):
        """Read the debugger's output for up to t s; returns early once `until` (bytes regex, b'' = any output) shows
        up in the output after `start` (default: what is read from now on). Returns the bytes read, -1 if the process
        is gone."""
        end = time.time() + t
        got = 0
        start = len(self.screen) if start is None else start
        while True:
            left = end - time.time()
            if left <= 0:
                return got
            r, _, _ = select.select([self.fd], [], [], min(left, 0.05))
            if r:
                try:
                    b = os.read(self.fd, 65536)
                except OSError:
                    return -1                          # process gone
                if not b:
                    return -1
                self.screen += b
                got += len(b)
                if until is not None and re.search(until, ANSI.sub(b' ', self.screen[start:])):
                    return got

    def cmd(self, text, wait=1.0, until=None):
        pre = len(self.screen)
        os.write(self.fd, text.encode() + b'\r')
        return self.pump(wait, until, pre)

    def alive(self):
        pid, st = os.waitpid(self.pid, os.WNOHANG)
        if pid:                                        # gone: keep how (signal / exit code) for the session log
            self.status = (f'signal {os.WTERMSIG(st)}' if os.WIFSIGNALED(st) else f'exit code {os.WEXITSTATUS(st)}')
        return pid == 0

    def go(self):
        """Run until DOSBox-X exits ('exit'), an int 3 breaks into the debugger ('break': a trap or a 'dump' step) or
        the timeout ('timeout' = hang without a trap, or the script did not get where expected)."""
        self.pump(1)
        for _ in range(30):                            # under load the debugger may not take input yet
            pre = len(self.screen)
            self.cmd('BPINT 3', 1, rb'breakpoint at INT 03')
            if b'breakpoint at INT 03' in ANSI.sub(b'', self.screen[pre:]):
                break
        else:
            return 'timeout'
        return self.go_on()

    def go_on(self):
        """F5 (resume) and watch, as go()."""
        t = time.time()
        if os.environ.get('SWOSTEST_BP4C') and self.eip is not None and not getattr(self, 'bp4c', False):
            self.cmd('BPINT 21 4C', 1, rb'breakpoint at INT 21')    # debug: after the first pause, also stop on
            for x in ('00', '06', '0D', '0E'):                 # the DOS exit (int 21h, AH 4Ch) and on CPU
                self.cmd('BPINT ' + x, 0.5)                        # exceptions (any break: SWOSTEST_BP4C only)
            self.bp4c = True
        self.probe_at, self.probe_cpu = 0, None
        for _ in range(3):                             # move the code view away: the next break must redraw it
            pre = len(self.screen)                     # (02/11: under load the command can be lost, then a break at
            os.write(self.fd, b'C 160:0\r')            # the same stub address is not redrawn and never seen: a
            self.pump(0.3, rb'160:0', pre)             # 'hang' with DOSBox-X idle in its debugger)
            if re.search(rb'160:0', ANSI.sub(b' ', self.screen[pre:])):
                break
        pre = len(self.screen)
        os.write(self.fd, b'\x1b[15~')                 # F5 = run
        self.pump(2, rb'Running', pre)                 # watch from the debugger's '(Running)' on
        i = self.screen.find(b'Running', pre)
        mark = i + 7 if i >= 0 else len(self.screen)
        start, nshot, first = time.time(), 0, True
        while True:
            n = self.pump(0.25, b'')
            if first:                                  # (a break right after F5 - the stadium's little players, ms
                n, first = max(n, 1), False            # apart - can come in one read with '(Running)': look at
                                                       # what is there once, else no new byte ever shows it)
            if n < 0 or not self.alive():
                for _ in range(20):                    # keep how DOSBox-X ended (exit code / signal) for the log
                    if not self.alive() or getattr(self, 'status', None):
                        break
                    time.sleep(0.1)
                return self.stat('run', t, 'exit')
            if n:
                m = (BREAK_ANY if getattr(self, 'anybreak', False) else BREAK).search(self.screen, mark)
                # (the debugger's code view redrawn on an int 3 (CD03); Session.sample: on any break)
                if not m and getattr(self, 'memwatch', False):   # SWOSTEST_BPLM: a memory breakpoint's hit, then
                    seg = ANSI.sub(b' ', self.screen[mark:])     # the code view (EIP after the writing instruction)
                    k = re.search(rb'Memory breakpoint[^\n]*->', seg)
                    if k:
                        m = re.compile(rb'0160:([0-9A-F]{8})\s').search(seg, k.end())
                        self.memhit = m is not None
                if not m and self.watch:               # or on one of our breakpoints (Session.bp)
                    seg = ANSI.sub(b' ', self.screen[mark:])
                    for w in re.finditer(rb'0160:([0-9A-F]{8})\s', seg):
                        if int(w.group(1), 16) in self.watch:
                            m = w
                            break
                if m:
                    self.pump(0.02)                    # the rest of the redraw
                    self.eip = int(m.group(1), 16)
                    return self.stat('run', t, 'break')
            el = time.time() - start
            if el >= (getattr(self, 'probe_at', 0) or 20) and self.eip is not None:
                cpu = dosbox_cpu(self.pid)             # stall probe: DOSBox-X idle (in its debugger) for 10 s while we
                last = getattr(self, 'probe_cpu', None)  # wait for a break = a break we did not see: the code view
                self.probe_cpu, self.probe_at = cpu, el + 10    # redrawn away and back on the last stub address
                if last is not None and cpu is not None and cpu - last < 0.5:
                    with open(os.path.join(self.run, 'stall.txt'), 'a') as fh:
                        fh.write(f'{time.strftime("%H:%M:%S")} no break seen, DOSBox-X idle {cpu - last:.2f} s CPU '
                                 f'in 10 s: code view redrawn at {self.eip:08X}\n')
                    os.write(self.fd, b'C 160:0\r')
                    self.pump(0.5)
                    mark = len(self.screen)
                    os.write(self.fd, f'C 160:{self.eip:X}\r'.encode())
                    self.probe_cpu = None
                    continue
            if self.shots and el >= nshot * self.shots:
                self.shot('t%04d' % int(time.time() - self.t0))
                nshot += 1
            if el > self.timeout:
                return self.stat('run', t, 'timeout')

    def stat(self, k, t, ret=None):
        self.stats[k] = self.stats.get(k, 0) + time.time() - t
        return ret

    def dump(self, lin, n):
        """n bytes of linear memory from lin (debugger MEMDUMPBIN into the run dir, read back)."""
        t = time.time()
        path = os.path.join(self.run, 'MEMDUMP.BIN')
        if os.path.exists(path):
            os.remove(path)
        for attempt in range(3):                       # a command typed while the debugger redraws can be lost
            os.write(self.fd, f'MEMDUMPBIN 168:{lin:X} 0{n:X}\r'.encode())   # (4.0.6: a bare AC / CF.. length is a flag name)
            end = time.time() + 10 + n / 0x200000
            while not (os.path.exists(path) and os.path.getsize(path) >= n) and time.time() < end:
                self.pump(0.01)
            if os.path.exists(path) and os.path.getsize(path) >= n:
                break
        else:
            raise RuntimeError(f'MEMDUMPBIN {lin:X} {n:X}: no file')
        data = open(path, 'rb').read()
        self.stat('dump', t)
        return data

    def shot(self, tag, pal=None, vga=None):
        """A frame of the game: runs/<name>/shots/<tag>.png. Paused game (pal = the palette, 768 bytes of VGA 6-bit
        values): 320x200, one pixel per game pixel, from the video memory at A0000 (vga = those 64000 bytes when
        already read). Running game (periodic shots, a timeout): a screencapture of the window, only with
        SWOSTEST_SCREENCAPTURE=1 (Davide, 2026-10-18: it made macOS ask for screen recording over and over)."""
        path = os.path.join(self.run, 'shots', tag + '.png')
        if pal is not None:
            from PIL import Image
            if vga is None:
                vga = self.dump(0xA0000, 64000)
            im = Image.frombytes('P', (320, 200), bytes(vga[:64000]))
            im.putpalette(bytes((v & 63) * 255 // 63 for v in pal[:768]))
            os.makedirs(os.path.dirname(path), exist_ok=True)
            im.save(path)
            return
        if not os.environ.get('SWOSTEST_SCREENCAPTURE'):
            return
        exe = os.path.join(WORK, 'bin', 'winid')            # window id of a pid (screencapture -l needs it)
        if not os.path.exists(exe):
            os.makedirs(os.path.dirname(exe), exist_ok=True)
            subprocess.run(['swiftc', '-O', os.path.join(ROOT, 'tools', 'swostest_winid.swift'), '-o', exe], check=True)
        win = subprocess.run([exe, str(self.pid)], capture_output=True, text=True)
        wid = win.stdout.strip()
        if wid and wid != '0':
            os.makedirs(os.path.join(self.run, 'shots'), exist_ok=True)
            subprocess.run(['screencapture', '-x', '-o', '-l', wid, path], capture_output=True)

    def post_mortem(self, shot=True, info=None):
        """After a break: full memory dump (MEMDUMP.BIN = linear 0..32 MB, read by Result) and, with the run's info
        (obj2 found in the dump), the frame 'final' from it; returns the break EIP."""
        mem = self.dump(0, MEMSIZE)
        if shot and info:
            off, chunk = info['anchor']
            base2 = mem.find(chunk) - off
            if base2 >= 0:
                self.shot('final', mem[base2 + info['pal']:base2 + info['pal'] + 768], mem[0xA0000:0xA0000 + 64000])
        return self.eip

    def kill(self):
        try:
            os.kill(self.pid, signal.SIGKILL)
            os.waitpid(self.pid, 0)
        except (ProcessLookupError, ChildProcessError):
            pass


# ----------------------------------------------------------------------------------------------------------- scenarios

class Result:
    """What a run left: outcome ('exit', 'dump', 'trap', 'timeout'), EIP, the game dir and the game's memory.
    Memory: the full dump MEMDUMP.BIN when there is one (obj1/obj2 linear bases found in it: they move with the exe's
    size), else read on demand from the paused game (box) at the bases a Session already knows; read() caches."""

    def __init__(self, run, outcome, eip, info, box=None, bases=None):
        self.run, self.game, self.outcome, self.eip = run, os.path.join(run, 'SWOS'), outcome, eip
        self.box, self.chunks, self._mem = box, [], None
        self.base1 = self.base2 = self.calls = None
        self.p3, self._base3 = info.get('p3') if info else None, None
        if bases:
            self.base1, self.base2 = bases
        else:
            path = os.path.join(run, 'MEMDUMP.BIN')
            if os.path.exists(path) and os.path.getsize(path) == MEMSIZE:
                self._mem = open(path, 'rb').read()
                off, chunk = info['code']
                self.base1 = self._mem.find(chunk) - off
                off, chunk = info['anchor']
                self.base2 = self._mem.find(chunk) - off
        if bases and box:                              # one dump: the stub's page + obj2's pages (adjacent; menus,
                                                       # slots; a big world's zero-filled tail is read on demand)
            lo, hi = self.base1 + info['page'], self.base2 + info['size2']
            if 0 < hi - lo <= 0x200000:
                self.read(lo, hi - lo)
        if self.base1 is not None and (self._mem is not None or box):
            self.calls = struct.unpack('<I', self.obj1(info['calls'], 4))[0]
        if eip is not None and self.base1 is not None:
            rel = eip - self.base1
            if info['page'] <= rel < info['page'] + 0x1000:
                self.outcome = 'dump'

    @property
    def mem(self):
        """The whole 32 MB (dumped now if this result only reads ranges)."""
        if self._mem is None and self.box:
            self._mem = self.box.dump(0, MEMSIZE)
        return self._mem

    def read(self, lin, n):
        if self._mem is not None:
            return self._mem[lin:lin + n]
        for a, d in self.chunks:
            if a <= lin and lin + n <= a + len(d):
                return d[lin - a:lin - a + n]
        assert self.box, 'memory of a finished pause'
        d = self.box.dump(lin, n)
        self.chunks.append((lin, d))
        return d

    def cached(self, lin, n):
        return self._mem is not None or any(a <= lin and lin + n <= a + len(d) for a, d in self.chunks)

    @property
    def base3(self):
        """obj3's linear base (4.0.6 builds: benchx there), from an obj1 pointer into it; None without obj3."""
        if self._base3 is None and self.p3 and self.base1 is not None:
            self._base3 = struct.unpack('<I', self.read(self.base1 + self.p3[0], 4))[0] - self.p3[1]
        return self._base3

    def lin(self, a):
        """The linear address of a (obj, offset) pair, or of a plain obj1 offset (older callers)."""
        if isinstance(a, tuple):
            return {1: self.base1, 2: self.base2, 3: self.base3}[a[0]] + a[1]
        if isinstance(a, Off3):
            return self.base3 + int(a)
        return self.base1 + a

    def obj1(self, off, n):
        return self.read(self.base1 + off, n)

    def obj2(self, off, n):
        return self.read(self.base2 + off, n)

    def where(self, lin):
        if self.base1 is None:
            return f'0x{lin:X}'
        if self.base3 is not None and lin >= self.base3 and (self.base3 > self.base2 or lin < self.base1):
            return f'obj3+0x{lin - self.base3:X}'
        if lin >= self.base2:
            return f'obj2+0x{lin - self.base2:X}'
        return f'obj1+0x{lin - self.base1:X}'

    def __str__(self):
        s = self.outcome
        if self.eip is not None:
            s += f' at {self.where(self.eip)} (linear 0x{self.eip:X}; obj1 0x{self.base1:X}, obj2 0x{self.base2:X})'
        if self.calls is not None:
            s += f', {self.calls} GetKey calls'
        return s


def run_case(name, exe_dir, cars, keys, timeout, shots=0, match=False, timer=False):
    """Run one key script on a copy of the game; returns a Result."""
    run, info = prepare(name, exe_dir, cars, steps_of(keys, TICKS if timer else RATE), match, timer)
    box = Dosbox(run, timeout, shots)
    eip = None
    try:
        outcome = box.go()
        if outcome == 'break':
            eip = box.post_mortem(info=info)
            outcome = 'trap'                           # Result turns it into 'dump' when EIP is in the stub
        elif outcome == 'timeout':
            box.shot('final')
    finally:
        box.kill()
        open(os.path.join(run, 'debugger.raw'), 'wb').write(box.screen)
    return Result(run, outcome, eip, info)


# SWOSTEST_UI=en: the harness drives the ENGLISH exe (run as ITALIAN.EXE) with its Italian menu logic: each screen
# text is translated to the Italian one the scenarios look for (world8485 / advance: a career's season loop, the
# season end); other texts stay as shown. Prefixes / suffixes: '<club> SQUAD' -> 'SQUADRA DEL <club>', '... END SEASON'
# -> 'FINE CAMP. ...'.
UI_EN = {'CAREER': 'CARRIERA', 'CHOOSE TEAM': 'SCEGLI SQUADRA', 'CLASSIC CAREERS': 'CARR. STORICHE',
         'WORLD 2026-27': 'MONDO 2026-27', 'EUROPE 1984-85': 'EUROPA 1984-85', 'EUROPE': 'EUROPA',
         'SOUTH AMERICA': 'SUDAMERICA', 'NORTH AMERICA': 'NORDAMERICA', 'ENGLAND': 'INGHILTERRA', 'ITALY': 'ITALIA',
         'CONTINUE': 'CONTINUA', 'CONTINUE CAREER': 'CONTINUA CARRIERA', 'EXIT': 'ESCI', 'FINISH SEASON': 'FINISCI STAGIONE',
         'EDIT TACTICS': 'MOD. TATTICA', 'VIEW OPPO': 'AVVERSARI', 'FIRST ROUND': 'PRIMO TURNO',
         'SECOND ROUND': 'SECONDO TURNO', 'SAVE CAREER': 'SALVA CARRIERA', 'FRIENDLY': 'AMICHEVOLE', 'PLAY MATCH': 'PARTITA',
         'TRANSFERS': 'TRASFERIMENTI', 'VIEW RESULT': 'VIS. RISULTATI', 'VIEW WORLD': 'VISUALIZZA MONDO',
         'SEASON': 'STAGIONE', 'CLASSIC SEASONS': 'STAG. STORICHE', 'VIEW COMPETITIONS': 'VISUAL. COMPETIZ.',
         '- MATCH -': '- PARTITA -', '- RESULT -': '- RISULTATO -', 'NEXT MATCH': 'PROSS. PARTITA', 'SQUAD': 'SQUADRA',
         'ADD INTERNATIONAL PLAYER (HOME)': 'AGGIUNGI GIOCA. INTERNAZIONALE (CASA)', 'STATS': 'STAT', 'FORMAT': 'FORMULA',
         'CHOOSE TEAMS': 'SCEGLI SQUADRE', 'CLUB TEAMS': 'SQUADRE CLUB', 'PLAY FRIENDLY': 'AMICHEVOLE'}


UI = os.environ.get('SWOSTEST_UI') or os.environ.get('SWOSTEST_LANG') or 'it'   # (SWOSTEST_LANG: an alias)
if UI != 'it':
    os.environ['SWOSTEST_UI'] = UI                 # (one switch for every check below)
# en / fr / de: tools/swostest_lang.json, the REL40 menus' labels per language collected from the same screens by
# index (club names never: they are not translated); umlauts / accents read as '?' for a known label
UI_MAP = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'swostest_lang.json'))).get(UI, {}) \
    if UI != 'it' else {}
UI_ORIG = {'it': 'ITALIAN', 'en': 'ENGLISH', 'fr': 'FRENCH', 'de': 'GERMAN'}.get(UI, 'ITALIAN') + '.EXE'
UI_ORIG_OF = {k: v + '.EXE' for k, v in {'it': 'ITALIAN', 'en': 'ENGLISH', 'fr': 'FRENCH', 'de': 'GERMAN'}.items()}
COLLECT = os.environ.get('SWOSTEST_COLLECT') == '1'    # (collecting the labels: raw texts, umlauts as '?')


def ui_it(text):
    if UI == 'it' or not text or COLLECT:
        return text
    if UI == 'en' and text in UI_EN:
        return UI_EN[text]
    if text in UI_MAP:
        return UI_MAP[text]
    if UI == 'en' and text.endswith(' SQUAD') and text != 'SQUAD':
        return 'SQUADRA DEL ' + text[:-6]
    if UI == 'en' and 'END SEASON' in text:
        return 'FINE CAMP. ' + text
    if text in ("SAISONS D'ANTAN", 'SAISONKLASSIKER'):   # (mkseason.SEASONS_NAMES: the historic seasons' button)
        return 'STAG. STORICHE'
    m = re.fullmatch(r'(ITALY|ITALIE|ITALIEN) (\d{4}-\d{2})', text)   # (the historic season's own button: Italy 1947-48)
    if m:
        return 'ITALIA ' + m.group(2)
    return text


class Screen:
    """The current menu read from a dump: entries [(index, text, invisible, disabled)], selected index."""

    def __init__(self, r, menu_off):
        m = r.base2 + menu_off
        self.n = struct.unpack('<H', r.read(m + 0x10, 2))[0]
        sel = struct.unpack('<I', r.read(m + 0x0C, 4))[0]
        self.selected = (sel - m - 0x16) // 0x38 if sel else None
        n = min(self.n, 120)
        mem = r.read(m, 0x16 + n * 0x38)
        ptrs = [struct.unpack_from('<I', mem, 0x16 + i * 0x38 + 0x26)[0] for i in range(n)]
        ptrs = [p if 0x1000 < p < MEMSIZE - 64 else 0 for p in ptrs]
        out = [p for p in ptrs if p and not r.cached(p, 64)]
        if out and max(out) - min(out) < 0x100000:     # texts outside the cached ranges: one dump for all
            r.read(min(out), max(out) + 64 - min(out))
        self.entries, self.nav, self.geom, self.colors, self.raw = [], [], [], [], []   # (raw: the bytes, '£' too)
        self.raw_texts = []                         # (4.0.6: the text as drawn - another language's - for widths)
        for i in range(n):
            e = 0x16 + i * 0x38
            inv, dis = struct.unpack_from('<HH', mem, e + 4)
            self.nav.append((tuple(mem[e + 8:e + 12]), tuple(mem[e + 16:e + 20])))   # l/r/u/d, skip l/r/u/d
            self.geom.append(struct.unpack_from('<4h', mem, e + 0x14))                # x, y, width, height
            self.colors.append(struct.unpack_from('<H', mem, e + 0x1E)[0])            # bg.backAndFrameColor
            text, raw = '', b''
            if ptrs[i]:
                raw = r.read(ptrs[i], 64).split(b'\0')[0]
                if raw and all(32 <= b < 127 for b in raw):
                    text = raw.decode()
                elif raw and (UI_MAP or COLLECT) and all(b >= 32 for b in raw):   # (another language's umlauts /
                    q = ''.join(chr(b) if b < 127 else '?' for b in raw)   # accents: '?', only a known label: the
                    text = q if q in UI_MAP or COLLECT else ''             # squad rows' drawn texts stay empty)
            self.raw_texts.append(text)
            self.entries.append((i, ui_it(text), inv, dis))
            self.raw.append(raw)

    def find(self, text, visible=True, exact=False):
        """Index of the first entry whose text starts with (exact: is) `text`, visible ones only by default."""
        for i, t, inv, dis in self.entries:
            if (t == text if exact else t.startswith(text)) and (not visible or not inv):
                return i
        return None

    def path(self, target, bad=frozenset(), steps=False):
        """Keys from the selected entry to entry `target` (BFS on the entries' left/right/up/down links); bad = moves
        (entry, key) seen to go elsewhere in the game; steps: [(key, expected entry)] instead of the keys."""
        if self.selected is None:
            return None
        prev, todo = {self.selected: None}, [self.selected]
        while todo:
            cur = todo.pop(0)
            if cur == target:
                out = []
                while prev[cur]:
                    p, k = prev[cur]
                    out.append((k, cur))
                    cur = p
                out = out[::-1]
                return out if steps else [k for k, _ in out]
            links, skips = self.nav[cur] if cur < len(self.nav) else ((), ())
            for d, (k, nxt, alt) in enumerate(zip(('left', 'right', 'up', 'down'), links, skips)):
                if (cur, k) in bad:
                    continue
                if nxt < len(self.entries) and self.entries[nxt][2] and alt < len(self.entries):
                    nxt = alt                            # invisible neighbour: the game takes the skip entry
                hops = 0
                while nxt < len(self.entries) and self.entries[nxt][2] and hops < 8:
                    nxt = self.nav[nxt][0][d]            # ... or goes on in the same direction
                    hops += 1
                if nxt < len(self.entries) and nxt not in prev and not self.entries[nxt][2]:
                    prev[nxt] = (cur, k)
                    todo.append(nxt)
        return None

    def texts(self):
        return [t for _, t, inv, _ in self.entries if t and not inv]

    def __str__(self):
        return ' | '.join(('>' if i == self.selected else '') + t + ('(inv)' if inv else '')
                          for i, t, inv, _ in self.entries if t)


def hexb(d):
    """Bytes as DOSBox-X SM values: '0' + hex for each (a bare AF / CF / DF / AC is read as a flag name and skipped)."""
    return ' '.join(f'0{x:X}' for x in d)


class Session:
    """Interactive run: the script pauses at each 'dump', the caller reads the screen and sends the next keys.

        with Session('name', build, cars, 'first keys dump:2') as s:
            while ...: scr = s.screen(); s.send('keys ... dump:1')
    """

    def __init__(self, name, exe_dir, cars, keys, timeout=60, shots=0, match=False, timer=False):
        self.rate = TICKS if timer else None           # (timer: SWOS++, keys fed from TimerProc at 70 Hz)
        self.run, self.info = prepare(name, exe_dir, cars, steps_of(keys, self.rate), match, timer)
        timeout = int(timeout * float(os.environ.get('SWOSTEST_TIMEOUT_MUL', 1)))   # (02/11: both Macs' slots full,
        self.timeout = timeout                          # bench_world BENCH_VIEW ran out of its 900 s at 90 pauses)
        self.box = Dosbox(self.run, timeout, shots)
        self.result = None
        self.log = []

    def __enter__(self):
        return self

    def __exit__(self, *a):
        self.box.kill()
        el = time.time() - self.box.t0
        if getattr(self.box, 'status', None):
            self.log.append(f'DOSBox-X ended: {self.box.status}')
        self.log.append(f'{getattr(self, "steps", 0)} pauses in {el:.0f} s: ' +
                        ', '.join(f'{k} {v:.0f} s' for k, v in sorted(self.box.stats.items())))
        open(os.path.join(self.run, 'debugger.raw'), 'wb').write(self.box.screen)
        open(os.path.join(self.run, 'session.log'), 'w').write('\n'.join(self.log) + '\n')

    def bp_stack(self, r):
        """SWOSTEST_BP_STACK=1: the obj1 return addresses in the 0x200 bytes above ESP at a breakpoint hit."""
        if not os.environ.get('SWOSTEST_BP_STACK'):
            return ''
        path = os.path.join(self.run, 'MEMDUMP.BIN')
        if os.path.exists(path):
            os.remove(path)
        self.box.cmd('MEMDUMPBIN 168:ESP 200', 2)
        if not os.path.exists(path):
            return ' stack ?'
        v = struct.unpack('<128I', open(path, 'rb').read()[:512])
        return ' stack ' + ' '.join(f'{x - r.base1:X}' for x in v if r.base1 <= x < r.base1 + 0xB3000)

    def bp(self, lin, callback):
        """Debugger breakpoint at a linear address; callback(result) runs at each hit, then the game goes on."""
        self.box.cmd(f'BP 0160:{lin:08X}', 0.3)
        self.box.watch.add(lin)
        self.bps = getattr(self, 'bps', {})
        self.bps[lin] = callback

    def wait(self):
        """Run to the next break; returns the Result (outcome 'dump' = our pause, 'trap', 'timeout', 'exit').
        The first pause dumps all memory (finds the obj1/obj2 bases); later pauses read only what is asked
        (Result.read: one dump of the stub page + obj2 up front, the rest on demand)."""
        b = self.box
        if self.result:
            self.result.box = None                     # its memory is gone once the game runs on
        if not hasattr(self, 'started'):
            self.started = True
            outcome = b.go()
        else:
            outcome = b.go_on()
        if os.environ.get('SWOSTEST_BP') and not getattr(self, 'bps', None) and outcome == 'break':
            base1 = self.paused('x', b.eip).base1
            self.bp_hits = {}
            for off in filter(None, os.environ.get('SWOSTEST_BPLM', '').split(',')):   # memory watches (obj2 offsets,
                b.cmd(f'BPLM {bplm_lin(self.paused("x", b.eip), off):08X}', 0.3)   # CORE=normal): a change
                b.memwatch = True                                                    # stops as a trap at its EIP
            for off in os.environ['SWOSTEST_BP'].split(','):     # counting breakpoints (use CORE=normal)
                o = int(off, 16)
                self.bp(base1 + o, lambda r, o=o: (self.bp_hits.__setitem__(o, self.bp_hits.get(o, 0) + 1),
                                                   self.log.append(f'BP obj1+{o:X} hit {self.bp_hits[o]}' + bp_str(r)
                                                                   + self.bp_stack(r))))
        while outcome == 'break' and getattr(b, 'memhit', False) and os.environ.get('SWOSTEST_BPLM_GO'):
            b.memhit = False                           # SWOSTEST_BPLM_GO: log the writer's EIP (+ stack), re-arm, go on
            r = self.paused('bplm', b.eip)
            self.log.append(f'BPLM obj1+{b.eip - r.base1:X}' + bp_str(r) + self.bp_stack(r))
            r.box = None
            b.cmd('BPDEL *', 0.3)
            b.cmd('BPINT 3', 0.2)
            for lin in getattr(self, 'bps', {}):
                b.cmd(f'BP 0160:{lin:08X}', 0.2)
            for off in filter(None, os.environ.get('SWOSTEST_BPLM', '').split(',')):
                b.cmd(f'BPLM {bplm_lin(r, off):08X}', 0.3)
            outcome = b.go_on()
        while outcome == 'break' and b.eip in getattr(self, 'bps', {}):
            r = self.paused('bp', b.eip)
            self.bps[b.eip](r)
            r.box = None
            pre = len(b.screen)
            b.cmd('BPLIST', 0.5)
            self.log.append('BPLIST: ' + ANSI.sub(b' ', b.screen[pre:]).decode('latin-1')[-300:])
            b.cmd('BPDEL *', 0.3)                     # re-arm: a DOSBox-X breakpoint may not survive its hit
            b.cmd('BPINT 3', 0.2)                      # (BPDEL * also removed the int 3 one)
            for lin in self.bps:
                b.cmd(f'BP 0160:{lin:08X}', 0.2)
            outcome = b.go_on()
        self.steps = getattr(self, 'steps', 0) + 1
        if outcome == 'break':
            self.result = self.paused('trap', b.eip)   # Result turns it into 'dump' when EIP is in the stub
            if self.result.outcome != 'dump' and self.result._mem is None:
                b.post_mortem(info=self.info)          # a real trap: full dump + frame for the post-mortem
                self.result = Result(self.run, 'trap', b.eip, self.info)
        else:
            if outcome == 'timeout':
                b.shot('final')
            dump = os.path.join(self.run, 'MEMDUMP.BIN')
            if os.path.exists(dump):
                os.remove(dump)                        # an older pause's dump
            self.result = Result(self.run, outcome, None, self.info)
        return self.result

    def sample(self, keys, secs=20.0):
        """Break a game that runs without waiting for a key (a busy loop, a slow season end): send keys with a
        breakpoint on the timer interrupt (BPINT 8, every tick, ~18 / s), log each tick's EIP and run on, for secs.
        Returns ({obj1 offset: ticks}, Result): Result 'dump' when the game reached our pause first (no hang),
        else 'trap' at the last tick's EIP with a full memory dump (MEMDUMP.BIN) for the post-mortem. The ticks
        slow the game ~10x: a histogram, not a timing. Use CORE=normal for exact EIPs. notes/harness.md 'Breaking a
        busy game'."""
        b = self.box
        b.cmd('BPINT 8', 0.5)
        b.anybreak = True
        hist, t0 = {}, time.time()
        r = self.send(keys)
        while r.outcome != 'dump' and r.outcome == 'trap' and time.time() - t0 < secs:
            off = b.eip - self.bases[0] if getattr(self, 'bases', None) else b.eip
            hist[off] = hist.get(off, 0) + 1
            outcome = b.go_on()
            if outcome != 'break':
                r = Result(self.run, outcome, None, self.info)
                break
            r = Result(self.run, 'trap', b.eip, self.info, b, self.bases)
            if b.eip == self.bases[0] + self.info['brk']:
                r.outcome = 'dump'
        b.cmd('BPDEL *', 0.3)                          # the timer breakpoint off, our int 3 one back
        b.cmd('BPINT 3', 0.2)
        b.anybreak = False
        if r.outcome == 'trap':
            b.post_mortem(info=self.info)
            r = Result(self.run, 'trap', b.eip, self.info)
        self.result = r
        self.log.append('SAMPLE ' + ', '.join(f'obj1+{o:X}:{c}' for o, c in sorted(hist.items(), key=lambda x: -x[1])[:12]))
        return hist, r

    def paused(self, outcome, eip):
        """Result of the paused game: the first time a full dump (bases), then reads on demand."""
        if not getattr(self, 'bases', None):
            self.box.post_mortem(shot=False)
            r = Result(self.run, outcome, eip, self.info, self.box)
            self.bases = (r.base1, r.base2)
            return r
        return Result(self.run, outcome, eip, self.info, self.box, self.bases)

    def shot(self, tag):
        """Frame of the paused game (Dosbox.shot from memory: video memory + g_workingPalette)."""
        assert self.result.outcome == 'dump', str(self.result)
        self.box.shot(tag, self.result.obj2(self.info['pal'], 768))

    def screen(self):
        assert self.result.outcome == 'dump', str(self.result)
        return Screen(self.result, self.info['menu'])

    def poke(self, lin, data):
        """Write bytes into the paused game's memory (debugger SM; the next read sees them). Each byte is typed with a
        leading 0 (DOSBox-X's SM parsed a bare AF / CF / DF / AC as a flag name and silently skipped that byte - Panchina,
        29/10), 16 bytes per SM, the echo read after each (many SMs at once filled the pty: both sides waited), then
        read back: a byte that did not land FAILs the scenario."""
        data = bytes(data)
        assert len(data) <= POKE_MAX, f'poke at {lin:#x}: {len(data)} B in one call (POKE_MAX {POKE_MAX}): split it'
        k0 = 0
        for i, k in enumerate(range(0, len(data), 16)):
            os.write(self.box.fd, f"SM 168:{lin + k:X} {hexb(data[k:k + 16])}\r".encode())
            self.box.pump(0.05)
            if (i + 1) % POKE_SYNC == 0 and k + 16 < len(data):   # (4.0.6, Motore: ~25 SMs in a row stalled the
                got = self.box.dump(lin + k0, k + 16 - k0)          # debugger mid-typing; a read every POKE_SYNC
                assert got == data[k0:k + 16], f'poke at {lin + k0:#x}: wrote {data[k0:k + 16].hex()}, read {got.hex()}'
                k0 = k + 16                                         # SMs lets it drain)
        if self.result:
            self.result.chunks = []
        got = self.box.dump(lin, len(data))
        assert got == data, f'poke at {lin:#x}: wrote {data.hex()}, read {got.hex()}'

    def send(self, keys):
        """Write the next steps into the stub's script area (ptr was reset to it by the pause), step over the int 3, resume
        (debugger commands typed in one go: DOSBox-X runs them in order before the F5)."""
        r, b = self.result, self.box
        t = time.time()
        steps = steps_of(keys, getattr(self, 'rate', None))
        assert len(steps) < SCRIPT_MAX
        data = b''.join(struct.pack('<HH', k, w) for k, w in steps) + b'\0' * 4
        base = r.base1 + self.info['script']
        cmds = [f'SM 168:{base + i:X} {hexb(data[i:i + 16])}' for i in range(0, len(data), 16)]   # (leading 0s: hexb)
        cmds.append(f'SR EIP {r.base1 + self.info["brk"] + 2:X}')   # int 3 = 2 bytes (CD 03)
        os.write(b.fd, ''.join(c + '\r' for c in cmds).encode())
        if os.environ.get('SWOSTEST_VERIFY'):          # read the script back (the SMs must have landed)
            got = b.dump(base, len(data))
            assert got == data, f'SM: wrote {data.hex()}, read {got.hex()}'
        b.stat('send', t)
        self.log.append(keys)
        return self.wait()


def press(s, scr, text, wait=2, exact=True, avoid=frozenset()):
    """Select the visible entry `text` (or entry number), check on the next pause that it is the selected one (a
    move can be taken twice), then fire; returns the new Result (None if not reachable). avoid = moves (entry, key)
    not to take (the long bench's window: up on row 12 / down on row 17 scroll it); none left: any way."""
    i = text if isinstance(text, int) else scr.find(text, exact=exact)
    if i is None:
        return None
    bad = set(avoid)
    for attempt in range(40):
        if scr.selected == i:
            return s.send(f'{PRESS_FIRE} dump:{wait}')
        steps = scr.path(i, bad, steps=True)
        if not steps and bad & set(avoid):
            bad -= set(avoid)                           # (no way around: the window may move)
            avoid = frozenset()
            steps = scr.path(i, bad, steps=True)
        if not steps:
            return None
        if attempt < 2 and not (bad - set(avoid)):     # the whole path at once (the usual case)
            if s.send(' '.join(k for k, _ in steps) + ' dump:0.5').outcome != 'dump':
                return s.result
            scr = s.screen()
            continue
        cur, (k, want) = scr.selected, steps[0]        # it went astray: one key at a time, and a move that lands
        if s.send(k + ' dump:0.5').outcome != 'dump':  # elsewhere (a link the model reads wrong) is not tried again
            return s.result
        scr = s.screen()
        if scr.selected != want:
            bad.add((cur, k))
    return None


# Career "results only", the fast loop (Davide): career menu PARTITA -> VIS. RISULTATI -> ESCI -> PARTITA ...
# (PROSS. PARTITA only shows each match). The squad screen hides VIS. RISULTATI while an injured/suspended player is
# in the first 16: he must be swapped with one beyond the 16th (face of the player -> left, then fire on the name).


# red on the frames built from memory (the game's palette, no colour management): the red row gradient (255,36,36)..
# (255,101,101) and the injury / red card red (255,0,0); not skin (182,72,0), (255,109,0) nor the shirts' maroon
RED = lambda c: c[0] >= 240 and c[1] <= 101 and abs(c[1] - c[2]) <= 8


def squad_rows(s, scr, tag):
    """Screenshot of the paused game -> [(entry, unavailable)] for the squad rows (entries 25,y,82,8 sorted by y).
    Unavailable = red row background (x=100) or red pixels in the face/icon column (x 2-11): red card / injury."""
    from PIL import Image
    rx = row_x(scr)
    rows = sorted((g[1], i) for i, g in enumerate(scr.geom)
                  if g[0] == rx and (g[2], g[3]) in SQ_WH and not scr.entries[i][1])   # drawn rows, not text copies
    dx = rx - 25                                         # (the ENGLISH exe's layout: 6 px to the right)
    s.shot(tag)
    im = Image.open(os.path.join(s.run, 'shots', tag + '.png')).convert('RGB')
    w, h = im.size
    top = h - w * 400 // 640                           # window title bar (0: frames built from memory)
    px = lambda x, y: im.getpixel((min(w - 1, int(x * w / 320)), min(h - 1, int(top + y * (h - top) / 200))))
    out = []
    for y, i in rows:
        icon = sum(RED(px(x + dx, y + dy)) for x in range(2, 12) for dy in range(1, 8))
        out.append((i, RED(px(100 + dx, y + 4)) or icon >= 16))     # faces have ~6 reddish points, red icons 20+
    return out


SLOT_ROLE = 'GDDDDMMMMAAGDMA'                     # record order of a SWOS squad: G RB LB D D RW LW M M A A, bench G D M A
POS_ROLE = {'P': 'G', 'TD': 'D', 'TS': 'D', 'D': 'D', 'MD': 'M', 'MS': 'M', 'M': 'M', 'A': 'A',
            'G': 'G', 'RB': 'D', 'LB': 'D', 'RW': 'M', 'LW': 'M'}    # (+ the ENGLISH exe's codes)
POS_ROLE_UI = {'fr': {'DD': 'D', 'DG': 'D', 'MG': 'M'},  # (the exes' own codes: FR G DD DG D MD MG M A;
               'de': {'T': 'G', 'RV': 'D', 'LV': 'D', 'A': 'D', 'RA': 'M', 'LA': 'M', 'S': 'A'}}   # DE T RV LV A RA LA M S -
                                                  # A = Abwehr there, a defender: the German squad screens' reserve keeper)


SQ_WH = ((82, 8), (81, 8), (80, 8), (79, 8))     # (numcol.py: 4.0.5 the rows 1 px right, 81 wide; 4.0.6 79)


def row_x(scr):
    """The squad rows' x (25 in the Italian exe, 31 in the English one; +1 from 4.0.5): the drawn 82 / 81 x 8 rows
    without text."""
    xs = [g[0] for i, g in enumerate(scr.geom) if (g[2], g[3]) in SQ_WH and not scr.entries[i][1]]
    return max(set(xs), key=xs.count) if xs else 25


def reserve_info(cur, y):
    """The 17th squad row (the reserve shown, the only row with texts): (name, role G/D/M/A or '', value)."""
    t = sorted((cur.geom[j][0], tx) for j, tx, inv, _ in cur.entries if tx and not inv and cur.geom[j][1] == y
               and cur.geom[j][0] < 180)
    x0 = min((x for x, tx in t), default=25)            # the name column: 25 (31 in the ENGLISH exe)
    name = next((tx for x, tx in t if x == x0), '')
    pr = dict(POS_ROLE, **POS_ROLE_UI.get(os.environ.get('SWOSTEST_UI', 'it'), {}))
    role = next((pr.get(tx, '') for x, tx in t if 95 + x0 - 25 <= x <= 125 + x0 - 25), '')
    price = next((tx for x, tx in t if x >= 138), '')
    m = re.fullmatch(r'L([0-9.]+)(K|MN|MD)', price)
    value = (float(m.group(1)) * {'K': 0.001, 'MN': 1, 'MD': 1000}[m.group(2)] if m else
             -1 if price in ('PROVA', 'TRIAL') else 0)          # RIS (the game's invented reserves) 0, trial players -1
    return name, role, value


def row_entries(scr):
    """The 17 squad rows' entries, top to bottom (no screenshot: the drawn rows' geometry)."""
    rx = row_x(scr)
    return [i for _, i in sorted((g[1], i) for i, g in enumerate(scr.geom)
                                 if g[0] == rx and (g[2], g[3]) in SQ_WH and not scr.entries[i][1])]


def to_entry(s, i, tries=24):
    """The cursor to entry i (no fire): the path again after each send (a key the window took)."""
    for _ in range(tries):
        q = s.screen()
        if q.selected == i:
            return True
        keys = q.path(i)
        if not keys or s.send(' '.join(keys) + ' dump:0.5').outcome != 'dump':
            return False
    return False


WIN_OFF = {13: 4, 28: 2, 11: 8}            # the rows' first entry -> benchx's window word: bx_pw (the pre-match
                                            # screen), bx_sq (SQUADRA), bx_tw (the tactics editor); the box = row 17 + 1


def bx_window(s):
    """benchx's window on the screen shown ((value, the box's entry)), or None: no benchx (bx_bench not found), not a
    17-row player list, or the game's bench of 5 (no window: the box rotates the reserves)."""
    rows = row_entries(s.screen())
    if len(rows) != 17 or rows[0] not in WIN_OFF:
        return None
    if not hasattr(s, 'bx'):
        try:
            s.bx = bench_switch(os.path.join(s.run, 'SWOS', 'ITALIAN.EXE'))[0]
        except AssertionError:
            s.bx = None
    if s.bx is None:
        return None
    r = s.result
    if bench_eff(r, s.bx) <= 5:
        return None
    return struct.unpack('<H', r.read(r.lin(s.bx) + WIN_OFF[rows[0]], 2))[0], rows[16] + 1


def window_home(s, tries=40):
    """The long bench's window back to the top, so that rows 12..16 are places 12..16 again: FIRE on the box (4.0.6,
    Marco: only the box moves it, one place on, back to the top after the last; the name rows never scroll). True
    with no window (the game's bench of 5); False if the squad screen is not there."""
    if len(row_entries(s.screen())) != 17:
        return False
    for _ in range(tries):
        w = bx_window(s)
        if w is None or w[0] == 0:
            return True
        if not to_entry(s, w[1]) or s.send(f'{PRESS_FIRE} dump:0.5').outcome != 'dump':
            return False
    return False


def swap_in(s, slot, rows, reserve, ry, want, tries=40):
    """Row `slot` (0-based, rows = squad_rows' list or row_entries) <-> the reserve the 17th row shows now (named
    want). The game swaps by place (benchx 4.0.6: the mark is the player's place, kept while the window scrolls), so
    a row that never moves (1..11) is pressed after the reserve: the reserve first, then the row; a bench row (12..16:
    a window row with a bench over 5) needs the window at the top: home, the row first, then FIRE on the box until
    the 17th row shows want again (4.0.6, Marco: only the box scrolls). (Up to rc14p the harness marked the row first
    and went back to row 17 while the cursor scrolled the window: row 17 showed another player and he went in;
    world_full_eng 30/10: a reserve keeper 'in' x384, 3 h.) True if done."""
    ent = [r[0] if isinstance(r, tuple) else r for r in rows]
    if slot < 11:
        return press(s, s.screen(), reserve, wait=1) is not None and \
            to_entry(s, ent[slot]) and s.send(f'{PRESS_FIRE} dump:1').outcome == 'dump'
    if not window_home(s) or press(s, s.screen(), ent[slot], wait=1) is None:
        return False
    for _ in range(tries):
        if reserve_info(s.screen(), ry)[0] == want:
            return press(s, s.screen(), reserve, wait=1) is not None
        w = bx_window(s)
        if w is None:
            return False                                # (the game's bench of 5: no window to move)
        if not to_entry(s, w[1]) or s.send(f'{PRESS_FIRE} dump:0.5').outcome != 'dump':
            return False
    return False


def swap_rows(s, rows, a, b):
    """Rows a < 11 and b (0-based) of the first 16 change places: a window row (12..16) first, after the window is
    back at the top (long bench), then the starter's row (rows 1..11 never move)."""
    ent = [r[0] if isinstance(r, tuple) else r for r in rows]
    if b >= 11 and not window_home(s):
        return False
    return press(s, s.screen(), ent[b], wait=1) is not None and \
        to_entry(s, ent[a]) and s.send(f'{PRESS_FIRE} dump:1').outcome == 'dump'


def lineup_stuck(s, why):
    """The fixer's stuck limit (Regia 30/10: rc14p looped for hours): the same squad screen left by ESCI without
    VIS. RISULTATI LINEUP_STUCK (3) times in a row -> an error (fail fast); a fixed line-up resets the count."""
    s.lineup_esc = getattr(s, 'lineup_esc', 0) + 1
    if s.lineup_esc >= int(os.environ.get('LINEUP_STUCK', 3)):
        return f'line-up fixer stuck ({s.lineup_esc} squad screens left without VIS. RISULTATI): {why}'
    return None


def lineup_mem(s, n=16):
    """(rc19 world_gplay_nzchamp) The career club's first n places from memory: (place 1 a goalkeeper, [the unavailable
    places, 0-based]) - careerTeam's records in careerMatchPlayers order (xtra.sites of the run's exe, cached per
    session; position bits 5-7 = 0: a keeper; cardsInjuries C0h injured, bits 0-1 suspended in a career). None if it
    cannot be read."""
    try:
        if not hasattr(s, 'ctsites'):
            sys.path.insert(0, os.path.join(ROOT, 'tools'))
            import lepatch
            import xtra
            _, cnp, ct, cmp_, _ = xtra.sites(lepatch.LEPatch(os.path.join(s.run, 'SWOS', 'ITALIAN.EXE')))
            s.ctsites = (cnp, ct, cmp_)
        cnp, ct, cmp_ = s.ctsites
        r = s.result
        order = r.obj2(cmp_, min(n, struct.unpack('<H', r.obj2(cnp, 2))[0]))
        recs = [r.obj2(ct + (76 + q * 38 if q < 16 else 684 + (q - 16) * 38) + 26, 2) for q in order]
        return recs[0][0] >> 5 == 0, [k for k, b in enumerate(recs) if b[1] & 0xC3]
    except Exception:
        return None


def heal_first16(s):
    """The career club's first 16 made fit again: the injury bits (cardsInjuries C0h) cleared in every copy of their
    records (as BENCH_INJ sets them), so a result-dependent injury (a training game's) cannot hide PLAY MATCH. The
    names healed; [] if none (or unreadable)."""
    if lineup_mem(s) is None:               # (caches s.ctsites)
        return []
    _, ct, cmp_ = s.ctsites
    r = s.result
    o2 = r.read(r.base2, 0x300000)
    healed = []
    for q in r.obj2(cmp_, 16):
        slot = ct + (76 + q * 38 if q < 16 else 684 + (q - 16) * 38)
        if not r.obj2(slot + 27, 1)[0] & 0xC0:
            continue
        nm = r.obj2(slot + 3, 22).split(b'\0')[0]
        for m_ in re.finditer(re.escape(nm) + b'\0', o2):
            h = m_.start() - 3
            s.poke(r.base2 + h + 27, bytes((o2[h + 27] & 0x3F,)))
        healed.append(nm.decode('latin-1'))
    return healed


LINEUP_REFUSED = ('the game refuses the line-up: VIS. RISULTATI hidden with a fit goalkeeper in goal, no red row and '
                  'the first 16 all available in memory - not a line-up fault the fixer can mend (the match / contest '
                  'itself: rc19 world_gplay_nzchamp, the NZ Grand Final)')


def no_red_bad(s):
    """No red row among the first 16 and VIS. RISULTATI hidden after a redraw: the places to fix, read from memory (a
    suspended player shows no red mark), [0] = no goalkeeper in goal, or LINEUP_REFUSED (a fit keeper and nobody
    unavailable: fail fast - rc19 nzchamp ping-ponged reserve keepers for 3 screens). None = unreadable: [0] as before."""
    m = lineup_mem(s)
    if m is None:
        return [0]
    gk, unfit = m
    if unfit:
        s.log.append(f'[subs] no red row, unavailable in memory: places {[k + 1 for k in unfit]}')
        return unfit
    return [0] if not gk else LINEUP_REFUSED


def substitute(s, scr, tries=40, full=False):
    """Squad screen (Davide, 2026-10-16: the harness used to put any fit reserve - a defender up front, a trial player -
    in place of a starter and leave him there). Two passes on the 17th row (the reserve shown; its face cycles through
    the reserves beyond the 16th):
    1. restore: a starter swapped out earlier (s.subs: slot -> (starter, stand-in)) who is fit again goes back to his
       slot;
    2. an unavailable player (red row / red icon) among the first 16: the best fit reserve of the slot's role (record
       order G D D D D M M M M A A, bench G D M A), by value; another role, the game's invented reserves (RIS) and
       trial players (PROVA) only when nothing better is there. Row 1 must be a goalkeeper (P): a fit one of the
       bench (row 12) first. Returns an error string or None."""
    subs = s.__dict__.setdefault('subs', {})
    gk_now, out_now = False, set()                      # (the bench keeper / a stand-in went in during this call)
    if not full and os.environ.get('SWOSTEST_LINEUP', 'min') != 'full':   # (the default: substitute_min; full =
        return substitute_min(s, tries)                     # the best-reserve search below, also its fallback)                      # search below, for a scenario that judges the club's results)

    def cycle(face, ry):                                # every reserve once: [(name, role, value, fit)]
        seen = []
        for _ in range(tries):
            c2 = s.screen()
            name, role, value = reserve_info(c2, ry)
            if seen and name == seen[0][0]:
                break
            rows2 = squad_rows(s, c2, f'sq{len(s.log):03d}')
            if len(rows2) != 17:                        # not the squad screen any more (a message, a shot
                break                                   # that failed): stop cycling, the caller looks again
            seen.append((name, role, value, not rows2[-1][1]))
            press(s, c2, face, wait=1)
        return seen

    def bring(face, ry, want):                          # cycle the 17th row to the reserve named want
        for _ in range(tries):
            if reserve_info(s.screen(), ry)[0] == want:
                return True
            press(s, s.screen(), face, wait=1)
            if s.result.outcome != 'dump':
                return False
        s.send('dump:1')                                # one more look after a pause (redraw)
        return reserve_info(s.screen(), ry)[0] == want

    def swap(k, rows, want):                            # row k and the reserve shown (want) change places
        return swap_in(s, k, rows, reserve, ry, want, tries)

    for _ in range(10):                                 # one swap per round, then look again
        window_home(s)                                  # (long bench: rows 12..16 = places 12..16 for the reads)
        cur = s.screen()
        rows = squad_rows(s, cur, f'sq{len(s.log):03d}')
        if len(rows) != 17:
            return f'squad screen: {len(rows)} rows'
        reserve = rows[-1][0]
        ry = cur.geom[reserve][1]
        face = next((i for i, (l, r) in enumerate(cur.nav) if l[1] == reserve and cur.geom[i][0] < row_x(cur)), None)
        if face is None:
            return 'squad screen: no face entry for the 17th row'
        # the first keeper fit again; row 12 must still be him (11 in subs: he left the 16, a stand-in is there)
        if s.__dict__.get('gk_swap') and not gk_now and 11 not in subs and not rows[11][1] and not rows[0][1]:
            swap_rows(s, rows, 0, 11)
            s.gk_swap = False
            s.log.append('[subs] slot 1: the first keeper back')
            continue
        pool = cycle(face, ry) if subs or any(un for _, un in rows[:16]) else []
        back = next(((k, st) for k, (st, _) in sorted(subs.items()) if k not in out_now
                     and any(n == st and fit for n, _, _, fit in pool) and not rows[k][1]), None)
        if back is None:                                # restore also over an unavailable stand-in
            back = next(((k, st) for k, (st, _) in sorted(subs.items()) if k not in out_now
                         and any(n == st and fit for n, _, _, fit in pool)), None)   # (not one taken out in this
                                                        # visit: a suspended reserve shows no red mark - it ping-ponged)
        if back is not None:                            # 1. a starter fit again: back to his slot
            k, st = back
            if bring(face, ry, st) and swap(k, rows, st):
                s.log.append(f'[subs] slot {k + 1}: {st} back')
            del subs[k]
            continue
        for k in [k for k, st in list(subs.items()) if not any(n == st[0] for n, _, _, _ in pool)]:
            del subs[k]                                 # the starter left the squad (sold, the game's changes)
        bad = [k for k, (i, un) in enumerate(rows[:16]) if un]
        if not bad and 'VIS. RISULTATI' not in cur.texts() and not vis_ok(s):
            bad = no_red_bad(s)                         # no goalkeeper in goal (the game's own squad changes), an
            if bad == LINEUP_REFUSED:                   # unmarked suspended player (memory), or the game's refusal
                return bad
        if not bad:
            return None if 'VIS. RISULTATI' in s.screen().texts() else 'squad screen without VIS. RISULTATI, no unavailable row'
        k = bad[0]
        need = SLOT_ROLE[k] if k < len(SLOT_ROLE) else ''
        if k == 0 and not rows[11][1] and not s.__dict__.get('gk_swap') and 11 not in subs:   # the keeper: row 12
            swap_rows(s, rows, 0, 11)                   # is the bench keeper in SWOS squads (drawn rows have no
                                                        # texts) unless a stand-in took his place
            s.gk_swap = gk_now = True                   # (not back in this same visit: a suspended keeper on the
            s.log.append('[subs] slot 1: the bench keeper (row 12) in')   # bench shows no red mark - it ping-ponged)
            continue
        pool = pool or cycle(face, ry)
        fit = [(n, r, v) for n, r, v, f in pool if f and n]
        rank = lambda c: ((c[1] == need) if need else 1,           # the slot's role first (G: keepers only)
                          c[2] > 0, c[2] >= 0, c[2])               # real players, then RIS, trial players last
        cand = ([c for c in fit if c[1] == 'G'] or fit) if k in (0, 11) else \
            ([c for c in fit if c[1] != 'G'] or fit)          # out of role only as a last resort (the game itself
        if not cand:                                          # puts an outfield player in goal when it must)
            return f'no fit reserve for row {k + 1}'
        best = None
        for c in sorted(cand, key=rank, reverse=True):        # the best one that the cycle shows again (a read
            if bring(face, ry, c[0]):                         # before the row's redraw can miss a name)
                best = c
                break
        if best is None:
            return f'row {k + 1}: no candidate found again in the reserves ({[c[0] for c in cand][:6]})'
        stand_in = best[0]
        if not swap(k, rows, stand_in):
            return f'row {k + 1}: {stand_in} not swapped in'
        out = reserve_info(s.screen(), ry)[0]           # the one who left the 16 is now the 17th row
        if k not in subs:
            subs[k] = (out, stand_in)
        out_now.add(k)
        s.log.append(f'[subs] slot {k + 1} ({need or "any"}): {out} out, {stand_in} ({best[1] or "?"}, {best[2]}) in')
    return 'squad screen: still unavailable players after 10 swaps'


def vis_ok(s):
    """VIS. RISULTATI shown after a redraw (a swap's screen is read before the game re-checks the line-up)."""
    s.send('dump:1')
    return s.result.outcome == 'dump' and 'VIS. RISULTATI' in s.screen().texts()


def keeper_from_reserves(s, cur, rows, tries=40):
    """Row 1 without a fit goalkeeper: cycle the 17th row (the reserve shown) to a fit G / P and swap him into row 1.
    Returns an error string or None."""
    reserve = rows[-1][0]
    ry = cur.geom[reserve][1]
    face = next((i for i, (l, r) in enumerate(cur.nav) if l[1] == reserve and cur.geom[i][0] < row_x(cur)), None)
    if face is None:
        return 'squad screen: no face entry for the 17th row'
    first = None
    for _ in range(tries):
        c2 = s.screen()
        rows2 = squad_rows(s, c2, f'sq{len(s.log):03d}')
        if len(rows2) != 17:
            return f'squad screen: {len(rows2)} rows'
        name, role, _ = reserve_info(c2, ry)
        if role == 'G' and not rows2[-1][1]:
            if not swap_in(s, 0, rows2, reserve, ry, name, tries):
                return f'slot 1: the reserve keeper {name} not swapped in'
            s.log.append(f'[subs] slot 1: {name} (a reserve keeper) in (min)')
            return None
        if first is None:
            first = name
        elif name == first:
            break
        press(s, c2, face, wait=1)
    return 'no fit goalkeeper among the reserves'


def substitute_min(s, tries=40):
    """The default line-up handling (SWOSTEST_LINEUP=min; Davide 2026-10-19: flow / calendar / save-load runs, where
    the line-up's quality does not matter; SWOSTEST_LINEUP=full = substitute's best-reserve search): only
    what the game needs to show VIS. RISULTATI - an unavailable player among the first 16 changes places with the
    first fit reserve the 17th row shows (cycled only while it shows an unavailable one), the keeper's slot with the
    bench keeper (row 12) first; no best-reserve search, no starter brought back later (substitute's two cycles over
    every reserve per squad screen were ~50-60% of a long career's pauses). Returns an error string or None."""
    keeper = False                                      # (the row-12 keeper swap: once)
    for _ in range(12):
        if 'VIS. RISULTATI' in s.screen().texts():      # (the match allowed: nothing to fix - with a bench over 5 an
            s.lineup_esc = 0                            # unavailable bench player is left out at the kick-off)
            return None
        window_home(s)                                  # (long bench: rows 12..16 = places 12..16 for the reads)
        cur = s.screen()
        rows = squad_rows(s, cur, f'sq{len(s.log):03d}')
        if len(rows) != 17:
            return f'squad screen: {len(rows)} rows'
        bad = [k for k, (i, un) in enumerate(rows[:16]) if un]
        if not bad and 'VIS. RISULTATI' not in cur.texts():
            if vis_ok(s):                               # (only not redrawn yet)
                s.lineup_esc = 0
                return None
            bad = no_red_bad(s)                         # no goalkeeper in goal (the game's own squad changes), an
            if bad == LINEUP_REFUSED:                   # unmarked suspended player (memory), or the game's refusal:
                return bad                              # fail fast (no fallback, no ESCI loop)
        if not bad:
            return None if 'VIS. RISULTATI' in cur.texts() else 'squad screen without VIS. RISULTATI, no unavailable row'
        k = bad[0]
        if k == 0 and (keeper or rows[11][1]):          # no fit keeper in goal (row 12 is not always one: an outfield
            err = keeper_from_reserves(s, cur, rows, tries)   # player in goal keeps VIS. RISULTATI hidden): a fit
            if err:                                           # keeper (P / G) of the reserves, the 17th row cycled
                return fallback_full(s, tries, err)
            continue
        if k == 0:                                      # the keeper: row 12 is the bench keeper in SWOS squads
            swap_rows(s, rows, 0, 11)
            keeper = True
            s.log.append('[subs] slot 1: the bench keeper (row 12) in (min)')
            continue
        reserve = rows[-1][0]
        ry = cur.geom[reserve][1]
        face = next((i for i, (l, r) in enumerate(cur.nav) if l[1] == reserve and cur.geom[i][0] < row_x(cur)), None)
        if face is None:
            return 'squad screen: no face entry for the 17th row'
        # the first fit reserve the 17th row shows with a real value; the game's invented reserves (RIS, value 0:
        # a red '?' once in the 16, VIS. RISULTATI hidden) and trial players (-1) only on a second lap
        name, _, value = reserve_info(cur, ry)
        first, lap, fit = name, 0, not rows[-1][1] and value > 0
        for _ in range(2 * tries):
            if fit:
                break
            press(s, s.screen(), face, wait=1)
            if s.result.outcome != 'dump':
                return f'squad screen: {s.result}'
            c2 = s.screen()
            rows2 = squad_rows(s, c2, f'sq{len(s.log):03d}')
            if len(rows2) != 17:
                break
            name, _, value = reserve_info(c2, ry)
            if name == first:                           # (every reserve seen once)
                lap += 1
                if lap == 2:
                    break
            fit = not rows2[-1][1] and (value > 0 or lap == 1)
        if not fit:                                     # (no fit reserve: the game may still allow the match, else
            return fallback_full(s, tries, f'no fit reserve for row {k + 1}')   # the full search, once)
        stand_in = reserve_info(s.screen(), ry)[0]
        if not swap_in(s, k, rows, reserve, ry, stand_in, tries):
            return fallback_full(s, tries, f'row {k + 1}: {stand_in} not swapped in')
        out = reserve_info(s.screen(), ry)[0]           # (the one who left the 16: now the 17th row; recorded as the
        subs = s.__dict__.setdefault('subs', {})        # full search does, so its fallback can bring him back)
        if k not in subs:
            subs[k] = (out, stand_in)
        s.log.append(f'[subs] slot {k + 1}: {stand_in} in (min)')
    return fallback_full(s, tries, '12 swaps without VIS. RISULTATI')


def fallback_full(s, tries, why):
    """The minimal line-up stuck: VIS. RISULTATI after a redraw is enough (the game allows the match), else the full
    best-reserve search for this screen; its error only if that fails too."""
    if vis_ok(s):
        s.log.append(f'[subs] {why}, but VIS. RISULTATI shown (min)')
        s.lineup_esc = 0
        return None
    s.log.append(f'[subs] {why} - the full search for this screen (min)')
    err = substitute(s, s.screen(), tries, full=True)
    if err and vis_ok(s):
        s.lineup_esc = 0
        return None
    if err:                                             # no fit reserve at all: an unavailable starter (rows 1-11)
        window_home(s)                                  # to the bench, a fit bench player (rows 12-16) in his place
        cur = s.screen()
        rows = squad_rows(s, cur, f'sq{len(s.log):03d}')
        if len(rows) == 17:
            fitb = [k for k in range(11, 16) if not rows[k][1]]
            for k in [k for k in range(11) if rows[k][1]]:
                if not fitb:
                    break
                b = fitb.pop(0)
                swap_rows(s, rows, k, b)
                window_home(s)                          # (the next bench row at its place again)
                s.log.append(f'[subs] slot {k + 1}: unavailable, to the bench (row {b + 1}) (min)')
            if vis_ok(s):
                s.lineup_esc = 0
                return None
    stuck = lineup_stuck(s, err) if err else None       # (fail fast instead of ESCI again and again)
    if stuck:
        return stuck
    if err and s.screen().find('ESCI', exact=True) is not None:   # nothing more to fix: leave the squad screen
        s.log.append(f'[subs] {err}: ESCI, the season loop goes on (min)')   # (advance's stuck check still applies)
        press(s, s.screen(), 'ESCI', wait=2)
        return None
    return err


def nat_callups(s, limit=120):
    """National team squad screen ('SQUADRA DEL ...', 'SCEGLI ALTRI N GIOCATORI ...'): add players from the home
    leagues' clubs (enabled player rows = eligible) until N is 0, then ESCI. Returns an error or None."""
    taken, clubs_done = set(), set()
    for _ in range(limit):
        scr = s.screen()
        texts = scr.texts()
        s.log.append(f'[callups] {scr}')
        need = next((int(m.group(1)) for t in texts for m in [re.match(r'SCEGLI ALTRI (\d+)', t)] if m), 0)
        if any(t.startswith('SQUADRA DEL ') for t in texts):
            if need == 0:
                press(s, scr, 'ESCI') or s.send('fire dump:2')
                return None
            s.squad_title = next(t for t in texts if t.startswith('SQUADRA DEL '))
            press(s, scr, 'AGGIUNGI GIOCATORE') or s.send('fire dump:2')
        elif 'AGGIUNGI GIOCA. INTERNAZIONALE (CASA)' in texts and len(texts) <= 4:
            if not hasattr(s, 'abroad'):        # once: the abroad chooser -> the world (CARR. STORICHE) -> its
                press(s, scr, next(t for t in texts if 'FUORI CASA' in t))   # countries, then back (4.0.1: the
                direct = s.screen().find('CARR. STORICHE', exact=True) is None   # countries at once, w_buy)
                if direct or press(s, s.screen(), 'CARR. STORICHE') is not None:
                    s.abroad = s.screen().texts()
                    s.log.append(f'[abroad] {s.screen()}')
                else:
                    s.abroad = []
                for _ in range(4):              # back to the squad screen
                    t2 = s.screen().texts()
                    if any(t.startswith('SQUADRA DEL ') for t in t2) or 'AGGIUNGI GIOCATORE' in t2:
                        break
                    sc2 = s.screen()
                    i = sc2.find('ABBANDONA', exact=True)
                    if i is None:
                        i = sc2.find('ESCI', exact=True)
                    if i is None:
                        s.send('esc dump:2')
                        continue
                    for _ in range(40):         # the country list: its links do not reach ESCI, walk down
                        if s.screen().selected == i:
                            break
                        s.send('down dump:0.3')
                    s.send('fire dump:2')
                continue
            press(s, scr, 'AGGIUNGI GIOCA. INTERNAZIONALE (CASA)')
        elif 'AGGIUNGI GIOCA. INTERNAZIONALE (CASA)' in texts and any('DIVISION' in t or 'LEAGUE' in t for t in texts) \
                and 'ABBANDONA' in texts:
            s.home_leagues = texts
            first = next(i for i, t, inv, dis in scr.entries if t and not inv and t != texts[0])
            press(s, scr, first)                # the top league
        elif 'AGGIUNGI GIOCA. INTERNAZIONALE (CASA)' in texts and 'ESCI' in texts and 'CONTINUA' in [
                t for _, t, _, _ in scr.entries]:   # a club's players
            club = scr.entries[1][1]
            rows = [i for i, t, inv, dis in scr.entries if scr.geom[i][0] == 8 and scr.geom[i][2] >= 304
                    and not inv and not dis and (club, scr.geom[i][1]) not in taken]
            if not rows:
                clubs_done.add(club)
                press(s, scr, 'ESCI') or s.send('fire dump:2')
                continue
            taken.add((club, scr.geom[rows[0]][1]))
            press(s, scr, rows[0], wait=1)
        elif any(t.startswith('AGGIUNGI GIOCA.') for t in texts):   # the clubs of the league
            if not hasattr(s, 'home_clubs'):
                s.home_clubs = texts
            club = next((t for i, t, inv, dis in scr.entries if t and not inv and not dis and i > 3
                         and t not in clubs_done and t not in ('ABBANDONA', 'ESCI') and scr.geom[i][2] > 60), None)
            if club is None:
                return f'call-ups: no club left ({need} players missing)'
            press(s, scr, club)
        else:
            press(s, scr, 'ESCI') or s.send('fire dump:2')
    return 'call-ups: too many steps'


# --- 4.0.5 the GENERIC contest-name check (Davide 28/10: "va controllato anche quello e sempre") ----------------------
# Every career-menu screen in advance(): the fixture list's rows are the calendar entries from the current one
# (obj2 CAL_AT; the count word at -4, the current entry's offset at CAL_CUR_AT); each entry's slot -> its contest
# (D8CAA[slot]) -> the label CareerGameListCommon draws: [contest + 5 + contest[5] + language * 8 + 4] + STR_BASE (the
# contest's own names block; 0 = 'SCENE PRESIDENZIALI', the 4.0.5 rc1-rc6 bug). The label must be one of the names the
# build's data gives THAT contest (by its id byte: its pack competition's names, long / short / fit_short; id FEh =
# slot 4: the country's play-offs, the supercups, the Coppa D), else -- an id the data does not know (the continental
# cups, the original game's contests) -- one of every known name (logged as a fallback). Errors FAIL the scenario.
LABEL_ERRS, LABEL_STATS = [], {'rows': 0, 'keyed': 0, 'fallback': set()}
CAL_CUR_AT, D8CAA_AT, D6CDC_AT, STR_BASE_AT = 0x1B52A, 0x18DF4, 0x16E26, 0x16F8   # (obj2, every language's exe)
GLA_AT, ARR_AT = 0xB440C, 0x18E40                 # gameListArray, arrayOfPointers (CareerGameListCommon; every exe)
_WORLD_AT = {}                                    # (game dir, exe, mtime, size) -> someLeaguesTable[1845] (cf_slt)
_LABEL_DATA = {}


def _label_data():
    """{contest id: set of labels}, the slot-4 set, every name: from the World 2026-27 data (W2627REL_DATA or the
    default snapshot) and tools/supercups2627.json, all four languages."""
    key = os.environ.get('W2627REL_DATA') or ''
    if _LABEL_DATA and _LABEL_DATA.get('src') == key:   # (rc19: keyed by its data - a scenario pinning one snapshot
        return _LABEL_DATA                              # left it cached for the next ones: S1's COPPA SERIE D)
    _LABEL_DATA.clear()
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import complist
    import json as _j
    ids, slot4, every = {}, set(), set()

    def forms(names):
        out = set()
        for v in (names or {}).values():
            for x in (v if isinstance(v, list) else [v]):
                if isinstance(x, str) and x:
                    u = x.upper()
                    out |= {u, complist.fit_short(u)}
        return out

    def walk(o, acc):
        if isinstance(o, dict):
            if isinstance(o.get('names'), dict):
                acc |= forms(o['names'])
            if isinstance(o.get('title'), list):
                acc |= forms({'*': o['title']})
            for v in o.values():
                walk(v, acc)
        elif isinstance(o, list):
            for v in o:
                walk(v, acc)
    src = os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-rel40-winnames-1031')
    for d in (sorted(os.listdir(src)) if os.path.isdir(src) else []):
        pj = os.path.join(src, d, 'pack.json')
        if not os.path.isfile(pj):
            continue
        m = _j.load(open(pj))
        for c in m.get('competitions', []):
            acc = set()
            walk(c, acc)
            every |= acc
            po = set()
            walk(c.get('ko_playoffs') or [], po)
            if any(isinstance(k, dict) and k.get('kind') == 'stage_title' for k in c.get('ko_playoffs') or []):
                for dv in c.get('divisions') or []:     # (a stage's final in slot 4 shows the stage's title: URU
                    for st in ((dv.get('split') or {}).get('stages') or []):   # INTERMEDIO, rc18 bench_cup)
                        if isinstance(st.get('title'), dict):
                            po |= forms(st['title'])
            slot4 |= po
            if c.get('id'):
                try:
                    ids.setdefault(int(str(c['id']), 16), set()).update(acc)
                except ValueError:
                    pass
    sc = _j.load(open(os.path.join(ROOT, 'tools', 'supercups2627.json')))
    for k, v in sc.items():
        if not k.startswith('_'):
            slot4 |= forms(v.get('names'))
    every |= slot4
    _LABEL_DATA.update(ids=ids, slot4=slot4, every=every, src=key)
    return _LABEL_DATA


def label_check(s, step):
    """The fixture list's competition labels of this career-menu screen (see LABEL_ERRS); errors go to LABEL_ERRS.
    The rows are the ones CareerGameListCommon draws: gameListArray (obj2 GLA_AT, 14 x (calendar entry, game) pointers, filled
    by cseg_3563E), not every calendar entry (rc7 gate: entries past the drawn rows hold contests not set up yet). The
    contest ids are World 2026-27's only in its careers (world byte 5); other worlds check the label offset only."""
    try:
        r = s.result
        b2 = r.base2
        div = struct.unpack('<H', bytes(r.obj2(D6CDC_AT, 2)))[0]
        if div > 15:
            return
        gla = struct.unpack('<28I', bytes(r.obj2(GLA_AT, 112)))
        ptrs = struct.unpack('<5I', bytes(r.obj2(D8CAA_AT, 20)))
        bufs = struct.unpack('<5I', bytes(r.obj2(ARR_AT, 20)))
        exe = next((os.path.join(r.game, x) for x in ('ITALIAN.EXE', 'ENGLISH.EXE', 'FRENCH.EXE', 'GERMAN.EXE')
                    if os.path.isfile(os.path.join(r.game, x))), None)
        key = (r.game, exe, os.path.getmtime(exe), os.path.getsize(exe)) if exe else (r.game,)   # (not the dir alone:
        if key not in _WORLD_AT:                        # release_groupb_titles' families share one run dir with
            try:                                        # different exes - mlt_title read gb_force3's address)
                _WORLD_AT[key] = cf_slt_exe(exe) + 1845 if exe else None
            except Exception:
                _WORLD_AT[key] = None
        world = r.obj2(_WORLD_AT[key], 1)[0] if _WORLD_AT[key] is not None else -1
        data = _label_data()
    except Exception:                                   # (no career calendar on this screen)
        return
    for k in range(14):
        cp = gla[2 * k]                                 # (a calendar entry: [0] = its slot; gla[2k + 1] = the game)
        if not cp:
            break
        try:
            slot = r.read(cp, 1)[0]
            if slot > 4 or not ptrs[slot] or not bufs[slot]:
                continue
            typ = struct.unpack('<H', bytes(r.read(bufs[slot], 2)))[0]
            c = bytes(r.read(ptrs[slot], 0x80))
            if not c[5]:                                # (no names block: the game's generic LEAGUE / CUP text)
                LABEL_STATS['fallback'].add(f'generic slot {slot}')
                continue
            no = 5 + c[5] + (div * 8 if typ == 0 else 0)  # (a league: its division's name - dseg_D6CDC; else one)
            if no + 8 > len(c):
                continue
            rel = struct.unpack_from('<I', c, no + 4)[0]
            txt = bytes(r.read(b2 + STR_BASE_AT + rel, 40)).split(b'\0')[0].decode('latin-1').upper() if rel < 0x100000 else '?'
        except Exception:
            continue
        cid = c[0]
        LABEL_STATS['rows'] += 1
        if slot == 4:                                   # (4.0.5 NZ: the Grand Final's row - byte 5 = 0 while undecided)
            try:
                e = bytes(r.read(cp, 16))
                cur = struct.unpack('<H', bytes(r.obj2(CAL_CUR_AT, 2)))[0]
                cw = r.obj2(CAL_AT + cur + 1, 1)[0]
                s.log.append(f'[slot4row] step {step} week {e[1]} plays {e[5]} cur {cw} teams '
                             f'{struct.unpack_from("<H", e, 12)[0]:x} {struct.unpack_from("<H", e, 14)[0]:x} {txt}')
            except Exception:
                pass
        bad = None
        if rel == 0 or txt == '?':
            bad = f'label offset {rel:X} ({txt})'
        elif world != 5:                                # (-1: a build without cupsf - no World 2026-27)
            LABEL_STATS['fallback'].add(f'w{world}:{cid:02X}:{txt}')
        elif cid == 0xFE:
            LABEL_STATS['keyed'] += 1
            if txt not in data['slot4'] and txt not in data['every']:
                bad = f'not a slot-4 contest name'
        elif cid in data['ids']:
            LABEL_STATS['keyed'] += 1
            if txt not in data['ids'][cid]:
                bad = f'not contest {cid:02X}\'s name (it has {sorted(data["ids"][cid])[:4]})'
        else:
            LABEL_STATS['fallback'].add(f'{cid:02X}:{txt}')
        if os.environ.get('SWOSTEST_LABELDBG'):
            s.log.append(f'[labeldbg] step {step} row {k} w{world} slot {slot} type {typ} contest {cid:02X} rel {rel:X} {txt!r}')
        if bad:
            e = f'step {step} row {k} contest {cid:02X} {txt!r}: {bad}'
            if e not in LABEL_ERRS:
                LABEL_ERRS.append(e)
                s.log.append('[label] ' + e)


def advance(s, stop, max_steps=400):
    """Press through the career until stop(screen) is true; returns (ok, message)."""
    recent = []
    for step in range(max_steps):
        r = s.result
        if r.outcome != 'dump':
            return False, f'step {step}: {r}'
        scr = s.screen()
        s.log.append(f'[{step}] {scr}')
        if os.environ.get('SWOSTEST_LABELS', '1') == '1' and scr.find('VISUAL. COMPETIZ.', exact=True) is not None:
            label_check(s, step)                         # (4.0.5: every competition name of the fixture list)
        if os.environ.get('GP_CALTRACE'):              # (debug: the calendar from the cursor - slot week b4 b5 b6)
            try:
                cur = struct.unpack('<H', bytes(r.obj2(CAL_CUR_AT, 2)))[0]
                cb = bytes(r.obj2(CAL_AT + cur, 64))
                o, out = 0, []
                while o + 8 <= len(cb) and len(out) < 4:
                    out.append(f'{cb[o]}/{cb[o+1]}/{cb[o+4]}/{cb[o+5]}/{cb[o+6]}')
                    ln = struct.unpack_from('<H', cb, o + 2)[0]
                    if not ln:
                        break
                    o += ln
                s.log.append(f'[calt] {step} cur {cur:x} ' + ' '.join(out))
            except Exception:
                pass
        if os.environ.get('W8485_CALDUMP') and not getattr(s, 'cald_done', 0) and \
                scr.find('VISUAL. COMPETIZ.', exact=True) is not None:   # (4.0.5: the career calendar, once a season)
            s.log.append(f'CALD {step} {bytes(s.result.obj2(CAL_AT - 4, 0x2000)).hex()}')
            s.cald_done = 1
        dw = os.environ.get('W8485_DIYWORD')             # (4.0.5: word:obj2 at:len - the first screen of a season
        if dw and scr.entries and not getattr(s, 'diyw_done', 0) and dw.split(':')[0] in scr.entries[0][1]:   # titled
            w_, a_, n_ = dw.split(':')                   # with that word: those bytes, e.g. the working DIY)
            s.log.append(f'DIYW {step} {bytes(s.result.obj2(int(a_, 16), int(n_, 16))).hex()}')
            s.diyw_done = 1
        if os.environ.get('W8485_SHOTWORD') and scr.entries and os.environ['W8485_SHOTWORD'] in scr.entries[0][1]:
            s.shot(f'word{step:03d}')                    # (the visual tour: every screen titled with that word)
        if os.environ.get('SWOSTEST_FILL') and fill_check(s, f'step {step}') is False and not getattr(s, 'fill_bad', 0):
            s.fill_bad = 1                               # (investigation: the menu texture at every step; the first
            s.log.append(f'[fill] FIRST CHANGE at step {step}, after: {recent[-1] if recent else "-"}')   # change)
        if not getattr(s, 'inmatch', False) or scr.entries:
            recent.append(str(scr))                      # stuck: the last 16 screens are 1 or 2 alternating ones
        rp_ = os.environ.get('W8485_REALPLAY')
        if getattr(s, 'inmatch', False) and rp_ and scr.entries and scr.entries[0][2] and rp_ in scr.entries[0][1]:
            s.send('fire dump:2')                        # (4.0.5: a final's line-ups before the kick-off, its title
            continue                                     #  inverted: still the match - goal_slot_sc_real)
        if scr.entries:
            s.inmatch = False
        if len(recent) >= 16 and len(set(recent[-16:])) <= 2:
            return False, f'step {step}: stuck on {" / ".join(sorted(set(recent[-16:])))[:300]}'
        if stop(scr):
            return True, f'{step} steps'
        texts = scr.texts()
        rp = os.environ.get('W8485_REALPLAY')            # (4.0.5 NZ GF, rc17: the matches of fixture screens titled
        if rp and scr.entries and rp in scr.entries[0][1]:   # with that word played for real, as Davide on the MiSTer
            i_ = scr.find('- PARTITA -', exact=True)    #  - the exe needs nop_league_int3)
            s.rpseen = getattr(s, 'rpseen', 0) + (i_ is not None and not scr.entries[i_][2])
            if i_ is not None and not scr.entries[i_][2] and s.rpseen > int(os.environ.get('W8485_REALSKIP', 0)):
                s.realplay = True
                s.log.append(f'[realplay] step {step}: {scr.entries[0][1]}')
                press(s, scr, '- PARTITA -') or s.send('fire dump:2')
                continue
        if getattr(s, 'inmatch', False) and not scr.entries:   # (the match: bench_world's pace - 3 fires a pause)
            if step % 25 == 0:
                s.shot(f'rp{step:03d}')
            s.send('fire:3 ' * 3 + 'dump:1')
            continue
        if getattr(s, 'realplay', False) and 'MOD. TATTICA' in texts and ('GIOCA PARTITA' in texts or 'PARTITA' in texts):
            s.realplay = False
            s.inmatch = True
            s.log.append(f'[realplay] step {step}: kick-off')
            press(s, scr, 'GIOCA PARTITA' if 'GIOCA PARTITA' in texts else 'PARTITA') or s.send('fire dump:2')
            continue
        if 'VIS. RISULTATI' in texts and 'MOD. TATTICA' in texts and (getattr(s, 'subs', None) or
                                                                     getattr(s, 'gk_swap', False)):
            err = substitute(s, scr)                     # stand-ins in the 16: bring fit starters back first
            if err:
                return False, f'step {step}: {err}'
            press(s, s.screen(), 'VIS. RISULTATI') or s.send('fire dump:2')
        elif 'VIS. RISULTATI' in texts:
            press(s, scr, 'VIS. RISULTATI') or s.send('fire dump:2')
        elif 'AMICHEVOLE' in texts and 'CONTINUA CARRIERA' in texts:     # main menu (after a save)
            press(s, scr, 'CONTINUA CARRIERA') or s.send('fire dump:2')
        elif 'MOD. TATTICA' in texts and 'AVVERSARI' in texts:          # squad screen without VIS. RISULTATI
            err = substitute(s, scr)
            if err:
                return False, f'step {step}: {err}'
        elif any(t.startswith('SQUADRA DEL ') for t in texts) and 'ESCI' in texts:   # national call-ups
            err = nat_callups(s)
            if err:
                return False, f'step {step}: {err}'
        elif 'SCEGLI SQUADRA' in texts and 'VISUALIZZA MONDO' in texts and \
                scr.entries[scr.find('PARTITA', exact=True)][3]:   # national team menu: squad first
            press(s, scr, 'SCEGLI SQUADRA') or s.send('fire dump:2')
        elif ('TRASFERIMENTI' in texts or 'VISUALIZZA MONDO' in texts) and 'PARTITA' in texts:
            press(s, scr, 'PARTITA') or s.send('fire dump:2')
        elif '- RISULTATO -' in texts:                   # cup round screen: -> squad screen
            press(s, scr, '- RISULTATO -') or s.send('fire dump:2')
        elif 'ESCI' in texts:
            press(s, scr, 'ESCI') or s.send('fire dump:2')
        else:
            s.send('fire dump:2')                        # message screens
    return False, f'no stop after {max_steps} steps'


CAR_FIXED = 95151                   # .CAR: fixed part (careerFileBuffer ..), then N cached teams + trailer
SLT = 59612                           # someLeaguesTable in the save (world byte [1845], balance [1846])
CUPS = {'CC': 71464, 'CWC': 71543, 'UEFA': 71635}   # euroCupCopy (79 B) / cupWinnersCupCopy / uefaCupCopy (92 B)


def car_info(path):
    """A few .CAR facts for the oracles."""
    d = open(path, 'rb').read()
    n = struct.unpack_from('<H', d, CAR_FIXED)[0]
    t = CAR_FIXED + 2 + n * 684
    tab = d[SLT:SLT + 2000]
    out = {'size': len(d), 'teams': n, 'trailer': d[t:t + 2], 'world': tab[1845], 'sum': sum(tab) % 256}
    for name, off in CUPS.items():
        c = d[off:off + (79 if name == 'CC' else 92)]
        n = 16 if name == 'CC' else c[10]
        lst = c[c[7] + 7:c[7] + 7 + 2 * n]
        out[name] = [(lst[i], lst[i + 1]) for i in range(0, len(lst), 2)]
    return out


# Key scripts. Waits: ':s' before the key, in menu frames (RATE per s). After a screen change wait >= 1 s: the new
# menu drops a key typed while it initialises. After a career load the first fire is always ignored (deterministic).
LOAD1 = 'down:3 down down down down fire fire:2'          # main menu -> CARICA VECCHIA COMP. -> first save -> career
FINISH = 'fire:2'                                 # career menu: FINISCI STAGIONE -> season-end menu


def name_entry(name):
    """Save screen (cursor on SALVA): NOME FILE field, clear it, type name, Enter (= save). The French exe reads the
    keys as AZERTY (a <-> q, w <-> z: 'w84a' was saved as Z84Q; m is the QWERTY ';' key), the German one as QWERTZ
    (y <-> z)."""
    lay = {'fr': {'a': 'q', 'q': 'a', 'w': 'z', 'z': 'w', 'm': 'semicolon'}, 'de': {'y': 'z', 'z': 'y'}}.get(UI, {})
    return 'up:2 fire:1 ' + 'bspace ' * 8 + ' '.join(lay.get(c, c) for c in name.lower()) + ' enter:1'


def save_as(name):
    """Season-end menu (cursor on OFFERTE LAVORO) -> SALVA CARRIERA -> name."""
    return 'down:3 down fire:1 ' + name_entry(name)


def quit_and_save(name):
    """Career menu (cursor on FINISCI STAGIONE) -> ESCI -> main menu SALVA CARRIERA -> name."""
    return 'down:2 down fire:2 down:2 down down down up fire:2 ' + name_entry(name)


def check(cond, msg, errs):
    if not cond:
        errs.append(msg)


def season_case(name, build, car, out, timeout=120, extra=None):
    """Load `car`, FINISCI STAGIONE, save as `out`, 'dump'; common oracles + extra(info, errs)."""
    r = run_case(name, build, {os.path.basename(car).upper(): car}, f'{LOAD1} {FINISH} {save_as(out)} dump:3',
                 timeout)
    errs = []
    path = os.path.join(r.game, out + '.CAR')
    check(r.outcome == 'dump', f'run ended with {r}', errs)
    if os.path.exists(path):
        info = car_info(path)
        check(info['sum'] == 0, f"someLeaguesTable sum {info['sum']} != 0", errs)
        if extra:
            extra(info, errs, path)
    else:
        errs.append(f'{out}.CAR not written')
    return not errs, f"{r}; {'; '.join(errs) or 'ok'}"


SCENARIOS = {}


def scenario(fn):
    SCENARIOS[fn.__name__] = fn
    return fn


def rel_data_default():
    """W2627REL_DATA unset + SWOSTEST_BUILD a release dir (c/RELxx/SWOS, buildrel.sh): the snapshot that release was built
    with, from its build.log ('RELxx = <sha>, data <name>, ...'), as the gate sets it - so the label checks and the
    release-data builds never silently use the old default snapshots (Dati coppe 30/10: world_gplay_nzchamp)."""
    rb = os.environ.get('SWOSTEST_BUILD') or os.environ.get('W8485_BUILD')   # (W8485_BUILD alone: the sweep's careers -
    if os.environ.get('W2627REL_DATA') or not rb:                          # MEX 'APERTU. 2026' checked on old data)
        return
    log = os.path.join(os.path.dirname(os.path.abspath(rb)), 'build.log')
    m = re.search(r'^\S+ = \w+, data (\S+?),', open(log, errors='replace').read(), re.M) if os.path.isfile(log) else None
    d = m and os.path.join(MAIN, 'internal', 'world2526', m.group(1))
    if d and os.path.isfile(d + '.txt'):
        os.environ['W2627REL_DATA'] = d
        print(f'W2627REL_DATA = {d} (the data of {os.path.dirname(log)}, from its build.log)', flush=True)


def builds():
    """Exe under test: SWOSTEST_BUILD (a ready dir with ITALIAN.EXE + DATA), else built from SWOSTEST_BRANCH (a git
    branch/commit), else from this checkout."""
    if not hasattr(builds, 'cache'):
        br = os.environ.get('SWOSTEST_BRANCH')
        tag = '_' + os.environ['SWOSTEST_TAG'] if os.environ.get('SWOSTEST_TAG') else ''   # (parallel sessions: their own
        builds.cache = {'it': os.environ.get('SWOSTEST_BUILD') or     # build dir, not a shared builds/it overwritten
                        build((re.sub(r'\W', '_', br) if br else 'it') + tag, branch=br)}   # under a running suite)
    return builds.cache


POKE_SYNC = 8                                         # Session.poke: SMs between sync reads
POKE_MAX = 0x4000                                     # Session.poke: bytes in one call
SAVES = os.path.join(MAIN, 'c', 'SWOS')               # read-only source of the reference saves (copied per run)


def juve2(fixed):
    """c/SWOS/JUVE2.CAR (Juventus 1997/98 at FINISCI STAGIONE, CC holder: Intercontinental + CWC), copied; fixed =
    byte 0x173A3 (E092F, the slot-3 cup id saved wrong by the pre-2b96905 euro_found) set to 0 like JUVEFIX."""
    d = bytearray(open(os.path.join(SAVES, 'JUVE2.CAR'), 'rb').read())
    if fixed:
        d[0x173A3] = 0
    path = os.path.join(WORK, 'saves', 'JUVE2F.CAR' if fixed else 'JUVE2.CAR')
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = f'{path}.{os.getpid()}'
    open(tmp, 'wb').write(d)
    os.replace(tmp, path)                              # parallel runs: never a half-written save
    return path


@scenario
def italy_season():
    """Juventus 1997/98 season end (JUVE2 with E092F fixed): no trap, save; next CC: 16 distinct, Italian clubs in"""
    def cc(info, errs, path):
        lst = info['CC']
        check(len(set(lst)) == 16, f'CC: {len(set(lst))} distinct clubs {lst}', errs)
        check(sum(f == 20 for f, o in lst) >= 1, 'CC: no Italian club', errs)
        check(info['trailer'] == b'C7', f"trailer {info['trailer']!r}", errs)
    return season_case('italy_season', builds()['it'], juve2(True), 'T1', extra=cc)


def two_saves(name, exe_dir, src, timeout=120):
    """Load src, save it from the main menu (X1), reload X1, save again (X2); returns (error or None, X1, X2)."""
    files = []
    for k in (1, 2):
        cur = src if k == 1 else files[-1]
        out = re.sub(r'[^A-Z0-9]', '', name.upper())[:6] + str(k)
        r = run_case(f'{name}_{k}', exe_dir, {os.path.basename(cur).upper(): cur},
                     f'{LOAD1} {quit_and_save(out)} dump:3', timeout)
        path = os.path.join(r.game, out + '.CAR')
        if r.outcome != 'dump' or not os.path.exists(path):
            return f'save {k}: {r}; written: {os.path.exists(path)}', None, None
        files.append(path)
    return None, files[0], files[1]


def ndiff(a, b):
    a, b = open(a, 'rb').read(), open(b, 'rb').read()
    return sum(x != y for x, y in zip(a, b)) + abs(len(a) - len(b))


def fill_lin_off():
    """obj2 offset of linAdr384k (LoadFillAndSwtitle's `mov eax, [linAdr384k]; add eax, 65536; mov [A1], eax`) in the
    exe language's original: the menu texture FILL.256 is at [linAdr384k] + 65536."""
    if not hasattr(fill_lin_off, 'off'):
        sys.path.insert(0, os.path.join(ROOT, 'tools'))
        from le import LE
        import sacups
        d1 = LE(open(os.path.join(ROOT, 'orig', UI_ORIG), 'rb').read()).obj_bytes(1)
        a1 = struct.pack('<I', sacups.regs(d1)['A0'] + 4)
        offs = {struct.unpack('<I', m.group(1))[0] for m in
                re.finditer(rb'\xa1(.{4})\x05\x00\x00\x01\x00\xa3' + re.escape(a1), d1, re.S)}
        assert len(offs) == 1, offs
        fill_lin_off.off = offs.pop()
    return fill_lin_off.off


def bplm_lin(r, off):
    """A SWOSTEST_BPLM entry's linear address: an obj2 offset (hex), or 'fill+<hex>' = a byte of the menu texture
    (FILL.256 at [linAdr384k] + 65536; 4.0.1, the job-offer letter's stray pixels)."""
    if off.startswith('lin:'):                      # (an absolute linear address)
        return int(off[4:], 16)
    if off.startswith('fill+'):
        return struct.unpack('<I', r.obj2(fill_lin_off(), 4))[0] + 65536 + int(off[5:], 16)
    return r.base2 + int(off, 16)


def fill_check(s, tag):
    """The menu buttons' texture: FILL.256 lives at linAdr384k + 65536 (64000 pixels) while the menus run; a match draws
    its virtual pitch over the whole 384k buffer, and GameLoop / highlights / animations reload it (LoadFillAndSwtitle)
    before the menus come back. Compares that memory with the game folder's FILL.256 and logs '[fill] <tag>: intact' or
    'CHANGED' (differing 16-byte blocks, the first one's byte offset). The address of linAdr384k: LoadFillAndSwtitle's `mov eax,
    [linAdr384k]; add eax, 65536; mov [A1], eax`. Returns True when intact (None if it could not be read)."""
    try:
        exe = os.path.join(ROOT, 'orig', UI_ORIG)
        if getattr(fill_check, 'exe', None) != exe:       # (the original of the exe under test: its linAdr384k)
            fill_check.exe = exe
            sys.path.insert(0, os.path.join(ROOT, 'tools'))
            from le import LE
            import sacups
            d1 = LE(open(exe, 'rb').read()).obj_bytes(1)
            a1 = struct.pack('<I', sacups.regs(d1)['A0'] + 4)
            offs = {struct.unpack('<I', m.group(1))[0] for m in
                    re.finditer(rb'\xa1(.{4})\x05\x00\x00\x01\x00\xa3' + re.escape(a1), d1, re.S)}
            assert len(offs) == 1, offs
            fill_check.off = offs.pop()
            fill_check.ref = open(os.path.join(s.run, 'SWOS', 'FILL.256'), 'rb').read()[:64000]
        lin = struct.unpack('<I', s.result.obj2(fill_check.off, 4))[0] + 65536
        mem = s.result.read(lin, 64000)
        diff = [i for i in range(0, 64000, 16) if mem[i:i + 16] != fill_check.ref[i:i + 16]]
        s.log.append(f'[fill] {tag}: ' + ('intact' if not diff else
                                          f'CHANGED ({len(diff)} of 4000 blocks, first +{diff[0]:#x})'))
        return not diff
    except Exception as e:                           # never let the check break a run
        s.log.append(f'[fill] {tag}: check failed {e}')
        return None


def menu_check(s, tag):
    """Main menu after a career (Davide, 2026-10-16: once its buttons showed an in-match frame instead of their
    FILL.256 texture): screenshot it and compare the MOD. TATTICA button with the game's gradient (a smooth dark
    blue left to right). A corrupted texture is noted in the session log as '[menu] CORRUPTED'. 4.0 (regia): the
    FILL.256 texture in memory changed = garbage graphics (it matched every corrupted season-end frame of 19/10: the
    30-club tables drawn past the screen) -> returns an error, the scenario FAILs."""
    try:
        from PIL import Image
        s.shot('menu_' + tag)
        path = os.path.join(s.run, 'shots', 'menu_' + tag + '.png')
        im = Image.open(path).convert('RGB')
        w, h = im.size
        top = h - w * 400 // 640
        y = int(top + 92 * (h - top) / 200)              # the button's middle row (game y 92), x 22..150
        row = [im.getpixel((int(x * w / 320), y)) for x in range(22, 150, 2)]
        jumps = sum(abs(a[0] - b[0]) + abs(a[1] - b[1]) + abs(a[2] - b[2]) > 60 for a, b in zip(row, row[1:]))
        if UI != 'it':                                 # (another language's menu: other buttons on that row, flat
            s.log.append(f'[menu] {tag}: ({jumps} jumps, not judged: {UI} layout)')   # fills: FILL.256 decides)
        else:
            s.log.append(f'[menu] {tag}: ' + ('CORRUPTED' if jumps > 20 else 'clean') + f' ({jumps} jumps)')
        if fill_check(s, tag) is False:
            return f'{tag}: the menu graphics are corrupted (FILL.256 texture changed in memory; frame menu_{tag}.png)'
    except Exception as e:                           # never let the check break a run
        s.log.append(f'[menu] {tag}: check failed {e}')


def rec_shot(s):
    """W8485_RECSHOT=1: on the season-end menu ('<year> FINE CAMP.'), once, the season record (ManagementRecordMenu:
    VISUAL. COMPETIZ. -> REGISTRO GESTIONE, EN MANAGEMENT RECORD): its texts logged '[record] ...', a shot 'record', back with
    ESCI twice. True if it was shown."""
    scr = s.screen()
    if os.environ.get('W8485_RECSHOT') != '1' or s.__dict__.get('rec_done') or \
            not any(t.endswith('FINE CAMP.') for t in scr.texts()):
        return False
    s.rec_done = True
    def watch(tag):                                    # (debug W8485_RECWATCH: the record's line pointers / codes)
        if os.environ.get('W8485_RECWATCH'):
            o = int(os.environ['W8485_RECWATCH'], 16)
            s.log.append(f"[rec] {tag} {s.result.obj2(o + 22, 16).hex()} {s.result.obj2(o + 86, 4).hex()}")
        if os.environ.get('W8485_RLDBG'):              # (debug: gp_rlines_c's GP_RLN / GP_RLC / GP_REC, SC_ST's header)
            rln, rlc, rec, scs = (int(x, 16) for x in os.environ['W8485_RLDBG'].split(','))
            s.log.append(f"[rl] {tag} {s.result.obj2(rln, 16).hex()} {s.result.obj2(rlc, 4).hex()} "
                         f"{s.result.obj2(rec, 4).hex()} {s.result.obj2(scs, 12).hex()}")
            rv = struct.unpack('<I', s.result.obj2(rec, 4))[0]
            if rv:
                s.log.append(f"[rl] {tag} rec {s.result.read(rv, 106).hex()}")
    watch('before')
    try:
        if press(s, scr, 'VISUAL. COMPETIZ.', wait=3) is None:
            s.log.append(f'[record] not reached: {scr}')
            return False
        watch('viscomp')
        vc = s.screen()
        lab = next((x for x in ('REGISTRO GESTIONE', 'MANAGEMENT RECORD') if vc.find(x, exact=True) is not None), None)
        if lab is None or press(s, vc, lab, wait=3) is None:
            s.log.append(f'[record] not reached: {vc}')
            press(s, s.screen(), 'ESCI', wait=2)
            return True
    except AssertionError as e:                    # (no path: logged, the season goes on)
        s.log.append(f'[record] not reached: {e}')
        return False
    s.send('dump:1')
    watch('record')
    s.log.append('[record] ' + ' | '.join(x for _, x, inv, _ in s.screen().entries if x and not inv))
    s.shot('record')
    for k in range(2):
        press(s, s.screen(), 'ESCI', wait=2) or s.send('fire dump:2')
        watch(f'esci{k}')
    return True


def next_season_save(s, name):
    """Season-end menu -> CONTINUA CARRIERA -> (messages) -> new season's career menu -> ESCI -> SALVA CARRIERA -> name.
    Returns the save path or an error string."""
    for _ in range(8):                                 # sacked: CONTINUA CARRIERA is disabled -> take a job offer
        scr = s.screen()
        i = scr.find('CONTINUA CARRIERA', exact=True)
        if i is not None and not scr.entries[i][3]:
            break
        s.log.append(f'[job] {scr}')
        if os.environ.get('W8485_FILLWATCH'):
            fill_check(s, 'job ' + (scr.entries[0][1] if scr.entries else ''))
        if scr.find('ACCETTA', exact=True) is not None:      # the offer letter: accept it
            press(s, scr, 'ACCETTA', wait=3)
            continue
        rows = [j for j, g in enumerate(scr.geom) if g[0] == 8 and g[2] == 304 and not scr.entries[j][2]
                and not scr.entries[j][3]]             # the offers screen: one selectable row per offer
        if scr.find('OFF. LAVORO DA') is not None and rows:
            for _ in range(12):
                if s.screen().selected in rows:
                    break
                s.send('up dump:0.5')
            s.send('fire dump:2')                      # take the selected offer
        elif scr.find('OFFERTE LAVORO', exact=True) is not None and i is not None:
            press(s, scr, 'OFFERTE LAVORO')
        else:
            press(s, scr, 'ESCI') or s.send('fire dump:2')
        if s.result.outcome != 'dump':
            return f'job offer: {s.result}'
    rec_shot(s)
    if os.environ.get('W8485_FILLWATCH'):
        fill_check(s, 'before CONTINUA CARRIERA')
    if press(s, s.screen(), 'CONTINUA CARRIERA', wait=3) is None:
        return f'no CONTINUA CARRIERA on {s.screen()}'
    for _ in range(20):                                # chairman's note, job offers ...: CONTINUA / fire
        if s.result.outcome != 'dump':
            return f'new season: {s.result}'
        scr = s.screen()
        s.log.append(f'[ns] {scr}')
        if os.environ.get('W8485_NSDUMP'):             # (debug: D8CAA[0..4] slot pointers + each slot's +2Dh / +39h)
            o = int(os.environ['W8485_NSDUMP'], 16)
            ptrs = struct.unpack('<5I', bytes(s.result.obj2(o, 20)))
            info = []
            for k_, lin in enumerate(ptrs):
                if lin and lin < 0x10000000:
                    b_ = bytes(s.result.read(lin, 0x40))
                    info.append(f'{k_}:{lin:#x} id {b_[0x2D]:#04x} +39 {b_[0x39]:#04x} t {b_[0]:#04x}')
                else:
                    info.append(f'{k_}:{lin:#x}')
            s.log.append('[nsd] ' + ' | '.join(info))
        if os.environ.get('W8485_FILLWATCH'):
            fill_check(s, 'ns ' + (scr.entries[0][1] if scr.entries else ''))
        if os.environ.get('W8485_RECWATCH'):           # (debug: the season record's line pointers / codes each step)
            o = int(os.environ['W8485_RECWATCH'], 16)
            s.log.append(f"[rec] {s.result.obj2(o + 22, 16).hex()} {s.result.obj2(o + 86, 4).hex()}")
        if any(t.endswith('FINE CAMP.') for t in scr.texts()) and rec_shot(s):
            continue
        if 'TRASFERIMENTI' in scr.texts() or 'VISUALIZZA MONDO' in scr.texts():    # club / national team menu
            break
        if any(t.startswith('SQUADRA DEL ') for t in scr.texts()):    # national squad call-ups
            err = nat_callups(s)
            if err:
                return err
            continue
        if ('AVVERSARI' in scr.texts() or 'VIS. SQUADRA' in scr.texts()) and 'ESCI' in scr.texts() and \
                any(t == 'GIOCA :' and inv for _, t, inv, _ in scr.entries):   # a match card with GIOCA off (a
            press(s, scr, 'ESCI', wait=3)                                      # fixture shown at the new season's
            continue                                                           # start): ESCI
        press(s, scr, 'CONTINUA') or s.send('fire dump:2')
    else:
        return 'career menu of the new season not reached'
    press(s, s.screen(), 'ESCI', wait=3)
    err = menu_check(s, 'season_end')            # the main menu after a career: corrupted buttons? (Davide)
    if err:
        return err
    if press(s, s.screen(), 'SALVA CARRIERA') is None:
        return f'no SALVA CARRIERA on {s.screen()}'
    s.send(name_entry(name) + ' dump:3')
    path = os.path.join(s.run, 'SWOS', name + '.CAR')
    return path if os.path.exists(path) else f'{name}.CAR not written ({s.result})'


@scenario
def italy_advance():
    """JUVEFIX3 (Juventus 1998/99 mid-season): results-only loop with substitutions to FINISCI STAGIONE, new season,
    save; next CC list: 16 distinct clubs incl. the Italian champion"""
    car = os.path.join(SAVES, 'JUVEFIX3.CAR')
    with Session('italy_advance', builds()['it'], {'JUVEFIX3.CAR': car}, 'dump:2', 180) as s:
        if s.wait().outcome != 'dump':
            return False, f'START: no first pause ({s.result})'
        s.send('down down down down down fire dump:2')
        s.send('fire dump:2')
        s.poke(s.result.base2 + nosack_off(os.path.join(builds()['it'], 'ITALIAN.EXE')), b'\x01\x00')   # 4.0.6: the
        ok, msg = advance(s, lambda scr: scr.find('FINISCI STAGIONE', exact=True) is not None)   # chairman never sacks
        # (finance's income moves the results' RNG: a sack by the league position is not what this case checks)
        if not ok:
            return False, 'advance: ' + msg
        press(s, s.screen(), 'FINISCI STAGIONE', wait=3)
        if s.result.outcome != 'dump':
            return False, f'FINISCI STAGIONE: {s.result}'
        path = next_season_save(s, 'ADV1')
        if not path.endswith('.CAR'):
            return False, f'{msg}; {path}'
    info, errs = car_info(path), []
    lst = info['CC']
    check(info['sum'] == 0 and info['trailer'] == b'C7', f"sum {info['sum']}, trailer {info['trailer']!r}", errs)
    check(len(set(lst)) == 16, f'CC: {len(set(lst))} distinct {lst}', errs)
    check(any(f == 20 for f, o in lst), 'CC: no Italian club', errs)
    return not errs, f"{msg}; {'; '.join(errs) or 'ok'}; next CC {sorted(lst)} (Juventus 20,32 {'in' if (20, 32) in lst else 'out'})"


SLOT = 0x1A22C            # player's European slot buffer dseg_DA0E2 (DIY layout), IT obj2 offset in a0f38ad5 builds
HOLDERS = 0xC058B         # CC / CWC / UEFA holder team numbers (words, FFFF none), set at the season end, not saved


W84_HOOK = None           # world8485: f(session, season, screen) at every step (set by a scenario, then reset)


AG_STORE = 0x18F08        # obj1: after cseg_28E76's 'mov [esi], al' (DIY+89h+tie = cseg_2AE97's D7; IT exe)
AG_A3 = 0x315E3           # obj2: A3 (cseg_28E76 points it at DIY_competitionStart)


def slot_scores(d):
    """A contest struct's current round (squads session's layout, cseg_28E76 / cseg_2AE97): id, round, ties, legs,
    leg flag, away rule, per tie (team a, team b, flags +89h, this leg's score +C9h, the first leg's +14Dh)."""
    w = lambda o: struct.unpack_from('<H', d, o)[0]
    team = lambda i: w(0x24D + 2 * i)
    n = w(0x51)
    ties = [(team(d[0x2CD + 2 * k]), team(d[0x2CD + 2 * k + 1]), d[0x89 + k], w(0xC9 + 2 * k), w(0x14D + 2 * k))
            for k in range(min(n, 64))]
    return dict(id=d[0x2D], round=w(0x57), n=n, legs=w(0x14B), leg2=w(0x149), away=w(0x5D), ties=ties)


def slot_ties(r, n):
    """(round index, contest id, [(country a, country b)] of the first n ties) from the player's European slot."""
    d = r.obj2(SLOT, 0x443)
    team = lambda i: struct.unpack_from('<H', d, 0x24D + 2 * i)[0]
    ties = [(team(d[0x2CD + 2 * k]) & 0xFF, team(d[0x2CD + 2 * k + 1]) & 0xFF) for k in range(n)]
    return struct.unpack_from('<H', d, 0x57)[0], d[0x2D], ties


@scenario
def euro_draws():
    """JUVE2F 1997/98 end -> 1998/99: CC holder rule (next CC list) and no same-country ties in rounds 1-2 of the
    player's CWC/UEFA (euro9697-nodorby; obj2 offsets of build a0f38ad5)"""
    with Session('euro_draws', builds()['it'], {'JUVE2F.CAR': juve2(True)}, 'dump:2', 180) as s:
        if s.wait().outcome != 'dump':
            return False, f'START: no first pause ({s.result})'
        s.send('down down down down down fire dump:2')
        s.send('fire dump:2')
        press(s, s.screen(), 'FINISCI STAGIONE', wait=3)
        if s.result.outcome != 'dump':
            return False, f'FINISCI STAGIONE: {s.result}'
        holders = struct.unpack_from('<3H', s.result.obj2(HOLDERS, 6))
        path = next_season_save(s, 'EUR1')
        if not path.endswith('.CAR'):
            return False, path
        if holders[0] in (0, 0xFFFF):                  # not set at the season-end menu: read again in the new season
            holders = struct.unpack_from('<3H', s.result.obj2(HOLDERS, 6))
        errs, notes = [], [f'holders CC/CWC/UEFA {[hex(h) for h in holders]}']
        lst = car_info(path)['CC']
        cc = holders[0]
        check(len(set(lst)) == 16, f'CC: {len(set(lst))} distinct', errs)
        if cc != 0xFFFF:
            check((cc & 0xFF, cc >> 8) in lst, f'CC holder {cc & 0xFF},{cc >> 8} not in the new CC list', errs)
            notes.append(f'holder country {cc & 0xFF} x{sum(f == cc & 0xFF for f, o in lst)} in the CC list')
        seen = {}

        def stop(scr):
            rnd, cid, ties = slot_ties(s.result, 16)
            title = scr.entries[0][1] if scr.entries else ''
            r2 = 'SECONDO TURNO' in title and ('EUFA' if cid == 2 else 'COPPE') in title   # that cup's round-2 screen
            if cid in (1, 2) and ((rnd == 0 and 0 not in seen and any(a or b for a, b in ties)) or (r2 and 1 not in seen)):
                k = 0 if rnd == 0 and not r2 else 1
                n = 16 if k == 0 else 8
                seen[k] = ties[:n]
                same = [j for j, (a, b) in enumerate(ties[:n]) if a == b]
                check(not same, f'round {k + 1} ({"CWC" if cid == 1 else "UEFA"}): same-country ties {same} '
                      f'{[ties[j] for j in same]} (screen: {title.strip()})', errs)
            return 1 in seen
        ok, msg = advance(s, stop)
        if not ok:
            return False, f"advance: {msg}; {'; '.join(errs + notes)}"
        hits = {f'obj1+{o:X}': n for o, n in getattr(s, 'bp_hits', {}).items()}
    return not errs, f"{msg}; {'; '.join(errs) or 'ok'}; {'; '.join(notes)}; rounds checked {sorted(seen)}; bp hits {hits}"


def rng_sites(exe):
    """obj2 offsets of the game's two random generators' states, 3 bytes each (seed, randXorIndex, randXorKey; Rand
    and Rand2: `mov al, [seed]; mov [D0], al; and word [D0], 0FFh; jnz; add byte [randXorIndex], 1; mov al,
    [randXorIndex]`), in the order they appear in the code."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    from le import LE
    le = LE(open(exe, 'rb').read())
    c = le.obj_bytes(1)
    fx = {f[1]: f[4] for f in le.fixups() if f[0] == 1 and f[3] == 2}
    out = []
    for m in re.finditer(rb'\xa0....\xa2....\x66\x81\x25....\xff\x00\x75.\x80\x05....\x01\xa0', c, re.S):
        o = m.start()
        sd, ix = fx.get(o + 1), fx.get(o + 23)
        if sd is not None and ix == sd + 1 and fx.get(o + 29) == ix:
            out.append(sd)
    assert len(out) == 2, out
    return out


def nosack_off(exe):
    """obj2 offset of dseg_D6B62 (non-zero: the chairman never sacks the manager; cleared by every season start):
    the second word of the `mov ax,[D6B64]; or ax,ax; jnz; mov ax,[D6B62]; or ax,ax; jnz` pair of both sacking
    checks (cseg_3CCF0)."""
    import collections
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    from le import LE
    le = LE(open(exe, 'rb').read())
    pat = re.compile(rb'\x66\xa1(.{4})\x66\x0b\xc0\x0f\x85.{4}\x66\xa1(.{4})\x66\x0b\xc0\x0f\x85', re.S)
    pairs = collections.Counter(struct.unpack('<II', m.group(1) + m.group(2)) for m in pat.finditer(le.obj_bytes(1)))
    hits = [b for (a, b), n in pairs.items() if a == b + 2 and n == 2]
    assert len(hits) == 1, hits
    return hits[0]


def checkw1(path):
    """internal/career-test/checkw1.py on a world save (DATA next to it); returns (ok, its output)."""
    r = subprocess.run([sys.executable, os.path.join(MAIN, 'internal', 'career-test', 'checkw1.py'), path],
                       capture_output=True, text=True, env=dict(os.environ, CHECKW1_TOOLS=os.path.join(ROOT, 'tools')))
    out = (r.stdout + r.stderr).strip()
    if os.environ.get('W8485_SMALL'):              # a world with small cups (<= 80 European clubs): no W1 block
        return 'trailer end ok: True' in out and 'table sum mod 256 0' in out, out
    ok = r.returncode == 0 and 'W1 block: True' in out and 'bad pairs 0' in out
    for line in out.splitlines():
        if line.startswith(('CC ', 'CWC ', 'UEFA ')):
            ok = ok and line.endswith('dups 0')
    m = re.search(r'table sum mod 256 (\d+)', out)
    want = os.environ.get('W8485_K', '128')            # 'N+': at least N (uefaq: the qualifying opponents' records)
    k = re.search(r'euro records k=(\d+)', out)
    ok = ok and k is not None and (int(k.group(1)) >= int(want[:-1]) if want.endswith('+') else k.group(1) == want)
    ok = ok and re.search(rf"world byte {os.environ.get('W8485_WNUM', '4')}\b", out) is not None
    return ok and m is not None and m.group(1) == '0', out


