def zones_force_played(s, lang, errs, tag):
    """4.0 (Davide): a table before its first match day has no zones and no legend. Checked on the table shown, then
    its first row's played count forced to 1 (DIY row 0 +4: a test poke, nothing saved) so the zones show."""
    scr = s.screen()
    leg = [e[1] for e in scr.entries[-zone_leg_n():] if not e[2]]
    rows, _ = zone_rows(s, tag + '_pre', 6)
    check(not leg and all(z == 'pl' for _, z in rows), f'{tag}: no match played: no zones, no legend '
          f'({[z for _, z in rows]}, {leg})', errs)
    s.poke(diy_lin(s, lang) + 0x2B3 + 4, [1, 0])
    s.send('dump:1')


def zb_info(b):
    """4.0.6 a release build's SEC_BQ (obj2 offset) and ZB rows [(team word, SEC index, flags)] from its build.log
    (zones.bskip_patch's line; ZBSKIP_LOG: that file, e.g. for remote_run), or None"""
    lg = os.environ.get('ZBSKIP_LOG') or os.path.join(os.path.dirname(b.rstrip('/')), 'build.log')
    m = re.search(r'SEC_BQ obj2\+(0x[0-9a-f]+); SEASONP obj2\+(0x[0-9a-f]+); ZB ([0-9a-f: ]+)\)', open(lg).read()) \
        if os.path.exists(lg) else None
    if not m:
        return None
    return int(m.group(1), 16), [tuple(int(x, 16) if k == 0 else int(x) for k, x in enumerate(e.split(':')))
                                 for e in m.group(3).split()], int(m.group(2), 16)


@scenario
def zones_bq_season():
    """4.0.6 gplay's season end writes SEC_BQ (may each B team go up next season; item 'BQ' in the .CAR): a World
    2026-27 career at ALMERIA (SEGUNDA DIVISION, REAL SOCIEDAD B), two seasons with a save and a reload between: after
    the first season end REAL SOCIEDAD B's byte is 1 or 2 (its first team in LaLiga: 2), byte 0 = the season that
    ended (valid in the next), and it stays set through the save and reload (never 0 again); the world's other B
    teams are set too (gplay's tables hold every country)
    (ZBSKIP_BUILD / SWOSTEST_BUILD: a release dir)"""
    b = os.environ.get('ZBSKIP_BUILD') or os.environ.get('SWOSTEST_BUILD') or builds()['it']
    zi = zb_info(b)
    if not zi:
        return True, f'SKIP: {b}: no SEC_BQ line in its build.log'
    off, zb, sp = zi
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import mkseason
    src = os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-403c6')
    pk = mkseason.Pack(os.path.join(src, 'esp'))
    esp = {pk.where[k][0] | pk.where[k][1] << 8 for k, c in pk.clubs.items() if c.get('second_of')}
    ie = [1 + i for w, i, f in zb if w in esp]
    keep = {x: os.environ.get(x) for x in ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K',
                                            'W8485_NOSACK', 'W8485_HEX', 'W8485_ONE')}
    os.environ.update(W8485_BUILD=b, W8485_WORLD='MONDO 2026-27', W8485_TEAM='EUROPA,SPAGNA,SEGUNDA DIVISION,ALMERIA',
                      W8485_WNUM='5', W8485_K='108+', W8485_NOSACK='1', W8485_HEX=f'{off:x}:24,{sp:x}:1')
    os.environ.pop('W8485_ONE', None)
    try:
        ok, msg = world8485()
    finally:
        for x, v in keep.items():
            if v is None:
                os.environ.pop(x, None)
            else:
                os.environ[x] = v
    errs = []
    check(ok, msg[:200], errs)
    seq, seas = [], []                                 # (the bytes as they change; the season byte at each change)
    for k in (1, 2):
        lg = os.path.join(RUNS, w84_tag() + f'_{k}', 'session.log')
        cur = None
        for ln in (open(lg, errors='replace') if os.path.exists(lg) else []):
            q = ln.split()
            if len(q) == 3 and q[0] == 'HEX' and q[1] == f'{sp:x}':
                cur = int(q[2], 16)
                seas.append((len(seq), cur))
            if len(q) == 3 and q[0] == 'HEX' and q[1] == f'{off:x}':
                seq.append(bytes.fromhex(q[2]))
    vals = [[v[i] for i in ie] for v in seq]
    first = next((j for j, v in enumerate(vals) if all(v)), None)
    check(ie and first is not None, f'ESP B bytes {vals} (SEC index {ie})', errs)
    if first is not None:
        check(all(all(v) for v in vals[first:]), f'ESP B byte back to 0 after the first season end: {vals}', errs)
        st = [(j, c) for j, c in seas]                 # (the season byte: written at the season end = the season
        wr = [seq[j][0] for j in range(first, len(seq))]   # that ended, the next one is +1)
        check(all(w + 1 in [c for _, c in seas] for w in wr), f'season stamps {wr}, seasons {st}', errs)
    return not errs, '; '.join(errs + [f'ESP B {vals} of {[x.hex() for x in seq]}; season byte {seas}'])


@scenario
def zones_bskip():
    """4.0.6 qualifying places skip the B teams that may not qualify (zones.py zb_eff / zb_rng, SEC_TAB without play-offs:
    REAL SOCIEDAD B, STUTTGART II / HOFFENHEIM II, PORTO B / BENFICA B / SPORTING B, the Jong (U21) sides): a new
    World 2026-27 career in each 2nd tier with B teams, VISUAL. COMPETIZ. > its table (played forced as zone_colours),
    the table's sorted list (DIY + 6Dh) poked so the B teams stand 1st and 3rd: they keep the plain row, the places
    after them move up (SEGUNDA: 2nd and 4th PROM light blue, 5th-8th P.OFF green, 9th plain) - a test poke, nothing
    saved (ZBSKIP_BUILD / SWOSTEST_BUILD: a release dir); ZBSKIP_NZ_BUILD (a build of the NZ Championship snapshot):
    the NORTHERN LEAGUE with AUCKLAND FC RES 1st (the A-League reserves: the Championship's places by the others; the
    Championship's own table, 1st-2nd to the Grand Final, the same zn_col path)"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import mkseason
    b = os.environ.get('ZBSKIP_BUILD') or os.environ.get('SWOSTEST_BUILD') or builds()['it']
    src = os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-403c6')
    sel = mkseason._hook_sites(lepatch.LEPatch(os.path.join(ROOT, 'orig', 'ITALIAN.EXE')))[3]
    # (country, league, club; up, play-off places; the B teams in the top: placed 1st and 3rd)
    nzb = os.environ.get('ZBSKIP_NZ_BUILD')            # (NZ: a build of the TM_NZ_CHAMP snapshot, W2627NZ_DATA)
    nzs = os.environ.get('W2627NZ_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-nzchamp')
    cases = [('ESP', 'EUROPA', 'SPAGNA', 'SEGUNDA DIVISION', 'ALMERIA', 2, 4, b, src),
             ('GER', 'EUROPA', 'GERMANIA', '3. LIGA', 'ROT-WEISS ESSEN', 2, 1, b, src),
             ('POR', 'EUROPA', 'PORTOGALLO', 'LIGA PORTUGAL 2', 'UNIAO TORREENSE', 2, 1, b, src),
             ('NED', 'EUROPA', 'OLANDA', 'EERSTE DIVISIE', 'DE GRAAFSCHAP', 2, 6, b, src),
             ('NZL', 'OCEANIA', 'NUOVA ZELANDA', 'NORTHERN LGE|NORTHERN LEAGUE', 'WESTERN SPRINGS', 2, 2, nzb, nzs)]
    only = os.environ.get('ZBSKIP_ONLY')
    errs, info = [], []
    for code, cont, country, league, club, up, po, b, src in cases:
        if (only and code not in only.split(',')) or not b:
            continue
        pk = mkseason.Pack(os.path.join(src, code.lower()))
        bw = [pk.where[k][0] | pk.where[k][1] << 8 for k, c in pk.clubs.items() if c.get('second_of')]
        with Session(f'zones_bskip_{code.lower()}', b, {}, 'dump:2', 900) as s:
            s.wait()
            for t in ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', cont, country, league, club]:
                if all(press(s, s.screen(), x, 3) is None for x in t.split('|')):
                    errs.append(f'{code}: {t} not reached')
                    break
            else:
                s.send('fire dump:3')
                walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)
                walk(s, 1, 3)
                zones_force_played(s, 'it', errs, f'{code} {league}')
                r = s.send('dump:1')
                diy = diy_lin(s)
                n = struct.unpack('<H', r.read(diy + 0x31, 2))[0]
                lst = list(struct.unpack(f'<{n}H', r.read(diy + 0x6D, 2 * n)))
                base = struct.unpack('<I', r.read(r.base2 + sel, 4))[0]
                word = lambda off: struct.unpack('<H', r.read(struct.unpack('<I', r.read(diy + off + 0x2B3, 4))[0] + base, 2))[0]
                bi = [j for j, off in enumerate(lst) if word(off) in bw]
                check(bi, f'{code}: no B row of {n} (B words {bw})', errs)
                if bi:
                    tops = [0, 2][:len(bi)]
                    order = [lst[j] for j in bi[:2]]
                    rest = [x for x in lst if x not in order]
                    for t, x in zip(tops, order):
                        rest.insert(t, x)
                    w0 = word(rest[0])                 # (the B team now 1st; read before the poke's pause ends)
                    s.poke(diy + 0x6D, list(struct.pack(f'<{n}H', *rest)))
                    s.send('dump:1')
                    m = 2 + up + po + 2
                    rows, _ = zone_rows(s, f'zbskip_{code.lower()}', m)
                    got = [z for _, z in rows]
                    want, q = [], 0
                    for k in range(m):
                        if k in tops[:len(order)]:
                            want.append('pl')
                            continue
                        q += 1
                        want.append('lb' if q <= up else 'gr' if q <= up + po else 'pl')
                    check(got == want, f'{code}: rows {got} (want {want})', errs)
                    info.append(f"{code} {''.join(z[0] for z in got)}")
                    bq = zb_info(b)                    # 4.0.6 gplay's season-end value (SEC_BQ): the first B team
                    if code == 'ESP' and bq:           # may go up -> its row PROM, the play-off places still
                        off, zb, sp = bq               # without it (no play-offs): 1-2 PROM, 3rd plain, 4-7 P.OFF
                        i = next(i for w, i, f in zb if w == w0)   # (stamped last season: valid)
                        r = s.send('dump:1')
                        s.poke(r.base2 + off, [(r.obj2(sp, 1)[0] - 1) & 0xFF])
                        s.poke(r.base2 + off + 1 + i, [1])
                        s.send('dump:1')
                        rows, _ = zone_rows(s, f'zbskip_{code.lower()}_bq', m)
                        got = [z for _, z in rows]
                        want = ['lb', 'lb', 'pl'] + ['gr'] * po + ['pl'] * (m - 3 - po)
                        check(got == want, f'{code} SEC_BQ 1: rows {got} (want {want})', errs)
                        info.append(f"{code} BQ=1 {''.join(z[0] for z in got)}")
    return not errs, '; '.join(errs + info)


@scenario
def zones_preseason():
    """4.0 (Davide): a table before its first match day (the clubs in their initial order) has no zone colours and no
    legend, and a league whose groups are known from day 0 shows them at once (split.py sp_pregroup: the MLS's
    CONFERENCE EST / OVEST). A new career at ATLANTA UNITED (World 2026-27): VISUAL. COMPETIZ. > MLS before the first
    match (no colours, no legend; the conference headers in the shot); then 3 career matches: the MLS table with P.OFF,
    STAT > CLASSIFICA GENERALE (the Supporters' Shield) 1-6 light blue with CONC. PREZONE_LANGS='en=DIR,fr=DIR,de=DIR':
    the pre-season check in those exes too (ITALIAN.EXE = that language's exe)."""
    b = os.environ.get('PREZONE_BUILD') or os.environ.get('ZONES_W2627')
    if not b:
        return True, 'SKIP: PREZONE_BUILD (a full 2026-27 build) not set'
    errs, info = [], []
    menus = {'it': (['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', 'NORDAMERICA', 'USA'], 'VISUAL. COMPETIZ.'),
             'en': (['CAREER', 'CHOOSE TEAM', 'CLASSIC CAREERS', 'WORLD 2026-27', 'NORTH AMERICA|N. AMERICA', 'USA'], 'VIEW COMPETITIONS'),
             'fr': (['CARRIERE', 'CHOISIR UNE EQUIPE', "CARR. D'ANTAN", 'MONDE 2026-27', 'NORD-AMERICA|AMERIQUE DU NORD', 'ETATS-UNIS|USA'], 'AFFICHER COMPET.'),
             'de': (['KARRIERE', '#10', 'KLASS. KARRIERE', 'WELT 2026-27', 'NORDAMERIKA', 'USA'], 'WETTBWRBE ANZEIGN')}
    runs = [('it', b)] + [tuple(x.split('=', 1)) for x in os.environ.get('PREZONE_LANGS', '').split(',') if x]
    for lang, d in runs:
        menu, view = menus[lang]
        with Session(f'zones_preseason_{lang}', d, {}, 'dump:2', 1500) as s:
            s.wait()
            for t in menu + ['ATLANTA UNITED']:
                if t.startswith('#'):
                    walk(s, int(t[1:]), 3)
                elif all(press(s, s.screen(), x, 3) is None for x in t.split('|')):   # (alternative names: '|')
                    return False, f'{lang}: {t} not reached ({s.screen().texts()[:8]})'
            s.send('fire dump:3')
            walk(s, s.screen().find(view, exact=True), 3)
            walk(s, 1, 3)
            scr = s.screen()
            leg = [e[1] for e in scr.entries[-zone_leg_n():] if not e[2]]
            rows, _ = zone_rows(s, f'mls_pre_{lang}', 15)
            check(not leg and all(z == 'pl' for _, z in rows), f'{lang} MLS before the first match: no zones, no legend '
                  f'({[z for _, z in rows]}, {leg})', errs)
            info.append(f'{lang} pre-season: legend {leg}, rows {"".join(z[0] for _, z in rows)}')
            if lang != 'it':
                continue
            for _ in range(3):
                if s.screen().find('ESCI', exact=True) is None:
                    break
                walk(s, s.screen().find('ESCI', exact=True), 3)
                if 'TRASFERIMENTI' in s.screen().texts():
                    break
            n = [0]
            def stop(scr):
                if 'VISUAL. COMPETIZ.' in scr.texts() and 'TRASFERIMENTI' in scr.texts():
                    n[0] += 1
                    return n[0] >= 4
                return False
            ok, m = advance(s, stop, 300)
            check(ok, f'3 matches: {m}', errs)
            walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)
            walk(s, 1, 3)
            scr = s.screen()
            leg = [e[1] for e in scr.entries[-zone_leg_n():] if not e[2]]
            s.shot('mls_mid')
            check(leg == ['P.OFF'], f'MLS mid-season: legend {leg}', errs)
            walk(s, scr.find('STAT', exact=True), 3)
            press(s, s.screen(), 'CLASSIFICA GENERALE', 3)
            rows, scr = zone_rows(s, 'mls_shield', 8)
            leg = [e[1] for e in scr.entries[-zone_leg_n():] if not e[2]]
            got = [z for _, z in rows]
            check(leg == ['CONC'] and got[:6] == ['lb'] * 6 and got[6] != 'lb', f"Supporters' Shield: {got} {leg}", errs)
            info.append(f"mid-season: MLS legend P.OFF, Supporters' Shield {''.join(z[0] for z in got)} {leg}")
    return not errs, '; '.join(errs + info) if errs else '; '.join(info)


@scenario
def zone_colours():
    """4.0 zone colours (zones.py): a new 1984-85 career at Liverpool, VISUAL. COMPETIZ. > First Division: place 1 light
    blue (Champions Cup), 2-5 green (UEFA Cup), 20-22 gray, the others plain (pixels of the stats columns); the legend
    CAMP / UEFA / RETR on the header line; STAT > FORMULA > back (the FORMAT page shares the zones' file buffer): the
    same colours again"""
    b = (os.environ.get('W8485_BUILD') or builds()['it'])   # (builds/w8485: a stale shared dir)
    want = ['lb'] + ['gr'] * 4 + ['pl'] * 14 + ['gy'] * 3
    errs, info = [], []
    with Session('zone_colours', b, {}, 'dump:2', 600) as s:
        s.wait()
        for t in ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'EUROPA 1984-85', 'INGHILTERRA', 'FIRST DIVISION',
                  'LIVERPOOL']:
            if press(s, s.screen(), t, 3) is None:
                return False, f'new career: {t} not reached'
        s.send('fire dump:3')
        walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)
        walk(s, 1, 3)
        zones_force_played(s, 'it', errs, 'w8485 first division')
        for k in (1, 2):
            rows, scr = zone_rows(s, f'zones_{k}', len(want))
            got = [z for _, z in rows]
            liv = None
            check(len(got) == 22 and all(a == w or (w == 'pl' and a != w and False) for a, w in zip(got, want)),
                  f'pass {k}: zones {got}', errs)
            leg = [e[1] for e in scr.entries[-zone_leg_n():] if not e[2]]
            check(leg == ['CAMP', 'UEFA', 'RETR'], f'pass {k}: legend {leg}', errs)
            info.append(f"pass {k}: {''.join({'gy': 'x'}.get(z, z[0]) for z in got)}, legend {leg}")
            if k == 1:                              # the FORMAT page (it reads its own file into the shared buffer)
                walk(s, scr.find('STAT', exact=True), 3)
                walk(s, s.screen().find('FORMULA', exact=True), 3)
                walk(s, s.screen().find('ESCI', exact=True), 3)
                walk(s, s.screen().find('ESCI', exact=True), 3)
    langs = os.environ.get('ZONES_LANGS')              # 'en=DIR,fr=DIR,de=DIR': full 2026-27 builds whose ITALIAN.EXE is
    for item in (langs.split(',') if langs else []):    # that language's exe: Italy's and Germany's tables, the keys
        lang, d = item.split('=', 1)                    # being the exe language's titles
        menu = {'en': ['CAREER', 'CHOOSE TEAM', 'CLASSIC CAREERS', 'WORLD 2026-27', 'EUROPE'],
                'fr': ['CARRIERE', 'CHOISIR UNE EQUIPE', "CARR. D'ANTAN", 'MONDE 2026-27', 'EUROPE'],
                'de': ['KARRIERE', '#10', 'KLASS. KARRIERE', 'WELT 2026-27', 'EUROPA']}[lang]
        view = {'en': 'VIEW COMPETITIONS', 'fr': 'AFFICHER COMPET.', 'de': 'WETTBWRBE ANZEIGN'}[lang]
        sys.path.insert(0, os.path.join(ROOT, 'tools'))
        import zones
        L = zones.LABELS[lang]
        cases = ((({'en': 'ITALY', 'fr': 'ITALIE', 'de': 'ITALIEN'}[lang], 'SERIE A', 'INTER'),
                  ['lb'] * 4 + ['gr', 'db'] + ['pl'] * 11 + ['gy'] * 3, [L['cl'], L['el'], L['conf'], L['down']]),
                 (({'en': 'GERMANY', 'fr': 'ALLEMAGNE', 'de': 'DEUTSCHLAND'}[lang], 'BUNDESLIGA', 'BAYERN|BAYERN MUNICH'),
                  ['lb'] * 4 + ['gr', 'db'] + ['pl'] * 9 + ['or'] + ['gy'] * 2,
                  [L['cl'], L['el'], L['conf'], L['out'], L['down']]))
        for path, want_l, leg_l in cases:
            with Session(f'zone_colours_{lang}_' + path[1].split()[-1].lower(), d, {}, 'dump:2', 1500) as s:
                s.wait()
                for t in menu + list(path):
                    if t.startswith('#'):
                        walk(s, int(t[1:]), 3)
                    elif all(press(s, s.screen(), x, 3) is None for x in t.split('|')):   # (alternatives: '|')
                        return False, f'{lang}: {t} not reached'
                s.send('fire dump:3')
                walk(s, s.screen().find(view, exact=True), 3)
                walk(s, 1, 3)
                zones_force_played(s, lang, errs, f'{lang} {path[1]}')
                rows, scr = zone_rows(s, f'zones_{lang}_' + path[1].split()[-1].lower(), len(want_l))
                got = [z for _, z in rows]
                check(got == want_l, f'{lang} {path[0]} {path[1]}: zones {got}', errs)
                leg = [e[1] for e in scr.entries[-zone_leg_n():] if not e[2]]
                check(leg == leg_l, f'{lang} {path[0]} {path[1]}: legend {leg}', errs)
                info.append(f"{lang} {path[0]} {path[1]}: {''.join({'gy': 'x'}.get(z, z[0]) for z in got)}, legend {leg}")
    w27 = os.environ.get('ZONES_W2627')                 # a full 2026-27 build (exe + DATA): two more tables
    if w27:
        for path, want27, leg27 in ((('INGHILTERRA', 'PREMIER LEAGUE', 'ARSENAL'),
                                     ['lb'] * 4 + ['gr', 'db'] + ['pl'] * 11 + ['gy'] * 3, ['CL', 'EL', 'CONF', 'RETR']),
                                    (('ITALIA', 'SERIE B', 'AVELLINO'),
                                     ['lb'] * 2 + ['gr'] * 6 + ['pl'] * 7 + ['or'] * 2 + ['gy'] * 3,
                                     ['PROM', 'P.OFF', 'P.OUT', 'RETR']),
                                    (('SUDAMERICA', 'BRASILE', 'BRASILEIRAO SERIE A|CAMPEONATO BRASILEIRO SERIE A', 'PALMEIRAS'),
                                     ['lb'] * 6 + ['gr'] * 6 + ['pl'] * 4 + ['gy'] * 4, ['LIB', 'SUD', 'RETR'])):
            with Session('zone_colours_' + path[1].split()[-1].lower(), w27, {}, 'dump:2', 1500) as s:
                s.wait()
                for t in ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27'] + \
                        ([] if path[0] == 'SUDAMERICA' else ['EUROPA']) + list(path):
                    if all(press(s, s.screen(), x, 3) is None for x in t.split('|')):   # (alternative names: '|')
                        return False, f'2026-27 career: {t} not reached'
                s.send('fire dump:3')
                walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)
                walk(s, 1, 3)
                zones_force_played(s, 'it', errs, path[1])
                rows, scr = zone_rows(s, 'zones_' + path[1].split()[-1].lower(), len(want27))
                got = [z for _, z in rows]
                check(got == want27, f'{path[1]}: zones {got}', errs)
                leg = [e[1] for e in scr.entries[-zone_leg_n():] if not e[2]]
                check(leg == leg27, f'{path[1]}: legend {leg}', errs)
                info.append(f"{path[1]}: {''.join({'gy': 'x'}.get(z, z[0]) for z in got)}, legend {leg}")
                if path[1] == 'PREMIER LEAGUE':         # another season year, the same ring: the same colours (they
                    import lepatch                      # come from uc_rank, not from the season)
                    pe = lepatch.LEPatch(os.path.join(w27, 'ITALIAN.EXE'))
                    m = re.search(rb'\x80\x2d(.{4})\x01\xe8', pe.le.obj_bytes(1), re.S)
                    sp = pe.target(1, m.start() + 2)[1]
                    s.poke(s.result.base2 + sp, [1])
                    s.send('dump:1')
                    rows, scr = zone_rows(s, 'zones_premier_s2', len(want27))
                    got = [z for _, z in rows]
                    leg = [e[1] for e in scr.entries[-zone_leg_n():] if not e[2]]
                    check(got == want27 and leg == leg27, f'another season: {got} {leg} (uc_rank: the same ring)', errs)
                    info.append(f"PREMIER LEAGUE season 2: {''.join({'gy': 'x'}.get(z, z[0]) for z in got)}, legend {leg}")
    return not errs, '; '.join(errs + info) if errs else '; '.join(info)


@scenario
def world8485():
    """Europe 1984-85 world (world 4): new career at Liverpool, two seasons (save, reload, save), checkw1 on both"""
    exe = os.environ.get('W8485_BUILD') or builds()['it']       # (builds/w8485 was a stale 3.0-era build)
    global W84_HOOK
    if os.environ.get('HT_SNAP_LABELS') and W84_HOOK is None:  # tools/hosttest fixtures from ANY world8485 run: a
        sys.path.insert(0, os.path.join(ROOT, 'tools', 'hosttest'))   # breakpoint at each label (the exe's
        import snapshot                                        # ITALIAN.syms.json: HOSTTEST_SYMS=1 build), dumps
        W84_HOOK = snapshot.make_hook(sys.modules[__name__], exe, os.environ['HT_SNAP_LABELS'],   # into HT_SNAP_OUT
                                      os.environ.get('HT_SNAP_OUT') or os.path.join(RUNS, 'ht_snap'),
                                      int(os.environ.get('HT_SNAP_WEEKMIN', 0)), int(os.environ.get('HT_SNAP_MAX', 12)))[0]
    out, msgs = [], []
    first = os.environ.get('W8485_FROM')                   # resume from a season-1 save (W84A.CAR)
    if first:
        out, msgs = [first], [f'season 1: from {first}']
    for season in ((2,) if first else (1,) if os.environ.get('W8485_ONE') == '1' else (1, 2)):   # (W8485_ONE: season 1 only)
        cars = {} if season == 1 else {'W84A.CAR': out[0]}
        with Session(f'{w84_tag()}_{season}', exe, cars, 'dump:2', int(os.environ.get('W8485_TMO', 240)), int(os.environ.get('W8485_SHOTS', 0)),
                     match=bool(os.environ.get('W8485_REALPLAY'))) as s:   # (a match played for real: the feeder in it)
            if s.wait().outcome != 'dump':
                return False, f'START: no first pause ({s.result})'
            if season == 1:
                team = os.environ.get('W8485_TEAM', 'INGHILTERRA,FIRST DIVISION,LIVERPOOL').split(',')
                path = ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', os.environ.get('W8485_WORLD', 'EUROPA 1984-85')] + team
                if os.environ.get('W8485_PATH'):              # the whole selector path; '<back>' = ESCI until the
                    path = ['CARRIERA', 'SCEGLI SQUADRA'] + os.environ['W8485_PATH'].split(',')   # next step shows
                for k, t in enumerate(path):
                    if t == '<back>':
                        for _ in range(6):
                            if s.screen().find(path[k + 1], exact=True) is not None:
                                break
                            for _ in range(40):              # (ESCI has no menu links the BFS knows: walk down)
                                scr = s.screen()
                                if any(e[0] == scr.selected and e[1] == 'ESCI' for e in scr.entries):
                                    break
                                s.send('down dump:0.5')
                            if s.send('fire dump:2').outcome != 'dump':
                                return False, f'new career: ESCI ({s.result})'
                        continue
                    scr = s.screen()                      # a group of a level (menulevels): its level first
                    alts = t.lstrip('?').split('|')       # ('a|b': alternative names, the first on screen - after its
                    if '|' in t or t.startswith('?'):     # level; '?a': an optional level, skipped when not on screen)
                        hit = next((x for x in alts if scr.find(x, exact=True) is not None), None)
                        if hit is None and t.startswith('?'):
                            continue
                        t = hit or next((x for x in alts if any(e[1] and x.startswith(e[1] + ' ') for e in scr.entries)),
                                        alts[0])
                    lvl = None if scr.find(t, exact=True) is not None else \
                        next((x for i, x, inv, _ in scr.entries if 11 <= i <= 20 and x and not inv and
                              t.startswith(x + ' ')), None)
                    if lvl and press(s, scr, lvl) is None:
                        return False, f'new career: level {lvl} of {t} not reached ({s.result})'
                    if os.environ.get('W8485_RNG_EARLY') and k == len(path) - 1:   # (4.0.5: the generators pinned
                        v = bytes.fromhex(os.environ['W8485_RNG_EARLY'])            # before the club's press -
                        for at, part in zip(rng_sites(os.path.join(exe, 'ITALIAN.EXE')), (v[:3], v[3:6])):   # its
                            s.poke(s.result.base2 + at, part)                       # CareerInitVars draws the
                        s.log.append(f'[rng early] {v.hex()}')                      # fixtures from them)
                    if all(press(s, s.screen(), x) is None for x in ([t] + [x for x in alts if x != t])) \
                            or s.result.outcome != 'dump':
                        return False, f'new career: {t} not reached ({s.result})'
                if os.environ.get('W8485_RNG'):                   # (4.0.5) the random generators' states pinned
                    v = bytes.fromhex(os.environ['W8485_RNG'])     # at the career's start: they advance with every
                    for at, part in zip(rng_sites(os.path.join(exe, 'ITALIAN.EXE')), (v[:3], v[3:6])):   # call since
                        s.poke(s.result.base2 + at, part)           # the game started, i.e. with the exe's load
                    s.log.append(f'[rng] {v.hex()}')                # time (31/10: f1dd98f's 233 B -> xtra_world30
                                                                    # took another season)
                if os.environ.get('W8485_START') == '1':          # menu check only: the career has started
                    return True, f'career started: {s.screen()}'[:400]
                if os.environ.get('W8485_START') == 'cal':        # (4.0.5) the drawn calendar, at once
                    return True, 'calendar ' + bytes(s.result.obj2(CAL_AT - 4, 0x2000)).hex()
            else:
                s.send('down down down down down fire dump:2')
                if W84_HOOK is not None and getattr(W84_HOOK, 'pre_load', False):   # (tools/hosttest: breakpoints
                    W84_HOOK(s, season, s.screen())                                     #  in the load itself)
                s.send('fire dump:3')
                if W84_HOOK is not None and getattr(W84_HOOK, 'at_load', False):   # (the loaded career's first
                    W84_HOOK(s, season, s.screen())                                    #  menu, before advance)
            seen, errs = {}, []
            nosack, poked = (nosack_off(os.path.join(exe, 'ITALIAN.EXE')) if os.environ.get('W8485_NOSACK') == '1'
                             else None), set()

            def hexlog():                              # W8485_HEX: obj2 offset:bytes (o1/ prefix: obj1, o3/: obj3),
                for a in filter(None, os.environ.get('W8485_HEX', '').split(',')):   # logged when they change
                    o, n = a.split(':')
                    if o[:3] in ('o1/', 'o3/'):
                        v = s.result.read(s.result.lin((int(o[1]), int(o[3:], 16))), int(n)).hex()
                    else:
                        v = s.result.obj2(int(o, 16), int(n)).hex()
                    if hexseen.get(o) != v:
                        hexseen[o] = v
                        s.log.append(f'HEX {o} {v}')

            mid = os.environ.get('W8485_MIDSAVE', '').split(':') if season == 1 else ['']   # obj2 off:byte:dumps:
            midc = [0]                                 # a career save mid-season once the byte held that long
            midt = (os.environ.get('W8485_MIDTEXT', '').split(':') + [''])[:2] + [None, 0] if season == 1 or first \
                else ['']                              # (W8485_FROM: its one season, the loaded one)

            def stop(scr):                             # the player's European cup: no same-country tie in rounds 1-2
                if os.environ.get('W8485_FILLWATCH') and not getattr(stop, 'fill_bad', False):   # (debug: the first
                    title = scr.entries[0][1] if scr.entries else ''                    # step whose screen left the
                    if fill_check(s, f'step {title}') is False:                         # menu texture changed)
                        stop.fill_bad = True
                if os.environ.get('W8485_RNGSTEP'):    # (4.0.5) the random states re-pinned at every pause, from
                    rs = getattr(s, 'rng_at', None)     # (season, pause number): CareerMenu reseeds Rand from
                    if rs is None:                      # currentTick on every entry, so one pin at the start still
                        rs = s.rng_at = rng_sites(os.path.join(exe, 'ITALIAN.EXE'))   # left the path to the exe's
                    s.rng_n = getattr(s, 'rng_n', 0) + 1    # load timing (xtra_world30: CELLE VARAZZE's play-out,
                    h = hashlib.md5(f"{os.environ['W8485_RNGSTEP']}:{season}:{s.rng_n}".encode()).digest()
                    for at, part in zip(rs, (h[:3], h[3:6])):   # no renewal, MODICA on f1dd98f / gs3 / gsOFF)
                        s.poke(s.result.base2 + at, part)
                if nosack is not None and season not in poked:   # W8485_NOSACK: the game's 'no sacking' word
                    s.poke(s.result.base2 + nosack, b'\x01\x00')   # (dseg_D6B62, cleared at every season start)
                    poked.add(season)
                if W84_HOOK is not None:               # a scenario's own per-step check (world_away_goals)
                    W84_HOOK(s, season, scr)
                if fill and season not in filled:      # W8485_FILL 'obj2 off:byte:count' (hex, hex, dec), once per
                    for f1 in fill.split(','):          # session (world_full_draw: simdraw's table, not in the save);
                        base = s.result.base2           # 4.0.5: several, comma-separated; 'o1:' = an obj1 offset
                        if f1.startswith('o1:'):        # (world_sc_tur: the extra-time margin table cseg_2C347)
                            base, f1 = s.result.base1, f1[3:]
                        o, v, n = f1.split(':')
                        for k in range(0, int(n), 16):  # (short SM commands, as lp36_tie's poke)
                            s.poke(base + int(o, 16) + k, bytes([int(v, 16)]) * min(16, int(n) - k))
                    filled.add(season)
                if peek is not None:                   # W8485_PEEK: the largest word seen at an obj2 offset
                    peek[1] = max(peek[1], struct.unpack_from('<H', s.result.obj2(peek[0], 2))[0])
                hexlog()
                for k, a in enumerate(filter(None, os.environ.get('W8485_POKEIF', '').split(','))):
                    co, cv, po, pv = a.split(':')          # W8485_POKEIF: once obj2 bytes at co == cv, poke pv at po
                    if ('if', k) not in poked and s.result.obj2(int(co, 16), len(cv) // 2).hex() == cv:
                        if pv.startswith('swap'):              # swap<hex offset>: exchange the bytes at po and there
                            q = int(pv[4:], 16)
                            x, y = s.result.obj2(int(po, 16), 1), s.result.obj2(q, 1)
                            s.poke(s.result.base2 + q, x)
                            pv = y.hex()
                        s.poke(s.result.base2 + int(po, 16), bytes.fromhex(pv))
                        poked.add(('if', k))
                        s.log.append(f'POKEIF {po} {pv}')
                if mid[0] and s.result.obj2(int(mid[0], 16), 1)[0] == int(mid[1], 0):
                    midc[0] += 1
                    if midc[0] >= int(mid[2]):
                        return True
                if midt[0] and '- RISULTATO -' in scr.texts() and any(midt[0] in x for x in scr.texts()) and \
                        tuple(scr.texts()) != midt[2]:         # W8485_MIDTEXT 'text:n': save after the n-th
                    midt[2] = tuple(scr.texts())                # match screen showing that text
                    midt[3] += 1
                    if midt[3] >= int(midt[1]):
                        mid[:] = ['t', 0, 0]
                        midc[0] = 1
                        return True
                if diy is not None:                    # W8485_DIY (world_split): the split league's DIY when its
                    b = s.result.obj2(diy[0], 0x733)    # day / freeze changes, the calendar once frozen
                    if diy_league(b) and diyseen.get('k') != (b[0x1C1:0x1C3], b[diy[1] + 4]):
                        diyseen['k'] = (b[0x1C1:0x1C3], b[diy[1] + 4])
                        s.log.append(f'DIY {b.hex()}')
                        open(os.path.join(s.run, 'diy.log'), 'a').write(f'DIY {b.hex()}\n')   # (live, for long runs)
                        if b[diy[1] + 4] and 'cal' not in diyseen:
                            diyseen['cal'] = 1
                            s.log.append(f'CAL {s.result.obj2(diy[2], 1870).hex()}')
                if UI != 'it':                         # (another language's exe: SLOT is the Italian exe's offset)
                    return season_over(scr)
                rnd, cid, ties = slot_ties(s.result, 32)
                if struct.unpack_from('<H', s.result.obj2(SLOT, 2))[0] == 2:   # a league phase (type 2): no ties
                    return season_over(scr)
                title = scr.entries[0][1] if scr.entries else ''
                k = {0: 'PRIMO TURNO', 1: 'SECONDO TURNO'}.get(rnd)
                if cid <= 2 and k and k in title and (season, rnd) not in seen and any(a or b for a, b in ties):
                    n = struct.unpack_from('<H', s.result.obj2(SLOT + 0x31, 2))[0] >> (rnd + 1)
                    seen[season, rnd] = ties[:n]
                    same = [ties[j] for j in range(n) if ties[j][0] == ties[j][1]]
                    check(not same, f'season {season} cup {cid} round {rnd + 1}: same-country ties {same}', errs)
                return season_over(scr) or (r2only and (season, 1) in seen)
            hexseen, diyseen = {}, {}
            fill, filled = os.environ.get('W8485_FILL'), set()
            diy = [int(x, 16) for x in os.environ['W8485_DIY'].split(',')] if os.environ.get('W8485_DIY') else None
            diy_league = lambda b: b[0:2] == b'\0\0' and (b[diy[1]:diy[1] + 2] == b'\xfeP' if len(diy) < 4 else
                                                            struct.unpack_from('<H', b, 0x31)[0] == diy[3])   # (a split
            # league by its mark; W8485_DIY's 4th field: any league of that many clubs, the odd-league scenario)
            r2only = os.environ.get('W8485_R2') == '1'         # stop once the player's round 2 is checked
            peek = [int(os.environ['W8485_PEEK'], 0), 0] if os.environ.get('W8485_PEEK') else None
            ok, msg = advance(s, stop, 900)
            if mid[0] and midc[0] >= int(mid[2]):          # W8485_MIDSAVE: ESCI -> SALVA CARRIERA -> W84A, mid-season
                for _ in range(5):                     # (ESCI up to the career's exit menu: a results screen, a
                    scr = s.screen()                   # chairman's note first)
                    press(s, scr, 'CONTINUA' if scr.find('CONTINUA', exact=True) is not None else 'ESCI', wait=3)
                    if s.screen().find('SALVA CARRIERA', exact=True) is not None:
                        break
                if press(s, s.screen(), 'SALVA CARRIERA') is None:
                    return False, f'mid-season save: no SALVA CARRIERA on {s.screen()}'
                s.send(name_entry('W84A') + ' dump:3')
                path = os.path.join(s.run, 'SWOS', 'W84A.CAR')
                return os.path.exists(path), f'saved mid-season: {path}'
            if r2only:
                return (season, 1) in seen and not errs, f"season {season}: {msg}; {'; '.join(errs) or 'ok'}"

            msg += f', euro rounds checked {sorted(seen)}' + (f', peek max {peek[1]}' if peek else '')
            if not ok or errs:
                return False, f"season {season}: {msg}; {'; '.join(errs)}"
            for _back in range(3):                     # (4.0.5 gp_fin: FINISH SEASON gives the menu back - PARTITA -
                for _ in range(8):                     # when gplay builds the club's play-off inside it: play on)
                    if s.screen().find('FINISCI STAGIONE', exact=True) is not None:   # FINISCI STAGIONE with the
                        press(s, s.screen(), 'FINISCI STAGIONE', wait=3)               # career club's matches still
                    if s.result.outcome != 'dump':                                     # in the calendar (a dplay
                        return False, f'season {season} FINISCI STAGIONE: {s.result}'   # play-off: no 'manager'
                    texts = s.screen().texts()                                         # flag on its entries)
                    if not ('MOD. TATTICA' in texts and 'AVVERSARI' in texts):         # plays them first
                        break
                    ok, m2 = advance(s, lambda scr: (hexlog(), season_over(scr) and 'MOD. TATTICA' not in scr.texts())[1], 200)   # (W8485_HEX: logged here too - 4.0.6 nzgf_defer)
                    msg += f', after FINISCI STAGIONE: {m2}'
                    if not ok:
                        return False, f"season {season}: {msg}"
                sc = s.screen()                        # (no note pressed here: a season-end note is the [job] path's)
                if not (sc.find('PARTITA', exact=True) is not None and 'TRASFERIMENTI' in sc.texts()
                        and sc.find('FINISCI STAGIONE', exact=True) is None):
                    break
                ok, m2 = advance(s, stop, 900)
                msg += f', FINISH SEASON gave the menu back (PARTITA): {m2}'
                if not ok:
                    return False, f"season {season}: {msg}" 
            if diy is not None and os.environ.get('W8485_SLOTS'):   # (the split league once the season is over,
                lin = struct.unpack('<I', s.result.obj2(int(os.environ['W8485_SLOTS'], 16), 4))[0]   # from its slot:
                b = s.result.read(lin, 0x733)          # its last days may come after the career club's last match)
                if diy_league(b):
                    s.log.append(f'DIY {b.hex()}')
            if os.environ.get('W8485_SAVE_END') and season >= int(os.environ.get('W8485_SAVE_END_SEASON', '1')):
                # (debug) a save at the season-end menu, before CONTINUA (W8485_SAVE_END_SEASON: from that season)
                hexlog()                               # (the season end's state first: W8485_HEX)
                rec_shot(s)                            # (W8485_RECSHOT: the season record before the save)
                nm = os.environ['W8485_SAVE_END']
                for _ in range(3):                     # (a chairman's note first: the contract not renewed)
                    if s.screen().find('SALVA CARRIERA') is not None or s.screen().find('CONTINUA', exact=True) is None:
                        break
                    press(s, s.screen(), 'CONTINUA')
                if press(s, s.screen(), 'SALVA CARRIERA') is None:
                    return False, f'season {season}: no SALVA CARRIERA on {s.screen()}'
                s.send(name_entry(nm) + ' dump:3')
                return True, f'season {season}: saved {os.path.join(s.run, "SWOS", nm + ".CAR")}'
            path = next_season_save(s, 'W84' + 'AB'[season - 1])
            if s.result.outcome == 'dump':             # (after the season end: its logs)
                hexlog()
            if W84_HOOK is not None and s.result.outcome == 'dump':   # (once more in the new season: the holders
                W84_HOOK(s, season, None)                                # are set by now)
            if not path.endswith('.CAR'):
                return False, f'season {season}: {path}'
        good, report = checkw1(path)
        out.append(path)
        msgs.append(f'season {season}: {msg}, ' + ('checkw1 ok' if good else 'checkw1 FAIL'))
        open(os.path.join(RUNS, f'{w84_tag()}_{season}', 'checkw1.txt'), 'w').write(report + '\n')
        if not good:
            return False, '; '.join(msgs) + '\n' + report
    return True, '; '.join(msgs)


def nat_offsets(exe):
    """obj2 offsets in the exe under test: national competition copies (careerContests: EC 6, ECQ 7-14, WC 20,
    WCQ 21-28) and dseg_17A3CE (2 = the national team of the manager's nationality offers a job at once: debug)."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    from le import LE
    le = LE(open(exe, 'rb').read())
    d1, d2 = le.obj_bytes(1), le.obj_bytes(2)
    t2 = {f[1]: f[4] for f in le.fixups() if f[0] == 2 and f[3] == 2 and f[4] is not None}
    cc = next(o for o in sorted(t2) if struct.unpack_from('<H', d2, o + 8)[0] == 79
              and struct.unpack_from('<H', d2, o + 18)[0] == 92 and struct.unpack_from('<H', d2, o + 28)[0] == 92)
    copy = [t2[cc + 10 * k + 4] for k in range(34)]
    t1 = {f[1]: f[4] for f in le.fixups() if f[0] == 1 and f[3] == 2}
    m = re.search(rb'\x66\x83\x3d(.{4})\x13\x0f\x84.{4}\x66\x83\x3d(.{4})\x01\x0f\x84', d1, re.S)
    k = re.search(rb'\xa1(.{4})\xa3.{4}\x80\x3d.{4}\x50\x74.\xa1(.{4})\xa3', d1, re.S)   # cseg_5C304: dseg_C8B14 =
    return {'ec': copy[6], 'ecq': copy[7:15], 'wc': copy[20], 'wcq': copy[21:29], 'force': t1[m.start(2)],  # seasons
            'mask': t1[k.start(1)],
            'isnat': t1[re.search(rb'\x66\xa1(.{4})\x66\x0b\xc0\x74.\x80\x3d.{4}\x50\x75.\xe8', d1, re.S).start(1)],
            'flags': t1[re.search(rb'\xf6\x05(.{4})\x80\x74.\x66\xa1.{4}\x66\xa3(.{4})\xf6\x05\1\x40\x0f\x84', d1, re.S).start(1)],
            'd6cd0': t1[re.search(rb'\xf6\x05(.{4})\x80\x74.\x66\xa1.{4}\x66\xa3(.{4})\xf6\x05\1\x40\x0f\x84', d1, re.S).start(2)],
            'csd': t1[re.search(rb'\x66\xa1.{4}\x66\x0b\xc0\x75.\x66\x83\x3d(.{4})\x03\x72', d1, re.S).start(1)]}                       # (bits) a European national team may offer a job


def team_list(r, off):
    """Team words of a competition copy (list at +7 + [+7]; groups: count at +0Dh; cups: the first stage)."""
    hdr = r.obj2(off, 0x30)
    lst = off + 7 + hdr[7]
    n = hdr[13] if hdr[1] == 0 else hdr[15]       # groups: teams at +0Dh; cups: the first stage's teams (+0Fh)
    words = struct.unpack(f'<{n}H', r.obj2(lst, 2 * n))
    return [w for w in words if w] if hdr[1] else list(words)


def nat_names(build):
    """Team word -> name from the national files of the build (TEAM.180-185 stand for 080-085)."""
    out = {}
    for f in range(180, 186):
        d = open(os.path.join(build, 'DATA', 'TEAM.%03d' % f), 'rb').read()
        for i in range(struct.unpack('>H', d[:2])[0]):
            r = d[2 + i * 684:]
            out[r[0] | r[1] << 8] = r[5:22].split(b'\0')[0].decode('latin-1')
    return out


def nat_offer_save(exe, off, name='W84NAT', season=None, lefts=0):
    """Slow part, once per build (kept in internal/swostest/saves/W84NAT.CAR; W84NAT_REDO=1 makes it again): new
    career at St. Andrews (Malta: 10 clubs, a short season; low expectations), debug switches poked so that England offers its job at once, the
    offer kept (CONSIDERA: a national job is accepted at the season end), season played, saved at the season-end menu.
    lefts: the coach's nationality moved that many times left from ENG first (5 = GDR). Returns the save path or an
    error."""
    if os.environ.get('W84SAVE_' + name):           # (a given save instead of the cache: a failing run's, re-played
        return os.environ['W84SAVE_' + name]       # on another build)
    dst = os.path.join(WORK, 'saves', name + '.CAR')
    stamp = dst + '.exe'
    if os.path.exists(dst) and open(stamp).read() == md5(os.path.join(exe, 'ITALIAN.EXE')) \
            and not os.environ.get('W84NAT_REDO'):
        return dst
    with Session('world8485_natA', exe, {}, 'dump:2', 240) as s:   # season: currentSeasonShowing poked (cycles)
        if s.wait().outcome != 'dump':
            return f'START: no first pause ({s.result})'
        if press(s, s.screen(), 'CARRIERA') is None:
            return f'no CARRIERA ({s.result})'
        if lefts:
            i = s.screen().find('ENG', exact=True)
            if i is None or press(s, s.screen(), i, wait=0.5) is None:
                return f'no nationality field on {s.screen()}'
            s.send(' '.join(['fire+left:0.5'] * lefts) + ' dump:0.5')
            s.log.append(f'[nationality] {s.screen().entries[i][1]}')
        for t in ['SCEGLI SQUADRA', 'CARR. STORICHE', 'EUROPA 1984-85', 'MALTA',
                  'ST. ANDREWS']:              # Davide: a small league (18 matches) and a weak club (no sacking)
            if press(s, s.screen(), t) is None or s.result.outcome != 'dump':
                return f'new career: {t} not reached ({s.result})'
        s.poke(s.result.base2 + off['force'], b'\x02')         # debug: the national team calls at once
        s.poke(s.result.base2 + off['mask'], b'\xff\xff\xff\x0f')   # in any season
        if season is not None:
            s.poke(s.result.base2 + off['csd'], struct.pack('<H', season))
        offer = lambda scr: 'TRASFERIMENTI' in scr.texts() and 'OFFERTE LAVORO' in scr.texts()
        ok, msg = advance(s, lambda scr: offer(scr) or season_over(scr), 600)
        if not ok or not offer(s.screen()):
            return f'no job offer ({msg})'
        err = nat_letter(s, 'CONSIDERA')
        if err:
            return err
        ok, msg = advance(s, season_over, 600)
        if not ok:
            return 'season 1: ' + msg
        if s.screen().find('FINISCI STAGIONE', exact=True) is not None:
            press(s, s.screen(), 'FINISCI STAGIONE', wait=3)
        if press(s, s.screen(), 'SALVA CARRIERA') is None:
            return f'no SALVA CARRIERA on {s.screen()}'
        s.send(name_entry(name) + ' dump:3')
        path = os.path.join(s.run, 'SWOS', name + '.CAR')
        if not os.path.exists(path):
            return f'{name}.CAR not written ({s.result})'
    shutil.copy(path, dst)
    open(stamp, 'w').write(md5(os.path.join(exe, 'ITALIAN.EXE')))
    return dst


def nat_letter(s, button):
    """Career menu with a job offer -> OFFERTE LAVORO -> the national offer's row -> the letter -> button (CONSIDERA
    during the season, ACCETTA at its end) -> back to the menu. Returns an error or None."""
    if press(s, s.screen(), 'OFFERTE LAVORO') is None:
        return f'no OFFERTE LAVORO on {s.screen()}'
    scr = s.screen()
    rows = [j for j, g in enumerate(scr.geom) if g[0] == 8 and g[2] == 304 and not scr.entries[j][2]
            and not scr.entries[j][3]]               # one selectable row per offer (as next_season_save)
    if scr.find('OFFERTA DI LAVORO INTERNAZIONALE', exact=False) is None or not rows:
        return f'no national offer on {scr}'
    s.offer = next(t for t in scr.texts() if t.startswith('OFFERTA DI LAVORO INTERNAZIONALE'))
    for _ in range(12):
        if s.screen().selected in rows:
            break
        s.send('up dump:0.5')
    s.send('fire dump:2')
    scr = s.screen()
    s.log.append(f'[letter] {scr}')
    i = scr.find(button, exact=True)
    if i is None or scr.entries[i][3]:
        return f'{button} not available on {scr}'
    press(s, scr, button, wait=3)
    for _ in range(6):
        if 'TRASFERIMENTI' in s.screen().texts() or 'CONTINUA CARRIERA' in s.screen().texts():
            return None
        press(s, s.screen(), 'ESCI') or s.send('fire dump:2')
    return f'after {button}: {s.screen()}'


@scenario
def world8485_nat():
    """Europe 1984-85 world, national teams (England's job by the debug switch; saves W84NAT / W84NAT3 made once per
    build): the real Euro 88 qualifying groups and Euro 88's 8 (host + 7 group winners); with the season index poked
    to the next cycle, the Italia 90 qualifying draw (host out) and its 24 (holder, host, 13 European, direct)"""
    exe = os.environ.get('W8485_BUILD') or builds()['it']       # (builds/w8485 was a stale 3.0-era build)
    off, names = nat_offsets(os.path.join(exe, 'ITALIAN.EXE')), nat_names(exe)
    nm = lambda ws: [names.get(w, hex(w)) for w in ws]
    errs, notes = [], []
    real = [{'SPAIN', 'ROMANIA', 'AUSTRIA', 'ALBANIA'}, {'ITALY', 'SWEDEN', 'PORTUGAL', 'SWITZERLAND', 'MALTA'},
            {'SOVIET UNION', 'EAST GERMANY', 'FRANCE', 'ICELAND', 'NORWAY'},
            {'ENGLAND', 'YUGOSLAVIA', 'NORTHERN IRELAND', 'TURKEY'}, {'HOLLAND', 'GREECE', 'HUNGARY', 'POLAND', 'CYPRUS'},
            {'DENMARK', 'CZECHOSLOVAKIA', 'WALES', 'FINLAND'},
            {'REPUBLIC IRELAND', 'BULGARIA', 'BELGIUM', 'SCOTLAND', 'LUXEMBOURG'}, set()]

    def england(name, season, seasons, lefts=0):
        """Load the save, accept the national offer; returns the Session (open)."""
        car = nat_offer_save(exe, off, name, season, lefts)
        if not car.endswith('.CAR'):
            raise RuntimeError(f'{name}: {car}')
        s = Session(f'world8485_nat_{name}', exe, {name + '.CAR': car}, 'dump:2', 240)
        if s.wait().outcome != 'dump':
            raise RuntimeError(f'START: no first pause ({s.result})')
        s.send('down down down down down fire dump:2')
        s.send('fire dump:3')
        err = nat_letter(s, 'ACCETTA')
        if err:
            raise RuntimeError(err)
        return s

    def season_end(s, label):
        ok, msg = advance(s, season_over, 600)
        if not ok:
            raise RuntimeError(f'{label}: {msg}')
        if s.screen().find('FINISCI STAGIONE', exact=True) is not None:
            press(s, s.screen(), 'FINISCI STAGIONE', wait=3)

    def after_end(s):
        """Season-end menu -> CONTINUA CARRIERA (enabled by a poke when the manager was sacked: only the season-end
        processing matters) -> the first screen after it (the national finalists are chosen there)."""
        for _ in range(6):                        # chairman's notes first
            scr = s.screen()
            i = scr.find('CONTINUA CARRIERA', exact=True)
            if i is not None:
                break
            press(s, scr, 'CONTINUA') or s.send('fire dump:2')
        else:
            raise RuntimeError(f'no CONTINUA CARRIERA on {scr}')
        if scr.entries[i][3]:
            s.poke(s.result.base2 + s.info['menu'] + 0x16 + i * 0x38 + 6, b'\0\0')
            s.send('dump:0.5')
        press(s, s.screen(), 'CONTINUA CARRIERA', wait=3)
        for _ in range(10):                       # chairman's opinion, then the season end runs
            scr = s.screen()
            if 'VISUALIZZA MONDO' in scr.texts() or any(t.startswith('SQUADRA DEL ') for t in scr.texts()):
                break
            press(s, scr, 'CONTINUA') or s.send('fire dump:2')

    def callups(s):
        """National team menu -> SCEGLI SQUADRA -> call-ups (records home leagues, the abroad chooser, the title)."""
        for _ in range(8):                        # from the main menu (after the save): back into the career
            texts = s.screen().texts()
            if 'SCEGLI SQUADRA' in texts:
                break
            press(s, s.screen(), 'CONTINUA CARRIERA' if 'CONTINUA CARRIERA' in texts else 'CONTINUA') \
                or s.send('fire dump:2')
        if press(s, s.screen(), 'SCEGLI SQUADRA') is None:
            raise RuntimeError(f'no SCEGLI SQUADRA on {s.screen()}')
        err = nat_callups(s)
        if err:
            raise RuntimeError(err)

    def new_season(s, label):
        path = next_season_save(s, 'W84NN')
        if not path.endswith('.CAR'):
            raise RuntimeError(f'{label}: {path}')

    with Session('world8485_nat_menu', exe, {}, 'dump:2', 120) as s:   # the coach's nationalities: + YUG, URS, GDR
        if s.wait().outcome != 'dump' or press(s, s.screen(), 'CARRIERA') is None:
            return False, f'START: {s.result}'
        i = s.screen().find('ENG', exact=True)
        seen = []
        if i is not None and press(s, s.screen(), i, wait=0.5) is not None:   # (fire on the field = right)
            for _ in range(5):
                s.send('fire+left dump:0.5')
                seen.append(s.screen().entries[i][1])
        notes.append(f'coach nationalities before ENG: {seen}')
        check(seen[-4:] == ['YUG', 'RFT', 'URS', 'RDT'], f'coach nationalities: {seen}', errs)   # Italian exe
    try:
        with england('W84NAT', None, 2) as s:             # Euro 88
            check(s.offer.endswith(('ENG', 'ENGLAND')), f'offer: {s.offer}', errs)   # (the row's whole name, read
                                                                            # today on 3.3.6 and rc2 alike: no change)
            new_season(s, '1985-86')
            callups(s)
            notes.append(f"call-ups: {getattr(s, 'squad_title', '?')}, home {getattr(s, 'home_leagues', '?')}, "
                         f"abroad {getattr(s, 'abroad', '?')}")
            check('FIRST DIVISION' in getattr(s, 'home_leagues', []), 'England: home call-ups not from the world', errs)
            ab = getattr(s, 'abroad', [])
            check('GERMANIA EST' in ab and 'URSS' in ab and not {'CROAZIA', 'UCRAINA'} & set(ab),
                  f'call-ups abroad: not the world 1984-85 ({ab})', errs)
            season_end(s, '1985-86')
            new_season(s, '1986-87')
            groups = [nm(team_list(s.result, o)) for o in off['ecq']]
            notes.append(f'Euro 88 qualifying {groups}')
            check([set(g) for g in groups] == real, 'Euro 88 qualifying groups are not the real ones', errs)
            season_end(s, '1986-87')
            after_end(s)
            ec = nm(team_list(s.result, off['ec']))
            notes.append(f'Euro 88 {ec}')
            check(len(ec) == 8 and ec[0] == 'WEST GERMANY' and all(sum(t in g for t in ec) == 1 for g in real[:7]),
                  f'Euro 88: {ec}', errs)
            season_end(s, '1987-88 (Euro 88 played)')     # the 8-team format: groups, semi-finals, final
            after_end(s)
            notes.append(f'after Euro 88: {str(s.screen())[:60]}')
            mid = os.path.join(s.run, 'SWOS', 'W84NN.CAR')   # saved at the start of 1986-87 (Euro 88 qualifying)
        with Session('world8485_nat_reload', exe, {'W84NN.CAR': mid}, 'dump:2', 240) as s:   # national career reload
            if s.wait().outcome != 'dump':
                raise RuntimeError(f'reload: no first pause ({s.result})')
            s.send('down down down down down fire dump:2')
            s.send('fire dump:3')
            for _ in range(6):
                if 'VISUALIZZA MONDO' in s.screen().texts():
                    break
                press(s, s.screen(), 'CONTINUA') or s.send('fire dump:2')
            groups = [nm(team_list(s.result, o)) for o in off['ecq']]
            check('ENGLAND' in s.screen().texts() and [set(g) for g in groups] == real,
                  f'reloaded national career: {str(s.screen())[:80]} groups {groups}', errs)
            notes.append(f'reloaded mid-qualifying: {str(s.screen())[:40]}')
        with england('W84GDR', None, 1, lefts=5) as s:   # an East German coach: the GDR job, DDR-Oberliga call-ups
            check(s.offer.endswith(('EAS', 'EAST GERMANY')), f'GDR coach: offer {s.offer}', errs)   # (3 letters, or
                                                                            # the whole name as the screen shows it)
            new_season(s, 'GDR 1985-86')
            callups(s)
            notes.append(f"GDR: {s.offer}, {getattr(s, 'squad_title', '?')}, home clubs {getattr(s, 'home_clubs', '?')}")
            check(getattr(s, 'squad_title', '') == 'SQUADRA DEL EAST GERMANY'      # one league: straight to its clubs
                  and 'DYNAMO DRESDEN' in getattr(s, 'home_clubs', []), 'GDR job / call-ups', errs)
        with england('W84NAT3', 3, 1) as s:               # next cycle: Italia 90
            new_season(s, 'WC 1990 qualifying')
            groups = [nm(team_list(s.result, o)) for o in off['wcq']]
            notes.append(f'WC 1990 qualifying {groups}')
            flat = [t for g in groups for t in g]
            check(len(flat) == len(set(flat)) and 'ITALY' not in flat and len(flat) == 32 and 'ENGLAND' in flat,
                  f'WC 1990 qualifying: {len(flat)} teams', errs)
            season_end(s, 'WC 1990 qualifying')
            after_end(s)
            wc = nm(team_list(s.result, off['wc']))
            notes.append(f'WC 1990 {wc}')
            check(len(wc) == 24 and len(set(wc)) == 24 and wc[0] == 'ITALY' and 'ARGENTINA' in wc,
                  f'WC 1990: {len(wc)} teams', errs)
            season_end(s, '1989-90 (WC 1990 played)')     # 24 teams, 6 groups, best thirds, knockout
            after_end(s)
            holder = nm([struct.unpack('<H', s.result.obj2(off['d6cd0'], 2))[0]])[0]
            notes.append(f'WC 1990 winner (new holder): {holder}')
            check(holder in wc, f'WC 1990 winner {holder} is not one of the 24', errs)
    except RuntimeError as e:
        return False, f'{e}; ' + '; '.join(errs + notes)
    return not errs, '; '.join(errs + notes)


def font_odd_all(texts):
    """The characters of texts the game's menu fonts cannot draw (complist.FONT; 4.0.6: no '&' / '!'), the known
    shipped names of complist.FONT_EXCEPT left out (known, each with its data owner)."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import complist
    out = set()
    for t in texts:
        u = t.upper()
        for n in complist.FONT_EXCEPT:
            u = u.replace(n, '')
        out |= set(u) - complist.FONT
    return sorted(out)


def nop_league_int3(name, src=None):
    """A test copy of src (default builds()['it']; builds-x/<name>_<build>) whose DIYLeagueTournamentMatch `int 3` (the game's own,
    at its start: harmless on a real PC, a trap under the harness's BPINT 3 - a season / league fixture's
    '- PARTITA -') is a NOP, as world_darkblond's."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    src = src or builds()['it']
    b = os.path.join(WORK, 'builds-x', f'{name}_' + os.path.basename(src.rstrip('/')))
    shutil.rmtree(b, ignore_errors=True)
    shutil.copytree(src, b, symlinks=True)
    p = lepatch.LEPatch(os.path.join(b, 'ITALIAN.EXE'))
    d1 = bytes(p.get(1, 0, len(p.le.obj_bytes(1))))
    m = [x.start() for x in re.finditer(rb'\xcc\x8b\x35....\x66\x8b\x46\x02\x66\xa3....\x66\xc7\x05....\x02\x00', d1, re.S)]
    assert len(m) == 1, f'DIYLeagueTournamentMatch int 3 not found once: {m}'
    p.put(1, m[0], b'\x90')
    p.save(os.path.join(b, 'ITALIAN.EXE'))
    return b


def se_vars():
    """shirtedit.sites() of the exe language's original (obj2 offsets: the same in the built exe)."""
    if not hasattr(se_vars, 'v'):
        sys.path.insert(0, os.path.join(ROOT, 'tools'))
        import lepatch
        import shirtedit
        se_vars.v = shirtedit.sites(lepatch.LEPatch(os.path.join(ROOT, 'orig', UI_ORIG)))
    return se_vars.v


def se_team(s):
    """(team record address, [shirt numbers by record slot (32)], pin byte, squad slots in order) of playMatchTeam1Ptr's
    team (the career club: careerNumPlayers slots by currentMatchPlayers, else the 16)."""
    v, r = se_vars(), s.result
    t = struct.unpack('<I', r.read(r.base2 + v['PM1'][1], 4))[0]
    d = r.read(t, 76 + 38 * 32)
    if t == r.base2 + v['CT'][1]:
        n = struct.unpack('<H', r.read(r.base2 + v['CNP'][1], 2))[0]
        sq = list(r.read(r.base2 + v['CMP'][1], n))
    else:
        sq = list(range(16))
    return t, [d[76 + 38 * i + 2] for i in range(32)], d[23], sq


def se_goto(s, i):
    """Move the cursor to entry i (no fire); returns the screen."""
    scr = s.screen()
    for _ in range(12):
        if scr.selected == i:
            return scr
        keys = scr.path(i)
        if not keys:
            return scr
        s.send(' '.join(keys[:4]) + ' dump:1')
        scr = s.screen()
    return scr


@scenario
def shirt_edit():
    """4.0.2 editable shirt numbers (shirtedit.py): JUVEFIX3 play-match screen: LEFT on a row lights the number, UP =
    next free number, typed 2 digits (a used number is swapped), ESC undoes, ENTER ends; the team gets the pin bit; a
    starter <-> bench swap keeps the numbers; saved (.CAR careerTeam at 56192), reloaded: the same numbers"""
    car = os.path.join(SAVES, 'JUVEFIX3.CAR')
    errs, notes = [], []
    with Session('shirt_edit', builds()['it'], {'JUVEFIX3.CAR': car}, 'dump:2', 240) as s:
        if s.wait().outcome != 'dump':
            return False, f'START: no first pause ({s.result})'
        s.send('down down down down down fire dump:2')
        s.send('fire dump:2')
        for _ in range(30):
            scr = s.screen()
            t = scr.texts()
            if 'MOD. TATTICA' in t and 'AVVERSARI' in t:
                break
            if 'PARTITA' in t:
                press(s, scr, 'PARTITA')
            else:
                s.send('fire dump:2')
        else:
            return False, f'no play-match screen ({scr})'
        team, n0, pin0, sq = se_team(s)
        ct = s.result.base2 + se_vars()['CT'][1]
        notes.append(f'team {"careerTeam" if team == ct else hex(team)}, numbers {n0[:16]}, pin {pin0:#x}')
        # row 7 (entry 20): LEFT, UP -> the next free number above
        scr = se_goto(s, 20)
        s.send('left dump:1')
        s.shot('lit')
        before = se_team(s)[1]                         # (after the first edit's one-number-per-player pass)
        check(len({before[i] for i in sq}) == len(sq), f'first edit: numbers not unique {[before[i] for i in sq]}', errs)
        s.send('up dump:1')
        after = se_team(s)[1]
        ch = [i for i in range(32) if before[i] != after[i]]
        check(len(ch) == 1, f'UP: {len(ch)} numbers changed ({before[:16]} -> {after[:16]})', errs)
        if len(ch) == 1:
            k, o, nw = ch[0], before[ch[0]], after[ch[0]]
            used = {before[i] for i in sq if i != k}
            want = next(x for x in list(range(o + 1, 100)) + list(range(1, o)) if x not in used)
            check(nw == want, f'UP: {o} -> {nw}, want {want} (next free)', errs)
            notes.append(f'UP {o} -> {nw}')
            # typed '2' '3': 23 (swapped with its holder if any)
            holder = next((i for i in sq if after[i] == 23 and i != k), None)
            s.send('2 3 dump:1')
            t3 = se_team(s)[1]
            check(t3[k] == 23 and (holder is None or t3[holder] == nw), f'typed 23: {t3[:16]} (holder {holder})', errs)
            # ESC: everything as before the edit
            s.send('esc dump:1')
            t4 = se_team(s)[1]
            check(t4 == before, f'ESC: {[t4[i] for i in sq]} != {[before[i] for i in sq]}', errs)
            # again: LEFT, type 7 (a starter's: swapped), ENTER
            s.send('left dump:1')
            h7 = next((i for i in sq if before[i] == 7 and i != k), None)
            s.send('7 dump:2')                       # (single digit: committed by the timer)
            s.send('enter dump:1')
            t5 = se_team(s)[1]
            check(t5[k] == 7 and (h7 is None or t5[h7] == before[k]), f'typed 7: {t5[:16]} (holder {h7})', errs)
            check(len({t5[i] for i in sq}) == len(sq), f'duplicate numbers {[t5[i] for i in sq]}', errs)
            notes.append(f'typed 7 (holder slot {h7} got {before[k]})')
            pin = se_team(s)[2]
            check(pin & 0x80, f'pin bit not set ({pin:#x})', errs)
            # the cursor moves again (edit over): DOWN goes to row 8
            s.send('down dump:1')
            check(s.screen().selected == 21, f'after ENTER, DOWN: selected {s.screen().selected}', errs)
            # starter (row 8, entry 21) <-> bench (row 12, entry 25): numbers stay with the players
            nb = se_team(s)[1]
            s.send('fire dump:1')
            se_goto(s, 25)
            s.send('fire dump:2')
            na = se_team(s)[1]
            check(na[:16] == nb[:16], f'swap with the bench: numbers {nb[:16]} -> {na[:16]}', errs)
            s.shot('after')
        final = se_team(s)[1]
        notes.append(f'final {[final[i] for i in sq]}')
        for _ in range(10):                            # back to the career menu, then save from the main menu
            scr = s.screen()
            if 'FINISCI STAGIONE' in scr.texts() or 'PARTITA' in scr.texts() and 'TRASFERIMENTI' in scr.texts():
                break
            press(s, scr, 'ESCI') or s.send('fire dump:2')
        press(s, s.screen(), 'ESCI', wait=2)
        press(s, s.screen(), 'SALVA CARRIERA', wait=2)
        s.send(name_entry('shirt1') + ' dump:3')
        game = s.result.game
    path = os.path.join(game, 'SHIRT1.CAR')
    if not os.path.exists(path):
        return False, '; '.join(errs + notes + [f'SHIRT1.CAR not saved ({sorted(os.listdir(game))})'])
    d = open(path, 'rb').read()
    saved = [d[56192 + 76 + 38 * i + 2] for i in range(32)]
    check(saved[:16] == final[:16] or sorted(saved[:16]) == sorted(final[:16]) and saved == final, f'.CAR numbers {saved[:16]}', errs)
    check(d[56192 + 23] & 0x80, f'.CAR pin byte {d[56192 + 23]:#x}', errs)
    # reload: the play-match screen shows the same numbers (no 12..16 renumbering of the bench)
    with Session('shirt_edit2', builds()['it'], {'SHIRT1.CAR': path}, 'dump:2', 240) as s:
        s.wait()
        s.send('down down down down down fire dump:2')
        s.send('fire dump:2')
        for _ in range(30):
            scr = s.screen()
            t = scr.texts()
            if 'MOD. TATTICA' in t and 'AVVERSARI' in t:
                break
            if 'PARTITA' in t:
                press(s, scr, 'PARTITA')
            else:
                s.send('fire dump:2')
        again = se_team(s)[1]
        check(again[:16] == saved[:16], f'reloaded: {again[:16]} != saved {saved[:16]}', errs)
    return not errs, '; '.join(errs + notes)


def sq_vars():
    """squadnum.sites() of the exe language's original (SADC obj1, SQT obj2)."""
    if not hasattr(sq_vars, 'v'):
        se_vars()
        import lepatch
        import squadnum
        sq_vars.v = squadnum.sites(lepatch.LEPatch(os.path.join(ROOT, 'orig', UI_ORIG)))
    return sq_vars.v


def sq_team(s):
    """(the squad screen's team, careerTeam's [shirt numbers by record slot (32)], its pin byte, squad slots in order)."""
    v, r = se_vars(), s.result
    t = struct.unpack('<I', r.read(r.base2 + sq_vars()['SQT'][1], 4))[0]
    ct = r.base2 + v['CT'][1]
    d = r.read(ct, 76 + 38 * 32)
    n = struct.unpack('<H', r.read(r.base2 + v['CNP'][1], 2))[0]
    return t, [d[76 + 38 * i + 2] for i in range(32)], d[23], list(r.read(r.base2 + v['CMP'][1], n))


def sq_rows(s):
    """The squad screen's player rows (after-draw SquadAfterDrawCommon)."""
    r = s.result
    m = r.base2 + s.info['menu']
    return [i for i in range(s.screen().n)
            if struct.unpack('<I', r.read(m + 0x16 + i * 0x38 + 0x34, 4))[0] == r.base1 + sq_vars()['SADC'][1]]


def sq_open(s):
    """Career menu -> SQUADRA (the club's squad screen); True when its rows are there."""
    for _ in range(10):
        scr = s.screen()
        t = scr.texts()
        if 'SQUADRA' in t and 'PARTITA' in t:
            press(s, scr, 'SQUADRA', 2)
            return bool(sq_rows(s))
        s.send('fire dump:2')
    return False


@scenario
def squad_numbers():
    """4.0.6 (Marco) editable shirt numbers on the club's squad screen (squadnum.py: shirtedit's editor there): JUVEFIX3
    career, SQUADRA: LEFT on a row lights the number, UP = next free, typed 23 (its holder swapped), ESC undoes, typed 7
    + ENTER (swap, the pin bit), the cursor moves again, a starter <-> bench swap keeps the numbers; saved (.CAR
    careerTeam at 56192) and reloaded: the squad screen shows the same numbers. Shots squad / lit / after (numcol: the
    name bar x 26, the number column x 14). Another club's squad there (VISUAL. COMPETIZ. > SERIE A > STAT > VIS. SQUADRE > CAGLIARI): LEFT, UP,
    23 change nothing"""
    car = os.path.join(SAVES, 'JUVEFIX3.CAR')
    errs, notes = [], []
    with Session('squad_numbers', builds()['it'], {'JUVEFIX3.CAR': car}, 'dump:2', 300) as s:
        if s.wait().outcome != 'dump':
            return False, f'START: no first pause ({s.result})'
        s.send('down down down down down fire dump:2')
        s.send('fire dump:2')
        if not sq_open(s):
            return False, f'no squad screen ({s.screen()})'
        ct = s.result.base2 + se_vars()['CT'][1]
        team, n0, pin0, sq = sq_team(s)
        rows = sq_rows(s)
        check(team == ct and rows == list(range(28, 45)), f'squad screen: team {team:#x} (careerTeam {ct:#x}), rows {rows}',
              errs)
        notes.append(f'numbers {[n0[i] for i in sq]}, pin {pin0:#x}')
        s.shot('squad')
        scr = se_goto(s, 35)                           # row 7: LEFT, UP -> the next free number above
        s.send('dump:1')
        s.send('left dump:1')
        s.shot('lit')
        before = sq_team(s)[1]
        check(len({before[i] for i in sq}) == len(sq), f'first edit: numbers not unique {[before[i] for i in sq]}', errs)
        s.send('up dump:1')
        after = sq_team(s)[1]
        ch = [i for i in range(32) if before[i] != after[i]]
        check(len(ch) == 1, f'UP: {len(ch)} numbers changed ({before[:20]} -> {after[:20]})', errs)
        if len(ch) == 1:
            k, o, nw = ch[0], before[ch[0]], after[ch[0]]
            used = {before[i] for i in sq if i != k}
            want = next(x for x in list(range(o + 1, 100)) + list(range(1, o)) if x not in used)
            check(nw == want, f'UP: {o} -> {nw}, want {want} (next free)', errs)
            notes.append(f'UP {o} -> {nw}')
            holder = next((i for i in sq if after[i] == 23 and i != k), None)
            s.send('2 3 dump:1')
            t3 = sq_team(s)[1]
            check(t3[k] == 23 and (holder is None or t3[holder] == nw), f'typed 23: {t3[:20]} (holder {holder})', errs)
            s.shot('typed23')
            s.send('esc dump:1')
            t4 = sq_team(s)[1]
            check(t4 == before, f'ESC: {[t4[i] for i in sq]} != {[before[i] for i in sq]}', errs)
            check(s.screen().find('PRATICA', exact=True) is not None, f'ESC left the squad screen ({s.screen()})', errs)
            s.send('left dump:1')
            h7 = next((i for i in sq if before[i] == 7 and i != k), None)
            s.send('7 dump:2')                         # (single digit: committed by the timer)
            s.send('enter dump:1')
            t5 = sq_team(s)[1]
            check(t5[k] == 7 and (h7 is None or t5[h7] == before[k]), f'typed 7: {t5[:20]} (holder {h7})', errs)
            check(len({t5[i] for i in sq}) == len(sq), f'duplicate numbers {[t5[i] for i in sq]}', errs)
            notes.append(f'typed 7 (holder slot {h7} got {before[k]})')
            check(sq_team(s)[2] & 0x80, f'pin bit not set ({sq_team(s)[2]:#x})', errs)
            s.send('down dump:1')
            check(s.screen().selected == 36, f'after ENTER, DOWN: selected {s.screen().selected}', errs)
            nb = sq_team(s)[1]                         # starter (row 8) <-> bench (row 12): numbers stay
            s.send('fire dump:1')
            se_goto(s, 40)
            s.send('fire dump:2')
            na = sq_team(s)[1]
            check(na == nb, f'swap with the bench: numbers {nb[:20]} -> {na[:20]}', errs)
            s.shot('after')
        final = sq_team(s)[1]
        notes.append(f'final {[final[i] for i in sq]}')
        for _ in range(10):                            # back to the career menu, then save from the main menu
            scr = s.screen()
            if 'FINISCI STAGIONE' in scr.texts() or 'PARTITA' in scr.texts() and 'TRASFERIMENTI' in scr.texts():
                break
            press(s, scr, 'ESCI') or s.send('fire dump:2')
        press(s, s.screen(), 'ESCI', wait=2)
        press(s, s.screen(), 'SALVA CARRIERA', wait=2)
        s.send(name_entry('squadn1') + ' dump:3')
        game = s.result.game
    path = os.path.join(game, 'SQUADN1.CAR')
    if not os.path.exists(path):
        return False, '; '.join(errs + notes + [f'SQUADN1.CAR not saved ({sorted(os.listdir(game))})'])
    d = open(path, 'rb').read()
    saved = [d[56192 + 76 + 38 * i + 2] for i in range(32)]
    check(saved == final, f'.CAR numbers {saved[:20]} != {final[:20]}', errs)
    check(d[56192 + 23] & 0x80, f'.CAR pin byte {d[56192 + 23]:#x}', errs)
    with Session('squad_numbers2', builds()['it'], {'SQUADN1.CAR': path}, 'dump:2', 300) as s:
        s.wait()
        s.send('down down down down down fire dump:2')
        s.send('fire dump:2')
        if not sq_open(s):
            return False, '; '.join(errs + notes + [f'reloaded: no squad screen ({s.screen()})'])
        again = sq_team(s)[1]
        check(again == saved, f'reloaded: {again[:20]} != saved {saved[:20]}', errs)
        s.shot('reloaded')
        press(s, s.screen(), 'ESCI', 2)                # another club's squad on the same screen: read-only
        vis = 'CAGLIARI'
        for t in ('VISUAL. COMPETIZ.', 'ITALIA SERIE A', 'STAT', 'VIS. SQUADRE', vis):
            if press(s, s.screen(), t, 2) is None:
                errs.append(f'{t} not found ({s.screen()})')
                break
        else:
            team, b0, _, _ = sq_team(s)
            rows = sq_rows(s)
            check(team != ct and rows, f'{vis} squad: team {team:#x}, rows {rows}', errs)
            if rows:
                se_goto(s, rows[7])
                s.send('dump:1')
                od = s.result.read(team, 76 + 38 * 16)
                s.send('left dump:1')
                s.send('up dump:1')
                s.send('2 3 dump:2')
                s.send('enter dump:1')
                nd = s.result.read(team, 76 + 38 * 16)
                check(nd == od, f'{vis} squad: LEFT / UP / 23 changed its record', errs)
                check(sq_team(s)[1] == saved, f'{vis} squad: careerTeam changed', errs)
                s.shot('opponent')
                notes.append(f'{vis} squad: unchanged')
    return not errs, '; '.join(errs + notes)


def se_to_playmatch(s, tries=12):
    """From a season / career menu to the team screen before the next match (MOD. TATTICA + AVVERSARI); the screen."""
    for _ in range(tries):
        scr = s.screen()
        t = scr.texts()
        if 'MOD. TATTICA' in t and 'AVVERSARI' in t:
            return scr
        if '- PARTITA -' in t:
            press(s, scr, '- PARTITA -', 2)
        elif 'PARTITA' in t:
            press(s, scr, 'PARTITA', 2)
        else:
            s.send('fire dump:2')
    return None


def se_rows(s):
    """The entries drawn by DrawPlayerEntries (the player rows)."""
    v, r = se_vars(), s.result
    m = r.base2 + s.info['menu']
    return [i for i in range(s.screen().n)
            if struct.unpack('<I', r.read(m + 0x16 + i * 0x38 + 0x34, 4))[0] == r.base1 + v['DPE'][1]]



MARCO_LAZIO = {'MARCHEGIANI': 1, 'CUDICINI': 22, 'NEGRO': 2, 'GOTTARDI': 17, 'FAVALLI': 5, 'NESTA': 13, 'CHAMOT': 6,
               'FISH': 3, 'RAMBAUDI': 7, 'MARCOLIN': 4, 'NEDVED': 18, 'OKON': 16, 'FUSER': 14, 'SIGNORI': 11,
               'CASIRAGHI': 9, 'PROTTI': 10}


@scenario
def shirt_marco():
    """4.0.5 (Marco Malave, 29/10): LAZIO numbered in an external editor (AG-SWSEDT 2.5.4: 22 / 17 / 18 ... - no pin
    bit) keeps them in a FRIENDLY: the team screen shows starters 1 2 13 6 5 7 16 14 18 11 9 and the bench 22 17 3 4 10
    (benchnum bn_big: a player above 16 = real squad numbers, SetBenchPlayersNumbers skipped; before: 12..16), and the
    first number edit (Nesta's row: LEFT, UP, ENTER - shirtedit se_unique runs at LEFT; it walked the file's record
    order and gave Nesta 3, Fuser 4, Protti 8) changes Nesta's number only, the team pinned"""
    b = builds()['it']
    src = os.path.join(b, 'DATA', 'TEAM.020')
    d = bytearray(open(src, 'rb').read())
    for t in range(struct.unpack('>H', d[:2])[0]):
        o = 2 + t * 684
        if d[o + 5:o + 22].split(b'\0')[0] == b'LAZIO':
            for k in range(16):
                nm = d[o + 76 + k * 38 + 3:o + 76 + k * 38 + 26].split(b'\0')[0].decode('latin1').split()[-1]
                d[o + 76 + k * 38 + 2] = MARCO_LAZIO[nm]
    team = os.path.join(WORK, 'saves', 'TEAM020_MARCO.BIN')
    os.makedirs(os.path.dirname(team), exist_ok=True)
    open(team, 'wb').write(d)
    errs, notes = [], []
    with Session('shirt_marco', b, {'DATA/TEAM.020': team}, 'dump:3', 300) as s:
        s.wait()
        for t in ('AMICHEVOLE', 'OK', 'SCEGLI SQUADRE', 'SQUADRE CLUB', 'EUROPA', 'ITALIA', 'SERIE A', 'LAZIO'):
            walk(s, t, 2)
        s.send('fire dump:2')                   # LAZIO: COMPUTER -> GIOCA-ALLENA (human)
        walk(s, 'ROMA', 2)
        for _ in range(12):                     # GIOCA AMICHEVOLE (entry 55)
            scr = s.screen()
            if scr.selected == 55:
                s.send('fire dump:4')
                break
            s.send(('right' if scr.selected in (56, 57) else 'down') + ' dump:0.5')
        scr = s.screen()
        if 'MOD. TATTICA' not in scr.texts():
            return False, f'no team screen: {scr}'
        s.shot('team')

        def lineup():
            t_, n, pin, _ = se_team(s)
            order = list(s.result.read(t_ + 60, 16))
            return [n[i & 15] for i in order], pin
        l0, p0 = lineup()
        want = [1, 2, 13, 6, 5, 7, 16, 14, 18, 11, 9, 22, 17, 3, 4, 10]
        check(l0 == want, f'team screen: {l0} (want {want})', errs)
        rows = se_rows(s)
        se_goto(s, rows[2])                     # (Nesta's row) the first edit: LEFT lights his number (se_unique
        s.send('dump:1')                        # runs then), UP = the next free number, ENTER ends
        s.send('left dump:1')
        s.send('up dump:1')
        s.send('enter dump:1')
        l1, p1 = lineup()
        s.shot('after_edit')
        check(l1[:2] + l1[3:] == want[:2] + want[3:] and l1[2] not in want and p1 & 0x80,
              f'after the first edit (Nesta UP): {l1}, pin {p1:#x}', errs)
        notes.append(f'{l0} -> {l1}, pin {p0:#x} -> {p1:#x}')
    return not errs, '; '.join(errs + notes)


def numgap_check(s, tag, errs, info):
    """(4.0.6, Davide 02/11) the shirt-number column on the current squad list (squad screen, team screen, tactics
    editor; numcol.py): in every row the number's ink (2 white, 8 shadow) keeps 1 column clear after the face box
    (its template entry, 12 x 8, left of the number's 10 x 8) and 1 before the name bar (the row entries; Davide 03/11:
    names +2 px on the lists); the frame saved as shot `tag`. Returns the rows checked and the two-digit ones (ink 9+ px wide)."""
    scr = s.screen()
    vga = s.result.read(0xA0000, 64000)
    s.shot(tag)
    num = [g for g in scr.geom if g[2:] == (10, 8)]
    if not num:
        errs.append(f'{tag}: no number column (10 x 8 entry)')
        return 0, 0
    nx = num[0][0]
    face = [g[0] for g in scr.geom if g[2:] == (12, 8) and g[0] < nx]
    names = [g for g in scr.geom if g[3] == 8 and g[2] in (79, 80, 81, 82, 131, 132, 134) and g[0] > nx]
    if not names:
        errs.append(f'{tag}: no name rows')
        return 0, 0
    fr, mx = (max(face) + 11 if face else nx - 2), min(g[0] for g in names)   # (no face box: the column's left only)
    bad, two, n, gaps = [], 0, 0, set()
    for y in sorted({g[1] for g in names}):
        ink = [x for x in range(fr + 1, mx) for yy in range(y, y + 8) if 0 <= yy < 200 and vga[yy * 320 + x] in (2, 8)]
        if not ink:
            continue
        n += 1
        two += max(ink) - min(ink) >= 8
        gaps.add((min(ink) - fr - 1 if face else None, mx - 1 - max(ink)))
        if (face and min(ink) < fr + 2) or max(ink) > mx - 2:
            bad.append((y, min(ink), max(ink)))
    check(n and not bad, f'{tag}: number ink touching the face box (last column {fr}) or the name bar (x {mx}): '
                         f'(row y, ink x0, x1) {bad[:6]} of {n} rows', errs)
    info.append(f'{tag}: {n} numbered rows ({two} two-digit), face box ends x {fr if face else None}, number column x '
                f'{nx}, names x {mx}' + f', columns clear (face, bar) {sorted(gaps, key=str)}')
    return n, two


@scenario
def squad_numgap():
    """4.0.6 (Davide 02/11, MiSTer): two-digit shirt numbers clear of the face box and the name bar (numcol.py: the
    number column x 14, the names 2 px right on the lists) on the club's squad screen, the team screen and the tactics editor. A new
    World 2026-27 ROMA career (99 SVILAR, 43, 86, 61...) on NUMGAP_BUILD (a release build, its ITALIAN.EXE = the
    language's exe) -> SQUADRA (numgap_check) -> PRATICA/TRAINING (the team screen) -> MOD. TATTICA (the tactics
    editor, the first user tactic: UTN A / USER_A / UTIL A / SPIEL A). Any SWOSTEST_UI (the labels as UI_MAP reads them back). Shots squad / team / tactics."""
    b = os.environ.get('NUMGAP_BUILD')
    if not b or not os.path.isdir(b):
        return True, 'SKIP: NUMGAP_BUILD not set'
    errs, info = [], []
    lbl = lambda k: {TRAIN_TXT.get(UI, TRAIN_TXT['it'])[k], TRAIN_TXT['it'][k]}

    def go(names, where):
        scr = s.screen()
        t = next((x for x in names if scr.find(x, exact=True) is not None), None)
        if t is None or press(s, scr, t, 3) is None:
            errs.append(f'{where}: {sorted(names)} not reached ({scr.texts()[:14]})')
            return False
        return True
    with Session('squad_numgap', b, {}, 'dump:2', 600) as s:
        if s.wait().outcome != 'dump':
            return False, f'START: no first pause ({s.result})'
        for t in ('CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27'):
            if press(s, s.screen(), t) is None:
                return False, f'new career: {t} not reached ({s.result})'
        if not pick_career(s, 'EUROPA,ITALIA,SERIE A,ROMA'.split(',')):
            return False, f'new career: ROMA not reached ({s.result})'
        s.send('fire dump:2')                   # (the chairman's note)
        if go(lbl(0), 'career menu'):
            n, two = numgap_check(s, 'squad', errs, info)
            check(two >= 3, f'squad: {two} two-digit numbers seen (ROMA has 99, 43, 86...)', errs)
            if go(lbl(1), 'squad screen'):
                numgap_check(s, 'team', errs, info)
                if go({'MOD. TATTICA'}, 'team screen') and go({'UTN A', 'USER_A', 'UTIL A', 'SPIEL A'}, 'tactics menu'):
                    numgap_check(s, 'tactics', errs, info)
    return not errs, '; '.join(errs + info)


@scenario
def shirt_edit_season():
    """4.0.2 editable shirt numbers in a SEASON (CLASSIC SEASONS Italy 1947-48, JUVENTUS played by the human): a row's
    number UP + typed 27, the pin bit; SALVA STAGIONE, reloaded (CARICA VECCHIA COMPETIZIONE): the team screen shows the
    same numbers, still pinned"""
    b = nop_league_int3('shirt_edit_season')
    errs, notes = [], []
    with Session('shirt_edit_season', b, {}, 'dump:2', 300) as s:
        s.wait()
        for t in ('STAGIONE', 'STAG. STORICHE', 'ITALIA 1947-48', 'JUVENTUS'):
            if press(s, s.screen(), t, 2) is None:
                return False, f'{t} not reached ({s.result})'
        for _ in range(14):                     # the STAGIONE button, right of ABBANDONA
            scr = s.screen()
            if scr.entries[scr.selected][1] == 'STAGIONE':
                break
            s.send(('right' if scr.entries[scr.selected][1] == 'ABBANDONA' else 'down') + ' dump:0.5')
        s.send('fire dump:3')
        if se_to_playmatch(s) is None:
            return False, f'no team screen ({s.screen()})'
        rows = se_rows(s)
        check(len(rows) == 17, f'{len(rows)} player rows', errs)
        _, n0, p0, sq = se_team(s)
        se_goto(s, rows[5])
        s.send('left dump:1')
        s.send('up dump:1')
        s.send('2 7 dump:1')
        s.send('enter dump:1')
        _, n1, p1, _ = se_team(s)
        ch = [i for i in sq if n0[i] != n1[i]]
        check(27 in [n1[i] for i in sq] and len({n1[i] for i in sq}) == 16 and p1 & 0x80,
              f'edit: {[n1[i] for i in sq]} pin {p1:#x}', errs)
        notes.append(f'{[n0[i] for i in sq]} -> {[n1[i] for i in sq]}')
        for _ in range(6):
            scr = s.screen()
            if 'SALVA STAGIONE' in scr.texts():
                break
            press(s, scr, 'ESCI', 2) or s.send('fire dump:2')
        press(s, s.screen(), 'SALVA STAGIONE', 2)
        s.send(name_entry('shirts') + ' dump:3')
        game = s.result.game
    saves = [f for f in os.listdir(game) if f.upper().endswith('.SEA')]
    if not saves:
        return False, '; '.join(errs + notes + [f'no .SEA saved ({sorted(os.listdir(game))})'])
    path = os.path.join(game, saves[0])
    with Session('shirt_edit_season2', b, {saves[0]: path}, 'dump:2', 300) as s:
        s.wait()
        press(s, s.screen(), 'CARICA VECCHIA COMPETIZIONE', 2)
        if press(s, s.screen(), 'SHIRTS', 3, exact=False) is None:
            return False, '; '.join(errs + notes + [f'reload: SHIRTS not listed ({s.screen()})'])
        if se_to_playmatch(s) is None:
            return False, '; '.join(errs + notes + [f'reload: no team screen ({s.screen()})'])
        _, n2, p2, _ = se_team(s)
        check([n2[i] for i in sq] == [n1[i] for i in sq] and p2 & 0x80, f'reloaded: {[n2[i] for i in sq]} pin {p2:#x}', errs)
    return not errs, '; '.join(errs + notes)


@scenario
def save_devname():
    """4.0.2: DOS device names refused as save names (devname.py): JUVE2F loaded, SALVA CARRIERA as CON / NUL / LPT1 /
    COM1 / AUX.. (an extension too: the dialog adds .CAR) -> the error box, no file; then DEVOK is saved"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import devname
    msg = devname.MSG[UI]
    errs, notes = [], []
    with Session('save_devname', builds()['it'], {'JUVE2F.CAR': juve2(True)}, f'{LOAD1} dump:2', 120) as s:
        if s.wait().outcome != 'dump':
            return False, f'START: no first pause ({s.result})'
        s.send(quit_and_save('con') + ' dump:2')
        for k, name in enumerate(('nul', 'lpt1', 'com1', 'aux', 'prn')):
            scr = s.screen() if s.result.outcome == 'dump' else None
            check(scr is not None and msg in scr.texts(), f'{"con" if not k else prev}: no "{msg}" box ({scr})', errs)
            if scr is None:
                break
            if k == 0:
                s.shot('box')
            prev = name
            s.send('fire:2 dump:2')                       # the box's CONTINUA: back to the dialog
            scr = s.screen()
            if k == 0:
                notes.append(f'after the box: {scr.texts()[-4:]}')
            s.send(name_entry(name)[len('up:2 '):] + ' dump:2')   # (the cursor is back on the name field)
        scr = s.screen() if s.result.outcome == 'dump' else None
        check(scr is not None and msg in scr.texts(), f'prn: no "{msg}" box ({scr})', errs)
        s.send('fire:2 dump:2')
        s.send(name_entry('devok')[len('up:2 '):] + ' dump:3')
        game = s.result.game
        scr = s.screen() if s.result.outcome == 'dump' else None
        notes.append(f'after DEVOK: {scr}')
    files = sorted(os.listdir(game))
    bad = [f for f in files if f.split('.')[0] in ('CON', 'NUL', 'LPT1', 'COM1', 'AUX', 'PRN')]
    check(not bad, f'device-named files {bad}', errs)
    check('DEVOK.CAR' in files, f'DEVOK.CAR not saved ({files})', errs)
    return not errs, '; '.join(errs + notes)


@scenario
def roundtrip():
    """Load/save round trip: JUVE2F loaded + saved from the main menu (ROUNDT1), reloaded + saved (ROUNDT2) = ROUNDT1"""
    err, x1, x2 = two_saves('roundtrip', builds()['it'], juve2(True))
    if err:
        return False, err
    n, info = ndiff(x1, x2), car_info(x2)
    return n == 0 and info['sum'] == 0, f'save 1 vs 2: {n} bytes differ, table sum {info["sum"]}'


@scenario
def world_roundtrip():
    """World 3 (31 countries, euro 128): W128B load/save twice; saves equal, W1 block, 128 records, cups 32/32/64"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import careerworld
    src = os.path.join(SAVES, 'W128B.CAR')
    err, x1, x2 = two_saves('world_roundtrip', world_build(), src, 150)
    if err:
        return False, err
    d = open(x2, 'rb').read()
    errs = []
    info = car_info(x2)
    check(info['world'] == 3 and info['sum'] == 0, f"world byte {info['world']}, table sum {info['sum']}", errs)
    check(d[2:4] == struct.pack('<H', careerworld.WMARK), 'no W1 block', errs)
    check(struct.unpack_from('<H', d, 0)[0] == 128, f'{struct.unpack_from("<H", d, 0)[0]} euro records', errs)
    for cup, off, n in (('CC', 0, 32), ('CWC', 92, 32), ('UEFA', 184, 64)):
        c = d[4 + off:4 + off + (160 if cup == 'UEFA' else 92)]
        lst = c[c[7] + 7:c[7] + 7 + 2 * c[10]]
        pairs = {(lst[i], lst[i + 1]) for i in range(0, len(lst), 2)}
        check(c[10] == n and len(pairs) == n, f'{cup}: {c[10]} clubs, {len(pairs)} distinct', errs)
    check(ndiff(x1, x2) == 0, f'save 1 vs 2: {ndiff(x1, x2)} bytes differ', errs)
    return not errs, f"{'; '.join(errs) or 'ok'} (vs W128B as written by its own build: {ndiff(src, x1)} bytes differ)"


@scenario
def w84_cache():
    """3.3.3: the 1984-85 world's team cache. W84E_TEAM254.CAR (Liverpool 1984-85, season end: league 22 + FA Cup 64
    + UEFA Cup 64 = 124 cached teams; 3.3.2 exits to DOS with data/team.254) -> CONTINUA CARRIERA -> the next season
    saved in the big cache (more than 100 records, BIGC); that save reloaded and saved twice: equal, BIGC kept; an old
    save (W84A.CAR, 3.0) reloaded and saved twice: equal, no BIGC (the game's cache)"""
