@scenario
def world_uq_nextmatch():
    """4.0.3 (Regia, the 4.0.2 queue: the calendar's qualifying rows after a drop): as world2627q (AJAX, CL Q1 forced,
    simdraw; on the 4.0.3 data AJAX loses CL Q1 on penalties and drops into the CONFERENCE LEAGUE Q2) with, at each of
    season 2's first career menus, PROSS. PARTITA opened and read (then ESCI): the next fixture before every leg of a
    qualifying tie must name that tie (PRELIM. + the competition actually played: CL, then the one it dropped into);
    reported: the next-match screens' titles in order"""
    seen, errs = [], []

    def hook(s, season, scr):
        if season != 2 or len(seen) >= 8 or scr is None or scr.find('TRASFERIMENTI') is None:
            return
        r = press(s, scr, 'PROSS. PARTITA')
        if r is None:
            return
        nx = s.screen()
        seen.append(nx.entries[0][1] if nx.entries else '?')
        if nx.find('ESCI') is not None:
            press(s, nx, 'ESCI')

    ok, msg, ties = q27_run(hook)
    if ok is None:
        return True, msg
    check(ok, msg, errs)
    pre = [t for t in seen if t.startswith('PRELIM.')]
    check(any('CHAMPIONS' in t for t in pre), f'no CL qualifying fixture announced: {seen}', errs)
    drop = [t for t in ties if 'CHAMPIONS' not in t]
    if drop:
        cup = drop[0].split()[1]
        check(any(cup in t for t in pre), f'the tie after the drop ({drop[0]}) never announced: {seen}', errs)
    return not errs, '; '.join(errs) or f'next-match titles {seen}; ties {ties}'


@scenario
def world_uq_early():
    """4.0.1 (Pietro's polish): the next UEFA qualifying tie is built as soon as the return leg is decided (uefaq's
    uq_daily also at the end of the day played), so the career calendar lists it at once, not only after PARTITA. As
    world2627q (AJAX, CL Q1 forced, simdraw: the ties won); at every career menu of season 2 slot 3 (arrayOfPointers)
    and the calendar: a qualifying tie whose winner is the career club may never be on the menu (its next tie, or the
    league phase, already in slot 3), and the menu after each won return leg shows the next tie's calendar days ahead"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import split
    import lepatch
    sp = split.sites(lepatch.LEPatch(os.path.join(MAIN, 'orig', 'ITALIAN.EXE')))['SLOTS']
    qids = (0x7C, 0x7D, 0x7E)                                  # (uefaq.QIDS)
    menus, errs = [], []

    def hook(s, season, scr):
        if season != 2 or scr is None or scr.find('TRASFERIMENTI') is None or scr.find('PROSS. PARTITA') is None:
            return
        lin = struct.unpack('<I', s.result.obj2(sp + 12, 4))[0]
        if not lin:
            return
        d = s.result.read(lin, 0x450)
        sid, date, win = d[0x2D], d[0x37], struct.unpack_from('<H', d, 0x39)[0]   # (+37h: the first leg's date)
        cal = s.result.obj2(CAL_AT - 8, 3000)
        cur, n = struct.unpack_from('<H', cal, 2)[0], struct.unpack_from('<H', cal, 4)[0]
        o, ahead = 8 + cur, 0
        for _ in range(n):                                     # slot-3 match days from the current entry on
            if o + 9 > len(cal):
                break
            ln_ = struct.unpack_from('<H', cal, o + 2)[0]
            if not ln_:
                break
            ahead += cal[o] == 3 and cal[o + 7] != 0xFF
            o += ln_
        menus.append((sid, date, win, ahead))
        open(os.path.join(s.run, 'uq_menus.log'), 'a').write(f'{sid:#x} {date:#x} {win:#x} ahead {ahead}\n')

    ok, msg, ties = q27_run(hook)
    if ok is None:
        return True, msg
    check(ok, msg, errs)
    check(len(ties) >= 2, f'ties played {ties}', errs)
    qs = [i for i, m in enumerate(menus) if m[0] in qids]
    late = [menus[i] for i in qs if menus[i][2] != 0xFFFF and any(x[:2] != menus[i][:2] for x in menus[i + 1:])]
    check(not late, f'a decided qualifying tie still in slot 3 on the menu, the next contest built only later: '
                    f'{[tuple(hex(x) for x in m) for m in late[:3]]}', errs)
    check(all(menus[i][3] for i in qs if menus[i][2] == 0xFFFF), 'a qualifying tie on the menu with no calendar day '
          f'ahead: {[tuple(hex(x) for x in menus[i]) for i in qs if menus[i][2] == 0xFFFF and not menus[i][3]][:3]}', errs)
    seen = list(dict.fromkeys((hex(m[0]), hex(m[1])) for m in menus))
    return not errs, '; '.join(errs) or f'{msg[:160]}; ties played {ties}; slot 3 on the menus {seen} ({len(menus)} menus)'


SLOW_FIRE = 0                           # (seconds more after walk / gwalk's fire: SWOS++'s timer keys, world_cgame_swospp)


def gwalk(s, text, w=3, tries=40):
    """Select the entry showing text by geometry, then fire (the team / competition picker: its links pass through
    hidden entries the game skips by position - walk's planner finds no path to the cup buttons above the nations,
    the stock MONDO screen's UEFA cups too); returns the new screen."""
    for _ in range(tries):
        scr = s.screen()
        i = scr.find(text, exact=True)
        if i is None:
            raise AssertionError(f'{text} not on screen ({scr.texts()[:16]})')
        if scr.selected == i:
            s.send(f'fire dump:{w + SLOW_FIRE}')
            return s.screen()
        (x0, y0, w0, h0), (x1, y1, w1, h1) = scr.geom[scr.selected], scr.geom[i]
        k = 'up' if y1 + h1 <= y0 else 'down' if y1 >= y0 + h0 else 'left' if x1 < x0 else 'right'
        s.send(k + ' dump:0.5')
    raise AssertionError(f'gwalk: {text} not reached ({s.screen()})')


def walk(s, target, w=3, tries=20, stays=48):
    """Select entry `target` (text or number) one key at a time, re-planning after each move (menus where a planned
    path drifts: two-column lists, moves taken twice), then fire; returns the new screen. A key that leaves the cursor
    where it was (4.0.5 long bench: down on row 17 / up on row 12 scroll the player list's window - ViewSquad of a
    32-player squad, world_transfer_sale rc14p) is not counted in tries: the next plan goes around it if it can, else
    the same key again (at the window's end the cursor moves), at most `stays` times."""
    bad, n = set(), 0
    while n < tries:
        scr = s.screen()
        i = scr.find(target) if isinstance(target, str) else target
        if i is None:
            raise AssertionError(f'{target} not on screen ({scr.texts()[:16]})')
        if scr.selected == i:
            s.send(f'fire dump:{w + SLOW_FIRE}')
            return s.screen()
        p = scr.path(i, frozenset(bad)) or scr.path(i)
        if not p:
            raise AssertionError(f'no path to {target} from {scr.selected}')
        s.send(p[0] + ' dump:0.5')
        if s.screen().selected == scr.selected and stays > 0:
            bad.add((scr.selected, p[0]))
            stays -= 1
        else:
            n += 1
    raise AssertionError(f'{target} not reached')


def career_entry(s, t):
    """walk() target for a menu label: the main menu's original CARRIERA (1996-97 career) when a release build also
    has the green 'CARRIERA 2026-27' button (4.0 mainbtn), which a plain 'CARRIERA' would pick first."""
    if t == 'CARRIERA':
        i = s.screen().find('CARRIERA', exact=True)
        return t if i is None else i
    return t


def friendly_prematch(s, home, away):
    """Main menu -> AMICHEVOLE with two Bundesliga clubs (player-controlled) -> pre-match screen."""
    for t in ('AMICHEVOLE', 'OK', 'SCEGLI SQUADRE', 'SQUADRE CLUB', 'EUROPA', 'GERMANIA', '1. LIGA', home, away):
        walk(s, t, 2)
    for _ in range(12):                         # AMICHEVOLE (55) is reached from the list by down, then right (56, 57)
        scr = s.screen()
        if scr.selected == 55:
            s.send('fire dump:4')
            return s.screen()
        s.send(('right' if scr.selected in (56, 57) else 'down') + ' dump:0.5')
    raise AssertionError('AMICHEVOLE not reached')


