@scenario
def swospp_menu():
    """4.0.5 (Davide 30/10, option 2): under SWOS++ the green CAREER 2026-27 button keeps entry 4 and SWOS++'s own entry
    is shown through entry 11 (SAVE) while no contest is loaded, at SWOS++'s place (top). SWOSPP_BUILD (a World 2026-27
    release-recipe dir whose ITALIAN.EXE is the English exe) + SWOS++ 1.9.2.2: (1) the main menu: entry 4 the button,
    entry 11 SWOS++ at x 93 y 21; (2) SWOS++'s menu opens from it and ESC comes back to the main menu; (3) a career
    loaded (W84E): CONTINUE / SAVE shown, entry 11 not SWOS++, SAVE opens its screen; (4) DIY COMPETITION > ABANDON:
    the SWOS++ entry is back"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import swospp
    if UI != 'en':
        return True, 'SKIP: SWOS++ is English only (SWOSTEST_UI=en)'
    b = os.environ.get('SWOSPP_BUILD')
    if not b or not os.path.isdir(b):
        return True, 'SKIP: SWOSPP_BUILD not set'
    pp = os.path.join(MAIN, 'internal', 'swospp-test')
    out = os.path.join(WORK, 'builds-x', 'swospp_menu')
    shutil.rmtree(out, ignore_errors=True)
    shutil.copytree(b, out)
    swospp.install(os.path.join(b, 'ITALIAN.EXE'), os.path.join(out, 'ITALIAN.EXE'))
    errs, info = [], []

    def menu(s, tag):
        r, m = s.result, s.info['menu']
        e = {i: ct_entry(r, m, i) for i in (4, 10, 11)}
        info.append(f'{tag}: 4 {e[4][0].decode()!r} 10 {e[10][0].decode()!r}{"(inv)" if e[10][1] else ""} '
                    f'11 {e[11][0].decode()!r}{"(inv)" if e[11][1] else ""} at {e[11][2]},{e[11][3]}')
        return e

    def is_main(s):                                     # (the menu buffer's address is fixed: the main menu by its entries)
        t = [x[1] for x in s.screen().entries]
        return 'MOD. TATTICA' in t and 'COMPET. PERSONAL.' in t
    with Session('swospp_menu', out, {'LOADER.BIN': os.path.join(pp, 'loader.bin'),
                                      'SWOSPP.BIN': os.path.join(pp, 'swospp.bin'),
                                      'W84E.CAR': os.path.join(WORK, 'saves', 'W84E_TEAM254.CAR')},
                 'dump:3', 300, timer=True) as s:
        if s.wait().outcome != 'dump':
            return False, f'START: no first pause ({s.result})'
        on, why = swospp_on(s.result, os.path.join(out, 'ITALIAN.EXE'))
        check(on, f'SWOS++ not running: {why}', errs)
        e = menu(s, 'start')
        check(e[4][0].endswith(b'2026-27') and not e[4][1], f'entry 4 not the button: {e[4]}', errs)
        check(e[11][0] == b'SWOS++' and not e[11][1] and e[11][2:4] == (93, 21), f'entry 11 not SWOS++: {e[11]}', errs)
        sc = walk(s, 11, 3)                                     # (2) SWOS++'s own menu, then ESC
        opened = not is_main(s)
        check(opened, f'SWOS++ menu not opened: {sc}', errs)
        info.append(f'SWOS++ menu: {str(sc)[:60]}')
        if sc.find('ESCI', exact=True) is not None:            # (its EXIT entry; ESC does not close it)
            walk(s, 'ESCI', 3)
        check(is_main(s), f'not back on the main menu: {s.screen()}', errs)
        e = menu(s, 'back')
        check(e[11][0] == b'SWOS++' and not e[4][1], f'after SWOS++ menu: {e}', errs)
        def go(s, target):                                      # (select target, fire, then UP at once: test menus
            for _ in range(20):                                 # read the latched last key, and a latched fire would
                sc = s.screen()                                 # be read again by the menu we come back to)
                i = sc.find(target, exact=True) if isinstance(target, str) else target
                if i is None:
                    raise AssertionError(f'{target} not on screen: {sc}')
                if sc.selected == i:
                    break
                s.send(sc.path(i)[0] + ' dump:0.5')
            s.send('fire up:0.05 dump:3')
        walk(s, 'CARICA VECCHIA COMPETIZIONE', 3)               # (3) a career loaded
        s.send('fire dump:3')
        go(s, 'ESCI')
        check(is_main(s), f'career menu -> ESCI: not the main menu: {s.screen()}', errs)
        e = menu(s, 'career')
        check(not e[10][1] and not e[11][1] and e[11][0] != b'SWOS++' and e[11][2:4] != (93, 21),
              f'CONTINUE / SAVE with a contest: {e[10]} {e[11]}', errs)
        check(e[4][0].endswith(b'2026-27') and not e[4][1], f'entry 4 with a contest: {e[4]}', errs)
        go(s, 11)                                               # SAVE opens its screen
        check(not is_main(s), f'SAVE did not open: {s.screen()}', errs)
        info.append(f'SAVE: {[t for _, t, inv, *_ in s.screen().entries if not inv][-3:]}')
        for _ in range(3):                                      # (the save screen: ABANDON = cancel)
            if is_main(s):
                break
            sc = s.screen()
            go(s, 'ABBANDONA') if sc.find('ABBANDONA', exact=True) is not None else go(s, 'ESCI')
        go(s, 'COMPET. PERSONAL.')                              # (4) drop the contest: the prompt's CONTINUE goes on
        sc = s.screen()                                         # into the DIY menu (ABANDON would keep the career)
        if sc.find('ABBANDONA', exact=True) is not None:
            go(s, sc.find('ABBANDONA', exact=True) - 1)
        for _ in range(4):
            if is_main(s):
                break
            sc = s.screen()
            go(s, 'ESCI') if sc.find('ESCI', exact=True) is not None else s.send('esc dump:3')
        e = menu(s, 'abandoned')
        check(e[10][1] and e[11][0] == b'SWOS++' and not e[11][1], f'SWOS++ entry not back: {e[10]} {e[11]}', errs)
        s.shot('main')
    return not errs, '; '.join(errs + info)


@scenario
def swospp_bench():
    """(Panchina, 4.0.5 regression) SWOS++ vs the mod's code changes: SWOSPP_BUILD (a dir whose ITALIAN.EXE is a modded ENGLISH exe,
    the release recipe) + tools/swospp.py + LOADER.BIN / SWOSPP.BIN; at the main menu obj1 in memory is compared with
    the run's exe (relocation fields masked): the bytes SWOS++ changed at run time. Each of its sites must be away from
    every byte the mod changed against orig/ENGLISH.EXE (overlap = FAIL); sites within 256 bytes of a mod change are
    listed for review (a SWOS++ jump that replaces a routine the mod hooks further on)."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import swospp
    if UI != 'en':
        return True, 'SKIP: SWOS++ is English only (SWOSTEST_UI=en)'
    b = os.environ.get('SWOSPP_BUILD')
    if not b or not os.path.isdir(b):
        return True, 'SKIP: SWOSPP_BUILD not set'
    pp = os.path.join(MAIN, 'internal', 'swospp-test')
    out = os.path.join(WORK, 'builds-x', 'swospp_bench')
    shutil.rmtree(out, ignore_errors=True)
    shutil.copytree(b, out)
    swospp.install(os.path.join(b, 'ITALIAN.EXE'), os.path.join(out, 'ITALIAN.EXE'))
    errs, info = [], []
    with Session('swospp_bench', out, {'LOADER.BIN': os.path.join(pp, 'loader.bin'),
                                       'SWOSPP.BIN': os.path.join(pp, 'swospp.bin')}, 'dump:3', 200, timer=True) as s:
        if s.wait().outcome != 'dump':
            return False, f'START: no first pause ({s.result})'
        sc = s.screen()
        on, why = swospp_on(s.result, os.path.join(out, 'ITALIAN.EXE'))
        check(on, f'SWOS++ not running: {why}', errs)
        e4 = [t for i, t, *_ in sc.entries if i == 4]          # (entry 4: the green CAREER 2026-27 button in a World
        check(e4 and e4[0] != 'SWOS++', f'main menu entry 4 {e4}: {sc}', errs)   # 2026-27 build, always - Davide 30/10)
        r = s.result
        run = lepatch.LEPatch(os.path.join(RUNS, 'swospp_bench', 'SWOS', 'ITALIAN.EXE'))
        orig = lepatch.LEPatch(os.path.join(ROOT, 'orig', 'ENGLISH.EXE'))
        o0 = orig.le.obj_bytes(1)
        n = len(o0)
        exe = run.le.obj_bytes(1)[:n]
        mem = r.read(r.base1, n)
        mask = bytearray(n)
        for gp, recs in enumerate(run.recs):
            objn, base = run.page_obj[gp]
            if objn != 1:
                continue
            for rc in recs:
                po = struct.unpack_from('<h', rc, 2)[0]
                for k in range(max(0, base + po), min(n, base + po + 4)):
                    mask[k] = 1
        pp_ = [i for i in range(n) if not mask[i] and mem[i] != exe[i]]
        mod = [i for i in range(n) if exe[i] != o0[i]]

        def ranges(xs):
            out_ = []
            for i in xs:
                if out_ and i <= out_[-1][1] + 4:
                    out_[-1][1] = i
                else:
                    out_.append([i, i])
            return out_
        spp, mr = ranges(pp_), ranges(mod)
        info.append(f'SWOS++ run-time sites in obj1: {len(spp)} ({len(pp_)} bytes); mod changes: {len(mr)} ranges')
        over, near, known = [], [], []
        for a, z in spp:
            if (z <= a + 6 and o0[a:a + 3] == b'\x66\x01\x05' and exe[a] == 0xe8 and exe[a + 5:a + 7] == b'\x90\x90'
                    and exe[a + 7] == 0xe8):            # (shirtnum, 3.2.6: SWOS++'s DrawControlledPlayerNumbers+0x184
                known.append(hex(a))                    # hook takes our `call num_sprite; nop; nop` = the game's add,
                continue                                # fix_d0 after it reads SWOS++'s 9000 + n mark: by design)
            for c, e in mr:
                if a <= e and c <= z:
                    over.append((hex(a), hex(z), hex(c), hex(e)))
                elif abs(a - e) < 256 or abs(c - z) < 256:
                    near.append((hex(a), hex(z), hex(c), hex(e)))
        open(os.path.join(RUNS, 'swospp_bench', 'sites.txt'), 'w').write(
            '\n'.join(f'{a:#x}..{z:#x} mem {mem[a:z + 1].hex()} exe {exe[a:z + 1].hex()}' for a, z in spp) + '\n\nnear:\n'
            + '\n'.join(map(str, near)) + '\n')
        info.append(f'overlaps {over[:8]}; by design (shirtnum) {known}; near {len(near)}: {near[:12]}')
        check(not over, f'SWOS++ sites overlap mod changes: {over[:12]}', errs)
    return not errs, '; '.join(errs + info)


@scenario
def full_graphics():
    """4.0.2 full graphics always (fullgfx.py): GOG's factory SETUP.DAT (video speed 10, the half mode before) -> at the
    main menu setupDatBuffer (EGA_graphics in the match) = 0; the same with the exe started with /H -> -1 (half)"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import re as _re
    import lepatch
    import fullgfx
    b = builds()['it']
    fac = os.path.join(MAIN, 'internal', 'joypad-gog', 'SETUP.DAT.factory')
    p = lepatch.LEPatch(os.path.join(ROOT, 'orig', UI_ORIG))
    m = _re.search(fullgfx.PAT, p.le.obj_bytes(1), _re.S)
    buf = p.target(1, m.start() + 3)[1]
    errs, notes = [], []
    for tag, args, want in (('factory', '', 0), ('factory /H', '/H', 0xFFFF)):
        old = os.environ.get('SWOSTEST_EXEARGS')
        os.environ['SWOSTEST_EXEARGS'] = args
        try:
            with Session('full_graphics' + ('_h' if args else ''), b, {'SETUP.DAT': fac}, 'dump:2', 120) as s:
                if s.wait().outcome != 'dump':
                    errs.append(f'{tag}: no pause ({s.result})')
                    continue
                r = s.result
                v = struct.unpack('<H', r.read(r.base2 + buf, 2))[0]
                spd = struct.unpack('<H', r.read(r.base2 + buf + 12, 2))[0]
                check(v == want, f'{tag}: setupDatBuffer {v:#x}, want {want:#x}', errs)
                notes.append(f'{tag}: speed {spd}, mode {"half" if v else "full"}')
        finally:
            if old is None:
                os.environ.pop('SWOSTEST_EXEARGS', None)
            else:
                os.environ['SWOSTEST_EXEARGS'] = old
    return not errs, '; '.join(errs + notes)


PURPLE_RGB, MAROON_MENU = (24, 8, 34), (27, 0, 9)


def italy_friendly(s, home, away):
    """Main menu -> AMICHEVOLE, ITALIA SERIE A: home (human) and away (computer) -> pre-match screen of home."""
    for t in ('AMICHEVOLE', 'OK', 'SCEGLI SQUADRE', 'SQUADRE CLUB', 'EUROPA'):
        walk(s, t, 2)
    for _ in range(30):                         # ITALIA (49): one key at a time down the middle column
        sel = s.screen().selected
        if sel == 49:
            break
        s.send(('down' if sel < 49 else 'up') + ' dump:0.5')
    s.send('fire dump:3')
    walk(s, 'SERIE A', 2)
    walk(s, home, 2)
    s.send('fire dump:2')                       # home: COMPUTER -> GIOCA-ALLENA
    walk(s, away, 2)
    for _ in range(12):
        scr = s.screen()
        i = scr.find('AMICHEVOLE', exact=True)
        if i is None:
            raise AssertionError(f'AMICHEVOLE not on screen ({scr.texts()[-10:]})')
        if scr.selected == i:
            s.send('fire dump:4')
            return s.screen()
        s.send(('right' if scr.selected in (i + 1, i + 2) else 'down') + ' dump:0.5')
    raise AssertionError('AMICHEVOLE not reached')


@scenario
def purple_kits():
    """3.3.0: kit colour 10 = purple (Fiorentina): palette entry 12 purple in the SELECT KITS editor for Fiorentina and
    maroon for Inter, purple in the match Fiorentina-Inter and Fiorentina-Roma (Roma's maroon kit clashes: green away);
    3.3.1: Inter in Barcelona's kits (blue and maroon stripes): the automatic choice avoids purple vs maroon; SELECT KITS
    opens on the automatic choice (Fiorentina-Roma: Roma second kit) and OK plays it; 3.3.3: the team name box in the
    colour of who controls the team (purple player, red computer); 3.3.4 (Marco): purple has palette entry 4 of its
    own in the editor and entry 12 stays maroon, so a maroon part of Fiorentina's second kit leaves the first purple"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    b = builds()['it']
    p = lepatch.LEPatch(os.path.join(b, 'ITALIAN.EXE'))
    import re as _re
    fp = _re.search(rb'\xbf....\xbe....\xb9\x0f\x00\x00\x00', p.le.obj_bytes(1), _re.S)
    working = p.target(1, fp.start() + 6)[1]
    errs, info = [], []
    d = bytearray(open(os.path.join(b, 'DATA', 'TEAM.020'), 'rb').read())
    for t in range(struct.unpack('>H', d[:2])[0]):          # 3.3.1: INTER MILAN in Barcelona's kits (blue and
        o = 2 + t * 684                                      # maroon stripes / light blue): purple vs maroon stripes
        if d[o + 5:o + 22].split(b'\0')[0] == b'INTER':
            d[o + 26:o + 36] = bytes([2, 5, 6, 5, 5, 0, 7, 7, 7, 7])
    fio = bytearray(open(os.path.join(b, 'DATA', 'TEAM.020'), 'rb').read())
    for t in range(struct.unpack('>H', fio[:2])[0]):        # 3.3.4 (Marco): Fiorentina's second kit with maroon
        o = 2 + t * 684                                      # shorts: the purple first kit stays purple in SELECT KITS
        if fio[o + 5:o + 22].split(b'\0')[0] == b'FIORENTINA':
            fio[o + 34] = 6
    fiom = os.path.join(WORK, 'saves', 'TEAM020_FIOMAROON.BIN')
    barca = os.path.join(WORK, 'saves', 'TEAM020_BARCA.BIN')
    os.makedirs(os.path.dirname(barca), exist_ok=True)
    open(barca, 'wb').write(d)
    open(fiom, 'wb').write(fio)
    for away, kits, cars in (('INTER', True, {'DATA/TEAM.020': fiom}), ('ROMA', False, {}),
                             ('INTER', False, {'DATA/TEAM.020': barca})):
        with Session('purple_kits_' + away[:5] + ('_barca' if cars and not kits else ''), b, cars, 'dump:3', 300, match=True) as s:
            s.wait()
            italy_friendly(s, 'FIORENTINA', away)
            if kits:
                scr = walk(s, 68, 3)
                pal = s.result.read(s.result.base2 + working + 36, 3)      # 3.3.4: purple has entry 120 of its
                own = s.result.read(s.result.base2 + working + 12, 3)      # own, entry 12 stays the menus' maroon
                check(scr.entries[1][1] == 'FIORENTINA' and tuple(own) == PURPLE_RGB and tuple(pal) == MAROON_MENU,
                      f'editor {scr.entries[1][1]} entry 4 {tuple(own)} entry 12 {tuple(pal)}', errs)
                s.shot('purple_kits_editor')        # Fiorentina: purple first kit, maroon second shorts
                check(scr.colors[1] == 11, f'team name box {scr.colors[1]} for the human player (want 11, purple)', errs)
                scr = walk(s, 1, 3)             # the other team
                check(scr.colors[1] == 10, f'team name box {scr.colors[1]} for the computer (want 10, red)', errs)
                pal = s.result.read(s.result.base2 + working + 36, 3)
                check(tuple(pal) == MAROON_MENU, f'editor {s.screen().entries[1][1]} {tuple(pal)}', errs)
                walk(s, 20, 3)                  # ESCI
                s.screen()                      # entry 4 back to the menus' skin brown outside the editor
                after = tuple(s.result.read(s.result.base2 + working + 12, 3))
                check(after == (27, 9, 0), f'entry 4 after SELECT KITS {after} (want 27, 9, 0)', errs)
            elif away == 'ROMA':                # 3.3.1 (Marco): SELECT KITS opens on the automatic choice (Roma's
                scr = walk(s, 68, 3)            # maroon vs purple: Roma in its second kit), and OK keeps it
                t = scr.texts()
                check('IN CAMPO: PRIMA TENUTA' in t and 'ROMA: SECONDA TENUTA' in t, f'SELECT KITS opens on {t[:5]}', errs)
                walk(s, 21, 3)                  # OK: the match is played in these kits
            for _ in range(22):
                s.send('down dump:0.5')
                if s.screen().selected == 9:
                    break
            r = s.send('fire ' + 'fire:3 ' * 8 + 'dump:2')
            check(r.outcome == 'dump', f'{away}: match {r}', errs)
            if r.outcome == 'dump':
                pal = tuple(r.read(r.base2 + working + 36, 3))
                o2 = r.read(r.base2, 0x100000)
                m = o2.find(b'PKMK')
                marks = tuple(o2[m + 4:m + 6]) if m >= 0 else None
                worn = (marks[0] | marks[1]) if marks else None     # bit 0 purple, bit 1 maroon worn
                want = PURPLE_RGB if worn == 1 else (25, 0, 8)
                check(marks is not None and pal == want and worn != 3, f'match vs {away}: marks {marks}, entry 12 {pal}', errs)
                info.append(f"{away}{' (Barcelona kits)' if cars and not kits else ''}: marks {marks}")
                if away == 'INTER' and kits:
                    check(worn == 1, f'Fiorentina-Inter: purple not worn ({marks})', errs)
    return not errs, '; '.join(errs + info) if errs else 'purple in the editor (maroon for Inter) and vs Inter; ' + '; '.join(info)


@scenario
def purple_manual():
    """3.3.2 (Marco): kits set by hand never put purple against maroon. Fiorentina-Roma with Roma forced into its maroon
    first kit: Roma plays its green second kit; against Zenit's kits (maroon / white with maroon shorts) forced into the
    first kit: the second kit with white shorts. Fiorentina stays purple in both"""
    errs, info = [], []
    b = builds()['it']
    d = bytearray(open(os.path.join(b, 'DATA', 'TEAM.020'), 'rb').read())
    for t in range(struct.unpack('>H', d[:2])[0]):
        o = 2 + t * 684
        if d[o + 5:o + 22].split(b'\0')[0] == b'ROMA':
            d[o + 26:o + 36] = bytes([0, 6, 6, 1, 6, 0, 1, 1, 6, 1])     # ZENIT's kits
    zenit = os.path.join(WORK, 'saves', 'TEAM020_ZENIT.BIN')
    os.makedirs(os.path.dirname(zenit), exist_ok=True)
    open(zenit, 'wb').write(d)
    for tag, cars in (('roma', {}), ('zenit', {'DATA/TEAM.020': zenit})):
        with Session('purple_manual_' + tag, b, cars, 'dump:3', 300, match=True) as s:
            s.wait()
            italy_friendly(s, 'FIORENTINA', 'ROMA')
            scr = walk(s, 68, 3)                # SELECT KITS: both teams in their first kits, by hand
            for _ in range(2):
                if 'IN CAMPO: SECONDA TENUTA' in scr.texts():
                    scr = walk(s, 2, 3)
                scr = walk(s, 1, 3)             # the other team
            t = scr.texts()
            check('IN CAMPO: PRIMA TENUTA' in t and 'ROMA: PRIMA TENUTA' in t + ['FIORENTINA: PRIMA TENUTA']
                  and not any(x.endswith('SECONDA TENUTA') for x in t), f'{tag}: not both first kits: {t[:5]}', errs)
            walk(s, 21, 3)                      # OK
            for _ in range(22):
                s.send('down dump:0.5')
                if s.screen().selected == 9:
                    break
            r = s.send('fire ' + 'fire:3 ' * 8 + 'dump:2')
            check(r.outcome == 'dump', f'{tag}: match {r}', errs)
            if r.outcome == 'dump':
                o2 = r.read(r.base2, 0x100000)
                m = o2.find(b'PKMK')
                marks = tuple(o2[m + 4:m + 6]) if m >= 0 else None
                check(marks is not None and (marks[0] | marks[1]) == 1, f'{tag}: marks {marks} (want purple only)', errs)
                info.append(f'{tag}: marks {marks}')
    return not errs, '; '.join(errs + info) if errs else 'manual kits: purple kept, no maroon (' + '; '.join(info) + ')'


@scenario
def purple_stadium():
    """3.3.1: the line-ups screen before the match (ShowStadiumInit) keeps Fiorentina purple: palette entry 12 purple
    after the screen's second copy of the stad.256 palette (breakpoints: normal core)"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import re as _re
    os.environ['CORE'] = 'normal'               # one process per scenario: only this one runs the slower core
    b = builds()['it']
    p = lepatch.LEPatch(os.path.join(b, 'ITALIAN.EXE'))
    d1 = p.le.obj_bytes(1)
    m = _re.search(rb'\x81\xC6\x00\xFA\x00\x00\xBF....(?:\xB9\x00\x03\x00\x00\xF3\xA4|\xE8....\x90\x90)\xFF\x35', d1, _re.S)
    after = m.end() - 2                         # the `push D0` after the copy the screen keeps (hooked or not)
    fp = _re.search(rb'\xbf....\xbe....\xb9\x0f\x00\x00\x00', d1, _re.S)
    working = p.target(1, fp.start() + 6)[1]
    got = []
    with Session('purple_stadium', b, {}, 'dump:3', 300, match=True) as s:
        s.wait()
        italy_friendly(s, 'INTER', 'FIORENTINA')
        base1, base2 = s.result.base1, s.result.base2
        s.bp(base1 + after, lambda r: got.append(tuple(r.read(base2 + working + 36, 3))))
        for _ in range(22):
            s.send('down dump:0.5')
            if s.screen().selected == 9:
                break
        r = s.send('fire ' + 'fire:3 ' * 4 + 'dump:2')
    ok = r.outcome == 'dump' and got and got[0] == PURPLE_RGB
    return ok, f'line-ups screen entry 12 {got} ({r.outcome})'


STNM_NAME, STNM_SHOWN, STNM_KEY, STNM_Y = 4, 37, 38, 40          # stadium.py's log after its 'STNM' mark


def stadium_log(r, at):
    """stadium.py's variables (at = the Off3 of its 'STNM' mark): name, shown, (file, ordinal), the name's top row."""
    v = r.read(r.lin(at), 48)
    return {'name': v[STNM_NAME:STNM_NAME + 33].split(bytes(1))[0].decode('latin-1'), 'shown': v[STNM_SHOWN],
            'key': (v[STNM_KEY], v[STNM_KEY + 1]), 'y': struct.unpack_from('<i', v, STNM_Y)[0]}


def stadium_vs(s, at):
    """A breakpoint after VersusInit's fade-in (its `mov ecx, 100`, stadium.sites' vs + 15, the exe language's
    original): each hit appends {log, vga, title (entry 0 geometry), bar (entry 2)} to the returned list."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import stadium
    vs = stadium.sites(lepatch.LEPatch(os.path.join(ROOT, 'orig', ORIG_EXE[UI])))['vs']
    got = []

    def hit(q):
        scr = Screen(q, s.info['menu'])
        got.append({'log': stadium_log(q, at), 'vga': q.read(0xA0000, 64000), 'pal': q.obj2(s.info['pal'], 768),
                    'title': scr.geom[0], 'bar': scr.geom[2]})
    s.bp(s.result.base1 + vs + 15, hit)
    return got


def stadium_vs_check(h, want, errs, info, tag, s=None):
    """The versus frame h (stadium_vs) with the name `want` ('' = none): under the bars the text ink colours (2 white,
    8 shadow) only in the name's rows, starting stadium.GAP rows below the bars' last row, centred on the title's
    centre (+-1), inside the screen; none at all without a name. Saves the frame as shot `tag`."""
    import stadium
    g, vga = h['log'], h['vga']
    bx, by, bw, bh = h['bar']
    tx, _, tw, _ = h['title']
    below = by + bh                                  # the first row under the bars
    ink = [(i % 320, i // 320) for i in range(below * 320, 64000) if vga[i] in (2, 8)]
    if s is not None:
        s.box.shot(tag, h['pal'], vga)
    if not want:
        check(not g['shown'] and not ink, f'{tag}: no name wanted, shown {g["shown"]}, {len(ink)} ink px under the bars', errs)
        info.append(f'{tag}: no name, nothing under the bars')
        return
    check(g['shown'] == 1 and g['name'] == want, f'{tag}: {g["name"]!r} shown {g["shown"]}, want {want!r}', errs)
    if not ink:
        errs.append(f'{tag}: no ink under the bars')
        return
    x0, x1 = min(x for x, _ in ink), max(x for x, _ in ink)
    y0, y1 = min(y for _, y in ink), max(y for _, y in ink)
    c = tx + tw // 2
    check(g['y'] == below + stadium.GAP and y0 >= g['y'] and y0 - below >= stadium.GAP,
          f'{tag}: gap {y0 - below} rows (name row {g["y"]}, ink {y0}..{y1}), want >= {stadium.GAP}', errs)
    check(y1 - y0 <= 9, f'{tag}: ink rows {y0}..{y1}: more than one text line', errs)
    check(0 < x0 and x1 < 319 and abs((x0 + x1) / 2 - c) <= 1.5, f'{tag}: ink x {x0}..{x1}, centre {c}', errs)
    info.append(f'{tag}: {want!r} rows {y0}..{y1} (gap {y0 - below}), x {x0}..{x1} (title centre {c})')


@scenario
def stadium_versus():
    """4.0.6 (Davide 02/11): the home club's stadium (DATA\\STADTEAM.DAT, test file) on the versus screen, under the
    two team bars (stadium.GAP rows clear), centred on the title, in the small font and the title's colour; nothing waits, the
    match goes on. Friendlies in ITALIA SERIE A, the two clubs of each the same case (RandomlySwapTeams picks the home
    side): INTER v MILAN (WEMBLEY / SAN SIRO), FIORENTINA v ROMA (32 chars: inside the screen), JUVENTUS v LAZIO (no
    record): the screen as the game draws it (no title ink under the bars). The names in the game charset, <= 32."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import stadium
    os.environ['CORE'] = 'normal'               # (the versus breakpoint)
    b = os.environ.get('STADIUM_BUILD') or builds()['it']
    p = lepatch.LEPatch(os.path.join(b, 'ITALIAN.EXE'))
    at = p.le.obj_bytes(3).find(b'STNM') if len(p.le.objs) > 2 else -1
    if at < 0:
        return False, 'no stadium.py in this build (no STNM in obj3)'
    at = Off3(at)
    d = open(os.path.join(b, 'DATA', 'TEAM.020'), 'rb').read()
    keys = {}
    for t in range(struct.unpack('>H', d[:2])[0]):
        o = 2 + t * 684
        keys[d[o + 5:o + 22].split(bytes(1))[0].decode('latin-1')] = (d[o], d[o + 1])
    long = 'STADIO COMUNALE CARLO CASTELLANI'
    assert len(long) == 32
    dat = os.path.join(WORK, 'saves', 'STADIUM_TEST.DAT')
    os.makedirs(os.path.dirname(dat), exist_ok=True)
    names = {keys['INTER']: 'WEMBLEY', keys['MILAN']: 'SAN SIRO', keys['FIORENTINA']: long,  # (friendlies swap the
             keys['ROMA']: long.replace('CARLO CASTELLANI', 'OLIMPICO DI ROMA')}             # teams at random,
    open(dat, 'wb').write(stadium.build(names))     # RandomlySwapTeams: both clubs of a pair are the same case)
    errs, info = [], []
    for tag, home, away in (('inter', 'INTER', 'MILAN'), ('long', 'FIORENTINA', 'ROMA'), ('none', 'JUVENTUS', 'LAZIO')):
        with Session('stadium_versus_' + tag, b, {'DATA/STADTEAM.DAT': dat}, 'dump:3', 300, match=True) as s:
            s.wait()
            italy_friendly(s, home, away)
            for _ in range(22):
                s.send('down dump:0.5')
                if s.screen().selected == 9:
                    break
            got = stadium_vs(s, at)
            r = s.send('fire dump:3')
            check(len(got) == 1, f'{tag}: versus breakpoint hits {len(got)}', errs)
            if got:
                g = got[0]['log']
                check(g['key'] in (keys[home], keys[away]), f'{tag}: key {g["key"]} not {home} / {away}', errs)
                stadium_vs_check(got[0], names.get(g['key'], ''), errs, info, tag, s)
            r = s.send('dump:2')
            check(r.outcome == 'dump', f'{tag}: after the versus screen {r}', errs)
    return not errs, '; '.join(errs + info)


@scenario
def stadium_world():
    """4.0.6 stadium names per team-file namespace: a World 2026-27 career at ROMA (STADIUM_BUILD / BENCH_BUILD: a
    release-style build with several worlds; ROMA = TMW5.102's record) -> SQUADRA -> TRAINING -> GIOCA PARTITA (no
    RandomlySwapTeams: the club is gameTeam1): DATA\\STADTMW5.DAT names it STADIO OLIMPICO, DATA\\STADTEAM.DAT has the
    same (file, ordinal) as WRONG NAMESPACE (TEAM.102 is another world's file): the versus screen shows the world's
    name (stadium_vs_check: gap, centre)."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import stadium
    b = os.environ.get('STADIUM_BUILD') or os.environ.get('BENCH_BUILD')
    if not b or not os.path.isdir(b):
        return True, 'SKIP: STADIUM_BUILD not set'
    b = nop_league_int3('stadium_world_' + os.path.basename(RUNS.rstrip('/')), b)
    p = lepatch.LEPatch(os.path.join(b, 'ITALIAN.EXE'))
    at = p.le.obj_bytes(3).find(b'STNM')
    if at < 0:
        return True, 'SKIP: no stadium.py in this build (no STNM in obj3)'
    at = Off3(at)
    d = open(os.path.join(b, 'DATA', 'TMW5.102'), 'rb').read()
    roma = [(d[o], d[o + 1]) for o in (2 + t * 684 for t in range(struct.unpack('>H', d[:2])[0]))
            if d[o + 5:o + 22].split(bytes(1))[0] == b'ROMA']
    if len(roma) != 1:
        return False, f'ROMA in TMW5.102: {roma}'
    w5 = os.path.join(WORK, 'saves', 'STADTMW5_TEST.DAT')
    t0 = os.path.join(WORK, 'saves', 'STADTEAM_TEST.DAT')
    os.makedirs(os.path.dirname(w5), exist_ok=True)
    open(w5, 'wb').write(stadium.build({roma[0]: 'STADIO OLIMPICO'}))
    open(t0, 'wb').write(stadium.build({roma[0]: 'WRONG NAMESPACE'}))
    errs, info = [], []
    os.environ['CORE'] = 'normal'               # (the versus breakpoint)
    with Session('stadium_world', b, {'DATA/STADTMW5.DAT': w5, 'DATA/STADTEAM.DAT': t0}, 'dump:2', 900, match=True) as s:
        if s.wait().outcome != 'dump':
            return False, f'START: no first pause ({s.result})'
        if train_start(s, 'EUROPA,ITALIA,SERIE A,ROMA'.split(','), errs) is None:
            return False, '; '.join(errs)
        q = s.screen()
        i = q.find(TRAIN_TXT[UI][2])
        if i is None or se_goto(s, i).selected != i:
            return False, f'training: {TRAIN_TXT[UI][2]} not reached ({q.texts()[:12]})'
        got = stadium_vs(s, at)
        s.send('fire dump:2')
        check(len(got) == 1, f'versus breakpoint hits {len(got)}', errs)
        if got:
            g = got[0]['log']
            check(g['key'] == roma[0], f'key {g["key"]}, want {roma[0]}', errs)
            stadium_vs_check(got[0], 'STADIO OLIMPICO', errs, info, 'roma', s)
        r = s.send('dump:3')
        check(r.outcome == 'dump', f'after the versus screen: {r}', errs)
    return not errs, '; '.join(errs + info)


def stadium_code(r, at):
    """stadium.py's st_find in the running game: (its first byte, its `.no` end: cmp byte [st_name], 0 / ret) linear,
    found by the runtime address of st_name (at = the STNM mark's Off3) in obj3's code."""
    nm = struct.pack('<I', r.lin(at + STNM_NAME))
    o3 = r.read(r.base3, int(at))
    a = [m.start() for m in re.finditer(re.escape(b'\xc6\x05' + nm + b'\x00\xa1'), o3)]
    b = [m.start() for m in re.finditer(re.escape(b'\x80\x3d' + nm + b'\x00\xc3'), o3)]
    assert len(a) == 1 and len(b) == 1, ('st_find', a, b)
    return r.base3 + a[0], r.base3 + b[0]


@scenario
def stadium_venues():
    """4.0.6 neutral finals (Regia / Davide 02/11): STADTMW5.DAT's venue rows, matched by the line-ups' competition +
    round (gameName / gameRound, exact) before the home club. A World 2026-27 career at ROMA (STADIUM_BUILD: a release
    build, its own shipped STADTMW5.DAT) -> TRAINING -> GIOCA PARTITA: a breakpoint at st_find's end records the name
    found, puts the next case's strings into gameName / gameRound (+ currentSeasonShowing) and runs st_find again
    (EIP back to its start): every venue row of the file (all 4 languages) -> its venue; the wrong season, a cut
    competition, another round -> ROMA's own stadium; the game's '*' padding ends a string; then the real strings
    back -> the club's stadium on the versus screen (stadium_vs_check), the line-ups after it. The strings themselves are the exes' own (the
    build's stadium.vcheck_exe prints a CSV string not in that language's exe / DATA; stadium_clublist fails on it)."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import stadium
    b = os.environ.get('STADIUM_BUILD') or os.environ.get('BENCH_BUILD')
    if not b or not os.path.isdir(b):
        return True, 'SKIP: STADIUM_BUILD not set'
    b = nop_league_int3('stadium_venues_' + os.path.basename(RUNS.rstrip('/')), b)
    p = lepatch.LEPatch(os.path.join(b, 'ITALIAN.EXE'))
    at = p.le.obj_bytes(3).find(b'STNM') if len(p.le.objs) > 2 else -1
    if at < 0:
        return True, 'SKIP: no stadium.py in this build (no STNM in obj3)'
    at = Off3(at)
    dat = os.path.join(b, 'DATA', 'STADTMW5.DAT')
    got = stadium.read(open(dat, 'rb').read()) if os.path.exists(dat) else None
    if not got or not got[1]:
        return False, f'no version-2 STADTMW5.DAT with venues in {b}'
    recs, ven = got
    d = open(os.path.join(b, 'DATA', 'TMW5.102'), 'rb').read()
    roma = [(d[o], d[o + 1]) for o in (2 + t * 684 for t in range(struct.unpack('>H', d[:2])[0]))
            if d[o + 5:o + 22].split(bytes(1))[0] == b'ROMA']
    if len(roma) != 1 or roma[0] not in recs:
        return False, f'ROMA in TMW5.102 / STADTMW5.DAT: {roma}'
    club = recs[roma[0]]
    st = stadium.sites(lepatch.LEPatch(os.path.join(ROOT, 'orig', ORIG_EXE[UI])))
    gname, ground, ssn = st['GNAME'][1], st['GROUND'][1], st['SSN'][1]
    cases = [(c, r_, 0, n, f'{c} / {r_}') for c, r_, n, sn in ven]          # (season 1 = currentSeasonShowing 0)
    c0, r0, n0, _ = ven[0]
    cases += [(c0, r0, 1, club, 'season 2'), (c0[:-1], r0, 0, club, 'cut competition'),
              (c0, r0 + 'X', 0, club, 'another round'), (c0 + '*', r0, 0, n0, "'*' padding")]
    errs, info, hits, state = [], [], [], {}
    show = int(os.environ['STADIUM_SHOW']) if os.environ.get('STADIUM_SHOW') else None   # (the visual tour: case k's
    final = cases[show][3] if show is not None else club                                  # strings on the screen)
    showname = os.environ.get('STADIUM_SHOWNAME')   # (the tour: this name poked into st_name at the last lookup's end)
    final = showname or final

    def at_end(q):
        hits.append(stadium_log(q, at)['name'])
        k = len(hits) - 1                       # (hit 0: the real lookup; hit k: case k - 1)
        if k == 0:
            state['orig'] = (q.obj2(gname, 40), q.obj2(ground, 40), q.obj2(ssn, 2))
        if k < len(cases):
            c, r_, sn, _, _ = cases[k]
            s.poke(q.base2 + gname, c.encode('latin-1') + b'\0')
            s.poke(q.base2 + ground, r_.encode('latin-1') + b'\0')
            s.poke(q.base2 + ssn, struct.pack('<H', sn))
        elif k == len(cases) and show is not None:
            c, r_, sn, _, _ = cases[show]
            s.poke(q.base2 + gname, c.encode('latin-1') + b'\0')
            s.poke(q.base2 + ground, r_.encode('latin-1') + b'\0')
            s.poke(q.base2 + ssn, struct.pack('<H', sn))
        elif k == len(cases):                   # the real strings back: the last run is the game's own
            g, r_, sn = state['orig']
            s.poke(q.base2 + gname, g)
            s.poke(q.base2 + ground, r_)
            s.poke(q.base2 + ssn, sn)
        else:
            if showname and k == len(cases) + 1:
                s.poke(q.lin(at + STNM_NAME), showname.encode('ascii') + b'\0')
            return
        s.box.cmd(f'SR EIP {state["start"]:X}', 0.3)

    os.environ['CORE'] = 'normal'               # (the versus breakpoint)
    with Session('stadium_venues', b, {}, 'dump:2', 1200, match=True) as s:
        if s.wait().outcome != 'dump':
            return False, f'START: no first pause ({s.result})'
        if train_start(s, 'EUROPA,ITALIA,SERIE A,ROMA'.split(','), errs) is None:
            return False, '; '.join(errs)
        q = s.screen()
        i = next((q.find(x) for x in (TRAIN_TXT[UI][2], TRAIN_TXT['it'][2]) if q.find(x) is not None), None)
        if i is None or se_goto(s, i).selected != i:
            return False, f'training: {TRAIN_TXT[UI][2]} not reached ({q.texts()[:12]})'
        state['start'], end = stadium_code(s.result, at)
        s.bp(end, at_end)
        vsg = stadium_vs(s, at)
        s.send('fire dump:2')
        g = vsg[0]['log'] if vsg else stadium_log(s.result, at)
        check(len(hits) == len(cases) + 2, f'st_find ran {len(hits)} times, want {len(cases) + 2}', errs)
        if showname and len(hits) == len(cases) + 2:
            hits[-1] = showname
        for k, (c, r_, sn, want, tag) in enumerate(cases):
            h = hits[k + 1] if k + 1 < len(hits) else None
            check(h == want, f'{tag} (season {sn + 1}): {h!r}, want {want!r}', errs)
        if len(hits) == len(cases) + 2:
            check(hits[0] == club and hits[-1] == final, f'the real lookups: {hits[0]!r} / {hits[-1]!r}, want {club!r} / {final!r}', errs)
        info.append(f'{len(ven)} venue rows, {len(cases) - len(ven)} near misses: '
                    f'{sum(h == w for h, (_, _, _, w, _) in zip(hits[1:], cases))} of {len(cases)} as expected')
        check(len(vsg) == 1 and g['key'] == roma[0], f'versus hits {len(vsg)}, key {g["key"]}', errs)
        if vsg:
            stadium_vs_check(vsg[0], final, errs, info, 'showname' if showname else 'roma' if show is None else f'show{show}', s)
        if show is not None:
            info.append(f'STADIUM_SHOW {show}: {cases[show][4]}')
        if state.get('orig') and show is None:
            check(s.result.obj2(gname, 40) == state['orig'][0], 'gameName not the game\'s own after the test', errs)
        r = s.send('dump:3')
        check(r.outcome == 'dump', f'after the versus screen: {r}', errs)
    return not errs, '; '.join(errs + info)


@scenario
def stadium_clublist():
    """4.0.6 the stadium club list against a release build's World 2026-27 data (STADIUM_BUILD, else W2627FULL: the
    release recipe): every tools/stadium_tmw5_clubs.csv row is that club in DATA\\TMW5.nnn (stadium.unmatched: 0 - the
    build itself tolerates an older snapshot, dropping the row), every venue string is in each exe present / DATA
    (stadium.venue_misses: none - the build only prints them), DATA\\STADTMW5.DAT is there. No DOSBox."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import stadium
    b = os.environ.get('STADIUM_BUILD') or os.environ.get('W2627FULL')
    if not b or not os.path.isdir(os.path.join(b, 'DATA')):
        return True, 'SKIP: STADIUM_BUILD / W2627FULL not set'
    bad = stadium.unmatched(os.path.join(b, 'DATA'))
    n = sum(1 for _ in open(stadium.CLUBS_CSV, encoding='utf-8')) - 1
    vm = {lang: stadium.venue_misses(os.path.join(b, exe), lang, os.path.join(b, 'DATA'))[0]
          for lang, exe in stadium.LANGS if os.path.exists(os.path.join(b, exe))}
    vm = {k: v for k, v in vm.items() if v}
    ok = not bad and not vm and os.path.exists(os.path.join(b, 'DATA', 'STADTMW5.DAT'))
    return ok, f'{n} club rows, {len(bad)} not that club in {b}: {bad[:5]}; venue strings missing {vm}; STADTMW5.DAT ' + \
        ('there' if os.path.exists(os.path.join(b, 'DATA', 'STADTMW5.DAT')) else 'MISSING')


@scenario
def stadium_nofile():
    """4.0.6 (Davide 02/11: names only in World 2026-27): outside it no STADTEAM.DAT ships, and an absent or an empty
    file just means nothing on the versus screen. A friendly INTER v MILAN (TEAM.020: the 'team' namespace) on STADIUM_BUILD (a release
    build, else the harness build): the build ships no DATA\\STADTEAM.DAT; with none, then with an empty one, then with
    a version-1 file: st_find ran (the pair's key logged), no name, no title ink under the bars, the match goes on."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    b = os.environ.get('STADIUM_BUILD') or builds()['it']
    p = lepatch.LEPatch(os.path.join(b, 'ITALIAN.EXE'))
    at = p.le.obj_bytes(3).find(b'STNM') if len(p.le.objs) > 2 else -1
    if at < 0:
        return False, 'no stadium.py in this build (no STNM in obj3)'
    at = Off3(at)
    os.environ['CORE'] = 'normal'               # (the versus breakpoint)
    errs, info = [], []
    check(not any(n.upper() == 'STADTEAM.DAT' for n in os.listdir(os.path.join(b, 'DATA'))),
          f'{b}: DATA\\STADTEAM.DAT ships', errs)
    d = open(os.path.join(b, 'DATA', 'TEAM.020'), 'rb').read()
    keys = {d[o + 5:o + 22].split(bytes(1))[0].decode('latin-1'): (d[o], d[o + 1])
            for o in (2 + t * 684 for t in range(struct.unpack('>H', d[:2])[0]))}
    os.makedirs(os.path.join(WORK, 'saves'), exist_ok=True)
    empty = os.path.join(WORK, 'saves', 'STADTEAM_EMPTY.DAT')
    open(empty, 'wb').close()
    v1 = os.path.join(WORK, 'saves', 'STADTEAM_V1.DAT')         # (a 4.0.6-beta layout: 'STAD', 1, 0 + the index)
    idx = bytearray(256 * 6)
    struct.pack_into('<IH', idx, keys['INTER'][0] * 6, 8 + 256 * 6, 1)
    open(v1, 'wb').write(b'STAD' + struct.pack('<HH', 1, 0) + bytes(idx) + bytes([keys['INTER'][1]]) + b'WEMBLEY'.ljust(33, b'\0'))
    for tag, files in (('absent', {}), ('empty', {'DATA/STADTEAM.DAT': empty}), ('v1', {'DATA/STADTEAM.DAT': v1})):
        with Session('stadium_nofile_' + tag, b, files, 'dump:3', 300, match=True) as s:
            s.wait()
            italy_friendly(s, 'INTER', 'MILAN')
            for _ in range(22):
                s.send('down dump:0.5')
                if s.screen().selected == 9:
                    break
            got = stadium_vs(s, at)
            s.send('fire dump:2')
            g = got[0]['log'] if got else stadium_log(s.result, at)
            info.append(f'{tag}: {g["name"]!r} key {g["key"]} shown {g["shown"]}')
            check(len(got) == 1 and g['name'] == '' and g['key'] in (keys['INTER'], keys['MILAN']), f'{tag}: {g}', errs)
            if got:
                stadium_vs_check(got[0], '', errs, info, tag, s)
            r = s.send('dump:2')
            check(r.outcome == 'dump', f'{tag}: {r}', errs)
    return not errs, '; '.join(errs + info)


@scenario
def blond_faces():
    """3.3.0: face 3 = black skin + blond hair: FIORENTINA's outfield players set to face 3 (test copy of TEAM.020);
    pre-match face icon 189 built (yellow hair), in the match the new sprite set 1418.. is registered and has hair in
    entry 15 (yellow) and dark skin (no entry 5)"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import shirtnum
    import blond
    b = builds()['it']
    d = bytearray(open(os.path.join(b, 'DATA', 'TEAM.020'), 'rb').read())
    for t in range(struct.unpack('>H', d[:2])[0]):
        o = 2 + t * 684
        if d[o + 5:o + 22].split(b'\0')[0] == b'FIORENTINA':
            for j in range(16):
                if d[o + 76 + j * 38 + 26] >> 5:
                    d[o + 76 + j * 38 + 26] |= 0x18
    team = os.path.join(WORK, 'saves', 'TEAM020_BLOND.BIN')
    os.makedirs(os.path.dirname(team), exist_ok=True)
    open(team, 'wb').write(d)
    spr = shirtnum.spr_index(lepatch.LEPatch(os.path.join(b, 'ITALIAN.EXE')))
    errs = []
    nib = lambda data: [x >> 4 for x in data] + [x & 15 for x in data]
    with Session('blond_faces', b, {'DATA/TEAM.020': team}, 'dump:3', 300, match=True) as s:
        s.wait()
        italy_friendly(s, 'FIORENTINA', 'INTER')
        r = s.result
        p189 = struct.unpack('<I', r.read(r.base2 + spr + 189 * 4, 4))[0]
        icon = r.read(struct.unpack('<I', r.read(p189, 4))[0], 64) if p189 else b''
        check(15 in nib(icon[:24]), f'face icon 189 without yellow hair ({icon[:24].hex()})', errs)
        for _ in range(22):
            s.send('down dump:0.5')
            if s.screen().selected == 9:
                break
        r = s.send('fire ' + 'fire:3 ' * 8 + 'dump:2')
        check(r.outcome == 'dump', f'match {r}', errs)
        if r.outcome == 'dump':
            vs = variant_sets(r)                  # (4.0.5: single-team slots - FIORENTINA's darkblond set)
            first = next((v for (t, f), v in vs.items() if f == 1), blond.NEW1)
            ptrs = struct.unpack('<101I', r.read(r.base2 + spr + first * 4, 101 * 4))
            check(all(ptrs), f'sprite set not registered ({vs})', errs)
            if all(ptrs):
                h = r.read(ptrs[0], 24)
                w, nl, wq = struct.unpack_from('<hhh', h, 10)
                px = nib(r.read(struct.unpack('<I', h[:4])[0], wq * 8 * nl))
                check(15 in px and 5 not in px, f'set {first} frame 0: yellow {15 in px}, light skin 5 {5 in px}', errs)
    return not errs, '; '.join(errs) or 'blond face icon in the pre-match screen; sprite set 1418.. yellow hair, dark skin'



@scenario
def world_byes():
    """National-cup first-round byes in a career (lib97 nc_bye / nc_adv): the template world (packs/_template_world)
    with the ALPHA cup cut to 6 clubs, 2 of them with a bye (ALPHA ROVERS, ALPHA ATHLETIC); career at ALPHA ROVERS:
    it plays no round 1, round 1 is ties.csv's (fixed draw, first season), round 2 the fixed draw (ALPHA ROVERS v
    ALPHA ATHLETIC = its a3 v a4), it plays its semi-final, the season ends"""
    import csv
    import shutil
    pk = os.path.join(WORK, 'packs', 'world-byes')
    shutil.rmtree(pk, ignore_errors=True)
    shutil.copytree(os.path.join(ROOT, 'packs', '_template_world'), pk)
    f = os.path.join(pk, 'alpha', 'ties.csv')
    rows = list(csv.DictReader(open(f)))
    r1 = [r for r in rows if r['round'] == '1']
    byes = [{'competition': r['competition'], 'round': '1', 'home': r['winner'], 'away': '', 'winner': ''} for r in r1[2:]]
    with open(f, 'w', newline='') as fh:
        w = csv.DictWriter(fh, fieldnames=['competition', 'round', 'home', 'away', 'winner'])
        w.writeheader()
        w.writerows(r1[:2] + byes + [r for r in rows if r['round'] != '1'])
    exe = build('world_byes', env={'SEASON_PACKS': ','.join(['ddr-1988-89'] + [os.path.join(pk, x) for x in ('alpha', 'beta')])})
    errs, titles, slot, seen = [], [], [None], []
    with Session('world_byes', exe, {}, 'dump:2', 900) as s:
        if s.wait().outcome != 'dump':
            return False, f'START: {s.result}'
        for t in ('CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', '1984-85', 'ALPHA', 'ALPHA LEAGUE', 'ALPHA ROVERS'):
            if press(s, s.screen(), t) is None or s.result.outcome != 'dump':
                return False, f'new career: {t} not reached ({s.result})'
        d = s.result.obj2(0, 0x100000)                  # the ALPHA cup's slot (id D3, 6 clubs)
        hits = [i - 0x2D for i in range(0x2D, len(d) - 0x443) if d[i] == 0xD3 and d[i + 4:i + 6] == b'\x06\x00'
                and d[i - 0x2D + 0x59] == 3]
        if not hits:
            return False, 'ALPHA cup slot not found'
        slot[0] = hits[0]
        start = list(s.result.obj2(slot[0] + 0x2CD, 6))   # round 1 in ties.csv order (fixed draw, first season)

        def stop(scr):
            t = scr.entries[0][1] if scr.entries else ''
            if 'ALPHA CUP' in t and t not in titles:
                titles.append(t)
            c = s.result.obj2(slot[0], 0x443)
            if c[0x57] == 1 and not seen:
                seen.append(list(c[0x2CD:0x2CD + 4]))
            return season_over(scr)
        ok, msg = advance(s, stop, 300)
    semi = bool(titles) and 'SEMIFINALE' in titles[0]
    if not ok and semi and 'squad screen' in msg:       # (the template's 16-man squads: no fit stand-in left after
        msg += ' (after the semi-final: accepted)'      # injuries; the cup checks below are already decided)
        ok = True
    check(ok, msg, errs)
    check(semi, f'ALPHA ROVERS cup matches {titles} (first must be the semi-final)', errs)
    check(start[:4] == [0, 1, 2, 3], f'round 1 list {start} (ties.csv order: 0 1 2 3, byes 4 5 left out)', errs)
    check(seen and seen[0][0] in (2, 3) and seen[0][1] in (0, 1) and seen[0][2:4] == [4, 5],
          f'round 2 list {seen} (fixed draw: winner of tie 2 v winner of tie 1, then 4 v 5 = ties.csv a2-a1, a3-a4)', errs)
    return not errs, '; '.join(errs) or f'{msg}; cup matches {titles}; round 1 {start[:4]}, round 2 list {seen[0]}'



def conti_free_ids(world):
    """An older world snapshot's competition ids that 4.0.1's conti reserves for the career club's continental contests
    (conti.IDS: e.g. world5tm-formats' AUS / CHN / EGY / IRN cups on DA..DF -> conti's build assert) moved to ids no
    pack of the snapshot uses, outside mkseason.RESERVED_IDS (the released data moved them the same way); returns
    {old: new} (hex strings)."""
    import json
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import conti
    import mkseason
    packs = [os.path.join(world, x, 'pack.json') for x in sorted(os.listdir(world))
             if os.path.exists(os.path.join(world, x, 'pack.json'))]
    data = {f: json.load(open(f)) for f in packs}
    used = {int(str(c['id']), 16) for d in data.values() for c in d.get('competitions', []) if c.get('id')}
    free = [i for i in range(0xE0, 0xFC) if i not in used and i not in conti.IDS and i not in mkseason.RESERVED_IDS]
    moved = {}
    for f, d in data.items():
        hit = False
        for c in d.get('competitions', []):
            if c.get('id') and int(str(c['id']), 16) in conti.IDS:
                new = '%X' % free.pop(0)
                moved[str(c['id'])] = new
                c['id'] = new
                hit = True
        if hit:
            json.dump(d, open(f, 'w'), indent=1, ensure_ascii=False)
    return moved


@scenario
def world_groups():
    """Parallel groups of one level (pgroups.py): the world 2026-27 (private data internal/world2526/world5tm) with
    Italy's Serie C as 3 groups of 20 below Serie B ('parallel', groups promote their winner only, B's 3 relegated
    clubs spread over the groups by area); a season at RENATE (Serie C): after it every Italian division holds 20,
    the 3 group winners are in B, B's 3 relegated clubs are in the groups, no club moved between groups"""
    import collections
    import json
    import shutil
    src = (os.environ.get('W2627G_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-formats')).rstrip('/')
                                     # (a snapshot with Italy in 5 divisions: world5tm's has 14, 'parallel' a list)
    if not os.path.isdir(src):
        return True, f'SKIP: private data {src} missing'
    w = os.path.join(WORK, 'world_groups')
    shutil.rmtree(w, ignore_errors=True)
    shutil.copytree(src, os.path.join(w, 'world5tm'))
    conti_free_ids(os.path.join(w, 'world5tm'))       # (the snapshot's cups off conti's reserved ids)
    f = os.path.join(w, 'world5tm', 'ita', 'pack.json')
    d = json.load(open(f))
    lg = next(c for c in d['competitions'] if c['type'] == 'league')
    dv = lg['divisions']
    dv[1]['promoted'], dv[1]['relegated'] = 3, 3
    for g in (2, 3, 4):
        dv[g]['promoted'], dv[g]['relegated'] = 1, 0
    lg['parallel'] = {'upper': 1, 'first': 2, 'count': 3}
    lg.pop('playoffs', None)                    # (pgroups alone: no dplay moves; world_playoffs has them)
    json.dump(d, open(f, 'w'), indent=1, ensure_ascii=False)
    order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]   # (the converter's file order)
    packs = [os.path.join(w, 'world5tm', x) for x in order]
    env = {'SEASON_PACKS': ','.join(['ddr-1988-89'] + packs)}
    exe = build('world_groups', env=env)
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    old = os.environ.get('SEASON_PACKS')
    os.environ['SEASON_PACKS'] = env['SEASON_PACKS']
    mkseason = mkseason_now()
    pk = [p for p in mkseason.packs() if p.parallel()][0]
    if old is None:
        os.environ.pop('SEASON_PACKS')
    else:
        os.environ['SEASON_PACKS'] = old
    _, levels, clubs = pk.parallel()
    first, sizes = next((d, sz) for d, sz in levels if len(sz) > 1)
    u = first - 1
    keep = {k: os.environ.get(k) for k in ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K',
                                            'W8485_NOSACK', 'W8485_SEASONS')}
    os.environ.update(W8485_BUILD=exe, W8485_WORLD='MONDO 2026-27', W8485_TEAM='EUROPA,ITALIA,SERIE C GIRONE A,RENATE',
                      W8485_WNUM='5', W8485_K='108+', W8485_NOSACK='1')
    try:
        ok, msg = world8485()
    finally:
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'W84A.CAR')
    if not os.path.exists(car):
        return False, f'no season-1 save: {msg}'
    slt = open(car, 'rb').read()[0xE8DC:0xE8DC + 2000]           # someLeaguesTable (ITA save offset)
    cnt, ups, downs, side = collections.Counter(), 0, 0, 0
    for g, base, _ in clubs:
        new = base + struct.unpack('b', slt[g:g + 1])[0]
        cnt[new] += 1
        if base >= first and new == u:
            ups += 1
        elif base == u and new >= first:
            downs += 1
        elif base >= first and new >= first and new != base:
            side += 1
    errs = []
    check(ok, msg, errs)
    check(all(cnt[first + i] == n for i, n in enumerate(sizes)) and cnt[u] == 20, f'divisions {sorted(cnt.items())}', errs)
    check(ups == len(sizes) and downs == 3 and side == 0, f'group winners up {ups}, B down {downs}, group to group {side}', errs)
    return not errs, '; '.join(errs) or f'{msg}; divisions {sorted(cnt.items())}; up {ups}, down {downs}'



@scenario
def world_playoffs():
    """Italian play-offs at the season end (dplay.py): the world 2026-27 (private data internal/world2526/world5tm)
    with Serie B promoted 2 / relegated 3, the Serie C groups promoted 1 / relegated 0 and league 'playoffs': 'ita';
    a season at RENATE (Serie C, Serie B simulated): after it every Italian division holds 20, Serie B sent 3 up and
    4 down, the groups sent 4 up (3 winners + the play-off winner), no club moved between groups"""
    import collections
    import json
    import shutil
    src = (os.environ.get('W2627G_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-formats')).rstrip('/')
                                     # (a snapshot with Italy in 5 divisions: world5tm's has 14, 'parallel' a list)
    if not os.path.isdir(src):
        return True, f'SKIP: private data {src} missing'
    w = os.path.join(WORK, 'world_playoffs')
    shutil.rmtree(w, ignore_errors=True)
    shutil.copytree(src, os.path.join(w, 'world5tm'))
    conti_free_ids(os.path.join(w, 'world5tm'))       # (the snapshot's cups off conti's reserved ids)
    f = os.path.join(w, 'world5tm', 'ita', 'pack.json')
    d = json.load(open(f))
    lg = next(c for c in d['competitions'] if c['type'] == 'league')
    dv = lg['divisions']
    dv[1]['promoted'], dv[1]['relegated'] = 2, 3
    for g in (2, 3, 4):
        dv[g]['promoted'], dv[g]['relegated'] = 1, 0
    lg['parallel'] = {'upper': 1, 'first': 2, 'count': 3}
    lg['playoffs'] = 'ita'
    json.dump(d, open(f, 'w'), indent=1, ensure_ascii=False)
    order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]   # (the converter's file order)
    packs = [os.path.join(w, 'world5tm', x) for x in order]
    env = {'SEASON_PACKS': ','.join(['ddr-1988-89'] + packs)}
    exe = build('world_playoffs', env=env)
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    old = os.environ.get('SEASON_PACKS')
    os.environ['SEASON_PACKS'] = env['SEASON_PACKS']
    mkseason = mkseason_now()
    pk = [p for p in mkseason.packs() if p.parallel()][0]
    if old is None:
        os.environ.pop('SEASON_PACKS')
    else:
        os.environ['SEASON_PACKS'] = old
    _, levels, clubs = pk.parallel()
    first, sizes = next((d, sz) for d, sz in levels if len(sz) > 1)
    u = first - 1
    keep = {k: os.environ.get(k) for k in ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K',
                                            'W8485_NOSACK', 'W8485_SEASONS')}
    os.environ.update(W8485_BUILD=exe, W8485_WORLD='MONDO 2026-27', W8485_TEAM='EUROPA,ITALIA,SERIE C GIRONE A,RENATE',
                      W8485_WNUM='5', W8485_K='108+', W8485_NOSACK='1')
    try:
        ok, msg = world8485()
    finally:
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'W84A.CAR')
    if not os.path.exists(car):
        return False, f'no season-1 save: {msg}'
    slt = open(car, 'rb').read()[0xE8DC:0xE8DC + 2000]           # someLeaguesTable (ITA save offset)
    cnt, mv = collections.Counter(), collections.Counter()
    for g, base, _ in clubs:
        new = base + struct.unpack('b', slt[g:g + 1])[0]
        cnt[new] += 1
        if new != base:
            mv['A' if base == 0 else 'B' if base == u else 'C', 'A' if new == 0 else 'B' if new == u else
               'C' if new >= first else '?'] += 1
            if base >= first and new >= first:
                mv['C-C'] += 1
    errs = []
    check(ok, msg, errs)
    check(all(cnt[first + i] == n for i, n in enumerate(sizes)) and cnt[u] == 20 and cnt[0] == 20,
          f'divisions {sorted(cnt.items())}', errs)
    check(mv['B', 'A'] == 3 and mv['A', 'B'] == 3 and mv['B', 'C'] == 4 and mv['C', 'B'] == 4 and not mv['C-C'],
          f'moves {dict(mv)}', errs)
    return not errs, '; '.join(errs) or f'{msg}; divisions {sorted(cnt.items())}; moves {dict(mv)}'


@scenario
def world_dplay_b(force='5', team='EUROPA,ITALIA,SERIE B,MODENA'):
    """The career club's Serie B play-off, played (dplay step 2): the world 2026-27 (private data internal/world2526/
    world5tm, 'playoffs': 'ita'; W2627D_DATA: another snapshot) built with DPLAY_FORCE=5 (at the league end the
    career club takes 5th place); a season at MODENA: the PLAY-OFF SERIE B contest is built in slot 4 after the last
    league day and played to its end (the season log in W84A.CAR: kind 1, the 6 clubs with MODENA 5th in the order 5th
    8th 6th 7th 3rd 4th, a winner among them), and that winner is the club Serie B sends up besides the first two"""
    src = (os.environ.get('W2627D_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm')).rstrip('/')
    if not os.path.isdir(src):
        return True, 'SKIP: private data internal/world2526/world5tm missing'
    order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
    env = {'SEASON_PACKS': ','.join(['ddr-1988-89'] + [os.path.join(src, x) for x in order]), 'DPLAY_FORCE': force}
    exe = build('world_dplay_' + force + ('_' + os.path.basename(src) if os.environ.get('W2627D_DATA') else ''),
                env=env)                                     # (another snapshot: its own build dir)
    keep = {k: os.environ.get(k) for k in ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K',
                                            'W8485_NOSACK', 'W8485_HEX')}
    os.environ.update(W8485_BUILD=exe, W8485_WORLD='MONDO 2026-27', W8485_TEAM=team,
                      W8485_WNUM='5', W8485_K='108+', W8485_NOSACK='1')
    os.environ.setdefault('W8485_HEX', f'156d8:16,18e04:4,1b528:6,{CAL_AT - 4:x}:3000')   # (the state's head, slot 4,
                                                                                      # the calendar)
    try:
        ok, msg = world8485()
    finally:
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'W84A.CAR')
    if not os.path.exists(car):
        return False, f'no season-1 save: {msg}'
    d = open(car, 'rb').read()
    k = d.find(b'DPLG')
    errs = []
    check(ok, msg, errs)
    if k < 0:
        return False, f'{msg}; no dplay log in W84A.CAR'
    magic, res, kind, n = struct.unpack_from('<HHBB', d, k + 4)      # dplay.c dp_save (912 B)
    lines = open(os.path.join(RUNS, w84_tag() + '_1', 'session.log'), errors='replace').read().splitlines()
    rp = cal_replays(lines, CAL_AT - 4)
    check(not rp, f'slot 4 has {rp} replay days in the calendar (dplay decides level ties: no replays)', errs)
    teams = struct.unpack_from('<28H', d, k + 4 + 8)
    places = d[k + 4 + 120:k + 4 + 148]
    groups = d[k + 4 + 148:k + 4 + 176]
    nmv = d[k + 4 + 912]                                     # (then dp_out's head: nmv, ntie, ..)
    mv = [struct.unpack_from('<HHb', d, k + 4 + 912 + 4 + 8 * i) for i in range(min(nmv, 4))]
    out, cpo = force in ('16', '17'), int(force) > 100
    want = (3, 28) if cpo else (2, 2) if out else (1, 6)
    check(magic == 0x5044 and (kind, n) == want, f'state magic {magic:#x} kind {kind} n {n}', errs)
    if cpo:                                                  # 5th v 10th, 6th v 9th, 7th v 8th per group, 4ths, 3rds,
        check(list(places[:18]) == [4, 9, 5, 8, 6, 7] * 3 and list(places[18:24]) == [3] * 3 + [2] * 3 and places[24] == 10
              and list(places[25:]) == [1] * 3 and list(groups[:18]) == [g for g in (1, 2, 3) for _ in range(6)],
              f'places {list(places)} groups {list(groups)}', errs)   # the best 11th, 2nds
    else:
        check(list(places[:n]) == ([16, 15] if out else [4, 7, 5, 6, 2, 3]), f'places {list(places[:n])}', errs)
    check(res in teams[:n], f'winner {res:#x} not among {[hex(t) for t in teams[:n]]}', errs)
    if cpo:
        check(any(t == res and dl == -1 for _, t, dl in mv), f'C winner {res:#x} not moved up: moves {mv}', errs)
        sys.path.insert(0, os.path.join(ROOT, 'tools'))      # the two groups simulated at the league end: their
        old = os.environ.get('SEASON_PACKS')                   # winners then (the state's tables) = the clubs the
        os.environ['SEASON_PACKS'] = env['SEASON_PACKS']       # season end promoted from them
        mkseason = mkseason_now()
        pk = [p for p in mkseason.packs() if p.parallel()][0]
        if old is None:
            os.environ.pop('SEASON_PACKS')
        else:
            os.environ['SEASON_PACKS'] = old
        glob = {}
        for key in pk.league_clubs:
            fl, i = pk.where[key]
            base = next(b for fk, (ff, b) in pk.files.items() if ff == fl)
            glob[fl | (i << 8)] = base + i
        slt = d[0xE8DC:0xE8DC + 2000]
        sg = d[k + 4 + 270:k + 4 + 272]
        for j in range(2):
            win = struct.unpack_from('<H', d, k + 4 + 272 + 320 * j)[0]
            g = glob.get(win)
            check(sg[j] and g is not None and sg[j] + struct.unpack('b', slt[g:g + 1])[0] == 1,   # (-> Serie B, pgroups)
                  f'group division {sg[j]}: early winner {win:#x} (global {g}) not promoted', errs)
    elif out:                                                # the play-out's loser goes down
        lose = teams[1] if res == teams[0] else teams[0]
        check(any(t == lose and dl == 1 for _, t, dl in mv), f'loser {lose:#x} not moved down: moves {mv}', errs)
    else:
        check(any(t == res and dl == -1 for _, t, dl in mv), f'winner {res:#x} not moved up: moves {mv}', errs)
    return not errs, '; '.join(errs) or (f'{msg}; clubs {[hex(t) for t in teams[:n]]}, winner {res:#x} '
                                         f'(place {places[teams.index(res)] + 1}), moves {mv}')



