@scenario
def squad_order_xtra():
    """TEST 8 regression (2026-10-21: ACCETTA OFFERTA froze in every World 2026-27 career): a new career at SAO PAULO
    (an XTRA club, 16 + its real extras) has a squad order in trainingMatchSavedPlayers: a permutation of
    0..careerNumPlayers-1. xtra skipped cseg_64A65 (the invented reserves) and with it cseg_6481C's copy of the order,
    so the array stayed 0 and a sale's cseg_639F9 ('int 3; jmp $' when the sold player is not in it) trapped. The
    1984-85 world (no XTRA: the game's own reserves) as the control."""
    from le import LE
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    exe = os.environ.get('W8485_BUILD') or builds()['it']
    d1 = LE(open(os.path.join(exe, 'ITALIAN.EXE'), 'rb').read()).obj_bytes(1)
    m = re.search(rb'\xc7\x05(.{4})(.{4})\x66\xa1(.{4})\x66\xa3.{4}\x66\x83\x2d.{4}\x01\x8b\x35\1.{0,40}?\xcc\xeb\xfe',
                  d1, re.S)                     # cseg_639F9's lookup: A6 = the order, careerNumPlayers, int 3; jmp $
    tmsp, cnp = struct.unpack('<I', m.group(2))[0], struct.unpack('<I', m.group(3))[0]
    errs, notes = [], []
    for world, team in (('MONDO 2026-27', 'SUDAMERICA,BRASILE,BRASILEIRAO SERIE A,SAO PAULO'),
                        ('EUROPA 1984-85', 'INGHILTERRA,FIRST DIVISION,LIVERPOOL')):
        with Session('squad_order_' + world.split()[0].lower(), exe, {}, 'dump:2', 300) as s:
            s.wait()
            path = ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', world] + team.split(',')
            for k, t in enumerate(path):
                if all(press(s, s.screen(), x) is None for x in t.split('|')):
                    if k == 3 and world.startswith('EUROPA'):      # (a test build without the 1984-85 world)
                        notes.append(f'{world}: not in this build'); break
                    return False, f'{world}: {t} not reached'
            else:
                path = None
            if path is not None:
                continue
            s.send('fire dump:3')
            n = struct.unpack('<H', s.result.obj2(cnp, 2))[0]
            order = list(s.result.obj2(tmsp, 32))[:n]
            notes.append(f'{world}: {n} players, order {order}')
            check(n > 16 and sorted(order) == list(range(n)), f'{world}: squad order {order} ({n} players)', errs)
    return not errs, '; '.join(errs + notes)


@scenario
def career_20seasons():
    """Release check (Davide, 4.0): a World 2026-27 career through 20 seasons, the most a career allows (an old mod
    froze at the 7th): season 1 new, then each season from the previous one's save (world8485 with W8485_FROM: load,
    play to the season end, next season's save) - a save + reload every season, checkw1 at each one. HAMRUN SPARTANS
    (Malta: a short league; C20_TEAM to change), the minimal line-up, no sacking. Logs every season end with its time.
    PASS = 20 seasons, no trap, no freeze."""
    team = os.environ.get('C20_TEAM', 'EUROPA,MALTA,?MALTESE PREMIER LEAGUE|PREMIER LEAGUE,HAMRUN SPARTANS')
    n = int(os.environ.get('C20_SEASONS', 20))
    keys = ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K', 'W8485_NOSACK', 'W8485_ONE',
            'W8485_FROM', 'SWOSTEST_TAG')
    keep = {k: os.environ.get(k) for k in keys}
    exe = os.environ.get('W8485_BUILD') or builds()['it']
    times, notes, car = [], [], None
    try:
        os.environ.update(W8485_BUILD=exe, W8485_WORLD='MONDO 2026-27', W8485_TEAM=team, W8485_WNUM='5',
                          W8485_K='108+', W8485_NOSACK='1')
        for season in range(1, n + 1):
            os.environ['SWOSTEST_TAG'] = f'_c20s{season:02d}'
            if season == 1:
                os.environ['W8485_ONE'] = '1'
                os.environ.pop('W8485_FROM', None)
            else:
                os.environ.pop('W8485_ONE', None)
                os.environ['W8485_FROM'] = car
            t0 = time.time()
            ok, msg = world8485()
            times.append(round(time.time() - t0))
            print(f'[c20] season {season}: {"ok" if ok else "FAIL"} in {times[-1]} s: {msg[:160]}', flush=True)
            if not ok and season == n == 20:              # (the 20th season's end: the game ends the career -
                log = open(os.path.join(RUNS, w84_tag() + '_2', 'session.log'), errors='replace').read()   # 'LA TUA
                if "CARRIERA E' FINITA" in log and 'PENSIONAMENTO' in log:   # CARRIERA E' FINITA', PENSIONAMENTO, no
                    notes.append(f'season {season}: the career ends (20 seasons: the game\'s limit)')   # next season)
                    break
            if not ok or 'checkw1 FAIL' in msg:
                return False, f'season {season} of {n}: {msg[:300]}; times {times}'
            nxt = os.path.join(RUNS, w84_tag() + ('_1' if season == 1 else '_2'), 'SWOS',
                               'W84A.CAR' if season == 1 else 'W84B.CAR')
            if not os.path.exists(nxt):
                return False, f'season {season}: no save {nxt}; times {times}'
            car = os.path.join(RUNS, f'c20_after_s{season:02d}.CAR')
            shutil.copy(nxt, car)
    finally:
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    return True, f'{n} seasons, save + reload each; seconds per season {times} (total {sum(times)}); ' + '; '.join(notes)


def odd_build():
    """world_odd_league's build when no ODD_BUILD is given: this checkout with the newest release data
    (internal/world2526/world5tm-rel40-*: India's Football League has 11 clubs), built once per run (the staged
    builds/w2627odd-* of 10-18 had gone stale: the per-country balance trap at obj1+0x8476C on b8's suite run)."""
    import glob
    if not os.environ.get('_ODD_B'):
        src = sorted((d for d in glob.glob(os.path.join(MAIN, 'internal', 'world2526', 'world5tm-rel40-*'))
                      if os.path.isdir(d)), key=os.path.getmtime)[-1]
        order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
        os.environ['_ODD_B'] = build('w2627odd-cur', env={'SEASON_PACKS': ','.join(
            ['ddr-1988-89'] + [os.path.join(src, x) for x in order])})
    return os.environ['_ODD_B']


@scenario
def world_odd_league():
    """A league with an odd number of clubs (mkseason.odd_leagues: the engine's own rest day, no phantom club): the
    full world with the real odd sizes (ODD_BUILD, default the newest internal/swostest/builds/w2627odd-*), a
    season at DEMPO (India's Football League, the 2nd division, 11 clubs; the NZ National League is gone from the
    final data): 22 days of 5 matches, every club 20 matches and 2 rests, the season ended and the next one started"""
    b = os.environ.get('ODD_BUILD') or odd_build()
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import split
    import lepatch
    sa = split.sites(lepatch.LEPatch(os.path.join(MAIN, 'orig', 'ITALIAN.EXE')))
    n = int(os.environ.get('ODD_CLUBS', 11))
    keep = {k: os.environ.get(k) for k in ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K',
                                            'W8485_NOSACK', 'W8485_DIY', 'W8485_TMO', 'W8485_SLOTS')}
    os.environ.update(W8485_BUILD=b, W8485_WORLD='MONDO 2026-27', W8485_WNUM='5', W8485_K='108+', W8485_NOSACK='1',
                      W8485_TEAM=os.environ.get('ODD_TEAM', 'ASIA,INDIA,INDIAN FOOTBALL LEAGUE,DEMPO'),
                      W8485_DIY=f"{sa['DIY']:x},{split.ST:x},{sa['CAL']:x},{n:x}", W8485_TMO='600',
                      W8485_SLOTS=f"{sa['SLOTS']:x}")
    try:
        ok, msg = world8485()
    finally:
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    log = open(os.path.join(RUNS, f'{w84_tag()}_1', 'session.log')).read().splitlines()
    diys = [bytes.fromhex(ln[4:]) for ln in log if ln.startswith('DIY ')]
    if not diys:
        return False, f'no snapshot of a {n}-club league; {msg}'
    clubs = lambda x: sorted(x[0x12D:0x12D + 2 * n])
    diys = [x for x in diys if clubs(x) == clubs(diys[0])]
    last = diys[-1]
    w = lambda k: struct.unpack_from('<H', last, k)[0]
    rows = [struct.unpack_from('<I7H', last, 0x2B3 + 18 * r) for r in range(n)]
    errs = []
    check(w(0x1C1) == w(0x1C3) == 2 * n and w(0x5F) == 0, f'days {w(0x1C1)} / {w(0x1C3)}, {2 * n} wanted', errs)
    check(all(t[1] == 2 * (n - 1) and t[2] + t[3] + t[4] == t[1] for t in rows),
          f'played {[t[1] for t in rows]}, {2 * (n - 1)} wanted', errs)
    check(ok, msg, errs)
    return not errs, '; '.join(errs) or f'{n} clubs, {2 * n} days, every club {2 * (n - 1)} matches; {msg}'


def sa_exact_build(code, also=()):
    """The world 2026-27 (SA_DATA, default the 4.0 RC data world5tm-a6cf4e34) with one South American country's real
    2026 format applied (internal/sam6/sa_exact.py, 4.0.1); SA_BUILD reuses one."""
    import json
    if os.environ.get('SA_BUILD'):
        return os.environ['SA_BUILD']
    src = os.environ.get('SA_DATA') or os.environ.get('W2627REL_DATA') or \
        os.path.join(MAIN, 'internal', 'world2526', 'world5tm-401nats')   # (4.0.1's snapshot; 4.0's was a6cf4e34)
    sys.path.insert(0, os.path.join(MAIN, 'internal', 'sam6'))
    import sa_exact
    w = os.path.join(WORK, f"world_sa_{'_'.join((code, *also))}")
    shutil.rmtree(w, ignore_errors=True)
    shutil.copytree(src, os.path.join(w, 'world5tm'))
    for c in (code, *also):
        f = os.path.join(w, 'world5tm', c, 'pack.json')
        m = json.load(open(f))
        lg = m['competitions'][0]
        if 'split' in (lg['divisions'][0] if 'divisions' in lg else lg):   # (release data, 4.0.1 rc: the exact design
            continue                                                    # already in the pack - applied once only)
        json.dump(sa_exact.EXACT[c](m), open(f, 'w'), indent=1, ensure_ascii=False)
    shutil.copy(src + '.txt', os.path.join(w, 'world5tm.txt'))      # (full_season: the data's file order)
    order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
    tag = '_' + os.environ['SWOSTEST_TAG'] if os.environ.get('SWOSTEST_TAG') else ''
    return build(f"world_sa_{'_'.join((code, *also))}{tag}", env={'SEASON_PACKS': ','.join(['ddr-1988-89'] + [os.path.join(w, 'world5tm', x)
                                                                                      for x in order])})


def world_sa_exact(code, team, n, days, stages=2):
    """A season of a South American country's real 2026 format (sa_exact) at team: its n-club league frozen in both
    tournaments, days match days, two stage titles (Apertura / Clausura or Finalizacion) in the season end's GP_LOG."""
    exe = sa_exact_build(code)
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import split
    import lepatch
    sa = split.sites(lepatch.LEPatch(os.path.join(MAIN, 'orig', 'ITALIAN.EXE')))
    log_at, st_at, log_n, st_n = gp_ptrs(exe)
    from le import LE
    d1 = LE(open(os.path.join(exe, 'ITALIAN.EXE'), 'rb').read()).obj_bytes(1)
    ssb = struct.unpack_from('<I', d1, d1.find(b'GPLOGPTR') + 8 + 64)[0]
    item = 6 + 4 * 32 * 12                      # (GP_SSB: bank 1 = the career league's stage tables)
    keep = {k: os.environ.get(k) for k in ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K',
                                            'W8485_NOSACK', 'W8485_HEX', 'W8485_DIY', 'W8485_TMO', 'W8485_ONE')}
    os.environ.update(W8485_BUILD=exe, W8485_WORLD='MONDO 2026-27', W8485_WNUM='5', W8485_K='108+', W8485_NOSACK='1',
                      W8485_TEAM=team, W8485_ONE='1', W8485_TMO='600',
                      W8485_HEX=f'{log_at:x}:{log_n},{ssb:x}:{2 * item}',
                      W8485_DIY=f"{sa['DIY']:x},{split.ST:x},{sa['CAL']:x}")
    try:
        ok, msg = world8485()
    finally:
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    log = open(os.path.join(RUNS, w84_tag() + '_1', 'session.log'), errors='replace').read().splitlines()
    errs = []
    check(ok, msg, errs)
    diys = [b for b in (bytes.fromhex(ln[4:]) for ln in log if ln.startswith('DIY ')) if b[0:2] == b'\0\0']
    w = lambda b, k: struct.unpack_from('<H', b, k)[0]
    diys = [b for b in diys if w(b, 0x31) == n]
    check(diys, f'no snapshot of the {n}-club league', errs)
    if diys:
        last = diys[-1]
        check(last[split.ST + split.OFF['frozen']] == stages and w(last, 0x1C1) == w(last, 0x1C3) == days,
              f'end: frozen {last[split.ST + split.OFF["frozen"]]}, day {w(last, 0x1C1)} / {w(last, 0x1C3)} ({days})', errs)
    logs = [bytes.fromhex(ln.split()[2]) for ln in log if ln.startswith('HEX ') and len(ln.split()) == 3]
    logs = [b for b in logs if b[:4] == b'GPLG']
    check(logs, 'no season-end GP_LOG', errs)
    sres = [struct.unpack_from('<BBHHHH', logs[-1], 982 + 10 * i) for i in range(3)] if logs else []
    nt = min(stages, 3)                         # (Uruguay: Apertura 0, Clausura 1, Intermedio 2)
    check(len(sres) == 3 and all(x[0] == 8 and x[2] for x in sres[:nt]), f'stage titles {sres}', errs)
    banks = [bytes.fromhex(ln.split()[2]) for ln in log if ln.startswith('HEX ') and len(ln.split()) == 3
             and int(ln.split()[1], 16) == ssb]
    if code in ('per', 'uru', 'par') and banks and len(sres) == 3:   # (rc3: a table title = its table's leader -
        b, o = banks[-1], item                                       # rc2 gave the Apertura to row 0 of the reset
        for stg, tab in ((0, 0), (1, 3 if stages == 3 else 1)):      # table, gp_lend_c's bank 0)
            lead = struct.unpack_from('<H', b, o + 6 + tab * 32 * 12)[0] if b[o + tab] else None
            check(lead is not None and sres[stg][2] == lead,
                  f'stage {stg} title {sres[stg][2]:#x} != table {tab} leader {lead and hex(lead)}', errs)
    return not errs, '; '.join(errs) or f'{msg}; {days} days, stage titles {sres[:nt]}'


@scenario
def world_sa_banks():
    """4.0.1 GP_SS banks (gplay.c GP_SSB): Peru and Colombia exactly next to Argentina (+ MLS) in one world, a season at
    ALIANZA LIMA; at the season end every bank holds only its own league's clubs: bank 0 = Argentina's Apertura /
    Clausura / annual (4.0's item 'SS'), bank 1 = the career league's (Peru, item 'SS2'), bank 3 = Colombia's
    (transient: 1 + its index)"""
    import json
    exe = sa_exact_build('per', ('col',))
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    from le import LE
    d1 = LE(open(os.path.join(exe, 'ITALIAN.EXE'), 'rb').read()).obj_bytes(1)
    k = d1.find(b'GPLOGPTR')
    ssb = struct.unpack_from('<I', d1, k + 8 + 64)[0]
    item = 6 + 4 * 32 * 12
    data = os.environ.get('SA_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-a6cf4e34')
    file_of = lambda c: json.load(open(os.path.join(data, c, 'pack.json')))['files']['league']['file']
    want = {0: file_of('arg'), 1: file_of('per'), 3: file_of('col')}   # (1: the career league's, saved; 1 + b)
    keep = {x: os.environ.get(x) for x in ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K',
                                            'W8485_NOSACK', 'W8485_HEX', 'W8485_ONE')}
    os.environ.update(W8485_BUILD=exe, W8485_WORLD='MONDO 2026-27', W8485_WNUM='5', W8485_K='108+', W8485_NOSACK='1',
                      W8485_TEAM='SUDAMERICA,PERU,ALIANZA LIMA', W8485_ONE='1', W8485_HEX=f'{ssb:x}:{4 * item}')
    try:
        ok, msg = world8485()
    finally:
        for x, v in keep.items():
            if v is None:
                os.environ.pop(x, None)
            else:
                os.environ[x] = v
    errs = []
    check(ok, msg, errs)
    dumps = [bytes.fromhex(ln.split()[2]) for ln in open(os.path.join(RUNS, w84_tag() + '_1', 'session.log'),
                                                             errors='replace') if ln.startswith('HEX ')]
    check(dumps, 'no GP_SSB dump', errs)
    info = []
    if dumps:
        b = dumps[-1]
        seen = {}
        for bank in range(4):
            base = bank * item
            n = list(b[base:base + 4])
            files = set()
            for t in range(4):
                for r in range(n[t] if n[t] <= 32 else 0):
                    files.add(struct.unpack_from('<H', b, base + 6 + (t * 32 + r) * 12)[0] & 255)
            info.append(f'bank {bank}: n {n} files {sorted(files)}')
            seen[bank] = files
        check(seen[0] and seen[0] <= {want[0], file_of('usa')}, f'bank 0 (4.0): files {sorted(seen[0])}', errs)
        check(seen[1] == {want[1]}, f'bank 1 (the career league, Peru): files {sorted(seen[1])}', errs)
        check(sum(seen[k] == {want[3]} for k in (2, 3)) == 1, f'Colombia in one transient bank: {seen}', errs)
        check(all(len(seen[k]) <= 1 for k in (1, 2, 3)), f'a bank with two leagues: {seen}', errs)
    return not errs, '; '.join(errs + info) + f'; {msg}'


@scenario
def world_sa_compat():
    """4.0 -> 4.0.1 save compatibility of the stage tables (GP_SS banks): a career at BOCA JUNIORS on the 4.0 build
    (SA_OLD_BUILD, default c/REL40/SWOS) saved right after Argentina's Apertura (split 'frozen' = 2), loaded on the
    4.0.1 build with Peru + Colombia exact and played to the season end: bank 0's annual table = the Apertura (from
    the 4.0 save) + the Clausura, club by club; the season ends"""
    import split
    import lepatch
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    from le import LE
    old = os.environ.get('SA_OLD_BUILD') or os.path.join(MAIN, 'c', 'REL40', 'SWOS')
    new_ = sa_exact_build('per', ('col',))
    sa = split.sites(lepatch.LEPatch(os.path.join(MAIN, 'orig', 'ITALIAN.EXE')))
    frozen = sa['DIY'] + split.ST + split.OFF['frozen']
    d1 = LE(open(os.path.join(new_, 'ITALIAN.EXE'), 'rb').read()).obj_bytes(1)
    k = d1.find(b'GPLOGPTR')
    ssb = struct.unpack_from('<I', d1, k + 8 + 64)[0]
    item = 6 + 4 * 32 * 12
    names = ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K', 'W8485_NOSACK', 'W8485_HEX',
             'W8485_ONE', 'W8485_MIDSAVE', 'W8485_FROM')
    keep = {x: os.environ.get(x) for x in names}
    base = dict(W8485_WORLD='MONDO 2026-27', W8485_WNUM='5', W8485_K='108+', W8485_NOSACK='1',
                W8485_TEAM='SUDAMERICA,ARGENTINA,LIGA PROFESIONAL DE FUTBOL,BOCA JUNIORS')
    errs, info = [], []
    try:
        for x in names:
            os.environ.pop(x, None)
        os.environ.update(base, W8485_BUILD=old, W8485_ONE='1', W8485_MIDSAVE=f'{frozen:x}:2:2')
        ok, msg = world8485()
        car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'W84A.CAR')
        check(ok and os.path.exists(car), f'4.0 mid-season save: {msg}', errs)
        if not errs:
            saved = os.path.join(RUNS, 'sa_compat_W84A.CAR')
            shutil.copy(car, saved)
            for x in names:
                os.environ.pop(x, None)
            os.environ.update(base, W8485_BUILD=new_, W8485_FROM=saved, W8485_HEX=f'{ssb:x}:{item}')
            ok, msg = world8485()
            check(ok, f'4.0.1 from the 4.0 save: {msg}', errs)
            dumps = [bytes.fromhex(ln.split()[2]) for ln in open(os.path.join(RUNS, w84_tag() + '_2', 'session.log'),
                                                                     errors='replace') if ln.startswith('HEX ')]
            ann = [b for b in dumps if b[4] & 4]              # (bank 0 with its annual table written)
            check(ann, f'no dump with the annual table ({len(dumps)} dumps)', errs)
            if ann:
                b = ann[-1]
                rows = lambda t: {struct.unpack_from('<H', b, 6 + (t * 32 + r) * 12 + 2)[0]:
                                  struct.unpack_from('<H', b, 6 + (t * 32 + r) * 12 + 10)[0] for r in range(b[t])}
                ap, cl, an = rows(0), rows(1), rows(2)
                bad = [g for g in an if an[g] != ap.get(g, -999) + cl.get(g, -999)]
                check(b[0] == b[1] == b[2] == 30 and not bad, f'annual != Apertura + Clausura for {len(bad)} clubs '
                      f'(n {list(b[:3])})', errs)
                info.append(f'annual of {len(an)} clubs = Apertura (4.0 save) + Clausura')
    finally:
        for x, v in keep.items():
            if v is None:
                os.environ.pop(x, None)
            else:
                os.environ[x] = v
    return not errs, '; '.join(errs + info)


@scenario
def world_sa_reload():
    """4.0.1 GP_SS banks across a mid-season save: a career at ALIANZA LIMA (Peru exact, Colombia exact in the same
    world) saved right after Peru's Apertura (bank 1 half-built), reloaded and played to the season end: Peru's annual
    = its Apertura (from the save) + Clausura, Colombia's (a transient bank, built at the season end) = its own two"""
    import split
    import lepatch
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    from le import LE
    exe = sa_exact_build('per', ('col',))
    sa = split.sites(lepatch.LEPatch(os.path.join(MAIN, 'orig', 'ITALIAN.EXE')))
    frozen = sa['DIY'] + split.ST + split.OFF['frozen']
    d1 = LE(open(os.path.join(exe, 'ITALIAN.EXE'), 'rb').read()).obj_bytes(1)
    ssb = struct.unpack_from('<I', d1, d1.find(b'GPLOGPTR') + 8 + 64)[0]
    item = 6 + 4 * 32 * 12
    names = ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K', 'W8485_NOSACK', 'W8485_HEX',
             'W8485_ONE', 'W8485_MIDSAVE', 'W8485_FROM', 'W8485_SAVE_END', 'W8485_NSDUMP')
    keep = {x: os.environ.get(x) for x in names}
    base = dict(W8485_BUILD=exe, W8485_WORLD='MONDO 2026-27', W8485_WNUM='5', W8485_K='108+', W8485_NOSACK='1',
                W8485_TEAM=os.environ.get('SA_TEAM') or 'SUDAMERICA,PERU,ALIANZA LIMA')
    errs, info = [], []
    try:
        for x in names:
            os.environ.pop(x, None)
        os.environ.update(base, W8485_ONE='1', W8485_MIDSAVE=f'{frozen:x}:2:2')
        ok, msg = world8485()
        car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'W84A.CAR')
        check(ok and os.path.exists(car), f'mid-season save: {msg}', errs)
        if not errs:
            saved = os.path.join(RUNS, 'sa_reload_W84A.CAR')
            shutil.copy(car, saved)
            for x in names:
                os.environ.pop(x, None)
            log_at, st_at, log_n, st_n = gp_ptrs(exe)
            d8caa = struct.unpack_from('<I', d1, d1.find(b'GPLOGPTR') + 8 + 60)[0]   # (GPLOGPTR's D8CAA)
            os.environ.update(base, W8485_FROM=saved, W8485_HEX=f'{ssb:x}:{4 * item},{st_at:x}:{st_n}',
                              W8485_NSDUMP=f'{d8caa:x}')
            ok, msg = world8485()                     # (to the next season: gp_season runs at CONTINUA CARRIERA)
            for ln in open(os.path.join(RUNS, w84_tag() + '_2', 'session.log'), errors='replace'):
                q = ln.split()
                if len(q) == 3 and q[0] == 'HEX' and int(q[1], 16) == st_at:
                    st = bytes.fromhex(q[2])
                    try:
                        k = gp_ko(st[GP_STKO:])
                        last_st = (f"GP_ST pend {st[:16].hex()} ko0 magic {k['magic']:#x} pi {k['pi']} season "
                                   f"{k['season']} n {k['n']} teams {[hex(x) for x in k['team'][:4]]}")
                    except (IndexError, KeyError) as e:
                        last_st = f'GP_ST {len(st)} B, undecoded ({e})'
            if 'last_st' in locals():
                info.append(last_st)
            check(ok, f'reloaded: {msg}', errs)
            dumps = [bytes.fromhex(ln.split()[2]) for ln in open(os.path.join(RUNS, w84_tag() + '_2', 'session.log'),
                                                                     errors='replace')
                     if ln.startswith('HEX ') and int(ln.split()[1], 16) == ssb]
            check(dumps, 'no GP_SSB dump', errs)
            if dumps:
                b = dumps[-1]
                for bank in (1, 2, 3):
                    o = bank * item
                    if not b[o]:
                        continue
                    rows = lambda t: {struct.unpack_from('<H', b, o + 6 + (t * 32 + r) * 12 + 2)[0]:
                                      struct.unpack_from('<H', b, o + 6 + (t * 32 + r) * 12 + 10)[0]
                                      for r in range(b[o + t])}
                    ap, cl, an, t3 = rows(0), rows(1), rows(2), rows(3)   # (table 3: Uruguay's Clausura, its
                    bad = [g for g in an                                     # Intermedio in table 1)
                           if an[g] != ap.get(g, -999) + cl.get(g, -999) + (t3.get(g, -999) if t3 else 0)]
                    what = 'the three stages' if t3 else 'the two tournaments'
                    check(an and not bad, f'bank {bank}: annual != {what} for {len(bad)} of {len(an)}', errs)
                    if an and not bad:
                        info.append(f'bank {bank}: {len(an)} clubs, annual = {what}')
    finally:
        for x, v in keep.items():
            if v is None:
                os.environ.pop(x, None)
            else:
                os.environ[x] = v
    return not errs, '; '.join(errs + info)


@scenario
def world_par_exact():
    """Paraguay 2026 (4.0.2: 44 days, option C's split - MAXDAYS 104): Apertura + Clausura double round robins at
    OLIMPIA; SKIP on a 4.0.1 engine (split's 40 days)"""
    import split
    if split.MAXDAYS < 44:
        return True, f'SKIP: 4.0.2 only (Paraguay 44 days, this split allows {split.MAXDAYS})'
    return world_sa_exact('par', 'SUDAMERICA,PARAGUAY,OLIMPIA', 12, 44)


@scenario
def world_winners_title():
    """4.0.2 WINNERS page, a national title play-off seeded by title_seed (winners.py / fmtgame 'Q'; WT_CODE per =
    Peru's PLAYOFFS LIGA 1, uru = Uruguay's CAMPEONATO URUGUAYO) at the league's weakest club (UTC /
    MALDONADO: not in the play-off): at the career's start the line shows DA GIOCARE (4.0.1 skipped it); at the season
    end (saved before CONTINUA, reloaded) the champion: A when one club won both tournaments (the bank's Apertura and
    Clausura 1st, A = C: no play-off), else the play-off's, previewed at the league's end (rc19, gp_pre_c) - pokes of
    the career bank's Clausura leader (GP_SSB bank 1) after the preview leave the line as it was decided; continued
    into 2027-28: the last season's page names the same champion"""
    code = os.environ.get('WT_CODE', 'per')
    team, title, ct = {'per': ('SUDAMERICA,PERU,UTC', 'PLAYOFFS LIGA 1', 1),
                       'uru': ('SUDAMERICA,URUGUAY,CAMPEONATO URUGUAYO,' + os.environ.get('WT_TEAM', 'MALDONADO'),
                               'CAMPEONATO URUGUAYO', 3)}[code]
    exe = sa_exact_build(code)
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    from le import LE
    d1 = LE(open(os.path.join(exe, 'ITALIAN.EXE'), 'rb').read()).obj_bytes(1)
    ssb = struct.unpack_from('<I', d1, d1.find(b'GPLOGPTR') + 8 + 64)[0]
    item = 6 + 4 * 32 * 12
    bank = ssb + item                                   # (bank 1: the career league's; table t row r at 6 + 12 (32t + r))
    lead = lambda b, t, r=0: struct.unpack_from('<H', b, 6 + 12 * (32 * t + r))[0]
    errs, info = [], []
    with Session(f'world_winners_title_{code}_start', exe, {}, 'dump:2', 600) as s:
        s.wait()
        for t in ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27'] + team.split(','):
            if press(s, s.screen(), t, 3) is None:
                return False, f'new career: {t} not reached'
        s.send('fire dump:3')
        e, ttl, lines = winners_page(s)
    b0 = winner_blocks(lines)
    check(b0.get(title) == 'DA GIOCARE', f'start: {title} {b0.get(title)!r} (page {ttl!r} {b0})', errs)
    info.append(f'start: {b0}')
    keys = ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K', 'W8485_NOSACK', 'W8485_ONE',
            'W8485_SAVE_END')
    keep = {k: os.environ.get(k) for k in keys}
    os.environ.update(W8485_BUILD=exe, W8485_WORLD='MONDO 2026-27', W8485_TEAM=team, W8485_WNUM='5', W8485_K='108+',
                      W8485_NOSACK='1', W8485_ONE='1', W8485_SAVE_END='WTIT')
    try:
        ok, msg = world8485()
    finally:
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    if not ok or 'saved ' not in msg:
        return False, '; '.join(errs + [f'season: {msg}'])
    car = msg.split('saved ', 1)[1]
    got = {}
    for case in ('as is', 'double', 'two'):
        with Session(f'world_winners_title_{code}_{case.replace(" ", "")}', exe, {'WTIT.CAR': car}, 'dump:2', 300) as s:
            s.wait()
            s.send(LOAD1 + ' dump:3')
            b = s.result.obj2(bank, item)
            a, c = lead(b, 0), lead(b, ct)
            if case == 'double':                        # (the Clausura's leader = the Apertura's)
                s.poke(s.result.base2 + bank + 6 + 12 * 32 * ct, struct.pack('<H', a))
                c = a
            elif case == 'two':                         # (another club leads the Clausura)
                c = lead(b, 0, 1)
                s.poke(s.result.base2 + bank + 6 + 12 * 32 * ct, struct.pack('<H', c))
            if case != 'as is':
                s.send('dump:1')
            e, ttl, lines = winners_page(s)
        blk = winner_blocks(lines)
        got[case] = blk.get(title)
        if case == 'as is':                             # (rc19: decided before the menu - A = C: A, else the
            want = team_name(exe, a) if a == c else None   # previewed play-off's champion, some club)
            ok_ = blk.get(title) == want if want else blk.get(title) not in (None, '', 'DA GIOCARE', 'IN CORSO')
        else:                                           # (the banks poked after the preview: the line as decided)
            want = got['as is']
            ok_ = blk.get(title) == want
        check(b[0] and b[ct] and ok_,
              f'end ({case}): {title} {blk.get(title)!r}, want {want!r} (A {team_name(exe, a)}, C {team_name(exe, c)};'
              f' n {list(b[:4])}; page {blk})', errs)
    info.append(f'end: {got}')
    with Session(f'world_winners_title_{code}_next', exe, {'WTIT.CAR': car}, 'dump:2', 600) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        nxt = next_season_save(s, 'WTIN')
    if not nxt.endswith('.CAR'):
        return False, '; '.join(errs + [f'next season: {nxt}'])
    with Session(f'world_winners_title_{code}_s2', exe, {'WTIN.CAR': nxt}, 'dump:2', 300) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        more = []
        e, ttl2, lines2 = winners_page(s, more)
    last = winner_blocks([x for pg in more for x in pg])   # (the last season's page and the next: 5 Uruguay titles)
    check(last.get(title) == got.get('as is'), f'season 2: last season {last}, the season end {got.get("as is")!r}',
          errs)
    info.append(f'last season: {last}')
    return not errs, '; '.join(errs + info)


