@scenario
def sc_rules_uefa():
    """4.0.6 the UEFA Super Cup (gplay.c usc_step, internal/handoff/csup.md), compiled for this Mac with forced holders
    (SC_U's season-end snapshot of the game's HOLD_CC / CWC / UEFA words), no exe run: (a) the career club the Champions League holder ->
    its tie v the Europa League holder built at the season's first advance (early; kind K_SC, slot 4, trace 11h),
    slot 4 held; (b) the career club also its country's early national supercup: the national one waits while the UEFA
    tie is pending, the UEFA one decided (won: state 3, record line), then the national one built; (c) one club holds
    both -> the Conference League holder; (d) ... and no Conference holder -> no edition (92h); (e) the career club not
    a holder: nothing built (94h), its national one built at the same advance; (f) the world's first season: skipped
    (91h); (g) lost -> no record line, another season -> none; (h) the reload's names follow the pending UEFA tie; (i) a snapshot of an older season (an older save) -> none."""
    import tempfile
    src = os.path.join(ROOT, 'tools', 'gplay.c')
    main = r"""#include <stdio.h>
#include "%s"
u8 GP_SEAS;
static u8 tab[1 + 2 * SC_E];
static struct gp_ko kk;
static void ent(u8 *t, int file, int from, int week) {
    t[0] = file; t[1] = file == SC_UEFA ? 0 : 0x82; t[2] = from | SC_EARLY; t[3] = week; t[4] = 1; t[5] = LV_PENS; t[6] = 2; t[7] = week;
    t[28] = 7; t[29] = 8;
    if (file == SC_UEFA) { t[8] = SCR_UCL; t[9] = SCR_UEL | SCR_UECL << 4; t[32] = 0x78; t[33] = 0x56; }
    else { t[8] = SCR_CHAMP; t[9] = SCR_CUPW | SCR_SECOND << 4; t[32] = 0x34; t[33] = 0x12; }
}
static void setup(int nat, u16 cl, u16 el, u16 ecl) {
    for (int i = 0; i < (int)sizeof SC_ST; i++) SC_ST[i] = 0;
    for (int i = 0; i < (int)sizeof GP_ST; i++) ((u8 *)&GP_ST)[i] = 0;
    for (int i = 0; i < (int)sizeof tab; i++) tab[i] = 0;
    CF_ST.magic = CF_MAGIC; CF_ST.file = 0x40;
    for (int i = 0; i < 256; i++) CF_ST.rank[i] = 0;
    CF_ST.rank[2] = 1; CF_ST.rank[5] = 2;                 /* (ENG: 0x0240 champion, 0x0540 2nd) */
    SC_ST[0] = 0x53; SC_ST[1] = 0x43; SC_ST[2] = 1;
    u8 *e = SC_ST + SC_H; e[0] = 0x40; e[1] = 0x82; e[4] = 0x40; e[5] = 0x03;   /* (cup winner 0x0340) */
    tab[0] = nat ? 2 : 1;
    ent(tab + 1, SC_UEFA, 2, 58);
    if (nat) ent(tab + 1 + SC_E, 0x40, 2, 59);
    SC_U[3] = 126; SC_U[6] = cl; SC_U[7] = cl >> 8; SC_U[8] = el; SC_U[9] = el >> 8; SC_U[10] = ecl; SC_U[11] = ecl >> 8;
    GP_SCT = tab; GP_SEAS = 127; SC_TRACE = 0; GP_SCFIRST = 0; GP_WK = 10;
}
static void decide(int won) {
    kk = GP_ST.ko[0]; kk.tw[0] = won ? (kk.team[0] == GP_MGR ? 0 : 1) : (kk.team[0] == GP_MGR ? 1 : 0);
    sc_done(&kk); GP_ST.ko[0].tw[0] = kk.tw[0];
}
static void out(const char *tag, u32 r) {
    printf("%%s %%u %%x %%x %%x %%d\n", tag, r, SC_TRACE, GP_ST.ko[0].team[0], GP_ST.ko[0].team[1], GP_ST.ko[0].kind);
}
int main(void) {
    u16 psg = 0x0130, villa = 0x0240, x = 0x0731;
    setup(0, psg, villa, x); GP_MGR = psg; out("a", sc_step_c());
    printf("a2 %%d %%d %%d %%d\n", sc_busy(), usc_live(), GP_ST.ko[0].d1, sc_step_c());
    setup(1, psg, villa, x); GP_MGR = villa; out("b", sc_step_c());
    printf("b1 %%u\n", sc_step_c());
    decide(1); printf("b2 %%d %%d %%x %%x %%d\n", SC_U[1], SC_U[2], SC_U[4] | SC_U[5] << 8, usc_rline(), usc_live());
    GP_ST.ko[0].kind = 0; SC_TRACE = 0; GP_WK = 58; out("b3", sc_step_c());
    setup(0, psg, psg, x); GP_MGR = x; out("c", sc_step_c());
    setup(0, psg, psg, 0xFFFF); GP_MGR = psg; out("d", sc_step_c());
    setup(1, psg, 0x0940, x); GP_MGR = villa; out("e", sc_step_c());
    setup(1, psg, villa, x); GP_MGR = villa; GP_SCFIRST = 1; out("f", sc_step_c());
    setup(0, psg, villa, x); GP_MGR = psg; sc_step_c(); decide(0); printf("g %%x %%d\n", usc_rline(), SC_U[1]);
    setup(0, psg, villa, x); GP_MGR = psg; sc_step_c(); decide(1); GP_SEAS = 128; printf("g2 %%x\n", usc_rline());
    setup(0, psg, villa, x); SC_U[3] = 125; GP_MGR = psg; out("i", sc_step_c());
    setup(0, psg, villa, x); GP_MGR = psg; sc_step_c();
    printf("h %%d %%d\n", usc_entry() == tab + 1, usc_live());
    return 0;
}
""" % src
    with tempfile.TemporaryDirectory() as d:
        open(os.path.join(d, 't.c'), 'w').write(main)
        r = subprocess.run(['clang', '-w', '-DSS_NB=1', '-c', 't.c', '-o', 't.o'], cwd=d, capture_output=True, text=True)
        if r.returncode:
            return False, 'clang: ' + r.stderr[-400:]
        und = [x.strip().lstrip('_') for x in subprocess.run(['nm', '-u', 't.o'], cwd=d, capture_output=True,
                                                              text=True).stdout.split()]
        open(os.path.join(d, 's.c'), 'w').write(''.join(f'char {x}[65536];\n' for x in und
                                                         if x and not x.startswith(('printf', 'memcpy', 'memset', 'dyld', '__'))))
        r = subprocess.run(['clang', '-w', 't.o', 's.c', '-o', 't'], cwd=d, capture_output=True, text=True)
        if r.returncode:
            return False, 'link: ' + r.stderr[-400:]
        got = {ln.split()[0]: ln.split()[1:] for ln in subprocess.run(['./t'], cwd=d, capture_output=True,
                                                                     text=True).stdout.splitlines()}
    want = {'a': ['1', '11', '130', '240', '10'], 'a2': ['1', '1', '58', '0'], 'b': ['1', '11', '130', '240', '10'],
            'b1': ['0'], 'b2': ['3', '1', '240', '5678', '0'], 'b3': ['1', '1', '240', '340', '10'],
            'c': ['1', '11', '130', '731', '10'], 'd': ['0', '92'], 'e': ['1', '1', '240', '340', '10'],
            'f': ['0', '81'], 'g': ['0', '3'], 'g2': ['0'], 'h': ['1', '1'], 'i': ['0', '92']}
    errs = [f'{k}: got {got.get(k)}, want {w}' for k, w in want.items() if (got.get(k) or [])[:len(w)] != w]
    return not errs, '; '.join(errs) or 'a CL holder v EL holder built early, b the national one after it, the record ' \
        'line, c double -> UECL holder, d no UECL -> none, e not a holder -> its national one, f season 1 skipped, ' \
        'g lost / next season no line, h reload names: all as expected'


@scenario
def tail_zero():
    """4.0.2 tailzero (Davide's MiSTer b3/b4, the 23/10 GOG DOSBox 0.74 report: no number over a controlled player
    numbered 17..99): the mod's obj2 tail (its run-time buffers: shirtnum's 'built' flag + sprites, careerworld / gplay /
    conti .bss ...) is not zeroed by the game's startup nor by DOS/4GW; DOSBox-X happens to give zeros. Every exe of the
    build dir (SWOSTEST_BUILD, else the test build) must route start's `call __CMain` through a stub that stores zero
    over exactly obj2's non-file part. (Negative control by hand: TAILZERO_FILL_TEST=5A builds a stub filling 5Ah, the
    MiSTer-like start: shirt_numbers then FAILs, spritesIndex[1335..] = 0.) No exe is run."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    d = os.environ.get('SWOSTEST_BUILD') or builds()['it']
    exes = [os.path.join(d, x) for x in ('ITALIAN.EXE', 'ENGLISH.EXE', 'FRENCH.EXE', 'GERMAN.EXE')
            if os.path.exists(os.path.join(d, x))]
    errs, info = [], []
    for exe in exes:
        p = lepatch.LEPatch(exe)
        c = p.le.obj_bytes(1)
        m = [x.start() for x in re.finditer(rb'\xb8\xff\x00\x00\x00\xe8....\x29\xed\xe8', c, re.S)]
        nm = os.path.basename(exe)
        if len(m) != 1:
            errs.append(f'{nm}: start call __CMain not found ({len(m)})')
            continue
        site = m[0] + 12
        stub = site + 5 + struct.unpack_from('<i', c, site + 1)[0]
        i = c.find(b'\xbf', stub, stub + 12)            # mov edi, TAIL / mov ecx, dwords / mov eax, fill / rep stosd
        o2 = p.le.obj(2)
        start, size = o2.npages * p.le.page_size, o2.vsize - o2.npages * p.le.page_size
        ok = i > 0 and c[i + 5] == 0xB9 and c[i + 10] == 0xB8 and c[i + 15:i + 18] == b'\xfc\xf3\xab'
        tgt = p.target(1, i + 1) if ok else None
        n = struct.unpack_from('<I', c, i + 6)[0] if ok else 0
        fill = struct.unpack_from('<I', c, i + 11)[0] if ok else None
        check(ok and tgt == (2, start) and n * 4 >= size and n * 4 - size < 4 and fill == 0,
              f'{nm}: stub obj1+{stub:#x} {c[stub:stub + 24].hex()} -> {tgt} x{n} fill {fill}; tail obj2+{start:#x}+{size:#x}', errs)
        info.append(f'{nm}: obj2+{start:#x}..+{size:#x} zeroed')
    if not exes:
        return False, f'no exe in {d}'
    return not errs, '; '.join(errs or info)


@scenario
def team_choice_colours():
    """4.0.2 teamstab (Davide, MiSTer b3): with no team chosen, every club button of a team list has the default colour.
    The lists colour a club by teamsTable[its ordinal], 100 bytes in the game; Italy 2026-27's file has 256 records and
    Brazil's 119: Serie D clubs (ordinals 100+) came out red / purple / blue (teamsIndex read). On a RELEASE dir
    (TEAMCOL_BUILD, else the suite's SWOSTEST_BUILD / W8485_BUILD with DATA\\TMW5.102): the career team choice of
    SERIE D GIRONE A / B, then, in a career at ALESSANDRIA, the domestic buy's club lists (ACQ. ALTRO GIOCAT. NAZION. >
    SERIE D GIRONE A / B). (Brazil's ordinals 100+ are Mato Grosso state clubs and spares: in no team list.) Group A
    fails on 4.0.2 b3 (ASTI / CHISOLA / CELLE VARAZZE; buy: BIELLESE / GOZZANO / VALENZANA MADO)."""
    exe = os.environ.get('TEAMCOL_BUILD') or next((d for d in (os.environ.get('SWOSTEST_BUILD'), os.environ.get('W8485_BUILD'))
                                                   if d and os.path.exists(os.path.join(d, 'DATA', 'TMW5.102'))), None)
    if not exe:
        return True, 'SKIP: no release dir (TEAMCOL_BUILD, or SWOSTEST_BUILD / W8485_BUILD with DATA\\TMW5.102)'
    errs, info = [], []
    head = ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27']

    def one_colour(scr, label, need=6):
        cc = club_colours(scr)
        n = sum(len(v) for v in cc.values())
        info.append(f'{label}: {n} clubs, colours {sorted(hex(c) for c in cc)}')
        check(n >= need, f'{label}: {n} club buttons ({scr})', errs)
        check(len(cc) == 1, f'{label}: {({hex(c): v for c, v in cc.items()})}', errs)

    def group(s, g, label):
        scr = s.screen()
        if scr.find('SERIE D GIRONE ' + g, exact=True) is None:
            press(s, scr, 'SERIE D')
        if press(s, s.screen(), 'SERIE D GIRONE ' + g, wait=3) is None:
            errs.append(f'{label}: SERIE D GIRONE {g} not reached ({s.screen()})')
            return
        one_colour(s.screen(), f'{label} SERIE D GIRONE {g}')
        list_exit(s)

    def list_exit(s):
        """The club list's ESCI (the model finds no path to it from the club buttons: down until it is selected)."""
        e = s.screen().find('ESCI', exact=True)
        for _ in range(12):
            if s.screen().selected == e:
                s.send('fire dump:3')
                return
            s.send('down dump:0.5')

    with Session('team_choice_colours', exe, {}, 'dump:3', 900) as s:
        s.wait()
        for t in head + ['EUROPA', 'ITALIA']:
            if press(s, s.screen(), t) is None:
                return False, f'career choice: {t} not reached ({s.screen()})'
        for g in 'AB':
            group(s, g, 'team choice')
    with Session('team_choice_colours_buy', exe, {}, 'dump:3', 900) as s:
        s.wait()
        for t in head + ['EUROPA', 'ITALIA', 'SERIE D', 'SERIE D GIRONE A', 'ALESSANDRIA']:
            if press(s, s.screen(), t) is None:
                return False, f'career at ALESSANDRIA: {t} not reached ({s.screen()}); ' + '; '.join(errs + info)
        for _ in range(10):
            scr = s.screen()
            if 'TRASFERIMENTI' in scr.texts():
                break
            press(s, scr, 'CONTINUA') or s.send('fire dump:2')
        walk(s, 'TRASFERIMENTI', 3)
        walk(s, 2, 3)                                   # ACQUISTA GIOCATORE
        scr = s.screen()
        i = next((e[0] for e in scr.entries if e[1].startswith('ACQ. ALTRO') and not e[2]), None)
        if i is None:
            return False, f'buy: no ACQ. ALTRO GIOCAT. NAZION. on {scr}; ' + '; '.join(errs + info)
        press(s, scr, i, wait=3)
        info.append(f'buy list: {s.screen().texts()[:16]}')
        for g in 'AB':
            group(s, g, 'domestic buy')
    return not errs, '; '.join(errs + info)


def xfer_sweep(env_extra, buyer, tag):
    """tools/xfersweep.py on the release dir (a poked third-party offer for SAO PAULO's player, accepted; LIST_ROW: that
    player listed on the transfer market first = a sale): the squad loses him, the bank gains, the order stays a
    permutation, and after a save + reload the names, the bank and the order are the same."""
    exe = foreign_exe()
    if not exe:
        return True, 'SKIP: no release SWOS dir (FOREIGNBUY_BUILD, or SWOSTEST_BUILD / W8485_BUILD with DATA/POOL05.DAT)'
    r = subprocess.run([sys.executable, os.path.join(ROOT, 'tools', 'xfersweep.py'), exe, 'MONDO 2026-27',
                        'SUDAMERICA,BRASILE,BRASILEIRAO SERIE A,SAO PAULO', buyer, 'accept'], capture_output=True, text=True,
                       env=dict(os.environ, SWOSTEST_RUNS=os.path.join(RUNS, 'xfer_' + tag), **env_extra), timeout=1500)
    out = r.stdout
    deal = re.search(r"DEAL accept sold (.+?) players (\d+) -> (\d+) bank (BANCA +L[\d,]+M) -> (BANCA +L[\d,]+M) gone (\w+) .*? order_ok (\w+)", out)
    rel = re.search(r"RELOAD players (\d+) same_names (\w+) bank (BANCA +L[\d,]+M) order_ok (\w+)", out)
    if not deal or not rel:
        return False, f'{tag}: no DEAL / RELOAD line: {(out + r.stderr)[-300:]!r}'
    errs = []
    sold, n0, n1, b0, b1, gone, ok1 = deal.groups()
    check(int(n1) == int(n0) - 1 and gone == 'True' and ok1 == 'True', f'{tag}: deal {deal.group(0)[:200]}', errs)
    n2, same, b2, ok2 = rel.groups()
    check(int(n2) == int(n1) and same == 'True' and b2 == b1 and ok2 == 'True', f'{tag}: reload {rel.group(0)}', errs)
    return not errs, '; '.join(errs) or f'{tag}: sold {sold}, squad {n0} -> {n1}, bank {b0} -> {b1}; reload squad {n2}, same names, bank {b2}'


@scenario
def world_transfer_offer():
    """A third-party offer (poked into the offer table as cseg_5AB36 writes it) for a SAO PAULO player, accepted, on the
    suite's release dir: the squad / bank / order after the deal and after a save + reload (the 4.0 'ACCETTA OFFERTA'
    freeze family)."""
    return xfer_sweep({}, '0x3066', 'offer')


@scenario
def world_transfer_sale():
    """A sale: the 6th squad row listed on the transfer market (AGG. GIOCATORE AL CALCIOMERC.), then a third-party offer for
    him accepted, on the suite's release dir: squad / bank / order, save + reload."""
    return xfer_sweep({'LIST_ROW': '6'}, '0x02A3', 'sale')



