def vc5_check(s, tag, want):
    """world_vc5: on the career menu, VISUAL. COMPETIZ.: the entry named want (slot 4's) shown, the competition rows +
    TOP SCORERS / REGISTRO in order, no two overlapping, all above ESCI; the entry reached through the links and opened
    (its view: want on screen), then ESCI back to the career menu. Returns the errors."""
    errs = []
    for _ in range(4):
        sc = s.screen()
        if sc.find('VISUAL. COMPETIZ.', exact=True) is not None:
            break
        press(s, sc, 'CONTINUA', 3) or s.send('fire dump:2')
    press(s, s.screen(), 'VISUAL. COMPETIZ.', 3)
    sc = s.screen()
    s.shot(f'{tag}_menu')
    vis = [(sc.geom[i][1], i, t) for i, t, inv, dis in sc.entries if not inv and i in (1, 2, 3, 4, 5, 6, 8)]
    vis.sort()
    s.log.append(f'[vc5] {tag}: ' + ' | '.join(f'{i}:{t}@{y}' for y, i, t in vis))
    hit = [i for y, i, t in vis if want in t]
    check(hit == [8], f'{tag}: the 5th entry {want!r}: {[(i, t) for y, i, t in vis]}', errs)
    order = [i for y, i, t in vis]
    want_order = [i for i in (1, 2, 3, 4, 8, 5, 6) if i in order]
    check(order == want_order, f'{tag}: rows in order {order} (want {want_order})', errs)
    ys = [y for y, i, t in vis]
    hs = [sc.geom[i][3] for y, i, t in vis]
    check(all(ys[k] + hs[k] + 5 <= ys[k + 1] for k in range(len(ys) - 1)) and ys[-1] + hs[-1] + 5 <= sc.geom[7][1],
          f'{tag}: rows less than 5 px apart {ys} (ESCI at {sc.geom[7][1]})', errs)   # (4.0.6: a gap, ESCI's too)
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import complist                                     # 4.0.6 (Davide): every entry's text within its button (the
    wide = [(sc.raw_texts[i], complist.px(sc.raw_texts[i])) for y, i, t in vis   # drawn text: the exe's language)
            if complist.px(sc.raw_texts[i]) > complist.VC_PX]
    check(not wide, f'{tag}: entries wider than the button ({complist.VC_PX} px): {wide}', errs)
    if hit == [8]:
        press(s, sc, sc.entries[8][1], 4)
        s.shot(f'{tag}_view')
        texts = s.screen().texts()
        s.log.append(f'[vc5] {tag} view: {texts[:12]}')
        check(any(want in x for x in texts), f'{tag}: the view has no {want!r}: {texts[:10]}', errs)
        for _ in range(4):
            sc = s.screen()
            if sc.find('VISUAL. COMPETIZ.', exact=True) is not None and sc.find('ESCI', exact=True) is not None \
                    and sc.find('PROSS. PARTITA', exact=True) is not None:
                break
            press(s, sc, 'ESCI', 3) or press(s, sc, 'CONTINUA', 3) or s.send('fire dump:2')
        check(s.screen().find('PROSS. PARTITA', exact=True) is not None, f'{tag}: not back on the career menu: '
              f'{s.screen()}', errs)
    return errs


def vc5_saves(exe):
    """world_vc5 / world_winners_sc: an INTER career's saves on exe - when its SUPERCOPPA ITALIANA tie is built and after
    its result is recorded (SC_TRACE 41h; cached in RUNS: vc5_before.CAR, vc5_after.CAR). Returns (before, after,
    message)."""
    mid1, mid2 = os.path.join(RUNS, 'vc5_before.CAR'), os.path.join(RUNS, 'vc5_after.CAR')
    if os.path.exists(mid1) and os.path.exists(mid2):
        return mid1, mid2, 'cached'
    team = 'EUROPA,ITALIA,SERIE A,INTER'
    ok, msg, _ = sc_season(team, dict(W8485_BUILD=exe, W8485_MIDSAVE=f'{sc_trace(exe):x}:1:1'))
    if not ok:
        return None, None, f'season 1 to the supercup tie: {msg}'
    shutil.copy(msg.split(': ', 1)[1], mid1)
    ok, msg, _ = sc_season(team, dict(W8485_BUILD=exe, W8485_MIDSAVE=f'{sc_trace(exe):x}:65:1'), 2)   # (SC_TRACE
                                                    # 41h: decided - sc_done ran, after the result screen)
    if not ok:
        return None, None, f'season 1 to the supercup result: {msg}'
    shutil.copy(msg.split(': ', 1)[1], mid2)
    return mid1, mid2, 'played'


@scenario
def world_winners_sc():
    """4.0.5 (Davide 29/10: "Mettilo nella pagina vincitori"): the national supercup on the career league's VINCITORI page
    all season - an INTER career (world_vc5's saves, VC5_BUILD / SC_BUILD): when its tie is built the page has
    'ITALIA SUPERCOPPA ...:' with DA GIOCARE; after its result the winner (INTER or LAZIO, as the saved result); then slot 4
    reused (forced: D8CAA[4] and the slot's buffer cleared, as a later play-off / Coppa D tie takes it): VISUAL.
    COMPETIZ. has no 5th entry, the VINCITORI line keeps the winner (gplay.c SC_ST +8, the 'SC' item)"""
    src = os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-rel40-winnames-1031')
    if not os.path.isdir(src):
        return True, f'SKIP: private data {src} missing'
    order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
    exe = os.environ.get('VC5_BUILD') or os.environ.get('SC_BUILD') or build('world_sc_cups', env={
        'SEASON_PACKS': ','.join(['ddr-1988-89'] + [os.path.join(src, x) for x in order])})
    mid1, mid2, msg = vc5_saves(exe)
    if not mid2:
        return False, msg
    errs, info = [], []

    def sc_line(lines):
        for k, x in enumerate(lines):
            if 'SUPERCOPPA' in x:
                return x, (lines[k + 1] if k + 1 < len(lines) else '')
        return None, None

    def career(s):
        for _ in range(4):
            sc = s.screen()
            if sc.find('VISUAL. COMPETIZ.', exact=True) is not None:
                return
            press(s, sc, 'CONTINUA', 3) or s.send('fire dump:2')

    def back(s):
        for _ in range(5):
            sc = s.screen()
            if sc.find('PROSS. PARTITA', exact=True) is not None:
                return
            press(s, sc, 'ESCI', 3) or s.send('fire dump:2')

    for tag, car in (('before', mid1), ('after', mid2)):
        with Session('world_winners_sc_' + tag, exe, {'W84A.CAR': car}, 'dump:2', 300) as s:
            s.wait()
            s.send(LOAD1 + ' dump:3')
            career(s)
            e, title, lines = winners_page(s)
            t, w = sc_line(lines)
            s.log.append(f'[wsc] {tag}: {title} {lines}')
            info.append(f'{tag}: {t} {w}')
            if tag == 'before':
                check(t is not None and w == 'DA GIOCARE', f'before: supercup line {t!r} {w!r} ({lines})', errs)
                continue
            check(t is not None and w in ('INTER', 'LAZIO'), f'after: supercup line {t!r} {w!r} ({lines})', errs)
            back(s)
            r = s.result                                # (slot 4 reused: its contest pointer and buffer cleared)
            buf = struct.unpack('<I', bytes(r.obj2(ARR_AT + 16, 4)))[0]
            s.poke(r.base2 + D8CAA_AT + 16, bytes(4))
            s.poke(buf, bytes(8))                       # (its type word and name: short pokes - one long SM line
            career(s)                                   # blocks the debugger's pty)
            press(s, s.screen(), 'VISUAL. COMPETIZ.', 3)
            sc = s.screen()
            check(sc.entries[8][2], f'after the reuse: the 5th entry still shown ({sc.entries[8]})', errs)
            back(s)
            e, title, lines2 = winners_page(s)
            t2, w2 = sc_line(lines2)
            info.append(f'reused: {t2} {w2}')
            check(t2 == t and w2 == w, f'after the reuse: supercup line {t2!r} {w2!r} (was {t!r} {w!r})', errs)
    return not errs, '; '.join(errs) or '; '.join(info)



def cv_trace(exe):
    """obj2 offsets of conti.c's CT_SEG, CT_ED, CT_OUT, the career calendar and its entry (ctview's 'CVTRPTR' block
    in obj3), else None."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    from le import LE
    le = LE(open(os.path.join(exe, 'ITALIAN.EXE'), 'rb').read())
    if len(le.objs) < 3:
        return None
    d3 = le.obj_bytes(3)
    k = d3.find(b'CVTRPTR\0')
    return struct.unpack_from('<IIIII', d3, k + 8) if k >= 0 else None


LIST_BAD = []


def vc_list_check(scr):
    """VISUAL. COMPETIZ.'s list (Davide 03/11): every visible entry's text within its button (complist.VC_PX, the
    game's font), rows and ESCI apart (>= 5 px between buttons, none overlapping). Returns the problems."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import complist
    bad, rows = [], []
    raw = scr.raw_texts
    for (i, text, inv, dis), (x, y, w, h) in zip(scr.entries, scr.geom):
        if i == 0 or inv or not text:
            continue
        t = raw[i] if raw else text
        if complist.px(t) > complist.VC_PX:
            bad.append(f'{t!r} {complist.px(t)} px > {complist.VC_PX}')
        rows.append((y, h, t))
    rows.sort()
    for (y0, h0, t0), (y1, h1, t1) in zip(rows, rows[1:]):
        if y1 - (y0 + h0) < 5:
            bad.append(f'{t0!r} y {y0} .. {t1!r} y {y1}: gap {y1 - (y0 + h0)} px')
    return bad


def contiview_open(s, k, pages=None):
    """Career menu -> VISUAL. COMPETIZ. -> COPPE CONTINENTALI -> button k (1..6): (the menu's button texts, the page's
    title, its lines; with pages: the next pages' lines too); then ESCI twice (back to VISUAL. COMPETIZ.'s list)."""
    if s.screen().find('COPPE CONTINENTALI', exact=True) is None:   # (else already in its list)
        walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)
    i = s.screen().find('COPPE CONTINENTALI', exact=True)
    if i is None:
        return None, None, []
    s.shot('contiview_list')
    LIST_BAD[:] = vc_list_check(s.screen())
    walk(s, i, 3)
    s.shot('contiview_menu')
    btn = [x[1] for x in s.screen().entries[1:7]]
    walk(s, k, 3)
    import ctview                                       # (4.0.6 P3: a confederation with drawn rounds opens its
    summ = ctview.TEXTS[UI][7].decode('latin1')         # rounds menu: the page is its RIEPILOGO)
    rounds_menu = s.screen().find(summ, exact=True) is not None
    if rounds_menu:
        s.shot(f'contiview_{k}_rounds')
        CR_LAST[:] = [x[1] for x in s.screen().entries[1:1 + ctview.CR_N] if not x[2]]
        walk(s, s.screen().find(summ, exact=True), 3)
    else:
        CR_LAST[:] = []
    scr = s.screen()
    s.shot(f'contiview_{k}')
    title, lines = scr.entries[0][1], [x[1] for x in scr.entries[1:15]]
    if pages is not None:
        for n in range(8):
            if s.screen().entries[15][2]:
                break
            walk(s, 15, 3)
            s.shot(f'contiview_{k}_p{n + 2}')
            pages.append([x[1] for x in s.screen().entries[1:15]])
    walk(s, 16, 3)                                      # EXIT -> the rounds menu / the confederations
    if rounds_menu:
        walk(s, ctview.CR_N + 2, 3)                     # (the rounds menu's ESCI)
    walk(s, s.screen().find('ESCI', exact=True), 3)     # -> VISUAL. COMPETIZ.
    return btn, title, lines


CR_LAST = []                                            # (contiview_open: the last rounds menu's visible buttons)


@scenario
def world_contiview():
    """4.0.6 COPPE CONTINENTALI (Gianmarco; ctview.py): VISUAL. COMPETIZ.'s entry 9 in a World 2026-27 career, the
    confederations (an INTER career: CONMEBOL first, no own one), each one's page. Season 1 (a new career): the build's
    main-round draws (COPA LIBERTADORES, TURNI PRECEDENTI..., GRUPPO A: DA GIOCARE). Season 2 (season 1's save, CV_S2 /
    RUNS cv_s2.CAR): CT_SEG / CT_ED / CT_OUT byte-identical before and after every page (the view's replay), each
    confederation's page with its cups' names, no line over the font / page (the game's own text entries)
    (W2627REL_DATA: the world's release data)"""
    src = os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-rel40-winnames-1031')
    if not os.path.isdir(src):
        return True, f'SKIP: private data {src} missing'
    order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
    env = {'SEASON_PACKS': ','.join(['ddr-1988-89'] + [os.path.join(src, x) for x in order])}
    if os.environ.get('CV_ALL'):                        # (CV_ALL=1: VC5_ALL_FORCE - the list's eight rows - and
        env.update(VC5_ALL_FORCE='1', GPLAY_FORCE='1')  # GPLAY_FORCE: the career club champion, its supercup in slot 4)
    exe = os.environ.get('CV_BUILD') or build('world_contiview' + ('_all' if os.environ.get('CV_ALL') else ''), env=env,
                                                 lang=UI)
    tr = cv_trace(exe)
    if not tr:
        return False, 'no CVTRPTR block (ctview not in the build)'
    seg_at, ed_at, out_at, cal_at, calcur_at = tr

    def week(s):                                        # (ctview's: the career calendar entry's +1)
        cur = struct.unpack('<H', bytes(s.result.obj2(calcur_at, 2)))[0]
        return cur, bytes(s.result.obj2(cal_at + cur, 1))[0], bytes(s.result.obj2(cal_at, 48)).hex()
    errs, info = [], []
    names = ['CONMEBOL', 'CONCACAF', 'AFC', 'CAF', 'OFC', 'FIFA']
    import ctview                                       # (the exe's language: its texts)
    T = [x.decode('latin1') for x in ctview.TEXTS[UI]]
    with Session('world_contiview_s1', exe, {}, 'dump:2', 300) as s:
        s.wait()
        if not pick_career(s, ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', 'EUROPA', 'ITALIA',
                               'SERIE A', 'INTER']):
            return False, 'season 1: career not reached'
        s.send('fire dump:3')
        for _ in range(6):
            if s.screen().find('VISUAL. COMPETIZ.', exact=True) is not None:
                break
            press(s, s.screen(), 'CONTINUA', 3) or s.send('fire dump:2')
        btn, title, lines = contiview_open(s, 1)
        s.log.append(f'[cv] s1 week {week(s)} {btn} {title} {lines}')
        check(btn == names, f'season 1 buttons {btn}', errs)
        check(title == T[6] + ' - CONMEBOL', f'season 1 title {title!r}', errs)
        check(lines[:1] == ['COPA LIBERTADORES'] and T[4] in lines and f'{T[3]} A: {T[1]}' in lines,
              f'season 1 page {lines}', errs)
        check(not LIST_BAD, f'season 1 VISUAL. COMPETIZ. list: {LIST_BAD}', errs)
        check(not any('?' in x for x in lines), f'season 1 unread club names {lines[:4]}', errs)
        info.append(f's1: {lines[:4]}')
    s2 = os.environ.get('CV_S2') or os.path.join(RUNS, f'cv_s2_{UI}.CAR')   # (this build's own season 1: a slot's
    if not os.path.exists(s2):                          # title is in the save - CV_TEAM, default ARSENAL: the list's most rows)
        ok, msg, _ = sc_season(os.environ.get('CV_TEAM', 'EUROPA,INGHILTERRA,PREMIER LEAGUE,ARSENAL'), dict(W8485_BUILD=exe))
        car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'W84A.CAR')
        if not ok or not os.path.exists(car):
            return False, f'season 1: {msg[:200]}'
        shutil.copy(car, s2)
    with Session('world_contiview_s2', exe, {'W84A.CAR': s2}, 'dump:2', 300) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        for _ in range(6):
            if s.screen().find('VISUAL. COMPETIZ.', exact=True) is not None:
                break
            press(s, s.screen(), 'CONTINUA', 3) or s.send('fire dump:2')
        st = lambda: (bytes(s.result.obj2(seg_at, 72)), bytes(s.result.obj2(ed_at, 2260)))
        b0 = st()
        check(b0[1][:2] == b'CE', f'season 2: no edition in progress (CT_ED {b0[1][:8].hex()})', errs)
        for k in range(1, 7):
            pages = []
            btn, title, lines = contiview_open(s, k, pages)
            s.log.append(f'[cv] s2 {k} week {week(s)} {title} {lines} {pages}')
            check(title == T[6] + ' - ' + names[k - 1], f'season 2 page {k} title {title!r}', errs)
            if k == 1:
                check(not LIST_BAD, f'season 2 VISUAL. COMPETIZ. list: {LIST_BAD}', errs)
            check(bool(lines) and lines[0], f'season 2 page {k}: {lines}', errs)
            import complist                             # (every character one the menu font draws)
            odd = font_odd_all(lines + [x for p in pages for x in p] + [title])
            check(not odd, f'season 2 page {k}: characters outside the menu font {odd}', errs)
            wide = [x for x in lines + [x for p in pages for x in p] if complist.px(x.upper()) > 298]   # (ctview PXMAX)
            check(not wide, f'season 2 page {k}: lines over 298 px {wide}', errs)
            unk = [x for x in lines + [x for p in pages for x in p] if '?' in x]   # (ctview name(): a team file not
            check(not unk, f'season 2 page {k}: unread club names {unk[:4]}', errs)   # opened - TEAM vs TMW5.nnn)
            b1 = st()
            dif = [(n, i, b0[j][i], b1[j][i]) for j, n in enumerate(('SEG', 'ED')) for i in range(len(b0[j]))
                   if b0[j][i] != b1[j][i]]
            fresh = not any(b0[0])                      # (CT_SEG still empty from the load: ct_pre - the season
            check(not dif or fresh and not any(n == 'ED' for n, *_ in dif),   # start's chain - computes it from the
                  f'season 2 page {k}: CT_SEG / CT_ED changed by the view: {dif[:12]} ({len(dif)})', errs)   # edition
            if dif:                                     # as the view's replay does)
                info.append(f'page {k}: CT_SEG computed from the load\'s empty one ({dif[:3]})')
            b0 = b1
            info.append(f'{names[k - 1]}: {lines[:3]} +{len(pages)} pages')
    return not errs, '; '.join(errs) or '; '.join(info)


def car_item(car, name, size):
    """An engine item's bytes in a .CAR (trailer's 'EN' block: word id = crc32(name) & FFFFh, word length, bytes)."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import engine
    d = open(car, 'rb').read()
    k = d.find(struct.pack('<HH', engine.item_id(name), size))
    return d[k + 4:k + 4 + size] if k >= 0 else None


@scenario
def world_s1conti():
    """4.0.6 B2 (Davide: option C season 1 = B2): season 1's continental editions are played. A new World 2026-27
    career (INTER) starts with the season-1 edition (CT_ED 'CE', the season-1 bit, the career club's word); after
    season 1 (world_contiview's season-2 save, ARSENAL: in no conti cup) every holder (CT_ST) is the winner conti.c
    gives natively on the same packs (conti.py --test-s1: the same edition, deterministic), the season-1 bit cleared.
    (W2627REL_DATA: the world's release data; CV_BUILD / CV_S2 as world_contiview)"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import conti
    src = os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-rel40-winnames-1031')
    if not os.path.isdir(src) and not os.environ.get('CV_BUILD'):
        return True, f'SKIP: private data {src} missing'
    order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
    packs = ','.join(['ddr-1988-89'] + [os.path.join(src, x) for x in order])
    exe = os.environ.get('CV_BUILD') or build('world_contiview', env={'SEASON_PACKS': packs}, lang=UI)
    tr = cv_trace(exe)
    if not tr:
        return False, 'no CVTRPTR block (ctview not in the build)'
    ed_at = tr[1]
    r = subprocess.run([sys.executable, os.path.join(ROOT, 'tools', 'conti.py'), '--test-s1'], capture_output=True,
                       text=True, env=dict(os.environ, SEASON_PACKS=packs))
    want = re.findall(r'^  (\S+) winner (0x[0-9a-f]+) holder (0x[0-9a-f]+)', r.stdout, re.M)
    if r.returncode or 'PASS' not in r.stdout or not want:
        return False, f'native --test-s1: {(r.stdout + r.stderr)[-400:]}'
    errs, info = [], []
    with Session('world_s1conti_s1', exe, {}, 'dump:2', 300) as s:
        s.wait()
        if not pick_career(s, ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', 'EUROPA', 'ITALIA',
                               'SERIE A', 'INTER']):
            return False, 'season 1: career not reached'
        s.send('fire dump:3')
        for _ in range(6):
            if s.screen().find('VISUAL. COMPETIZ.', exact=True) is not None:
                break
            press(s, s.screen(), 'CONTINUA', 3) or s.send('fire dump:2')
        ed = bytes(s.result.obj2(ed_at, 12))
        check(ed[:2] == b'CE' and ed[11] & 1, f'season 1: no season-1 edition (CT_ED {ed.hex()})', errs)
        info.append(f's1 CT_ED {ed.hex()} (entries {struct.unpack_from("<H", ed, 2)[0]}, club {struct.unpack_from("<H", ed, 8)[0]:#x})')
    s2 = os.environ.get('CV_S2') or os.path.join(RUNS, f'cv_s2_{UI}.CAR')
    if not os.path.exists(s2):
        ok, msg, _ = sc_season(os.environ.get('CV_TEAM', 'EUROPA,INGHILTERRA,PREMIER LEAGUE,ARSENAL'), dict(W8485_BUILD=exe))
        car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'W84A.CAR')
        if not ok or not os.path.exists(car):
            return False, f'season 1: {msg[:200]}'
        shutil.copy(car, s2)
    st, ce = car_item(s2, 'CT', conti.ST_SIZE), car_item(s2, 'CE', conti.ED_SIZE)
    if st is None or ce is None:
        return False, f'season-2 save {s2}: no CT / CE item'
    got = [struct.unpack_from('<H', st, 4 + 12 * i)[0] for i in range(len(want))]
    bad = [(cu, w, h, hex(g)) for (cu, w, h), g in zip(want, got) if int(h, 16) != g]
    check(not bad, f'season 2: holders not season 1\'s winners (cup, native winner, native holder, game) {bad}', errs)
    check(not ce[11] & 1, f'season 2: the season-1 bit still set (CT_ED {ce[:12].hex()})', errs)
    info.append(f'holders = season 1\'s winners: {[(cu, h) for cu, _, h in want]}')
    return not errs, '; '.join(errs) or '; '.join(info)


@scenario
def world_s1conti_oldsave():
    """4.0.6 B2 M3 (Davide: old saves built at load): Davide's rc7 season-1 career PHILA.CAR (no 'CE', no 'CT') on a
    release-like build (world_winners_oldsave's recipe) gets season 1's edition at the load (conti.c ct_load1): CT_ED
    'CE', the season-1 bit, the entries of the build's block, the career club's word (its season end: world_winners_oldsave)"""
    car = os.environ.get('WINNERS_OLDSAVE') or os.path.join(MAIN, 'internal', 'davide-mister-20261021', 'PHILA.CAR')
    if not os.path.exists(car):
        return True, f'SKIP: no {car}'
    check_ce = car_item(car, 'CE', 2260)
    if check_ce is not None and check_ce[:2] == b'CE':
        return False, f'{car} already has an edition: not an old save'
    exe = os.environ.get('WINNERS_W27')
    if not exe:
        src = os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-rel40-winnames-1031')
        if not os.path.isdir(src):
            return True, f'SKIP: private data {src} missing'
        order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
        w4 = os.path.join(ROOT, 'packs', 'europe-1984-85')     # (world_winners_oldsave's build: the save's numbering)
        packs = ['ddr-1988-89', 'italia-1947-48', 'world-cup-1934'] + \
            [os.path.join(w4, c) for c in sorted(os.listdir(w4)) if not c.startswith('.')] + \
            [os.path.join(src, x) for x in order]
        exe = build('winners_w27', env={'SEASON_PACKS': ','.join(packs)})
    tr = cv_trace(exe)
    if not tr:
        return False, 'no CVTRPTR block (ctview not in the build)'
    errs, eds = [], []
    with Session('world_s1conti_oldsave', exe, {'PHILA.CAR': car}, 'dump:2', 300) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        eds.append(bytes(s.result.obj2(tr[1], 2260)))
    ed = eds[0]
    ne, mgr = struct.unpack_from('<H', ed, 2)[0], struct.unpack_from('<H', ed, 8)[0]
    check(ed[:2] == b'CE' and ed[11] & 1 and ne > 100, f'old save: no season-1 edition at the load (CT_ED {ed[:12].hex()})', errs)
    return not errs, '; '.join(errs) or f'CT_ED {ed[:12].hex()}: {ne} entries, club {mgr:#x}'


@scenario
def world_cgame_view():
    """4.0.6 option C P3: COPPE CONTINENTALI's rounds menu -> the round in the game's own competition screen (ctgame
    cg_view: knockout legs + aggregate + pens / away goals, group tables + fixtures, as at the career's week). On
    world_contiview's build and season-2 save (CV_BUILD, CV_S2 / RUNS cv_s2_<ui>.CAR): every confederation's rounds menu
    (labels within 144 px, menu font), each visible round opened (shot cgv_<k>_<j>, its texts in the menu font and within
    their boxes), ESCI back to the rounds menu; CT_SEG / CT_ED byte-identical before and after (the view closed).
    4.0.6 continent screens (Davide GO 03/11): VISUALIZZA MONDO - MONDO's FIFA cup above the continents, every continent
    (gwalk) its green cup buttons above its nations (EUROPA: the UEFA cups, the game's own views), names in the font and within their buttons;
    each cup button -> its rounds menu (title = the cup, the rounds' own labels), every round opened and back,
    RIEPILOGO = that cup's part only, ESCI -> the career menu, CT state unchanged. CV_OWN=<club>: a save with the club
    in a conti round in progress - its round on screen through the game's slot 3 (CG_G's opens unchanged)"""
    src = os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-rel40-winnames-1031')
    if not os.path.isdir(src) and not os.environ.get('CV_BUILD'):
        return True, f'SKIP: private data {src} missing'
    exe = os.environ.get('CV_BUILD')
    if not exe:
        order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
        exe = build('world_contiview', env={'SEASON_PACKS': ','.join(['ddr-1988-89'] + [os.path.join(src, x)
                                                                                          for x in order])}, lang=UI)
    s2 = os.environ.get('CV_S2') or os.path.join(RUNS, f'cv_s2_{UI}.CAR')
    if not os.path.exists(s2):
        return False, f'no season-2 save {s2} (run world_contiview first)'
    tr = cv_trace(exe)
    if not tr:
        return False, 'no CVTRPTR block (ctview not in the build)'
    seg_at, ed_at = tr[0], tr[1]
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import complist
    import ctview
    summ = ctview.TEXTS[UI][7].decode('latin1')
    errs, info = [], []
    pp = os.environ.get('CGV_SWOSPP')                   # (world_cgame_swospp: SWOS++'s loader files, timer keys)
    extra = {'LOADER.BIN': os.path.join(pp, 'loader.bin'), 'SWOSPP.BIN': os.path.join(pp, 'swospp.bin')} if pp else {}
    with Session('world_cgame_view', exe, {'W84A.CAR': s2, **extra}, 'dump:4' if pp else 'dump:2', 600,
                 timer=bool(pp)) as s:
        s.wait()
        if pp:
            on, why = swospp_on(s.result, os.path.join(exe, 'ITALIAN.EXE'))
            check(on, f'SWOS++ not running: {why}', errs)
            info.append('SWOS++ on')
        plain = {}
        if pp:                                          # (SWOS++'s main menu has its own entry: LOAD1's keys miss;
            walk(s, 'CARICA VECCHIA COMPETIZIONE', 3)   #  the save's list opens on ABBANDONA, the load ends on the
            walk(s, 'W84A', 3)                          #  day's table - its ESCI: the chairman's note, the menu;
            s.send('dump:3')                            #  4.0.5 + SWOS++ the same)
        else:
            s.send(LOAD1 + ' dump:3')
        for _ in range(6):
            if s.screen().find('VISUAL. COMPETIZ.', exact=True) is not None:
                break
            if pp and s.screen().find('- PARTITA -', exact=True) is not None:
                walk(s, 'ESCI', 3)
                continue
            press(s, s.screen(), 'CONTINUA', 3) or s.send('fire dump:2')
        st = lambda: (bytes(s.result.obj2(seg_at, 72)), bytes(s.result.obj2(ed_at, 2260)))
        gtr = cg_trace(exe)                             # (ctgame's CG_G[3]: the views opened - none for the career
        opens = lambda: struct.unpack('<I', bytes(s.result.read(s.result.lin((3, gtr[3] + 12)), 4)))[0]   # club's own
        own, own_seen = os.environ.get('CV_OWN'), []    #  round in progress: the game's slot 3, CV_OWN = its name)

        def tr_ok(tag):                                 # (the career menu: TRASFERIMENTI enabled, up from OFFERTE
            sc = s.screen()                             #  LAVORO lands on it - 4.0.6 careerworld w_vcup: a cup's own
            i = sc.find('TRASFERIMENTI', exact=True)    # view from VIEW WORLD left dseg_DF4F4 set, transfers closed
            if i is None or own:                        # till the next match - as on 4.0.5; contestMenu's entry 5,
                return                                  # job offers, below it: its text changes - NO JOB OFFERS ...)
            check(not sc.entries[i][3], f'{tag}: TRASFERIMENTI disabled', errs)
            j = i + 1                                   # (job offers - NESS. OFF. LAVORO disabled: the game skips
            if sc.entries[j][3] or sc.entries[j][2]:    #  it, up from the next one lands on TRASFERIMENTI)
                j += 1
            for _ in range(8):                          # (a key at a time: a move onto a disabled entry skips it)
                c_ = s.screen()
                if c_.selected == j or not c_.path(j):
                    break
                s.send(c_.path(j)[0] + ' dump:0.5')
            check(s.screen().selected == j, f'{tag}: not on entry {j} ({s.screen().selected})', errs)
            s.send('up dump:0.5')
            got = s.screen().selected
            check(got == i, f'{tag}: up from entry {j} -> entry {got}, not TRASFERIMENTI', errs)
            info.append(f'{tag}: menu ok')
        tr_ok('after load')
        if not own and not pp and not os.environ.get('CGV_NOMARKET'):   # (the foreign market's club picker, careerworld w_buy: the
            walk(s, 'TRASFERIMENTI', 3)                 #  plain lists too - first: after a game's own cup view the
                                                        #  menu's links go through its fixtures; CV_OWN's save:
                                                        #  its week has no market)
            walk(s, 2, 3)
            walk(s, 5, 3)                               # ACQ. ALTRO GIOCAT. STRANIERO
            plain['foreign market MONDO'] = s.screen().texts()
            for cont in ('EUROPA', 'SUDAMERICA', 'NORDAMERICA', 'ASIA', 'AFRICA', 'OCEANIA'):
                gwalk(s, cont, 3)
                plain[f'foreign market {cont}'] = s.screen().texts()
                s.shot(f'cgw_buy_{cont.lower()}')
                for _ in range(3):                      # (SWOS++'s timer keys: a fire can be missed - ESCI again)
                    gwalk(s, 'ESCI', 3)
                    if s.screen().find('OCEANIA', exact=True) is not None:
                        break
            for _ in range(6):                          # (ABBANDONA, then the market menus' ESCI)
                if s.screen().find('VISUALIZZA MONDO', exact=True) is not None:
                    break
                sc = s.screen()
                gwalk(s, 'ABBANDONA' if sc.find('ABBANDONA', exact=True) is not None else 'ESCI', 3)

        def rounds(tag, conf):                          # (a rounds menu on screen: every round opened and back)
            sc = s.screen()
            s.shot(f'{tag}_rounds')
            btns = [(i, sc.raw_texts[i] if sc.raw_texts else t) for i, t, inv, dis in sc.entries[1:1 + ctview.CR_N + 1]
                    if not inv and t]
            odd = font_odd_all(t for i, t in btns)
            check(not odd, f'{conf}: rounds menu characters outside the font {odd}', errs)
            wide = [(t, complist.px(t.upper())) for i, t in btns if complist.px(t.upper()) > 144]
            check(not wide, f'{conf}: rounds menu labels over 144 px {wide}', errs)
            opened = []
            s.log.append(f'[cgv] {conf} rounds menu: {btns} nav {sc.nav[1:4]} {sc.nav[ctview.CR_N + 1:ctview.CR_N + 3]}')
            for j, (i, label) in enumerate(btns):
                if i > ctview.CR_N:
                    continue
                if pp:                                  # (SWOS++'s timer keys: a late key may have reopened a view)
                    s.send('dump:3')
                    for _ in range(4):
                        if s.screen().find(summ, exact=True) is not None:
                            break
                        press(s, s.screen(), 'ESCI', 4)
                b0, o0 = st(), opens()
                walk(s, i, 4)
                if pp and s.screen().find(summ, exact=True) is not None:
                    s.send('dump:4')                    # (SWOS++'s timer keys: the fire taken late)
                v = s.screen()
                s.shot(f'{tag}_{j}')
                texts = v.texts()
                if own and opens() == o0 and texts and v.find(summ, exact=True) is None:
                    own_seen.append(f'{conf} {label}')  # (no ctgame view opened, a screen shown: the game's slot 3 -
                    check(v.find('PASSA') is not None,  #  the club's group stage, its names drawn in the table rows)
                          f'{conf} {label}: shown without a view, not a group stage ({texts[:6]})', errs)
                s.log.append(f'[cgv] {conf} {label}: {texts[:24]}')
                check(v.find(summ, exact=True) is None and texts, f'{conf} {label}: no view ({texts[:6]})', errs)
                raw = v.raw_texts or texts
                bad = font_odd_all(t for t, e in zip(raw, v.entries) if not e[2])
                check(not bad, f'{conf} {label}: characters outside the font {bad}', errs)
                over = [(t, complist.px(t.upper()), g[2]) for t, g, e in zip(raw, v.geom, v.entries) if t and g[2] > 0
                        and not e[2] and complist.px(t.upper()) > g[2]]   # (visible entries: the game's own hidden
                                                                          #  texts - FR's tooltips - aside)
                check(not over, f'{conf} {label}: texts wider than their boxes {over[:4]}', errs)
                win = {'it': r'VINCE', 'en': r'WIN', 'fr': r'VICT(?:OIRE DE)?', 'de': r'GEWINNT'}[UI]
                for t in raw:                           # (the game's tie line: the winner's score first - the
                    for a, b in re.findall(win + r'\D*?(\d+)-(\d+)', t.upper()):   # aggregate, the shoot-out)
                        check(int(a) > int(b), f'{conf} {label}: winner first but {a}-{b} in {t.strip()!r}', errs)
                if v.find('PASSA') is not None:         # (a group stage: the game's next-stage button - its view, back)
                    press(s, v, v.entries[v.find('PASSA')][1], 4)
                    s.shot(f'{tag}_{j}_passa')
                    s.log.append(f'[cgv] {conf} {label} PASSA: {s.screen().texts()[:16]}')
                for _ in range(6):
                    if s.screen().find(summ, exact=True) is not None:
                        break
                    press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')
                check(s.screen().find(summ, exact=True) is not None, f'{conf} {label}: not back on the rounds menu',
                      errs)
                s.log.append(f'[cgv] back: {s.screen()} nav {s.screen().nav[1:4]}')
                s.shot(f'{tag}_{j}_back')
                b1 = st()
                check(b0 == b1, f'{conf} {label}: CT_SEG / CT_ED changed by the view', errs)
                opened.append(label)
            return opened

        walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)
        vc = next((e[0] for e in s.screen().entries if e[1] and 'UEFA' in e[1] and not e[2]), None)
        if vc is not None:                              # (a stock VISUAL. COMPETIZ. cup view: the menu stays as it was)
            walk(s, vc, 4)
            for _ in range(5):
                if s.screen().find('VISUALIZZA MONDO', exact=True) is not None:
                    break
                press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')
            tr_ok('after VISUAL. COMPETIZ.')
            walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)
        walk(s, s.screen().find('COPPE CONTINENTALI', exact=True), 3)
        for k in range(1, 7):
            conf = s.screen().entries[k][1]
            walk(s, k, 3)
            if s.screen().find(summ, exact=True) is None:
                info.append(f'{conf}: no rounds')
                walk(s, 16, 3)
                continue
            opened = rounds(f'cgv_{k}', conf)
            info.append(f'{conf}: {len(opened)} rounds {opened[:3]}')
            walk(s, ctview.CR_N + 1, 3)                 # (RIEPILOGO and back: the links again)
            walk(s, 16, 3)
            check(s.screen().find(summ, exact=True) is not None and s.screen().path(ctview.CR_N + 2),
                  f'{conf}: rounds menu after RIEPILOGO: {s.screen()}', errs)
            walk(s, ctview.CR_N + 2, 3)                 # (the rounds menu's ESCI -> the confederations)

        def career_menu():
            for _ in range(5):
                if s.screen().find('VISUALIZZA MONDO', exact=True) is not None:
                    return True
                sc = s.screen()                         # (the picker's ESCI: by geometry, walk finds no path)
                b = [t for t in ('ESCI', 'ABBANDONA') if sc.find(t, exact=True) is not None]
                if b:                                   # (a continent's ESCI -> MONDO, MONDO's ABBANDONA -> the menu)
                    gwalk(s, b[0], 3)
                else:
                    s.send('fire dump:2')
            return s.screen().find('VISUALIZZA MONDO', exact=True) is not None

        def picker(tag, want_cups):                     # (VIEW WORLD's picker on screen: its green cup buttons -
            sc = s.screen()                             #  the competitions, entries 1..20 - and the rest)
            s.shot(tag)
            raw = sc.raw_texts or [t for _, t, _, _ in sc.entries]
            cups = [(i, raw[i]) for i, t, inv, _ in sc.entries if 1 <= i <= 20 and t and not inv]
            rest = [raw[i] for i, t, inv, _ in sc.entries if 21 <= i <= 86 and t and not inv]
            check(bool(rest), f'{tag}: no nations / continents ({sc.texts()[:8]})', errs)
            if want_cups:
                check(len(cups) >= want_cups, f'{tag}: {len(cups)} cup buttons, want >= {want_cups}', errs)
                y_n = min(sc.geom[i][1] for i, t, inv, _ in sc.entries if 21 <= i <= 86 and t and not inv)
                check(all(sc.geom[i][1] < y_n for i, _ in cups), f'{tag}: cup buttons not above the list', errs)
            odd = font_odd_all(t for _, t in cups)
            check(not odd, f'{tag}: cup buttons characters outside the font {odd}', errs)
            wide = [(t, complist.px(t.upper()), sc.geom[i][2]) for i, t in cups if complist.px(t.upper()) > sc.geom[i][2] - 2]
            check(not wide, f'{tag}: cup names wider than their buttons {wide}', errs)
            s.log.append(f'[cgw] {tag}: cups {cups} list {rest[:12]}')
            return [t for _, t in cups], rest
        check(career_menu(), f'VIEW WORLD: not back on the career menu ({s.screen()})', errs)
        walk(s, 'VISUALIZZA MONDO', 3)
        mcups, mrest = picker('cgw_mondo', 1)
        fifa = mcups                                    # (FIFA's only: the UEFA cups on EUROPA, Davide 03/11)
        conts = [t for t in s.screen().texts() if t in ('EUROPA', 'SUDAMERICA', 'NORDAMERICA', 'ASIA', 'AFRICA', 'OCEANIA')]
        check(len(conts) == 6 and len(fifa) >= 1, f'MONDO: continents {conts}, FIFA cups {fifa}', errs)
        todo = [(None, c) for c in fifa]
        for cont in conts:
            gwalk(s, cont, 3)
            cups, rest = picker(f'cgw_{cont.lower()}', 3 if cont == 'EUROPA' else 1)
            todo += [(cont, c) for c in cups]
            info.append(f'{cont}: {cups} + {len(rest)} nations')
            check(career_menu(), f'{cont}: not back on the career menu ({s.screen()})', errs)
            walk(s, 'VISUALIZZA MONDO', 3)
        career_menu()
        for q, (cont, cup) in enumerate(todo):
            walk(s, 'VISUALIZZA MONDO', 3)
            if cont:
                gwalk(s, cont, 3)
            b0 = st()
            gwalk(s, cup, 4)
            sc = s.screen()
            title = (sc.raw_texts or [sc.entries[0][1]])[0]
            if sc.find(summ, exact=True) is None:      # (no round drawn: the cup's page part; a UEFA cup:
                check(any(cup in t for t in [title] + (sc.raw_texts or []) + sc.texts()) or   # the game's own
                      (cont == 'EUROPA' and not title and 'STAT' in sc.texts()),               #  view: its title
                      f'{cup}: page title {title!r}', errs)     # (DE's long ones - 'UEFA EUROPA LEAGUE VIERTELFINALE
                                                                #  RUCKSP.' - read empty: shot cgw_<q>_view)
                s.shot(f'cgw_{q}_view')
                s.log.append(f'[cgw] {cup} view: {sc.texts()[:8]}')
                info.append(f'{cup}: {"view" if cont == "EUROPA" else "page"}')
            else:
                check(title == cup, f'{cup}: rounds menu title {title!r}', errs)
                opened = rounds(f'cgw_{q}', cup)
                walk(s, ctview.CR_N + 1, 3)             # (RIEPILOGO: the cup's part only)
                pg = s.screen()
                s.shot(f'cgw_{q}_sum')
                s.log.append(f'[cgw] {cup} RIEPILOGO: {pg.texts()[:16]}')
                check(cup in (pg.raw_texts or pg.texts())[0], f'{cup}: RIEPILOGO title {pg.texts()[:2]}', errs)
                walk(s, 16, 3)
                check(s.screen().find(summ, exact=True) is not None, f'{cup}: rounds menu after RIEPILOGO', errs)
                info.append(f'{cup}: {len(opened)} rounds')
            check(st() == b0, f'{cup}: CT_SEG / CT_ED changed', errs)
            check(career_menu(), f'{cup}: not back on the career menu ({s.screen()})', errs)
            if cont == 'EUROPA':
                tr_ok(f'after {cup}')
        if own:
            check(own_seen, f'{own}: its own round never on screen', errs)
            info.insert(0, f'{own} from slot 3: {own_seen}')
    with Session('world_cgame_view_pick', exe, {'W84A.CAR': s2}, 'dump:2', 300) as s:
        s.wait()                                        # (the new career's club picker: the plain lists, no cup
        for t in ('CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27'):   # buttons - ctview cw_on /
            press(s, s.screen(), t, 3)                  #  cw_off swap them in for VIEW WORLD only)
        plain['new career MONDO'] = s.screen().texts()
        for cont in ('EUROPA', 'SUDAMERICA', 'NORDAMERICA', 'ASIA', 'AFRICA', 'OCEANIA'):
            gwalk(s, cont, 3)
            plain[f'new career {cont}'] = s.screen().texts()
            s.shot(f'cgw_new_{cont.lower()}')
            gwalk(s, 'ESCI', 3)
        allcups = {c for _, c in todo} | set(mcups)
        for k, tx in plain.items():
            s.log.append(f'[cgw] {k}: {tx}')
            check(len(tx) >= 2 and not allcups & set(tx), f'{k}: cup buttons {sorted(allcups & set(tx))} ({tx[:6]})', errs)
        info.append(f'pickers plain: {len(plain)} screens')
    return not errs, '; '.join(errs[:12]) or '; '.join(info)


@scenario
def world_cgame_fallback():
    """4.0.6 option C P4: a round the game's own screen can't show -> version A's page (the confederation's or the cup's
    text page, as its RIEPILOGO), the career as it was. On world_cgame_view's build and season-2 save (CV_BUILD, CV_S2):
    the first confederation with a rounds menu, its RIEPILOGO page kept; ctgame's guard poked sticky (CG_G[6], what a
    bad sum leaves: E_GUARD) -> every round button shows that same page, no view opened (CG_G[3]), back on the rounds
    menu with its links, CT_SEG / CT_ED unchanged; the guard poked back -> the first round is the game's screen again.
    (The other reasons - E_GUEST a club in no team file, E_NOREC no goals kept, E_CACHE, E_KIND - are Tier B
    test_cg_fallback's: cg_view 0 is the one path to the page.) Then season 1 of a new career (CGF_TEAM, default
    EUROPA,ITALIA,SERIE A,ROMA: no edition yet - no 'CE'): every confederation's COPPE CONTINENTALI button the page at
    once (no rounds menu), VIEW WORLD's SUDAMERICA cups the page, no view opened."""
    exe = os.environ.get('CV_BUILD')
    if not exe:
        return True, 'SKIP: CV_BUILD not set (world_cgame_view\'s build)'
    s2 = os.environ.get('CV_S2') or os.path.join(RUNS, f'cv_s2_{UI}.CAR')
    if not os.path.exists(s2):
        return False, f'no season-2 save {s2}'
    tr, gtr = cv_trace(exe), cg_trace(exe)
    if not tr or not gtr:
        return False, 'no CVTRPTR / CGTRPTR block'
    seg_at, ed_at = tr[0], tr[1]
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import ctview
    summ = ctview.TEXTS[UI][7].decode('latin1')
    errs, info = [], []

    def G(s):
        r = s.result
        return struct.unpack('<12I', bytes(r.read(r.lin((3, gtr[3])), 48)))

    def sticky(s, v):
        s.poke(s.result.lin((3, gtr[3] + 24)), struct.pack('<I', v))

    def back_to(s, text, n=6):
        for _ in range(n):
            if s.screen().find(text, exact=True) is not None:
                return True
            press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')
        return s.screen().find(text, exact=True) is not None

    with Session('world_cgame_fallback', exe, {'W84A.CAR': s2}, 'dump:2', 400) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        for _ in range(6):
            if s.screen().find('VISUAL. COMPETIZ.', exact=True) is not None:
                break
            press(s, s.screen(), 'CONTINUA', 3) or s.send('fire dump:2')
        st = lambda: (bytes(s.result.obj2(seg_at, 72)), bytes(s.result.obj2(ed_at, 2260)))
        walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)
        walk(s, s.screen().find('COPPE CONTINENTALI', exact=True), 3)
        conf = None
        for k in range(1, 7):
            c = s.screen().entries[k][1]
            walk(s, k, 3)
            if s.screen().find(summ, exact=True) is not None:
                conf = c
                break
            walk(s, 16, 3)
        if conf is None:
            return False, 'no confederation with a rounds menu on the season-2 save'
        sc = s.screen()
        btns = [(i, t) for i, t, inv, _ in sc.entries[1:1 + ctview.CR_N] if t and not inv]
        walk(s, ctview.CR_N + 1, 3)                     # (RIEPILOGO: the page a fallback shows)
        ref = s.screen().texts()
        s.shot('cgf_summary')
        walk(s, 16, 3)
        check(s.screen().find(summ, exact=True) is not None, f'{conf}: rounds menu after RIEPILOGO', errs)
        g0, b0 = G(s), st()
        sticky(s, 1)
        for j, (i, label) in enumerate(btns[:4]):
            walk(s, i, 4)
            v = s.screen()
            s.shot(f'cgf_{j}')
            s.log.append(f'[cgf] {conf} {label} (sticky): {v.texts()[:12]}')
            check(v.texts() == ref, f'{conf} {label}: not the summary page ({v.texts()[:6]} vs {ref[:6]})', errs)
            walk(s, 16, 3)
            sc = s.screen()
            check(sc.find(summ, exact=True) is not None and sc.path(ctview.CR_N + 2) is not None,
                  f'{conf} {label}: not back on the rounds menu with its links ({sc})', errs)
        g1 = G(s)
        check(g1[3] == g0[3] and g1[7] == 7 and not g1[5] and g1[0] != 0x4E45504F,
              f'sticky: opens {g0[3]} -> {g1[3]}, last error {g1[7]}, bad {g1[5]}, open {g1[0]:#x}', errs)
        check(st() == b0, f'{conf}: CT_SEG / CT_ED changed', errs)
        sticky(s, 0)
        walk(s, btns[0][0], 4)
        v = s.screen()
        s.shot('cgf_view_again')
        check(v.find(summ, exact=True) is None and v.texts() != ref and G(s)[3] == g0[3] + 1,
              f'{conf} {btns[0][1]}: no view with the guard back ({v.texts()[:6]}, opens {G(s)[3]})', errs)
        check(back_to(s, summ), f'{conf}: not back on the rounds menu after the view', errs)
        check(st() == b0, f'{conf}: CT_SEG / CT_ED changed by the view', errs)
        info.append(f'{conf}: {min(4, len(btns))} rounds -> the page (sticky), then a view')
    team = (os.environ.get('CGF_TEAM') or 'EUROPA,ITALIA,SERIE A,ROMA').split(',')
    with Session('world_cgame_fallback_s1', exe, {}, 'dump:2', 400) as s:
        s.wait()
        for t in ('CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27'):
            if press(s, s.screen(), t, 3) is None:
                return False, f'new career: {t} not reached ({s.result})'
        if not pick_career(s, team):
            return False, f'new career: {team} not reached ({s.result})'
        s.send('fire dump:2')                           # (the chairman's note)
        g0 = G(s)
        walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)
        walk(s, s.screen().find('COPPE CONTINENTALI', exact=True), 3)
        pages = 0
        for k in range(1, 7):
            c = s.screen().entries[k][1]
            walk(s, k, 3)
            v = s.screen()
            s.shot(f'cgf_s1_{k}')
            s.log.append(f'[cgf] season 1 {c}: {v.texts()[:10]}')
            check(v.find(summ, exact=True) is None and v.texts(), f'season 1 {c}: a rounds menu ({v.texts()[:6]})', errs)
            q = [t for t in v.texts() if '?' in t]      # (an unknown name: the list read past the round's places)
            check(not q, f'season 1 {c}: unknown names {q[:3]}', errs)
            pages += 1
            walk(s, 16, 3)
        check(back_to(s, 'VISUALIZZA MONDO'), f'season 1: not back on the career menu ({s.screen()})', errs)
        walk(s, 'VISUALIZZA MONDO', 3)
        gwalk(s, 'SUDAMERICA', 3)
        sc = s.screen()
        raw = sc.raw_texts or [t for _, t, _, _ in sc.entries]
        cups = [raw[i] for i, t, inv, _ in sc.entries if 1 <= i <= 20 and t and not inv]
        check(bool(cups), f'season 1 SUDAMERICA: no cup buttons ({sc.texts()[:8]})', errs)
        if cups:
            gwalk(s, cups[0], 4)
            v = s.screen()
            s.shot('cgf_s1_world')
            title = (v.raw_texts or [v.entries[0][1]])[0]
            check(v.find(summ, exact=True) is None and cups[0] in title,
                  f'season 1 {cups[0]}: not its page ({v.texts()[:6]})', errs)
        g1 = G(s)
        check(g1[3] == g0[3] and not g1[5], f'season 1: views opened {g0[3]} -> {g1[3]}, bad {g1[5]}', errs)
        info.append(f'season 1: {pages} confederation pages + {cups[:1]} from VIEW WORLD, no view')
    return not errs, '; '.join(errs[:10]) or '; '.join(info)


@scenario
def world_cgame_swospp():
    """4.0.6 option C P4, SWOS++ (English only): world_cgame_view on the English release exe (CV_BUILD, SWOSTEST_UI=en)
    with SWOS++ 1.9.2.2 installed (tools/swospp.py; LOADER.BIN / SWOSPP.BIN, keys fed from the timer as
    controls_swospp): SWOS++ running, every round in the game's screen and back, the pickers, CT state unchanged - its
    ShowMenu / MenuProc / DrawMenuText hooks run over the rounds menu and the views (no clash: else version A's page)"""
    if UI != 'en':
        return True, 'SKIP: SWOS++ is English only (SWOSTEST_UI=en)'
    exe = os.environ.get('CV_BUILD')
    if not exe:
        return True, 'SKIP: CV_BUILD not set (the English release exe)'
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import swospp
    pp = os.path.join(MAIN, 'internal', 'swospp-test')
    out = os.path.join(WORK, 'builds-x', 'world_cgame_swospp')
    shutil.rmtree(out, ignore_errors=True)
    shutil.copytree(exe, out)
    swospp.install(os.path.join(exe, 'ITALIAN.EXE'), os.path.join(out, 'ITALIAN.EXE'))
    keep = {k: os.environ.get(k) for k in ('CV_BUILD', 'CGV_SWOSPP')}
    os.environ.update(CV_BUILD=out, CGV_SWOSPP=pp)
    global SLOW_FIRE
    SLOW_FIRE = 3
    try:
        ok, msg = world_cgame_view()
    finally:
        SLOW_FIRE = 0
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    return ok, f'SWOS++: {msg}'


@scenario
def world_contiview_old():
    """4.0.6 COPPE CONTINENTALI on an older career (M4): season 1 of an INTER career on the 4.0.5 release exe (CV_OLD,
    default c/REL405/SWOS: no view), its save loaded by this build as world_contiview's season 2 (CV_S2): every
    confederation's page opens, its texts in the font, CT_SEG / CT_ED unchanged by the view (ct_resume on the old
    edition), no hang"""
    old = os.environ.get('CV_OLD') or os.path.join(MAIN, 'c', 'REL405', 'SWOS')
    if not os.path.isdir(old):
        return True, f'SKIP: old release {old} missing'
    s2 = os.path.join(RUNS, f'cv_old_{UI}.CAR')
    if not os.path.exists(s2):
        ok, msg, _ = sc_season('EUROPA,ITALIA,SERIE A,INTER', dict(W8485_BUILD=old))
        car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'W84A.CAR')
        if not ok or not os.path.exists(car):
            return False, f'old season 1: {msg[:200]}'
        shutil.copy(car, s2)
    keep = os.environ.get('CV_S2')
    os.environ['CV_S2'] = s2
    try:
        ok, msg = world_contiview()
    finally:
        if keep is None:
            os.environ.pop('CV_S2', None)
        else:
            os.environ['CV_S2'] = keep
    return ok, f'4.0.5 save: {msg}'


@scenario
def world_contiview_tie():
    """4.0.6 COPPE CONTINENTALI with the career club in a conti cup (M4): a FLAMENGO career on a test build with
    CONTI_FORCE=lib:q1 (the club into the Libertadores' first qualifying round at every season end) and CONTI_KOWIN (it
    wins its conti ties). Season 1 played; season 2 (its save) saved at its 5th Libertadores result screen (q3's first
    leg, September: q1 and q2, August, are over). The view (CONMEBOL first, the club's own): q1 and q2 list FLAMENGO's
    ties with it in brackets (through), q3 its tie without them (the next game: the opponent of that result screen), the
    groups DA GIOCARE; CT_SEG / CT_ED unchanged by the view (CV_TIE_S2: a cached season-2 save). On a release exe
    (CV_TIE_BUILD=<release dir>: no CONTI_FORCE / CONTI_KOWIN) set CV_TIE_S2 to the test build's season-2 save - its
    'CE' item has FLAMENGO through q1 / q2 and the release exe only replays it (the names from TMW5.nnn)"""
    src = os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-rel40-winnames-1031')
    if not os.path.isdir(src):
        return True, f'SKIP: private data {src} missing'
    order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
    exe = os.environ.get('CV_TIE_BUILD') or build('world_contiview_tie', env={
        'SEASON_PACKS': ','.join(['ddr-1988-89'] + [os.path.join(src, x) for x in order]),
        'CONTI_FORCE': 'lib:q1', 'CONTI_KOWIN': '1'}, lang=UI)
    tr = cv_trace(exe)
    if not tr:
        return False, 'no CVTRPTR block (ctview not in the build)'
    seg_at, ed_at = tr[0], tr[1]
    import ctview
    T = [x.decode('latin1') for x in ctview.TEXTS[UI]]
    team = 'SUDAMERICA,BRASILE,BRASILEIRAO SERIE A,FLAMENGO'
    mid = os.environ.get('CV_TIE_S2') or os.path.join(RUNS, f'cv_tie_{UI}.CAR')
    opp = None
    if not os.path.exists(mid):
        ok, msg, _ = sc_season(team, dict(W8485_BUILD=exe))
        car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'W84A.CAR')
        if not ok or not os.path.exists(car):
            return False, f'season 1: {msg[:200]}'
        s1 = os.path.join(RUNS, f'cv_tie_s1_{UI}.CAR')
        shutil.copy(car, s1)
        ok, msg, l2 = sc_season(team, dict(W8485_BUILD=exe, W8485_FROM=s1, W8485_MIDTEXT=f'LIBERTADORES:{3 if UI == "de" else 5}'), 2)   # (DE: the 2nd legs' 'R\x9aCKSP.'
        # titles read empty - Screen keeps umlaut texts only for known labels - so q3's first leg is its 3rd screen)
        if not ok or 'saved mid-season' not in msg:
            return False, f'season 2 to q3\'s first leg: {msg[:200]}'
        shutil.copy(msg.split(': ', 1)[1], mid)
        res = [ln for ln in l2 if ln.startswith('[') and 'LIBERTADORES' in ln.split('|')[0] and '- RISULTATO -' in ln]
        if res:                                         # (the last one: q3's first leg - its two clubs)
            opp = [t for t in (x.strip() for x in res[-1].split('|')) if t and t != 'FLAMENGO']
    errs, info = [], []
    with Session('world_contiview_tie', exe, {'W84A.CAR': mid}, 'dump:2', 300) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        for _ in range(6):
            if s.screen().find('VISUAL. COMPETIZ.', exact=True) is not None:
                break
            press(s, s.screen(), 'CONTINUA', 3) or s.send('fire dump:2')
        st = lambda: (bytes(s.result.obj2(seg_at, 72)), bytes(s.result.obj2(ed_at, 2260)))
        b0 = st()
        pages = []
        btn, title, lines = contiview_open(s, 1, pages)
        b1 = st()
        allx = lines + [x for p in pages for x in p]
        s.log.append(f'[cv] tie {btn} {title} {allx}')
        sys.path.insert(0, os.path.join(ROOT, 'tools'))
        import complist                                 # (every character one the menu font draws: '>' was a box)
        odd = font_odd_all(allx + [title])
        check(not odd, f'characters outside the menu font {odd}', errs)
        wide = [x for x in allx if complist.px(x.upper()) > 298]   # (ctview PXMAX: a long tie wraps)
        check(not wide, f'lines over 298 px {wide}', errs)
        unk = [x for x in allx if '?' in x]             # (ctview name(): a team file not opened - TEAM vs TMW5.nnn)
        check(not unk, f'unread club names {unk[:4]}', errs)
        check(btn and btn[0] == 'CONMEBOL', f'buttons {btn}', errs)
        check(not LIST_BAD, f'VISUAL. COMPETIZ. list: {LIST_BAD}', errs)
        check(not any(b0[1][i] != b1[1][i] for i in range(len(b0[1]))) and (b0[0] == b1[0] or not any(b0[0])),
              'CT_SEG / CT_ED changed by the view', errs)
        lib = []
        for x in allx:                                  # (the Libertadores' lines: up to the next cup's title)
            if lib and x and not x.startswith(' ') and ':' not in x:
                break
            if x == 'COPA LIBERTADORES' or lib:
                lib.append(x)
        fl = [x for x in lib if 'FLAMENGO' in x]
        info.append(f'FLAMENGO lines {fl}')
        check(len(fl) >= 3, f'FLAMENGO in fewer than 3 Libertadores rounds: {lib}', errs)
        if len(fl) >= 3:
            check(all('(FLAMENGO)' in x for x in fl[:2]), f"q1 / q2 without FLAMENGO in brackets: {fl[:2]}", errs)
            check('(' not in fl[2], f"q3 (its next game) with brackets: {fl[2]}", errs)
            other = [x.strip(' ()') for x in fl[2].split(' - ') if 'FLAMENGO' not in x]
            if opp is not None:                         # (its other club exactly one of that screen's texts)
                check(len(other) == 1 and other[0] in opp, f'q3 tie {fl[2]!r} is not the result screen\'s', errs)
            later = lib[lib.index(fl[2]) + 1:]
            check(any(T[1] in x for x in later), f'no {T[1]} round after q3: {later}', errs)
    return not errs, '; '.join(errs) or '; '.join(info)


def cg_trace(exe):
    """obj3 offsets of ctgame.c's CG_T, its scratch, CG_ERR and CG_G (P2's guard; the 'CGTRPTR' block), else None."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    from le import LE
    f = next(os.path.join(exe, x) for x in ('ITALIAN.EXE', 'ENGLISH.EXE', 'FRENCH.EXE', 'GERMAN.EXE')
             if os.path.exists(os.path.join(exe, x)))
    le = LE(open(f, 'rb').read())
    if len(le.objs) < 3:
        return None
    d3 = le.obj_bytes(3)
    k = d3.find(b'CGTRPTR\0')
    return struct.unpack_from('<IIII', d3, k + 8) if k >= 0 else None


def cg_relocated(a, b, diff, exes):
    """world_cgame_guard: A and B are two exes, and DOS/4GW may load B's objects a page higher (a longer fixup
    section): the game's own absolute pointers in the .CAR (the contests' pointers ProcessCareerFile rebuilds) then
    differ by that page delta. Both exes booted once for their object bases; a differing byte is excused only inside
    a dword whose A value lies in A's objects and whose B value is exactly A's + the delta. (excused count, the rest)"""
    bases = {}
    for k in ('A', 'B'):
        with Session(f'cgg_base_{k.lower()}', exes[k], {}, 'dump:2', 60) as s:
            s.wait()
            r = s.result
            bases[k] = (r.base1, r.base2, r.base3 or r.base2)
    d = bases['B'][1] - bases['A'][1]
    cg_relocated.delta = d
    if not d or any(bases['B'][i] - bases['A'][i] != d for i in range(3)):
        return 0, diff
    lo, hi = bases['A'][0], bases['A'][2] + 0x100000
    ok = set()
    for i in diff:
        for j in range(max(0, i - 3), i + 1):
            va, vb = struct.unpack_from('<I', a, j)[0], struct.unpack_from('<I', b, j)[0]
            if lo <= va < hi and vb - va == d:
                ok.update(range(j, j + 4))
                break
    left = [i for i in diff if i not in ok]
    return len(diff) - len(left), left


@scenario
def world_cgame_guard():
    """4.0.6 option C, P2 gate (GO/NO-GO 2): a view opened and closed leaves the career exactly as it was. Two exes of
    one recipe (CGG_A: without, CGG_B: with CONTI_CGVIEW=1 - a test build: conti's ct_daily opens one drawn conti round
    every day (cg_open: the state kept, cg_build), does to it what the game's view does (cseg_8B71C / cseg_8B7EA on the
    contest) and closes it (cg_close: put back, the saved state's sum checked)). Season 1 on A (CGG_S1: a cached save),
    then season 2 from its save on A and on B: the two season-2 .CARs byte-identical, B's guard (CG_G) opened views,
    no bad sum, no fallback, no failed build. CGG_TEAM (default HAMRUN SPARTANS: a short league)."""
    src = os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-rel40-winnames-1031')
    if not os.path.isdir(src) and not (os.environ.get('CGG_A') and os.environ.get('CGG_B')):
        return True, f'SKIP: private data {src} missing'
    exes = {}
    for k, env in (('A', {}), ('B', {'CONTI_CGVIEW': '1'})):
        exes[k] = os.environ.get('CGG_' + k)
        if not exes[k]:
            order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
            env['SEASON_PACKS'] = ','.join(['ddr-1988-89'] + [os.path.join(src, x) for x in order])
            exes[k] = build('world_cgame_guard_' + k.lower(), env=env, lang=UI)
    tr = cg_trace(exes['B'])
    if not tr or len(tr) < 4:
        return False, 'no CGTRPTR block with CG_G in B (ctgame not in the build)'
    g_at = tr[3]
    team = os.environ.get('CGG_TEAM', 'EUROPA,MALTA,?MALTESE PREMIER LEAGUE|PREMIER LEAGUE,HAMRUN SPARTANS')
    s1 = os.environ.get('CGG_S1') or os.path.join(RUNS, f'cgg_s1_{UI}.CAR')
    if not os.path.exists(s1):
        ok, msg, _ = sc_season(team, dict(W8485_BUILD=exes['A']))
        car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'W84A.CAR')
        if not ok or not os.path.exists(car):
            return False, f'season 1: {msg[:200]}'
        shutil.copy(car, s1)
    seen = {}
    global W84_HOOK

    def hook(s, season, scr):
        r = s.result
        if r is None or r.base3 is None:
            return
        g = struct.unpack('<12I', r.read(r.base3 + g_at, 48))
        if g != seen.get('last'):
            seen['last'] = g
    errs, cars, info = [], {}, []
    for k in ('A', 'B'):
        seen.clear()
        W84_HOOK = hook if k == 'B' else None
        try:
            ok, msg, _ = sc_season(team, dict(W8485_BUILD=exes[k], W8485_FROM=s1), 2)
        finally:
            W84_HOOK = None
        car = os.path.join(RUNS, w84_tag() + '_2', 'SWOS', 'W84B.CAR')
        check(ok and os.path.exists(car), f'season 2 on {k}: {msg[:150]}', errs)
        if os.path.exists(car):
            cars[k] = os.path.join(RUNS, f'cgg_s2_{k}_{UI}.CAR')
            shutil.copy(car, cars[k])
            os.remove(car)
    if len(cars) == 2:
        a, b = (open(cars[x], 'rb').read() for x in ('A', 'B'))
        diff = [i for i in range(min(len(a), len(b))) if a[i] != b[i]]
        rel, left = cg_relocated(a, b, diff, exes) if diff and len(a) == len(b) else (0, diff)
        check(len(a) == len(b) and not left, f'season-2 .CAR with the view != without: {len(a)} / {len(b)} B, '
              f'{len(left)} bytes differ, first {[hex(i) for i in left[:8]]}', errs)
        info.append(f'.CAR {len(a)} B identical' + (f' (but {rel} of the game\'s absolute pointers, B loaded '
                    f'{cg_relocated.delta:#x} higher)' if rel else '') if not left else '')
    g = seen.get('last')
    if not g:
        errs.append('B: CG_G never read')
    else:
        info.append(f'CG_G opens {g[3]} vtest builds {g[8]} fails {g[9]} trips {g[4]} bad {g[5]} sticky {g[6]} '
                    f'last err {g[7]}')
        check(g[3] > 0 and g[8] > 0, f'B: no view opened ({g[:10]})', errs)
        check(g[0] == 0 and g[5] == 0 and g[6] == 0 and g[9] == 0, f'B: guard {g[:10]}', errs)
    return not errs, '; '.join(errs + info) or '; '.join(info)


@scenario
def world_cgame_self():
    """4.0.6 option C, P1 gate: the builder (ctgame.c - the view's contests by the game's own code into the scratch)
    against the game's own slot-3 contests. A FLAMENGO career on a CONTI_FORCE=lib:q1 + CONTI_KOWIN + CONTI_CGTEST
    test build: in season 2 every contest conti's ct_build puts in slot 3 from the daily (the Libertadores' q2, q3 ties,
    its group stage; q1 is built at the season start) is rebuilt at once by cg_build from conti.c's replay and must be byte-identical to slot 3 (cg_selftest:
    CG_T builds / mismatches / first diff), the team cache unchanged by it (every club already in). CG_FILL=1: the
    scratch filled with 5Ah first (DOS/4GW leaves it as it was - the builder must clear what it uses)."""
    src = os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-rel40-winnames-1031')
    if not os.path.isdir(src):
        return True, f'SKIP: private data {src} missing'
    order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
    fill = os.environ.get('CG_FILL')
    env = {'SEASON_PACKS': ','.join(['ddr-1988-89'] + [os.path.join(src, x) for x in order]),
           'CONTI_FORCE': 'lib:q1', 'CONTI_KOWIN': '1', 'CONTI_CGTEST': '1'}
    if fill:
        env['CG_FILL_TEST'] = '5A'
    exe = os.environ.get('CG_BUILD') or build('world_cgame_self' + ('_fill' if fill else ''), env=env, lang=UI)
    tr = cg_trace(exe)
    if not tr:
        return False, 'no CGTRPTR block (ctgame not in the build)'
    t_at = tr[0]
    team = 'SUDAMERICA,BRASILE,BRASILEIRAO SERIE A,FLAMENGO'
    s1 = os.environ.get('CG_S1') or os.path.join(RUNS, f'cg_self_s1_{UI}.CAR')
    if not os.path.exists(s1):
        ok, msg, _ = sc_season(team, dict(W8485_BUILD=exe))
        car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'W84A.CAR')
        if not ok or not os.path.exists(car):
            return False, f'season 1: {msg[:200]}'
        shutil.copy(car, s1)
    seen = {}
    global W84_HOOK

    def hook(s, season, scr):
        r = s.result
        if r is None or r.base3 is None:
            return
        t = struct.unpack('<8I', r.read(r.base3 + t_at, 32))
        if t[0] and t != seen.get('last'):
            seen['last'] = t
            seen.setdefault('lens', set()).add(t[4])
            s.log.append(f'[cg] builds {t[0]} mismatches {t[1]} first {t[2]:#x} last cup/round/tie {t[3]:#x} '
                         f'len {t[4]:#x} cache {t[5]}->{t[6]} err {t[7]}')
    W84_HOOK = hook
    try:
        ok, msg, lines = sc_season(team, dict(W8485_BUILD=exe, W8485_FROM=s1), 2)
    finally:
        W84_HOOK = None
    t = seen.get('last')
    if not t:
        return False, f'no cg_selftest build seen; season 2: {ok} {msg[:150]}'
    errs = []
    lens = seen.get('lens', set())                       # (q1 goes into slot 3 at the season start, not from the
    check(t[0] >= 3 and {0x443, 0xB52} <= lens,          #  daily: q2, q3 and the group stage here)
          f'{t[0]} slot-3 contests rebuilt, kinds {sorted(hex(x) for x in lens)} (ties 443h and a group stage B52h)', errs)
    check(t[1] == 0, f'{t[1]} rebuilt contests differ from slot 3 (first at {t[2] & 0xFFFF:#x}, err {t[7]})', errs)
    check(t[5] == t[6], f'the team cache changed {t[5]} -> {t[6]}', errs)
    check(ok, f'season 2: {msg[:150]}', errs)
    cg = [ln for ln in lines if ln.startswith('[cg]')]
    return not errs, '; '.join(errs + cg[-3:]) or '; '.join(cg[-4:])


