@scenario
def world_buycont():
    """4.0.1 foreign purchase in a historic world (careerworld w_buy: competitionsTable[254] = the world's W_CONT list):
    TRASFERIMENTI > ACQUISTA GIOCATORE > ACQ. ALTRO GIOCAT. STRANIERO opens without the violet CARR. STORICHE entry -
    a World 2026-27 career at CORDOBA on the world's continents (EUROPA > ITALIA > SERIE A > ATALANTA), a 1984-85 one
    at LIVERPOOL on the world's countries (ITALIA > SERIE A > JUVENTUS); both reach the club's players (release recipe,
    SWOSTEST_BUILD)"""
    errs, info = [], []
    for tag, path, want, then in (
            ('w2627', ['CARR. STORICHE', 'MONDO 2026-27', 'EUROPA', 'SPAGNA', 'SEGUNDA DIVISION', 'CORDOBA'],
             ('EUROPA', 'AFRICA'), ('EUROPA', 'ITALIA', 'SERIE A', 'ATALANTA')),
            ('w8485', ['CARR. STORICHE', 'EUROPA 1984-85', 'INGHILTERRA', 'FIRST DIVISION', 'LIVERPOOL'],
             ('ITALIA', 'JUGOSLAVIA'), ('ITALIA', 'SERIE A', 'JUVENTUS'))):
        with Session(f'world_buycont_{UI}_{tag}', builds()['it'], {}, 'dump:2', 900) as s:
            s.wait()
            for t in ['CARRIERA', 'SCEGLI SQUADRA'] + path:
                if press(s, s.screen(), t, 3) is None:
                    return False, f'{tag}: {t} not reached: {[e[1] for e in s.screen().entries if e[1]]}'
            s.send('fire dump:3')
            for k in (4, 2, 5):                          # TRASFERIMENTI, ACQUISTA GIOCATORE, ACQ. ALTRO GIOCAT. STRANIERO
                walk(s, k, 3)
            top = [e[1] for e in s.screen().entries if e[1] and not e[2]]
            s.shot('chooser')
            check(all(x in top for x in want) and 'CARR. STORICHE' not in top, f'{tag}: first list {top}', errs)
            info.append(f'{tag}: first list {top[1:7]}')
            for t in then:
                if press(s, s.screen(), t, 3) is None:
                    return False, f'{tag}: {t} not reached: {[e[1] for e in s.screen().entries if e[1]]}; ' + '; '.join(errs)
            got = [e[1] for e in s.screen().entries if e[1] and not e[2]]
            s.shot('club')
            check(len(got) > 4, f'{tag}: {then[-1]}: {got}', errs)
            info.append(f'{tag} {then[-1]}: {got[:5]}')
    return not errs, '; '.join(errs + info)

@scenario
def world_viewcont():
    """4.0.2 VISUALIZZA MONDO in a historic world's career (careerworld w_view, as w_buy: competitionsTable[254] = the
    world's W_CONT list): no one-entry 'SCEGLI COMPETIZIONE - MONDO' menu with the violet CARR. STORICHE - a World
    2026-27 career at CORDOBA lands on the world's cups and continents (EUROPA > ITALIA lists SERIE A, SERIE B), a
    1984-85 one at LIVERPOOL on the world's countries (ITALIA), a 1996-97 one at JUVENTUS on the game's own continents
    (no CARR. STORICHE either); ABBANDONA back to the career menu, from that list and
    at once from the first one (release recipe, SWOSTEST_BUILD)"""
    errs, info = [], []
    for tag, path, want, then in (
            ('w2627', ['CARR. STORICHE', 'MONDO 2026-27', 'EUROPA', 'SPAGNA', 'SEGUNDA DIVISION', 'CORDOBA'],
             ('EUROPA', 'AFRICA', 'SUDAMERICA'), ('EUROPA', 'ITALIA')),
            ('w8485', ['CARR. STORICHE', 'EUROPA 1984-85', 'INGHILTERRA', 'FIRST DIVISION', 'LIVERPOOL'],
             ('ITALIA', 'JUGOSLAVIA'), ('ITALIA',)),
            ('w9697', ['EUROPA', 'ITALIA', 'SERIE A', 'JUVENTUS'], ('EUROPA', 'SUDAMERICA'), ('EUROPA', 'ITALIA'))):
        with Session(f'world_viewcont_{UI}_{tag}', builds()['it'], {}, 'dump:2', 900) as s:
            s.wait()
            for t in ['CARRIERA', 'SCEGLI SQUADRA'] + path:
                if press(s, s.screen(), t, 3) is None:
                    return False, f'{tag}: {t} not reached: {[e[1] for e in s.screen().entries if e[1]]}'
            s.send('fire dump:3')
            for back in (False, True):                  # (twice: the second time ABBANDONA at once)
                if press(s, s.screen(), 'VISUALIZZA MONDO', 3) is None:
                    return False, f'{tag}: no VISUALIZZA MONDO: {s.screen().texts()[:12]}'
                top = [e[1] for e in s.screen().entries if e[1] and not e[2]]
                if not back:
                    s.shot('view_' + tag)
                    check(all(x in top for x in want) and 'CARR. STORICHE' not in top, f'{tag}: first list {top}', errs)
                    info.append(f'{tag}: first list {top[:8]}')
                    for t in then:
                        if press(s, s.screen(), t, 3) is None:
                            return False, f'{tag}: {t} not reached: {[e[1] for e in s.screen().entries if e[1]]}; ' + \
                                '; '.join(errs)
                    got = [e[1] for e in s.screen().entries if e[1] and not e[2]]
                    check('SERIE A' in got and 'SERIE B' in got, f'{tag}: {then[-1]}: {got}', errs)
                    info.append(f'{tag} {then[-1]}: {got[1:5]}')
                for _ in range(8):                      # ESCI / ABBANDONA up to the career menu
                    if 'TRASFERIMENTI' in s.screen().texts():
                        break
                    ns_exit(s)                          # (lists: no menu links the BFS knows)
                check('TRASFERIMENTI' in s.screen().texts(), f'{tag}: back {"at once" if back else "from the clubs"}: '
                      f'{s.screen().texts()[:10]}', errs)
    return not errs, '; '.join(errs + info)


@scenario
def world_winners_bank():
    """4.0.1 WINNERS 'S' lines read the VIEWED league's stage bank (gplay.c ss_view(GP_WNFILE), read only), not the last
    selected one: a World 2026-27 career at SAPRISSA (Costa Rica: the career's bank 1; release recipe, SWOSTEST_BUILD)
    - mid-season, VISUALIZZA MONDO > ARGENTINA's and USA's VINCITORI pages (bank 0: ARG, MLS) name no club (DA GIOCARE /
    IN CORSO, or no line at all: their seasons are simulated at the season end), never a Costa Rican one; at the season end (saved before
    CONTINUA, reloaded) the career's own page names PRIMERA DIVISION's annual winner (stage table 2 of bank 1)"""
    import csv as _csv
    crc = {r['name'] for r in _csv.DictReader(open(os.path.join(
        os.environ.get('W2627REL_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-401nats'), 'crc', 'clubs.csv')))}
    errs, info = [], []
    exe = builds()['it']
    with Session('world_winners_bank_mid', exe, {}, 'dump:2', 600) as s:
        s.wait()
        for t in ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', 'NORDAMERICA', 'COSTA RICA', 'SAPRISSA']:
            if press(s, s.screen(), t, 3) is None:
                return False, f'new career: {t} not reached'
        s.send('fire dump:3')
        for path in (('SUDAMERICA', 'ARGENTINA', 'LIGA PROFESIONAL'), ('NORDAMERICA', 'USA', 'MAJOR LEAGUE SOCCER')):
            for t in ('VISUALIZZA MONDO',) + path + ('STAT',):   # (4.0.2: the world's continents at once)
                if press(s, s.screen(), t, 3) is None:
                    return False, f'{path[1]}: {t} not reached: {[e[1] for e in s.screen().entries if e[1]]}'
            e = next((x for x in s.screen().entries if x[1] == 'VINCITORI'), None)
            if e is None or e[2]:
                return False, f'{path[1]}: no VINCITORI entry'
            walk(s, e[0], 3)
            lines = [x[1] for x in s.screen().entries[1:] if x[1] and not x[2]]
            s.shot('wn_' + path[1])
            b = winner_blocks(lines)
            check(all(v in ('DA GIOCARE', 'IN CORSO') for v in b.values()) and not set(b.values()) & crc,   # (none: another
                                                                                    # country's titles with nothing yet)
                  f'mid-season {path[1]}: {b}', errs)
            info.append(f'mid {path[1]}: {b}')
            for _ in range(8):                           # back to the career menu
                if s.screen().find('VISUALIZZA MONDO', exact=True) is not None:
                    break
                i = s.screen().find('ESCI', exact=True)
                if i is None:
                    i = s.screen().find('ABBANDONA', exact=True)
                walk(s, i, 3)
    keys = ('W8485_BUILD', 'W8485_WORLD', 'W8485_TEAM', 'W8485_WNUM', 'W8485_K', 'W8485_NOSACK', 'W8485_ONE',
            'W8485_SAVE_END', 'W8485_TMO')
    keep = {k: os.environ.get(k) for k in keys}
    try:
        os.environ.update(W8485_BUILD=exe, W8485_WORLD='MONDO 2026-27', W8485_TEAM='NORDAMERICA,COSTA RICA,SAPRISSA',
                          W8485_WNUM='5', W8485_K='108+', W8485_NOSACK='1', W8485_ONE='1', W8485_SAVE_END='WBANK',
                          W8485_TMO=os.environ.get('W8485_TMO', '1800'))
        ok, msg = world8485()
    finally:
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    car = os.path.join(RUNS, w84_tag() + '_1', 'SWOS', 'WBANK.CAR')
    if not ok or not os.path.exists(car):
        return False, f'season: {msg}; ' + '; '.join(errs + info)
    with Session('world_winners_bank_end', exe, {'WBANK.CAR': car}, 'dump:2', 600) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        e, title, lines = winners_page(s)
        b = winner_blocks(lines)
        pd = b.get('PRIMERA DIVISION')
        check(pd in crc, f'end: PRIMERA DIVISION shows {pd!r} ({title!r} {b})', errs)
        info.append(f'end {title}: {b}')
    return not errs, '; '.join(errs + info)


@scenario
def world_titlefit():
    """4.0.1 match titles in px (rnames rn_tfit / rn_tend: the 304-px bar, PXMAX 302, was 40 characters): a 1984-85
    career at LIVERPOOL (release recipe, SWOSTEST_BUILD) - the Champions Cup's first match screen keeps the long round
    name ('<cup> <round> <leg>', no fallback), and with the contest's name poked to 34 characters (rule 15) the title
    recomposed at re-entry is the whole '<34> <round> <leg>' (it fits in px), not a fallback or a cut"""
    import split
    import lepatch
    diy = split.sites(lepatch.LEPatch(os.path.join(MAIN, 'orig', UI_ORIG)))['DIY']   # (the exe language's obj2)
    errs, info = [], []
    with Session('world_titlefit_' + UI, builds()['it'], {}, 'dump:2', 600) as s:
        s.wait()
        for t in ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'EUROPA 1984-85', 'INGHILTERRA', 'FIRST DIVISION',
                  'LIVERPOOL']:
            if press(s, s.screen(), t, 3) is None:
                return False, f'{t} not reached'
        s.send('fire dump:3')
        cur = lambda: s.result.obj2(diy + 4, 35).split(b'\0')[0].decode('latin1')   # (the contest on screen)
        ok, msg = advance(s, lambda scr: '- PARTITA -' in scr.texts() and scr.entries[0][1].startswith(cur() + ' ')
                          and len(scr.entries[0][1].split()) >= len(cur().split()) + 3, 300)
        if not ok:
            return False, f'no cup match screen: {msg}'
        name = cur()
        t0 = s.screen().entries[0][1]
        s.shot('cup')
        rest = t0[len(name):].split()
        check(len(rest) >= 3, f'cup title {t0!r}: a fallback (medium round) or a cut', errs)
        check(t0 == ' '.join(t0.split()), f'cup title {t0!r}: a leading / double space', errs)
        info.append(f'cup: {t0!r} ({len(t0)})')
        s.poke(s.result.base2 + diy + 4, list(b'W' * 34 + b'\0'))
        walk(s, s.screen().find('ESCI', exact=True), 3)
        walk(s, s.screen().find('PARTITA', exact=True), 3)
        t1 = s.screen().entries[0][1]
        s.shot('poked')
        check(t1 == 'W' * 34 + ' ' + ' '.join(rest) or t1.startswith('W' * 34 + ' '),
              f'poked title {t1!r}: not the whole one', errs)
        info.append(f'poked: {t1!r} ({len(t1)})')
    return not errs, '; '.join(errs + info)


@scenario
def world_seasonend_titles():
    """4.0.1 rc3 (Davide's MiSTer, rc2): every competition screen the World 2026-27 season end SHOWS has a title in the
    game font. Davide's own 4.0 save (SEASONEND_CAR, default internal/swostest/repro/mister-rc2/disk/PHILA.CAR:
    PHILADELPHIA at the season-end menu) loaded on SWOSTEST_BUILD, CONTINUA CARRIERA to the new season with
    breakpoints (CORE=normal) on the two show routines (ShowDiyLeaguesTournamentMenu obj1+0x38195, the cup results'
    obj1+0x359A5): each shown title (DIY+4) only font characters, the three European cups' among them. On 4.0
    (REL40hf) and rc2 the European cups' season-end simulation (cseg_92D55 / cseg_9307A / cseg_9339D, before the
    career country) showed its finals - PARIS-SG v BARCELONA, SUNDERLAND v CRYSTAL PALACE - under a team order list:
    the save's W1 cups kept the name offsets of the exe that wrote it (careerworld w_cupnames takes this exe's since
    rc3). SEASONEND_CMP=<build dir>: the same run on that build too, reported (REL40hf)."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import complist
    car = os.environ.get('SEASONEND_CAR') or os.path.join(WORK, 'repro', 'mister-rc2', 'disk', 'PHILA.CAR')
    if not os.path.exists(car):
        return True, f'SKIP: no {car}'
    import lp36
    import lepatch
    diy = lp36._sites(lepatch.LEPatch(os.path.join(MAIN, 'orig', 'ITALIAN.EXE')))['DIY']
    ok_chars = set(complist.SMALL_W) | {' '}

    def run(exe, tag):
        keep = {k: os.environ.get(k) for k in ('SWOSTEST_BP', 'SWOSTEST_BP_HEX', 'CORE')}
        os.environ.update(SWOSTEST_BP='38195,359a5', SWOSTEST_BP_HEX=f'{diy:x}:40', CORE='normal')
        try:
            with Session('seasonend_titles_' + tag, exe, {'W84A.CAR': car}, 'dump:2', 1500) as s:
                s.wait()
                s.send(LOAD1 + ' dump:3')
                if press(s, s.screen(), 'CONTINUA CARRIERA', 5) is None:
                    return None, f'{tag}: no CONTINUA CARRIERA on {s.screen()}'
                for _ in range(6):
                    if s.result.outcome != 'dump' or 'TRASFERIMENTI' in s.screen().texts():
                        break
                    press(s, s.screen(), 'CONTINUA' if s.screen().find('CONTINUA', exact=True) is not None else 0, 3)
                done = s.result.outcome == 'dump' and 'TRASFERIMENTI' in s.screen().texts()
                log = list(s.log)
        finally:
            for k, v in keep.items():
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
        titles = []
        for ln in log:
            m = re.search(rf'^BP obj1\+\w+ hit \d+ {diy:x}:([0-9a-f]+)', ln)
            if m:
                titles.append(bytes.fromhex(m.group(1))[4:39].split(b'\0')[0])
        bad = [t for t in titles if not t or any(chr(c) not in ok_chars for c in t)]
        return (done, titles, bad), ''

    errs, info = [], []
    r, msg = run(builds()['it'], 'build')
    if r is None:
        return False, msg
    done, titles, bad = r
    check(done, 'the new season not reached', errs)
    check(titles, 'no competition shown at the season end (the breakpoints never hit)', errs)
    check(not bad, f'{len(bad)} garbage titles: {bad[:4]}', errs)
    euro = [t for t in titles if t.startswith(b'UEFA ')]
    check(len(set(euro)) >= 3 or os.environ.get('SEASONEND_CAR'), f'the European finals not all shown: {euro}', errs)
    info.append(f'{len(titles)} shown, e.g. {sorted({t.decode("latin1") for t in titles})[:6]}')
    cmp_ = os.environ.get('SEASONEND_CMP')
    if cmp_:
        r2, msg2 = run(cmp_, 'cmp')
        info.append(f'{os.path.basename(os.path.dirname(cmp_.rstrip("/")))}: ' +
                    (msg2 if r2 is None else f'{len(r2[1])} shown, {len(r2[2])} garbage {r2[2][:2]}'))
    return not errs, '; '.join(errs + info)


def unplane(data):
    """Pixels of a planar sprite (DoUnchainSprite: plane k at k * len / 4, bit k of 8 pixels per byte, first = MSB)."""
    q = len(data) // 4
    return [sum(((data[k * q + j] >> (7 - t)) & 1) << k for k in range(4)) for j in range(q) for t in range(8)]


def dkb_half(r):
    """The running game is in half / EGA mode: setupDatBuffer = -1 (= EGA_graphics in the match). 4.0.2 (fullgfx):
    only with /H (SWOSTEST_EXEARGS) or low memory; before, SETUP.DAT's video speed <= 85 (GOG's factory file)."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import re as _re
    import lepatch
    import fullgfx
    if not hasattr(dkb_half, 'buf'):
        p = lepatch.LEPatch(os.path.join(ROOT, 'orig', UI_ORIG))
        dkb_half.buf = p.target(1, _re.search(fullgfx.PAT, p.le.obj_bytes(1), _re.S).start() + 3)[1]
    return r.read(r.base2 + dkb_half.buf, 2) == b'\xff\xff'


def variant_sets(r):
    """blond.copy_sets' allocation this match: {(team 0 / 1, flag): the slot's first sprite} (flag 1 darkblond, 2 / 3
    receding dark / light, 4 / 5 shaved dark / light - 4.0.5 single-team slots; 6 / 7 white hair dark / light,
    4.0.6), from its block after 'BLDSLOT5' / 'BLDSLOT7' in obj1: SFL[5], STM[5], (align 2) VBT[2][4] words, VBT5 =
    [2] words (flag 5 per team; '7': [3][2], flags 5, 6, 7)."""
    if not hasattr(r, '_vsig'):
        d1 = r.read(r.base1, 0x100000)
        k, r._vnx = d1.find(b'BLDSLOT7'), 3
        if k < 0:
            k, r._vnx = d1.find(b'BLDSLOT5'), 1
        r._vsig = k + 8 if k > 0 else None
    if r._vsig is None:
        return {}
    b = r.read(r.base1 + r._vsig, 48)
    sfl, stm = b[0:5], b[5:10]
    o = 10 + ((r._vsig + 10) & 1)
    vbt = struct.unpack_from('<8H', b, o)
    vb5 = struct.unpack_from(f'<{2 * r._vnx}H', b, o + 16)
    out = {}
    for t in (0, 1):
        for f in (1, 2, 3, 4):
            if vbt[t * 4 + f - 1]:
                out[(t, f)] = vbt[t * 4 + f - 1]
        for f in range(5, 5 + r._vnx):
            if vb5[(f - 5) * 2 + t]:
                out[(t, f)] = vb5[(f - 5) * 2 + t]
    assert sorted(out) == sorted((stm[i], sfl[i]) for i in range(5) if sfl[i]), (out, sfl, stm)
    return out


def vs_flags(vs):
    """The variant flags allocated this match (either team), as DKB_EXPECT's 'a,b,c'."""
    return ','.join(map(str, sorted({f for _, f in vs})))


def dkb_sets(r, spr, blond, info):
    """In a running match: every frame of the darkblond sets (blond.NEW1 / NEW2, 101 each) against the same frame of
    the team's black-skin set (543.. / 846..): the same width / lines and the same pixel positions, differing only in
    hair colours; and each raw set's size against blond.SET_BYTES (copy_sets' room per team). Returns the errors."""
    errs = []
    nib = lambda data: [x >> 4 for x in data] + [x & 15 for x in data]
    idx = lambda i: struct.unpack('<I', r.read(r.base2 + spr + i * 4, 4))[0]
    planar = dkb_half(r)                        # half / EGA mode: sprites 309.. as 4 bitplanes (DoUnchainSprite)

    def frame(i):
        h = r.read(idx(i), 24)
        wq, nl = struct.unpack_from('<hh', h, 14)[0], struct.unpack_from('<h', h, 12)[0]
        data = r.read(struct.unpack('<I', h[:4])[0], wq * 8 * nl)
        return wq, nl, unplane(data) if planar else nib(data)
    vs = variant_sets(r)
    info.append(f'variant sets {vs}')
    for tag, raw, black, tm in (('team 1', 341, 543, 0), ('team 2', 644, 946 - 100, 1)):
        size = 0
        for k in range(101):
            h = r.read(idx(raw + k), 24)
            size += 24 + 8 * struct.unpack_from('<h', h, 14)[0] * struct.unpack_from('<h', h, 12)[0]
        info.append(f'{tag}: raw set {size} B (room {blond.SET_BYTES})')
        check(size <= blond.SET_BYTES, f'{tag}: raw set {size} B > copy_sets room {blond.SET_BYTES}', errs)
        other = [k for k in range(101) if not (frame(raw + k)[:2] == frame(raw + 101 + k)[:2] == frame(black + k)[:2])]
        check(not other, f'{tag}: the three skin / hair sets differ in size at frames {other[:12]}', errs)
        if (tm, 1) in vs:
            new = vs[(tm, 1)]
            bad = []
            for k in range(101):
                a, b_ = frame(black + k), frame(new + k)
                if a[:2] != b_[:2] or [x != 0 for x in a[2]] != [x != 0 for x in b_[2]]:
                    bad.append(k)
            check(not bad, f'{tag}: darkblond frames differing from the black set: {bad[:12]} ({len(bad)})', errs)
            hair = {x for k in range(101) for x in frame(new + k)[2]}
            check(15 in hair and 5 not in hair, f'{tag}: darkblond colours {sorted(hair)} (yellow 15, no light skin 5)',
                  errs)
        for f in (6, 7):                                # 4.0.6 white hair (R2): the hair pixels (where the light set
            if (tm, f) not in vs:                       # and face 1's differ: only their hair colours do - the game
                continue                                # converted the 'raw' sets in place) grey 1, the top hair row's
            look, name = blond.FLAGS[f]                 # two end pixels off (3 or more), the rest as the face's set
            ref = black if name == 'dark' else raw
            rm = (lambda v: v) if planar else \
                (lambda v: [v[i // 2] if i % 2 == 0 else v[len(v) // 2 + i // 2] for i in range(len(v))])
            bad, grey = [], 0
            for k in range(101):
                h0, h1 = rm(frame(raw + k)[2]), rm(frame(raw + 101 + k)[2])
                a, b_ = frame(ref + k), frame(vs[(tm, f)] + k)
                a, b_ = (a[0], a[1], rm(a[2])), (b_[0], b_[1], rm(b_[2]))
                hair = [i for i, (x, y) in enumerate(zip(h0, h1)) if x != y]
                want = list(a[2])
                wt = blond.WHITE_TONES[os.environ.get('WHITE_TONE', blond.WHITE_TONE)]
                for i in hair:                          # (raw 12, the darkest shade, is not told apart in the
                    want[i] = wt[0] if b_[2][i] not in wt else b_[2][i]   # converted sets: either colour)
                top = [i for i in hair if hair and i // (16 * a[0]) == hair[0] // (16 * a[0])]
                if len(top) >= 3:
                    want[top[0]] = want[top[-1]] = 0
                if a[:2] != b_[:2] or b_[2] != want:
                    if not bad:
                        info.append(f'{tag}: {look} {name} frame {k} (cell, want, got): '
                                    f'{[(i, w, g) for i, (w, g) in enumerate(zip(want, b_[2])) if w != g][:12]}')
                    bad.append(k)
                grey += len(hair)
            check(not bad and grey, f'{tag}: {look} {name} frames differing from R2: {bad[:12]} ({len(bad)})', errs)
            if not bad:
                info.append(f'{tag}: {look} {name}: all 101 frames = R2 ({grey} hair pixels white/grey)')
        for f in (2, 3, 4, 5):
            if (tm, f) not in vs:                       # 4.0.5 bald: the face's set reshaped by the variant's look
                continue                                # (blond.LOOKS): E = its top hair (3) in skin colours, the rest
            look, name = blond.FLAGS[f]                 # kept; art = shavedart's heads over the face's frames, exactly
            ref, skin = (black, {3, 4}) if name == 'dark' else (raw, {4, 5, 6})
            bald = vs[(tm, f)]
            lk = blond.LOOKS[look][name]
            col = (7 if not planar else lk["ega"]) if lk["skull"] == 7 else lk["skull"]
            if lk['shape'] == 'oval':
                col = {6: (4 if name == 'dark' else 6)}.get(col, col)          # (raw -> the face's conversion)
            gone, skinned, bad = 0, 0, []
            if lk['shape'] == 'art':                    # (the art's raw nibbles as the face converts them; the dark
                import shavedart                        # shade raw 13 = nibble 7, the half mode's EGA colour instead)
                main_, lo_, io_, dark_ = shavedart.blobs()
                conv = {'dark': {0: 0, 1: 1, 2: 2, 4: 3, 6: 4, 13: col if col != 6 else 4},
                        'light': {**{v: v for v in range(7)}, 13: col}}[name]
                rm = (lambda v: v) if planar else \
                    (lambda v: [v[i // 2] if i % 2 == 0 else v[len(v) // 2 + i // 2] for i in range(len(v))])
                for k in range(101):                    # (row-major pixels: nib() gives the high nibbles first)
                    a, b_ = frame(ref + k), frame(bald + k)
                    a, b_ = (a[0], a[1], rm(a[2])), (b_[0], b_[1], rm(b_[2]))
                    W_ = 16 * a[0]
                    g = [[None] * W_ for _ in range(a[1])]
                    o_ = main_[3 * k + (1 if name == 'dark' else 2)]
                    shavedart.decode(dark_ if name == 'dark' else main_[lo_:io_], main_[3 * k], o_ >> 4, o_ & 15, name, g)
                    want = [conv[g[i // W_][i % W_]] if g[i // W_][i % W_] is not None else x for i, x in enumerate(a[2])]
                    if a[:2] != b_[:2] or b_[2] != want:
                        bad.append(k)
                    skinned += sum(1 for x, y in zip(a[2], want) if x != y and y)
                    gone += sum(1 for x, y in zip(a[2], want) if x != y and not y)
                check(not bad and skinned, f'{tag}: {look} {name} (art) frames differing from the art: {bad[:12]} '
                      f'({len(bad)})', errs)
                if not bad:
                    info.append(f'{tag}: {look} {name} (art): all 101 frames = the art ({skinned} pixels painted, '
                                f'{gone} cleared)')
                continue
            for k in range(101):
                a, b_ = frame(ref + k), frame(bald + k)
                d_ = [(x, y) for x, y in zip(a[2], b_[2]) if x != y]
                if lk['shape'] == 'oval':
                    wrong = a[:2] != b_[:2] or any(y not in (0, col) or x not in (0, 3, 4, 5, 6) for x, y in d_)
                    skinned += sum(1 for x, y in d_ if y == col)
                    gone += sum(1 for x, y in d_ if y == 0)
                else:
                    wrong = a[:2] != b_[:2] or any(x != 3 or y not in skin for x, y in d_)
                    skinned += len(d_)
                    gone += sum(1 for x, y in zip(a[2], b_[2]) if x == 3 and y == 3)     # (here: hair pixels kept)
                if wrong:
                    bad.append(k)
            what = ('dropped', f'in colour {col}') if lk['shape'] == 'oval' else ('kept', 'in skin')
            check(not bad and gone and skinned, f'{tag}: {look} {name} ({lk["shape"]}) frames {bad[:12]} ({len(bad)}), '
                  f'pixels {gone} {what[0]} / {skinned} {what[1]}', errs)
            info.append(f'{tag}: {look} {name} ({lk["shape"]}): {gone} pixels {what[0]}, {skinned} {what[1]}')
    return errs


@scenario
def world_darkblond():
    """4.0.1 user report (4.0 GOG, Italian: Roma's dark-skinned blond player - DONYELL MALEN, face 3 'darkblond' =
    blond.py's dark skin + blond hair - drawn as a garbled block at a kick-off; internal/reports/
    malen_darkblond_match_20261025.jpg): a World 2026-27 career at ROMA (DKB_TEAM) on a test copy of SWOSTEST_BUILD
    whose DIYLeagueTournamentMatch int 3 is a NOP (the game's own int 3 at its start: harmless on a real PC, a trap
    under the harness's BPINT 3 - the league fixture's '- PARTITA -'), its SQUADRA screen (MALEN's face icon 189:
    yellow hair) and its first match played (GIOCA PARTITA): pitch frames from the line-ups to kick-off, and in the
    running match (dkb_sets) every frame of both teams' darkblond sets against the team's black-skin set (size and
    pixel positions), the three skin / hair sets' sizes, the darkblond colours, each raw set within copy_sets' room.
    Not reproduced so far (CD / GOG, 4.0 / 4.0hf / rc3, home / away, played / watched, replay): notes/darkblond-402.md"""
    import re as _re
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import shirtnum
    import blond
    src = builds()['it']
    b = os.path.join(WORK, 'builds-x', os.environ.get('DKB_NAME', 'world_darkblond').replace('world_', '') + '_' +
                     os.path.basename(os.path.dirname(src.rstrip('/'))))
    shutil.rmtree(b, ignore_errors=True)
    shutil.copytree(src, b, symlinks=True)
    p = lepatch.LEPatch(os.path.join(b, 'ITALIAN.EXE'))
    d1 = bytes(p.get(1, 0, len(p.le.obj_bytes(1))))
    m = [x.start() for x in _re.finditer(rb'\xcc\x8b\x35....\x66\x8b\x46\x02\x66\xa3....\x66\xc7\x05....\x02\x00', d1, _re.S)]
    if len(m) != 1:
        return False, f'DIYLeagueTournamentMatch int 3 not found once: {m}'
    p.put(1, m[0], b'\x90')                       # (test copy only)
    p.save(os.path.join(b, 'ITALIAN.EXE'))
    spr = shirtnum.spr_index(lepatch.LEPatch(os.path.join(b, 'ITALIAN.EXE')))
    nib = lambda data: [x >> 4 for x in data] + [x & 15 for x in data]
    errs, info = [], []
    team = os.environ.get('DKB_TEAM', 'EUROPA,ITALIA,SERIE A,ROMA').split(',')
    if 'DKB_POKE' not in os.environ:                  # (4.0.3: MALEN is bald in the data: darkblond again here;
        os.environ['DKB_POKE'] = 'DONYELL MALEN:unbald,DONYELL MALEN:darkblond,NAHUEL MOLINA:unbald'   # 4.0.5: MOLINA
                                                      # shaved light in the data (bald-looks-2627.csv) - plain here)
    if os.environ.get('DKB_STADIUM') is not None:
        os.environ['CORE'] = 'normal'             # (4.0.6 the stadium screen's breakpoints; one process per scenario)
    cars = {'SETUP.DAT': os.environ['DKB_SETUP']} if os.environ.get('DKB_SETUP') else {}   # (GOG's factory file:
    with Session(os.environ.get('DKB_NAME', 'world_darkblond'), b, cars, 'dump:2', 600, match=True) as s:   # (video
                                                                                         # speed 10 = half mode)
        s.wait()
        for t in ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27'] + team:
            if press(s, s.screen(), t, 3) is None:
                return False, f'new career: {t} not reached'
        s.send('fire dump:3')
        s.shot('career')
        if os.environ.get('DKB_EARLY'):              # (review captures: the pokes before the squad screen - its face
            r = s.result                             # icons, bald light 1910 too)
            o2 = r.read(r.base2, 0x300000)
            for it_ in filter(None, os.environ.get('DKB_POKE', '').split(',')):
                nm_, op_ = it_.rsplit(':', 1)
                for m_ in _re.finditer(_re.escape(nm_.encode()) + b'\0', o2):
                    h = m_.start() - 3
                    at_, v_ = (26, o2[h + 26] | 0x18) if op_ == 'darkblond' else \
                        (25, o2[h + 25] & 0xFC | 1 if op_ == 'bald' else o2[h + 25] | 3 if op_ == 'shaved' else o2[h + 25] & 0xF8 | 4 if op_ == 'white' else o2[h + 25] & 0xFC)
                    s.poke(r.base2 + h + at_, bytes((v_,)))
            s.send('dump:1')
        press(s, s.screen(), 'SQUADRA', 3)
        s.shot('squad')
        r = s.result
        p189 = struct.unpack('<I', r.read(r.base2 + spr + 189 * 4, 4))[0]
        icon = r.read(struct.unpack('<I', r.read(p189, 4))[0], 64) if p189 else b''
        check(15 in nib(icon[:24]), f'face icon 189 without yellow hair ({icon[:24].hex()})', errs)
        # 4.0.5: the shaved icons (blond.ICON3 / + 1: light / dark; receding: ICONBL / + 1) - world_bald: MALEN's (shaved
        # dark in the data); world_bald_looks with DKB_EARLY (MOLINA poked before the squad screen): both
        icon_cases = [('shaved', 'dark', blond.ICON3 + 1)] if os.environ.get('DKB_NAME') == 'world_bald' else []
        if os.environ.get('DKB_NAME') == 'world_bald_looks' and os.environ.get('DKB_EARLY'):
            icon_cases = [('shaved', 'light', blond.ICON3), ('shaved', 'dark', blond.ICON3 + 1)]
        if os.environ.get('DKB_NAME') == 'world_white' and os.environ.get('DKB_EARLY'):   # 4.0.6 white hair
            icon_cases = [('white', 'light', blond.ICONW), ('white', 'dark', blond.ICONW + 1)]
        for look_, skin_, ii in icon_cases:
            pb =struct.unpack('<I', r.read(r.base2 + spr + ii * 4, 4))[0]
            ib = r.read(struct.unpack('<I', r.read(pb, 4))[0], 64) if pb else b''
            lk = blond.LOOKS[look_][skin_]
            if lk['shape'] == 'art':                     # (the art's icon, dark first: shavedart.blobs)
                import shavedart
                main_, lo_, io_, _ = shavedart.blobs()
                ok_ = pb and ib == main_[io_ + (64 if skin_ == 'light' else 0):][:64]
            elif lk['shape'] == 'white':                 # (R2: the face icon 186 / 188 with the hair 3 of its top
                ps = struct.unpack('<I', r.read(r.base2 + spr + (186 if skin_ == 'light' else 188) * 4, 4))[0]
                px_ = [v for x in r.read(struct.unpack('<I', r.read(ps, 4))[0], 64) for v in (x >> 4, x & 15)]
                hair = [i for i in range(48) if px_[i] == 3]  # three rows grey 1, its top row off)
                wt = blond.WHITE_TONES[os.environ.get('WHITE_TONE', blond.WHITE_TONE)]
                top_ = [i for i in hair if i // 16 == hair[0] // 16]   # (4.0.6 MiSTer 02/11: the full silhouette,
                for i in hair:                          # the top row's two ends off when it has 3 or more; WHITE_TONES:
                    px_[i] = wt[1] if i // 16 > hair[0] // 16 + 1 else wt[0]   # the hair, its third row)
                if len(top_) >= 3:
                    px_[top_[0]] = px_[top_[-1]] = 0
                ok_ = pb and hair and ib == bytes(px_[i] << 4 | px_[i + 1] for i in range(0, 128, 2))
            elif lk['shape'] == 'oval':                    # (oval: one colour - black for skull 3, else the skin)
                want = 3 if lk['skull'] == 3 else 5
                ok_ = pb and want in nib(ib) and not (set(nib(ib)) - {0, want, 1, 2, 4, 8})
            else:
                ok_ = pb and 3 not in nib(ib[:8]) and 3 in nib(ib[8:])
            check(ok_, f'bald icon {ii} missing or not look {lk["shape"]} ({ib.hex()})', errs)
            info.append(f'bald icon {ii} built ({ib.hex()})')
        press(s, s.screen(), 'ESCI', 3)
        press(s, s.screen(), 'PARTITA', 3)
        opp = os.environ.get('DKB_OPP')               # (the reporter's case: the career club v that opponent, e.g. ROMA)
        for _ in range(40 if opp else 0):
            if opp in s.screen().texts()[5:9]:
                break
            press(s, s.screen(), '- RISULTATO -', 3)      # (the fixtures before it settled by result)
            press(s, s.screen(), 'VIS. RISULTATI', 3)
            for _ in range(6):
                scr = s.screen()
                if 'TRASFERIMENTI' in scr.texts() and scr.find('PARTITA', exact=True) is not None:
                    break
                press(s, scr, 'PROSS. PARTITA' if scr.find('PROSS. PARTITA') is not None else
                      'CONTINUA' if scr.find('CONTINUA', exact=True) is not None else 'ESCI', 3)
            press(s, s.screen(), 'PARTITA', 3)
        fx = s.screen().texts()[5:9]
        s.shot('fixture')
        vis = next((e[0] for e in s.screen().entries if e[1] == '- PARTITA -' and not e[2]), None)
        if vis is None:
            return False, f'no visible - PARTITA - on {s.screen()}'
        walk(s, vis, 3)
        for _ in range(3):                            # ('GIOCA :' cycles who plays: GIOCA PARTITA shows for the human)
            e = next((x for x in s.screen().entries if x[1] == 'GIOCA PARTITA'), None)
            if e is not None and not e[2]:
                break
            if s.screen().find('GIOCA :', exact=True) is None:
                break
            press(s, s.screen(), 'GIOCA :', 2)
        s.shot('prematch')
        for it_ in filter(None, os.environ.get('DKB_POKE', '').split(',')):   # 4.0.3 test pokes NAME:bald / unbald /
            nm_, op_ = it_.rsplit(':', 1)                                    # darkblond, in every copy of the player's
            r = s.result                                                     # record in obj2 (byte 25 bit 0 / byte
            o2 = r.read(r.base2, 0x300000)                                   # 26 bits 3-4)
            hits = [m_.start() - 3 for m_ in _re.finditer(_re.escape(nm_.encode()) + b'\0', o2)]
            for h in hits:
                at_, v_ = (26, o2[h + 26] | 0x18) if op_ == 'darkblond' else \
                    (25, o2[h + 25] & 0xFC | 1 if op_ == 'bald' else o2[h + 25] | 3 if op_ == 'shaved' else o2[h + 25] & 0xF8 | 4 if op_ == 'white' else o2[h + 25] & 0xFC)
                s.poke(r.base2 + h + at_, bytes((v_,)))
            info.append(f'{nm_} {op_} x{len(hits)}')
        if not any(x[1] == 'GIOCA PARTITA' and not x[2] for x in s.screen().entries):
            return False, f'fixture {fx}: no GIOCA PARTITA on {s.screen()}'
        sw = stadium_watch(s, 'career', spr=spr) if os.environ.get('DKB_STADIUM') is not None else None   # 4.0.6 the
        press(s, s.screen(), 'GIOCA PARTITA', 3)                                                  # stadium screen
        if sw is not None:
            errs += stadium_eval(s, sw, blond, info, {int(x) for x in os.environ['DKB_STADIUM'].split(',') if x})
        checked = False
        for k in range(10):                           # line-ups, the stadium screen, kick-off: a frame each
            r = s.send('fire dump:1.5')
            if r.outcome != 'dump':
                break
            s.shot(f'm{k}')
            if k == 6:                                # (the match running: the sets as converted for it)
                errs += dkb_sets(r, spr, blond, info)
                want = os.environ.get('DKB_EXPECT', '1')       # 4.0.3: the variants allocated this match ('a|b':
                got = vs_flags({k: v for k, v in variant_sets(r).items() if k[0] == 0})   # (team 1's) - world_bald: the opponent's own darkblond
                check(got in want.split('|'), f'variant sets {got or "-"}, expected {want}', errs)   # players take set 1
                if '|' in want:
                    info.append(f'variant sets {got}' + (' (a darkblond player in the match: set 1)' if '1' in got.split(',') else ''))
                checked = True
                if os.environ.get('DKB_SHEET'):          # 4.0.3: the converted sets side by side (review image)
                    bald_sheet(r, spr, blond, s.result.obj2(s.info['pal'], 768),
                               os.path.join(s.run, 'shots', 'sets.png'), info)
        for k in range(int(os.environ.get('DKB_MORE', '0'))):   # (review captures: more in-match frames)
            r = s.send('dump:0.6')
            if r.outcome != 'dump':
                break
            s.shot(f'p{k:02d}')
        check(checked, f'the match never ran ({r})', errs)
        info.append(f'fixture {fx}')
    return not errs, '; '.join(errs + info)


def bald_sheet(r, spr, blond, pal, path, info, tm=0):
    """Team tm's (0: team 1, the home team) match sprites as converted, frames 0..23 of the sets light (341.. / 644..),
    bald / shaved / white light (variant sets), face 1 (442.. / 745..), black (543.. / 846..), bald / shaved / white dark,
    darkblond: one row each, 6x, PNG; *_zoom.png: frames 0 / 7 / 16, hair vs the team's first light / dark variant, 24x."""
    from PIL import Image
    idx = lambda i: struct.unpack('<I', r.read(r.base2 + spr + i * 4, 4))[0]
    vs = variant_sets(r)
    raw0 = 341 + 303 * tm
    lt = [vs[(tm, f)] for f in (3, 5, 7) if (tm, f) in vs]
    dk = [vs[(tm, f)] for f in (2, 4, 6, 1) if (tm, f) in vs]
    rows = [raw0] + lt + [raw0 + 101, raw0 + 202] + dk
    raw = {}                                    # (the frames as JSON next to the PNG: offline mock-ups)
    cw, chh, z = 20, 24, 6
    img = Image.new('RGB', (24 * cw * z, len(rows) * chh * z), (40, 110, 40))
    rgb = [tuple(min(255, c * 4) for c in pal[3 * i:3 * i + 3]) for i in range(16)]
    for ri, base in enumerate(rows):
        for k in range(24):
            h = r.read(idx(base + k), 24)
            wq, nl = struct.unpack_from('<h', h, 14)[0], struct.unpack_from('<h', h, 12)[0]
            data = r.read(struct.unpack('<I', h[:4])[0], wq * 8 * nl)
            raw[f'{base}+{k}'] = [wq, nl, data.hex()]
            for y in range(min(nl, chh)):
                for x in range(min(16 * wq, cw)):
                    b_ = data[y * wq * 8 + x // 2]
                    c = b_ >> 4 if x % 2 == 0 else b_ & 15
                    if c:
                        for dy in range(z):
                            for dx in range(z):
                                img.putpixel(((k * cw + x) * z + dx, (ri * chh + y) * z + dy), rgb[c])
    img.save(path)
    zf, zz = (0, 7, 16), 24                     # x4 of the sheet's 6x: 3 frames each, light / bald light / dark / bald dark
    zimg = Image.new('RGB', (len(zf) * 2 * cw * zz, 2 * chh * zz), (40, 110, 40))
    for ri, pair in enumerate([pr for pr in ((raw0, (lt or [0])[0]), (raw0 + 202, (dk or [0])[0])) if pr[1]]):
        for zi, k in enumerate(zf):
            for pj, base in enumerate(pair):
                h = r.read(idx(base + k), 24)
                wq, nl = struct.unpack_from('<h', h, 14)[0], struct.unpack_from('<h', h, 12)[0]
                data = r.read(struct.unpack('<I', h[:4])[0], wq * 8 * nl)
                for y in range(min(nl, chh)):
                    for x in range(min(16 * wq, cw)):
                        b_ = data[y * wq * 8 + x // 2]
                        c = b_ >> 4 if x % 2 == 0 else b_ & 15
                        if c:
                            x0, y0 = ((zi * 2 + pj) * cw + x) * zz, (ri * chh + y) * zz
                            zimg.paste(rgb[c], (x0, y0, x0 + zz, y0 + zz))
    zimg.save(path[:-4] + '_zoom.png')
    json.dump({'pal': list(pal), 'frames': raw}, open(path[:-4] + '.json', 'w'))
    info.append(f'sheet {path}')


