@scenario
def white_data():
    """4.0.6 white hair in the build's data (packs/white-hair.csv, blond.WHITE): every record of a listed name in the
    team files (the original 1996-97 TEAM.008 / TEAM.080 too: FABRIZIO RAVANELLI) has byte 25 bit 2 and no bald bit;
    no other player of the TEAM.* files has bit 2 (no namesake, no stray bit)"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import blond
    d = os.path.join(builds()['it'], 'DATA')
    found, bad = {}, []
    for f in sorted(os.listdir(d)):
        if not re.fullmatch(r'TEAM\.\d{3}|TMW\d\.\d{3}|XTW\d\.\d{3}|.*\.TMD', f):
            continue
        b = open(os.path.join(d, f), 'rb').read()
        for n in blond.WHITE:                             # (every copy of a listed name: its byte 25)
            for m in re.finditer(re.escape(n) + b'\0', b):
                v = b[m.start() - 3 + blond.BALD_AT]
                found.setdefault(n.decode('latin-1'), []).append(f)
                if v & 7 != blond.WHITE_BIT:
                    bad.append(f'{f} {n.decode("latin-1")} byte 25 = {v:#x}')
        if f.startswith('TEAM.') and len(b) == 2 + 684 * struct.unpack('>H', b[:2])[0]:   # (any other player with
            for k in range((len(b) - 2) // 684):                                           # bit 2: team records)
                for j in range(16):
                    p = 2 + k * 684 + 76 + j * 38
                    nm = b[p + 3:p + 25].split(b'\0')[0]
                    if b[p + 3:p + 25].count(b'\0') and b[p + blond.BALD_AT] & blond.WHITE_BIT and nm not in blond.WHITE:
                        bad.append(f'{f} {nm.decode("latin-1")}: bit 2 not listed')
    rav = found.get('FABRIZIO RAVANELLI', [])
    check('TEAM.008' in rav and 'TEAM.080' in rav, f'RAVANELLI in {rav} (want TEAM.008 + TEAM.080)', bad)
    missing = sorted(n.decode('latin-1') for n in blond.WHITE if n.decode('latin-1') not in found)
    check(not missing, f'listed but in no team file: {missing}', bad)
    return not bad, '; '.join(bad[:8]) or f'white hair in the data: {found}'


@scenario
def white_ravanelli():
    """4.0.6 white hair from the 1996-97 data (no poke): a friendly MIDDLESBROUGH (FABRIZIO RAVANELLI, TEAM.008 byte 25
    bit 2) v ARSENAL - his white icon (blond.ICONW) built for the pre-match screen, and in the match MIDDLESBROUGH's
    white light set (flag 7) checked frame by frame (dkb_sets). Review shots: prematch.png, sets.png"""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import shirtnum
    import blond
    b = builds()['it']
    spr = shirtnum.spr_index(lepatch.LEPatch(os.path.join(b, 'ITALIAN.EXE')))
    errs, info = [], []
    os.environ['CORE'] = 'normal'               # (the stadium screen's breakpoints; one process per scenario)
    with Session('white_ravanelli', b, {}, 'dump:3', 400, match=True) as s:
        s.wait()
        for t in ('AMICHEVOLE', 'OK', 'SCEGLI SQUADRE', 'SQUADRE CLUB', 'EUROPA', 'INGHILTERRA', 'PREMIER',
                  'MIDDLESBROUGH'):
            walk(s, t, 2)
        s.send('fire dump:2')                       # home: COMPUTER -> GIOCA-ALLENA (as italy_friendly)
        walk(s, 'ARSENAL', 2)
        for _ in range(12):
            scr = s.screen()
            i = scr.find('AMICHEVOLE', exact=True)
            if scr.selected == i:
                s.send('fire dump:4')
                break
            s.send(('right' if scr.selected in (i + 1, i + 2) else 'down') + ' dump:0.5')
        s.shot('prematch')
        r = s.result
        pw = struct.unpack('<I', r.read(r.base2 + spr + blond.ICONW * 4, 4))[0]
        check(pw, f'white icon {blond.ICONW} not built on the pre-match screen', errs)
        info.append(f'white icon {blond.ICONW} ' + ('built' if pw else 'missing'))
        for _ in range(22):
            s.send('down dump:0.5')
            if s.screen().selected == 9:
                break
        sw = stadium_watch(s, 'friendly', bald=True, spr=spr)   # 4.0.6 the stadium screen (Davide, MiSTer 02/11): RAVANELLI's
        s.send('fire dump:2')                       # little player white-haired, the opponent's bald ones (poked) bald
        errs += stadium_eval(s, sw, blond, info, {7, 2, 3, 4, 5})
        r = s.send('fire:3 ' * 8 + 'dump:2')
        check(r.outcome == 'dump', f'match {r}', errs)
        if r.outcome == 'dump':
            vs = variant_sets(r)
            check(any(f == 7 for _, f in vs), f'no white light set for MIDDLESBROUGH ({vs})', errs)   # (either side:
                                                                                                     # only he has it)
            errs += dkb_sets(r, spr, blond, info)
            tm = next((t for t, f in vs if f == 7), 0)
            bald_sheet(r, spr, blond, s.result.obj2(s.info['pal'], 768), os.path.join(s.run, 'shots', 'sets.png'), info,
                       tm)
    return not errs, '; '.join(errs) or '; '.join(i for i in info if 'white' in i or 'variant' in i or 'stadium' in i)


def bald_run(name, poke, expect):
    keep = {k: os.environ.get(k) for k in ('DKB_NAME', 'DKB_POKE', 'DKB_SHEET', 'DKB_EXPECT', 'DKB_STADIUM')}
    os.environ.update(DKB_NAME=name, DKB_POKE=poke, DKB_SHEET='1', DKB_EXPECT=expect,   # (4.0.6: the stadium screen's
                      DKB_STADIUM=','.join(x for x in expect.split('|')[0].split(',') if x != '1'))   # looks too)
    try:
        return world_darkblond()
    finally:
        for k, v in keep.items():
            os.environ.pop(k, None) if v is None else os.environ.__setitem__(k, v)


@scenario
def world_titlespace():
    """4.0.1 match titles with no leading / double space (rnames rn_trim): a 1996-97 career saved by the original game
    (internal/swostest/repro/OLDCAR_orig.CAR, its European cups' titles stored as ' <name>': the empty country prefix
    before 3.x's w_pfx) loaded on SWOSTEST_BUILD and played on - every match screen's title until its first European cup
    match is free of leading, trailing and double spaces"""
    car = os.environ.get('TITLESPACE_CAR') or os.path.join(WORK, 'repro', 'OLDCAR_orig.CAR')
    if not os.path.exists(car):
        return True, f'SKIP: no {car}'
    seen = []
    with Session('world_titlespace', builds()['it'], {'W84A.CAR': car}, 'dump:2', 600) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')

        def stop(scr):
            t = scr.entries[0][1] if scr.entries else ''
            if '- PARTITA -' in scr.texts() and t and t not in seen:
                seen.append(t)
            return '- PARTITA -' in scr.texts() and any(k in t for k in ('EUROPEA', 'UEFA', 'COPPE', 'INTERTOTO'))
        ok, msg = advance(s, stop, 300)
        s.shot('euro')
    bad = [t for t in seen if t != ' '.join(t.split())]
    euro = [t for t in seen if any(k in t for k in ('EUROPEA', 'UEFA', 'COPPE', 'INTERTOTO'))]
    return ok and euro and not bad, f'{msg[:80]}; titles {seen[:8]}' + (f'; with spaces {bad}' if bad else '')


@scenario
def world_cup_prefix():
    """The continental cups' names without the empty country's prefix (careerworld w_pfx: cseg_95C18): a World
    2026-27 career at INTER (world5tm-poule) and a 1984-85 one at LIVERPOOL - VISUAL. COMPETIZ. lists 'UEFA CHAMPIONS
    LEAGUE' / the European cup with no leading space, its screen's title starts with it, the national contests keep
    their country ('ITALIA SERIE A')"""
    src = os.environ.get('W2627P_DATA') or os.path.join(MAIN, 'internal', 'world2526', 'world5tm-poule')
    if not os.path.isdir(src):
        return True, 'SKIP: private data (world5tm-poule) missing'
    order = [ln.split()[0].lower() for ln in open(src + '.txt') if ' file ' in ln]
    env = {'SEASON_PACKS': ','.join(['ddr-1988-89'] + [os.path.join(src, x) for x in order])}
    errs, info = [], []
    for tag, exe, path, cup in (
            ('w2627', os.environ.get('GPLAY_BUILD') or build('world_cup_prefix', env=env),
             ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', 'EUROPA', 'ITALIA', 'SERIE A', 'INTER'],
             'UEFA CHAMPIONS LEAGUE'),
            ('w8485', os.environ.get('W8485_BUILD') or builds()['it'],
             ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'EUROPA 1984-85', 'INGHILTERRA', 'FIRST DIVISION',
              'LIVERPOOL'], 'COPPA CAMPIONI EUROPEA')):
        with Session('cup_prefix_' + tag, exe, {}, 'dump:2', 900) as s:
            s.wait()
            for t in path:
                scr = s.screen()
                lvl = None if scr.find(t, exact=True) is not None else next(
                    (x for i, x, inv, _ in scr.entries if 11 <= i <= 20 and x and not inv and t.startswith(x + ' ')), None)
                if lvl:
                    press(s, scr, lvl, 3)
                if press(s, s.screen(), t, 3) is None:
                    return False, f'{tag}: {t} not reached'
            s.send('fire dump:3')
            walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)
            comps = [e[1] for e in s.screen().entries if e[1] and not e[2]]
            mine = [c for c in comps if cup in c]
            check(mine == [cup], f'{tag}: the cup listed as {mine} (all: {comps})', errs)
            check(any(c.startswith(('ITALIA ', 'INGHILTERRA ')) for c in comps), f'{tag}: a national contest lost its country: {comps}', errs)
            if mine:
                walk(s, s.screen().find(mine[0], exact=True), 3)
                title = next((e[1] for e in s.screen().entries if e[1] and not e[2]), '')
                check(title.startswith(cup), f'{tag}: the title of the cup screen {title!r}', errs)
                info.append(f'{tag}: listed {mine[0]!r}, title {title!r}')
    return not errs, '; '.join(errs + info)


