@scenario
def statespec_test():
    """State championships (statespec.py, STATESPEC_TEST=1 build: world 0's Brazil gets a Paranaense-shaped test state,
    id F1): a career at ATL PARANAENSE plays it in slot 1: 12 clubs in 2 blocks of 6 playing only the OTHER block
    (lp36 fixture contest, 6 days of 6): at every pause of the group stage every row has played the same number of
    matches and block A's goals for = block B's goals against (and the reverse; a round robin inside the groups
    would give A's for = A's against); points 3W + D; the season to its end (knockout 8, 4, 2; the league)"""
    b = os.environ.get('STATESPEC_BUILD') or build(f'statespec_t1' + ('_' + os.environ['SWOSTEST_TAG'] if os.environ.get('SWOSTEST_TAG') else ''),
                  env={'STATESPEC_TEST': '1'})   # (its own test build)
    errs, snaps = [], {}
    with Session('statespec_test', b, {}, 'dump:2', 1800) as s:
        s.wait()
        new_career(s, 'BRASILE', None, 'ATL PARANAENSE', 'SUDAMERICA')

        seen = {}

        orders, resort = {}, [None]
        from le import LE
        _d1 = LE(open(os.path.join(b, 'ITALIAN.EXE') if os.path.isdir(b) else b, 'rb').read()).obj_bytes(1)
        _k = _d1.find(b'STRDBGPT')
        rd_at = struct.unpack_from('<I', _d1, _k + 8)[0] if _k >= 0 else None

        def stop(scr):
            if rd_at is not None:
                v = s.result.read(s.result.base1 + rd_at, 240)
                if any(v):
                    resort[0] = v
            for rows, order in contest_orders(s.result, 0xF1, 2, 6):
                pl = {x[0] for x in rows}
                if len(pl) == 1 and pl != {0}:
                    snaps[pl.pop()] = rows
                    orders[max(snaps)] = order
            state_rounds(s.result, 0xF1, seen)
            return season_over(scr)
        ok, msg = advance(s, stop, 1700)
    check(ok, f'season: {msg}', errs)
    R = seen.get('rank')                         # (knockout: QF 4X v 1X, 3X v 2X inside each group, lib97.st_ko;
    if R and seen.get(8) and seen.get(4):        # SF the winners of the same group's two ties, st_kend)
        grp = lambda t: t // 6
        order = {g: [t for t in R if grp(t) == g] for g in (0, 1)}
        want = [frozenset((order[g][3], order[g][0])) for g in (0, 1)] + \
               [frozenset((order[g][2], order[g][1])) for g in (0, 1)]
        qf = tie_sets(*seen[8][0])
        check(sorted(map(sorted, qf)) == sorted(map(sorted, want)), f'QF {seen[8][0][0]} (ranking {R})', errs)
        for t in tie_sets(*seen[4][0]):
            check(len({grp(x) for x in t}) == 1 and all(any(x in q for q in qf) for x in t)
                  and len({next(k for k, q in enumerate(qf) if x in q) for x in t}) == 2,
                  f'SF tie {sorted(t)} (QF {[sorted(q) for q in qf]})', errs)
    else:
        check(False, f'knockout rounds seen {sorted(k for k in seen if k != "rank")}', errs)
    check(len(snaps) >= 3 and max(snaps) <= 6, f'group-stage snapshots after days {sorted(snaps)}', errs)
    for d, rows in sorted(snaps.items()):
        a, bb = rows[:6], rows[6:]
        gf = lambda rs: sum(x[4] for x in rs)
        ga = lambda rs: sum(x[5] for x in rs)
        check(gf(a) == ga(bb) and ga(a) == gf(bb), f'day {d}: A for/against {gf(a)}/{ga(a)}, B {gf(bb)}/{ga(bb)}', errs)
        check(all(x[6] == 3 * x[1] + x[2] for x in rows), f'day {d}: points 3W + D', errs)

    return not errs, '; '.join(errs + [f'{msg}; snapshots {sorted(snaps)}, last {snaps.get(max(snaps)) if snaps else None}'])

def main(argv):
    if not argv or argv[0] == 'list':
        for k, f in SCENARIOS.items():
            print(f'{k:20} {(f.__doc__ or "").strip().splitlines()[0]}')
        return 0
    if argv[0] == 'keys':                              # keys EXE_DIR CAR|- 'k1:t1 k2:t2 ...' [-shots N] [-t T]
        exe_dir, car, keys = argv[1], argv[2], argv[3]
        shots = float(argv[argv.index('-shots') + 1]) if '-shots' in argv else 3
        timeout = float(argv[argv.index('-t') + 1]) if '-t' in argv else 60
        cars = {} if car == '-' else {os.path.basename(car).upper(): car}
        name = argv[argv.index('-name') + 1] if '-name' in argv else 'keys'
        r = run_case(name, exe_dir, cars, keys, timeout, shots, '-match' in argv, '-timer' in argv)
        print(r, '->', r.run)
        return 0
    if argv[0] == 'run':
        rel_data_default()
        names = [a for a in argv[1:] if not a.startswith('-j')] or list(SCENARIOS)
        jobs = int(next((a[2:] for a in argv[1:] if a.startswith('-j')), 1) or 4)
        if jobs > 1 and len(names) > 1:
            return run_parallel(names, jobs)
        bad = 0
        for n in names:
            t = time.time()
            os.environ['SWOSTEST_SCENARIO'] = n
            try:
                del LABEL_ERRS[:]
                LABEL_STATS.update(rows=0, keyed=0, fallback=set())
                ok, msg = SCENARIOS[n]()
                if ok and LABEL_ERRS:                       # (4.0.5: a wrong competition name FAILs the scenario)
                    ok, msg = False, f'contest names: {LABEL_ERRS[:3]}; ' + msg
                if LABEL_STATS['rows']:
                    msg += f" [names: {LABEL_STATS['rows']} rows, {LABEL_STATS['keyed']} keyed" + \
                        (f", fallback {sorted(LABEL_STATS['fallback'])[:6]}" if LABEL_STATS['fallback'] else '') + ']'
                if not ok and msg.startswith('START'):      # rare stall at the main menu (cause unknown): retry once
                    print(f'RETRY {n}: {msg}', flush=True)
                    ok, msg = SCENARIOS[n]()
            except BuildOnly:
                print(f'BUILT {n} ({time.time() - t:.0f} s)', flush=True)
                continue
            except Exception as e:                         # (one scenario's exception: a FAIL, the suite goes on)
                import traceback
                at = [f'{os.path.basename(x.filename)}:{x.lineno} {x.name}' for x in traceback.extract_tb(e.__traceback__)][-3:]
                ok, msg = False, f'exception {type(e).__name__}: {e} (at {" < ".join(reversed(at))})'
            bad += not ok
            print(f'{"PASS" if ok else "FAIL"} {n} ({time.time() - t:.0f} s) {msg}', flush=True)
        return 1 if bad else 0
    print(__doc__)
    return 2


@scenario
def setup_nojoy():
    """4.0.1 joypad (opt-in, C): the UNTICKED path of the patcher leaves the factory SETUP.DAT (controls 1, the CD's copy in
    orig/setup-factory) and the game must reach the main menu and play a friendly HAMBURG - SCHALKE (HAMBURG human) with NO
    joystick (DOSBox-X joysticktype none, then auto): menu keys move the selection, the match runs. (SETUPNJ_DAT=<file> tries
    another SETUP.DAT: the calibrated one - tools/setup_calibrated.dat - needs a pad, without one its menus freeze.) On a release dir
    (FOREIGNBUY_BUILD / SWOSTEST_BUILD). Prints g_inputControls"""
    exe = foreign_exe()
    if not exe:
        return True, 'SKIP: no release SWOS dir (FOREIGNBUY_BUILD, or SWOSTEST_BUILD / W8485_BUILD with DATA/POOL05.DAT)'
    dat = os.environ.get('SETUPNJ_DAT') or os.path.join(MAIN, 'orig', 'setup-factory', 'CD.DAT')   # (the factory file; SETUPNJ_DAT: another)
    d = open(dat, 'rb').read()
    errs, info = [], []
    check(len(d) == 105, f'SETUP.DAT: {len(d)} bytes', errs)
    keep = os.environ.get('SWOSTEST_JOY')
    try:
        for joy in os.environ.get('SETUPNJ_JOY', 'none,auto').split(','):
            os.environ['SWOSTEST_JOY'] = joy
            with Session('setup_nojoy_' + joy, exe, {'SETUP.DAT': dat}, 'dump:3', 300, match=True) as s:
                r = s.wait()
                check(r.outcome == 'dump', f'{joy}: the first menu not reached: {r}', errs)
                if r.outcome != 'dump':
                    continue
                at = r.mem.find(d[92:105])
                ctl = struct.unpack_from('<H', r.mem, at - 92 + 6)[0] if at > 0 else None
                jx = struct.unpack_from('<HH', r.mem, at - 92 + 22)[0], struct.unpack_from('<H', r.mem, at - 92 + 56)[0] if at > 0 else None
                info.append(f'{joy}: g_inputControls {ctl}, g_joy1X {jx[0]}, g_joy2X {jx[1]}')
                check(at > 0, f'{joy}: the SETUP.DAT block not found in memory', errs)
                try:
                    friendly_prematch(s, 'HAMBURG', 'SCHALKE')
                except AssertionError as e:
                    check(False, f'{joy}: friendly menus: {e}', errs)
                    continue
                for _ in range(22):                     # pre-match: down the rows to VIS. PARTITA
                    s.send('down dump:0.5')
                    if s.screen().selected == 9:
                        break
                r = s.send('fire ' + 'fire:3 ' * 30 + 'dump:2')
                check(r.outcome == 'dump', f'{joy}: match: {r}', errs)
    finally:
        if keep is None:
            os.environ.pop('SWOSTEST_JOY', None)
        else:
            os.environ['SWOSTEST_JOY'] = keep
    return not errs, '; '.join(errs + info) or 'ok'

@scenario
def kbfirst():
    """4.0.6 fix A (tools/kbfirst.py, Davide 04/11): a held keyboard direction beats a stick that reads off centre. NO
    joystick (DOSBox-X joysticktype none: the port reads all ones, ReadGamePort counts g_numLoopsJoy1), the factory
    SETUP.DAT; then g_inputControls poked 3 (P1 joypad + P2 keyboard) with stick 1 read as held UP: g_numLoopsJoy1 166 =
    the count, centre x 166 (x 0), centre y 300 / min y 200 (Joy1NormalizeY clips to full up, no divide).
    DOWN held = keyboardControlFlags poked 2, what Int9KeyboardHandler holds while the key is down (the feeder's typed key
    is released before the next dump, and on release the stick takes the cursor back up at once).
    - menu: the stick takes the cursor to the top entry; DOWN held moves it down (the original: DOWN dead, player 1's
      direction wins); with SWOS++'s mark poked (kbfirst off) the cursor stays;
    - match (friendly HAMBURG - SCHALKE, HAMBURG human = player 1: its fire came in KEYBOARD ONLY; the device poked 3 on
      the pitch): pl1Direction and the team's direction 0 (UP, the stick), then DOWN held: 4, and the controlled
      player's y grows."""
    import kbfirst
    import controls
    exe = builds()['it']
    _, k = kbfirst.find(lepatch_orig())
    spp = controls.locate(lepatch_orig())['SWOSPP'][1]
    buf = k['INCTL'][1] - 6
    dat = os.path.join(MAIN, 'orig', 'setup-factory', 'CD.DAT')
    errs, info = [], []

    def stick_up(s):
        s.poke(s.result.base2 + buf + 92, struct.pack('<H', 166))               # g_numLoopsJoy1
        s.poke(s.result.base2 + buf + 30, struct.pack('<HH', 166, 300))         # centre x, y
        s.poke(s.result.base2 + buf + 38, struct.pack('<HH', 200, 0))           # min y, min x
        s.poke(s.result.base2 + buf + 6, struct.pack('<H', 3))                  # g_inputControls: P1 joypad + P2 keyboard

    def w(r, sym):
        return struct.unpack('<h', r.obj2(k[sym][1], 2))[0]

    kcf = lambda s, v: s.poke(s.result.base2 + k['KCF'][1], struct.pack('<H', v))
    keep = os.environ.get('SWOSTEST_JOY')
    os.environ['SWOSTEST_JOY'] = 'none'
    try:
        with Session('kbfirst', exe, {'SETUP.DAT': dat}, 'dump:3', 400, match=True) as s:
            r = s.wait()
            if r.outcome != 'dump':
                return False, f'the first menu not reached: {r}'
            stick_up(s)
            ys = []
            for _ in range(3):
                s.send('dump:1')
                scr = s.screen()
                ys.append((scr.selected, scr.geom[scr.selected][1] if scr.selected is not None else None))
            raw = struct.unpack('<HH', s.result.obj2(buf + 22, 4))
            info.append(f'stick 1 raw {raw}, pl1Direction {w(s.result, "PL1DIR")}; menu under the stick {ys}')
            check(raw == (166, 166) and w(s.result, 'PL1DIR') == 0 and len(set(ys)) == 1,
                  f'stick UP not set up: raw {raw}, pl1Direction {w(s.result, "PL1DIR")}, cursor {ys}', errs)
            for mark in (0xFF, 0xB8):                   # (0B8h: SWOS++ runs - kbfirst off, the original)
                s.poke(s.result.base1 + spp, bytes([mark]))
                s.send('dump:1')
                scr = s.screen()
                y0 = scr.geom[scr.selected][1]
                kcf(s, 2)
                s.send('dump:0.5')
                scr = s.screen()
                y1 = scr.geom[scr.selected][1]
                kcf(s, 0)
                s.send('dump:1')
                tag = 'SWOS++' if mark != 0xFF else 'kbfirst'
                info.append(f'{tag}: DOWN held: cursor y {y0} -> {y1} ({scr.texts()[:1]})')
                check((y1 > y0) if mark == 0xFF else (y1 == y0), f'{tag}: DOWN under a stick held UP: y {y0} -> {y1}', errs)
            s.poke(s.result.base1 + spp, b'\xff')
            s.poke(s.result.base2 + buf + 6, struct.pack('<H', 1))  # (the friendly's menus as KEYBOARD ONLY: HAMBURG
            s.send('dump:1')                                        #  is player 1's)
            for t in ('AMICHEVOLE', 'OK', 'SCEGLI SQUADRE', 'SQUADRE CLUB', 'EUROPA', 'GERMANIA', '1. LIGA', 'HAMBURG'):
                walk(s, t, 2)
            s.send('fire dump:2')                       # HAMBURG: COMPUTER -> human
            walk(s, 'SCHALKE', 2)
            for _ in range(12):                         # (friendly_prematch's way to AMICHEVOLE)
                scr = s.screen()
                if scr.selected == 55:
                    s.send('fire dump:4')
                    break
                s.send(('right' if scr.selected in (56, 57) else 'down') + ' dump:0.5')
            for _ in range(22):
                s.send('down dump:0.5')
                if s.screen().selected == 9:
                    break
            info.append(f'pre-match row 9 {s.screen().entries[9][1]!r}')
            r = s.send('fire ' + 'fire:3 ' * 30 + 'dump:2')
            if r.outcome != 'dump':
                return False, f'match: {r}'
            top, bot = k['TOP_PN'][1] - 4, k['BOT_PN'][1] - 4
            pn = [struct.unpack('<H', s.result.obj2(t + 4, 2))[0] for t in (top, bot)]
            team = top if pn[0] == 1 else bot
            check(1 in pn and 2 not in pn, f'match: playerNumber top / bottom {pn}', errs)
            stick_up(s)
            s.send('dump:0.5')

            def state(r):
                cp = struct.unpack('<I', r.obj2(team + 0x20, 4))[0]
                y = struct.unpack('<i', r.read(cp + 0x22, 4))[0] >> 16 if cp else None
                return w(r, 'PL1DIR'), struct.unpack('<h', r.obj2(team + 0x2E, 2))[0], y

            a = state(s.result)
            kcf(s, 2)                                   # DOWN held
            seq = []
            for _ in range(8):                          # (no controlled player while the ball is out - a corner, a
                s.send('dump:0.5')                      #  throw-in: sampled until two readings in play show the move)
                seq.append(state(s.result))
                ys = [x[2] for x in seq[-2:]]
                if len(ys) == 2 and None not in ys and ys[1] > ys[0]:
                    break
            kcf(s, 0)
            info.append(f'match (playerNumber {pn}): stick UP pl1Direction / team direction / player y {a}; DOWN held '
                        f'{seq}')
            check(a[:2] == (0, 0), f'match: the stick UP not read: {a}', errs)
            check(all(x[:2] == (4, 4) for x in seq), f'match: DOWN held: {seq}', errs)
            ys = [x[2] for x in seq[-2:]]
            check(len(ys) == 2 and None not in ys and ys[1] > ys[0], f'match: the controlled player did not go down: {seq}',
                  errs)
            s.shot('match_down')
    finally:
        if keep is None:
            os.environ.pop('SWOSTEST_JOY', None)
        else:
            os.environ['SWOSTEST_JOY'] = keep
    return not errs, '; '.join(errs + info) or 'ok'

@scenario
def world_kits_always():
    """4.0.5 SELEZIONA MAGLIE's SOLO PARTITA / SEMPRE (kitcolors km_keep): a World 2026-27 career at ATALANTA, the
    first match's pre-match screen > MAGLIE AUTO > the career club's first shirt colour changed > OK. SOLO PARTITA
    (the default): careerTeam's kits unchanged. SEMPRE: careerTeam (careerFileBuffer + 0DB80h + 1Ah) holds the new
    kits; saved, then played from the save to the season end (world8485: its matches, the season end's kit refresh
    careerworld w_kits) - the kits stay (release recipe, SWOSTEST_BUILD)"""
    import careerworld
    import lepatch
    exe = builds()['it']
    kits = careerworld.sites(lepatch.LEPatch(os.path.join(MAIN, 'orig', 'ITALIAN.EXE')))['cfb'] + 0xDB80 + 0x1A
    path = ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', 'EUROPA', 'ITALIA', 'SERIE A', 'ATALANTA']
    errs, info, car = [], [], None

    def leave(s):
        for _ in range(8):
            if 'PROSS. PARTITA' in s.screen().texts():
                break
            press(s, s.screen(), 'CONTINUA', 3) or press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')

    for mode in ('match', 'always'):
        with Session(f'world_kits_always_{mode}', exe, {}, 'dump:2', 600) as s:
            s.wait()
            if not pick_career(s, path):
                return False, 'new career: ' + str(s.screen().texts()[:8])
            s.send('fire dump:3')
            leave(s)
            k0 = s.result.obj2(kits, 10)
            press(s, s.screen(), 'PARTITA', 3)
            for _ in range(4):                          # (the competition screen: fire -> the pre-match screen)
                scr = s.screen()
                if len(scr.entries) > 68 and scr.entries[68][1] in ('MAGLIE AUTO', 'MAGLIE FISSE'):
                    break
                s.send('fire dump:2')
            scr = s.screen()
            if not (len(scr.entries) > 68 and scr.entries[68][1] == 'MAGLIE AUTO'):
                return False, f'{mode}: no pre-match screen: {scr.texts()[:10]}'
            scr = walk(s, 68, 3)
            if scr.entries[1][1] != 'ATALANTA':
                scr = walk(s, 1, 2)
            check(scr.entries[1][1] == 'ATALANTA' and len(scr.entries) > 23 and not scr.entries[23][2]
                  and scr.entries[23][1] == 'SOLO PARTITA', f'{mode}: SELEZIONA MAGLIE {scr.texts()[:6]} '
                  f'entry 23 {scr.entries[23] if len(scr.entries) > 23 else None}', errs)
            opp = walk(s, 1, 2)                         # (the opponent: no toggle)
            check(opp.entries[1][1] != 'ATALANTA' and opp.entries[23][2], f'{mode}: opponent {opp.entries[1][1]!r} '
                  f'entry 23 {opp.entries[23]}', errs)
            scr = walk(s, 1, 2)
            if mode == 'always':
                scr = walk(s, 23, 2)
                check(scr.entries[23][1] == 'SEMPRE', f'toggle: {scr.entries[23]}', errs)
            s.shot('kits_' + mode)
            walk(s, 5, 2)                               # (the first kit's shirt, then the shirt type beside it:
            s.send('right dump:1')                      #  the game's editor - ATALANTA's stripes become plain)
            s.send('fire dump:1')
            s.shot('edited_' + mode)
            walk(s, 21, 3)                              # OK
            k1 = s.result.obj2(kits, 10)
            info.append(f'{mode}: careerTeam kits {k0.hex(" ")} -> {k1.hex(" ")}')
            check((k1 != k0) if mode == 'always' else (k1 == k0), f'{mode}: kits {k0.hex(" ")} -> {k1.hex(" ")}', errs)
            if mode == 'always':
                kept = k1
                for _ in range(6):                      # pre-match ESCI -> the career menu -> main menu: save
                    if s.screen().find('SALVA CARRIERA', exact=True) is not None:
                        break
                    press(s, s.screen(), 'ESCI', 3) or press(s, s.screen(), 'ABBANDONA', 3)
                walk(s, 'SALVA CARRIERA', 2)
                s.send(name_entry('WKAL') + ' dump:3')
                car = os.path.join(s.run, 'SWOS', 'WKAL.CAR')
                check(os.path.exists(car) and open(car, 'rb').read()[56192 + 0x1A:56192 + 0x24] == kept,
                      f'save: {car} kits', errs)
    if car and os.path.exists(car) and not errs:
        keys = ('W8485_BUILD', 'W8485_FROM', 'W8485_NOSACK', 'W8485_HEX', 'SWOSTEST_SCENARIO')
        keep = {k: os.environ.get(k) for k in keys}
        try:
            os.environ.update(W8485_BUILD=exe, W8485_FROM=car, W8485_NOSACK='1', W8485_HEX=f'{kits:x}:10',
                              SWOSTEST_SCENARIO='world_kits_always_season')
            ok, msg = world8485()
            dumps = [bytes.fromhex(ln.split()[2]) for ln in open(os.path.join(RUNS, w84_tag() + '_2', 'session.log'),
                                                                     errors='replace')
                     if ln.startswith('HEX ') and len(ln.split()) == 3 and int(ln.split()[1], 16) == kits]
            check('season 2:' in msg and 'steps' in msg, f'season: {msg[:200]}', errs)
            check(dumps and set(dumps) == {kept}, f'season: kits {[x.hex(" ") for x in dumps]} (kept {kept.hex(" ")})',
                  errs)
            info.append(f'reloaded + season end: {[x.hex(" ") for x in dumps]}')
        finally:
            for k, v in keep.items():
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
    return not errs, '; '.join(errs + info)


@scenario
def world_kitfix():
    """4.0.5 the career club's kits after a data update (kitfix.py, careerworld w_kits at the season end): Francesco's
    ISCHIA save (KITFIX_CAR, a 4.0 kit 0 6 6 1 6 / 0 1 1 6 1 in its careerTeam) played on from its load to the season
    end on SWOSTEST_BUILD (release recipe, data world5tm-403c4: 3 5 9 5 5 / 0 1 1 1 1): careerTeam takes the current
    kits; the same save with the home kit edited by hand (as SELECT KITS would) keeps it"""
    import careerworld
    import lepatch
    car = os.environ.get('KITFIX_CAR') or os.path.join(MAIN, 'internal', 'reports', 'ischia', 'ISCHIA_francesco_20261028.CAR')
    exe = builds()['it']
    if not os.path.exists(os.path.join(exe, 'DATA', 'KITFIX.DAT')):
        return False, f'no DATA\\KITFIX.DAT in {exe}'
    kits = careerworld.sites(lepatch.LEPatch(os.path.join(MAIN, 'orig', 'ITALIAN.EXE')))['cfb'] + 0xDB80 + 0x1A
    d = open(car, 'rb').read()
    old = d[56192 + 0x1A:56192 + 0x1A + 10]
    want = next((r[29:39] for r in (open(os.path.join(exe, 'DATA', 'KITFIX.DAT'), 'rb').read()[i:i + 39]
                                    for i in range(0, os.path.getsize(os.path.join(exe, 'DATA', 'KITFIX.DAT')), 39))
                 if r[:2] == d[56192:56194] and r[19:29] == old), None)
    if want is None:
        return False, f'the save\'s kits {old.hex(" ")} are no shipped pair of KITFIX.DAT'
    edited = bytearray(d)
    edited[56192 + 0x1A:56192 + 0x1A + 5] = bytes([0, 2, 2, 2, 2])
    ed = os.path.join(RUNS, 'kitfix_edited.CAR')
    os.makedirs(RUNS, exist_ok=True)
    open(ed, 'wb').write(edited)
    errs, info = [], []
    keys = ('W8485_BUILD', 'W8485_FROM', 'W8485_NOSACK', 'W8485_HEX', 'SWOSTEST_SCENARIO')
    keep = {k: os.environ.get(k) for k in keys}
    try:
        for tag, src, expect in (('as_saved', car, want), ('edited', ed, bytes(edited[56192 + 0x1A:56192 + 0x1A + 10]))):
            os.environ.update(W8485_BUILD=exe, W8485_FROM=src, W8485_NOSACK='1', W8485_HEX=f'{kits:x}:10',
                              SWOSTEST_SCENARIO=f'world_kitfix_{tag}')   # (a run dir per case)
            ok, msg = world8485()
            dumps = [bytes.fromhex(ln.split()[2]) for ln in open(os.path.join(RUNS, w84_tag() + '_2', 'session.log'),
                                                                     errors='replace')
                     if ln.startswith('HEX ') and len(ln.split()) == 3 and int(ln.split()[1], 16) == kits]
            check('season 2:' in msg and 'steps' in msg, f'{tag}: {msg[:200]}', errs)   # (to the season end; the
            if not ok:                                  # save's own world checks - checkw1 on a save of older data -
                info.append(f'{tag}: {msg[-60:]}')      # are not this scenario's)
            check(dumps and dumps[-1] == expect, f'{tag}: kits {[x.hex(" ") for x in dumps]} (want {expect.hex(" ")})',
                  errs)
            info.append(f'{tag}: {" -> ".join(x.hex(" ") for x in dumps[:1] + dumps[-1:])}')
    finally:
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    return not errs, '; '.join(errs + info)

def job_offer_sites(exe_dir):
    """obj2 offsets of numNewJobOffers and newJobOffers (AddJobOffer: cmp word [numNewJobOffers], 5; jz; ...
    mov [A0], offset newJobOffers) in the original exe of the build's language (obj2 data does not move)."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import sacups
    p = lepatch.LEPatch(os.path.join(MAIN, 'orig', 'ITALIAN.EXE'))
    d1 = p.le.obj_bytes(1)
    a0 = sacups.regs(d1)['A0']
    for m in re.finditer(rb'\x66\x83\x3d(....)\x05\x0f\x84....\x66\xa1\1\x66\xa3....\x66\x0b\xc0\x74.\xc7\x05' +
                         re.escape(struct.pack('<I', a0)) + rb'(....)', d1, re.S):
        return p.target(1, m.start() + 3)[1], p.target(1, m.start(2))[1]
    raise AssertionError('AddJobOffer')


@scenario
def world_job_squad():
    """4.0.5 the job letter's VIS. SQUADRA (xbrowse vs_*: viewSquadMenu in ViewFutureTeam's view): a World 2026-27 career
    at ATALANTA, a job offer of KUPS KUOPIO forced (newJobOffers / numNewJobOffers poked as AddJobOffer writes them), OFFERTE
    LAVORO > the letter > VIS. SQUADRA: page 1 = the record's 16, a PAG. SUCC. button left of CONTINUA, page 2 = the club's
    extras 17.. (its XTW5 block); CONTINUA; then ACCETTA: the career club is KUPS KUOPIO with the extras in careerTeam's
    slots 16.. (xtra.py's load on the new job) - the full squad (release recipe, SWOSTEST_BUILD)"""
    import careerworld
    import lepatch
    exe = builds()['it']
    club = os.environ.get('JOB_CLUB', 'KUPS KUOPIO')
    blk = xtra_club_block(exe, club)
    if not blk:
        return False, f'{club}: no XTRA block in {exe}'
    word, extras = blk
    extras = [x for x in extras if x]
    num, offers = job_offer_sites(exe)
    ct = careerworld.sites(lepatch.LEPatch(os.path.join(MAIN, 'orig', 'ITALIAN.EXE')))['cfb'] + 0xDB80
    path = ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', 'EUROPA', 'ITALIA', 'SERIE A', 'ATALANTA']
    errs, info = [], []
    vis = lambda scr: [e[1] for e in scr.entries if e[1] and not e[2]]

    def leave(s):
        for _ in range(8):
            if 'PROSS. PARTITA' in s.screen().texts():
                break
            press(s, s.screen(), 'CONTINUA', 3) or press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')

    with Session('world_job_squad', exe, {}, 'dump:2', 600) as s:
        s.wait()
        if not pick_career(s, path):
            return False, 'new career: ' + str(s.screen().texts()[:8])
        s.send('fire dump:3')
        leave(s)
        b2 = s.result.base2
        s.poke(b2 + offers, struct.pack('<H', word) + b'\xff' + bytes(17) + struct.pack('<I', 500000) + bytes(2))
        s.poke(b2 + num, struct.pack('<H', 1))
        walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)    # (back: ContestMenuOnReturn -> CheckJobOffers)
        press(s, s.screen(), 'ESCI', 3)
        leave(s)
        i = next((e[0] for e in s.screen().entries if e[1] and ('LAVORO' in e[1]) and not e[2] and not e[3]), None)
        if i is None:
            return False, f'no job offer entry: {s.screen().texts()[:20]}'
        walk(s, i, 3)
        s.log.append(f'[offers] {s.screen()}')
        s.shot('offers')
        letter = s.screen()
        vb = next((e[0] for e in letter.entries if e[1] and 'SQUADRA' in e[1] and not e[2] and not e[3]), None)
        if vb is None:                                  # (the offers list: the offer's row first)
            rows = [j for j, g in enumerate(letter.geom) if g[0] == 8 and g[2] == 304 and not letter.entries[j][2]
                    and not letter.entries[j][3]]
            if rows:
                walk(s, rows[0], 3)
                letter = s.screen()
                s.log.append(f'[letter] {letter}')
                vb = next((e[0] for e in letter.entries if e[1] and 'SQUADRA' in e[1] and not e[2] and not e[3]), None)
        s.shot('letter')
        if vb is None:
            return False, f'no letter: {letter.texts()[:24]}'
        press(s, letter, 'VIS. SQUADRA', 3)
        sq = s.screen()
        s.log.append(f'[squad] {sq}')
        s.shot('page1')
        btn = sq.entries[2]                             # (the rows are drawn, not menu texts: the pictures page1 / page2)
        check(club in sq.texts() and not btn[2] and btn[1] == 'PAG. SUCC.', f'page 1: button {btn}, {sq.texts()[:6]}', errs)
        press(s, sq, 'PAG. SUCC.', 2)
        sq2 = s.screen()
        s.shot('page2')
        check(sq2.entries[2][1] == 'PAG. PREC.', f'page 2: button {sq2.entries[2]}', errs)
        info.append(f'letter VIS. SQUADRA: PAG. SUCC. -> page 2 ({len(extras)} extras: {extras[0]} .. {extras[-1]})')
        press(s, sq2, 'PAG. PREC.', 2)                  # (back to page 1)
        check(s.screen().entries[2][1] == 'PAG. SUCC.', f'back to page 1: {s.screen().entries[2]}', errs)
        press(s, s.screen(), 'CONTINUA', 3)             # -> the letter
        back = s.screen()
        if back.find('CONSIDERA', exact=True) is None:
            return False, '; '.join(errs + [f'no CONSIDERA on the letter: {back.texts()[:14]}'])
        press(s, back, 'CONSIDERA', 3)                  # (mid-season: ACCETTA only at the season end)
        for _ in range(6):
            s.log.append(f'[after] {s.screen()}')
            if 'TRASFERIMENTI' in s.screen().texts():
                break
            press(s, s.screen(), 'CONTINUA', 3) or press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')
        for _ in range(6):                              # career menu -> ESCI -> main menu: save
            s.log.append(f'[save] {s.screen()}')
            if s.screen().find('SALVA CARRIERA', exact=True) is not None:
                break
            press(s, s.screen(), 'ESCI', 3) or press(s, s.screen(), 'ABBANDONA', 3)
        walk(s, 'SALVA CARRIERA', 2)
        s.send(name_entry('WJOB') + ' dump:3')
        car = os.path.join(s.run, 'SWOS', 'WJOB.CAR')
    if not os.path.exists(car):
        return False, '; '.join(errs + ['no WJOB.CAR'])
    keys = ('W8485_BUILD', 'W8485_FROM', 'W8485_NOSACK', 'W8485_SAVE_END', 'SWOSTEST_SCENARIO')
    keep = {k: os.environ.get(k) for k in keys}
    try:                                                # the season to its end (saved before CONTINUA)
        os.environ.update(W8485_BUILD=exe, W8485_FROM=car, W8485_NOSACK='1', W8485_SAVE_END='WJOE',
                          SWOSTEST_SCENARIO='world_job_squad_season')
        ok, msg = world8485()
    finally:
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    if 'saved ' not in msg:
        return False, '; '.join(errs + [f'season: {msg[:200]}'])
    end = msg.split('saved ', 1)[1].strip()
    with Session('world_job_squad_next', exe, {'WJOE.CAR': end}, 'dump:2', 600) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        if press(s, s.screen(), 'OFFERTE LAVORO', 3) is None:
            return False, '; '.join(errs + [f'season end: no OFFERTE LAVORO {s.screen().texts()[:14]}'])
        scr = s.screen()
        s.log.append(f'[end offers] {scr}')
        row = next((e[0] for e in scr.entries if e[1] and club in e[1] and not e[2] and not e[3]), None)
        if row is None:
            return False, '; '.join(errs + [f'season end: no offer of {club}: {scr.texts()[:10]}'])
        rows = [j for j, g in enumerate(scr.geom) if g[0] == 8 and g[2] == 304 and not scr.entries[j][2]
                and not scr.entries[j][3]]              # (the selectable full-width rows: the one at the text's height)
        pick = next((j for j in rows if abs(scr.geom[j][1] - scr.geom[row][1]) <= 4), rows[-1] if rows else row)
        s.log.append(f'[end rows] {[(j, scr.geom[j]) for j in rows]} text {row} {scr.geom[row]} -> {pick}')
        walk(s, pick, 3)
        s.log.append(f'[end letter] {s.screen()}')
        if s.screen().find('ACCETTA', exact=True) is None:
            return False, '; '.join(errs + [f'season end: not the letter of {club}: {s.screen().texts()[:6]}'])
        if press(s, s.screen(), 'VIS. SQUADRA', 3) is not None:    # (the letter at the season end: the same pages)
            check(s.screen().entries[2][1] == 'PAG. SUCC.' and not s.screen().entries[2][2],
                  f'season end letter: button {s.screen().entries[2]}', errs)
            s.shot('end_page1')
            press(s, s.screen(), 'CONTINUA', 3)
        if press(s, s.screen(), 'ACCETTA', 3) is None:
            return False, '; '.join(errs + [f'season end: no ACCETTA {s.screen().texts()[:14]}'])
        nxt = next_season_save(s, 'WJON')               # CONTINUA CARRIERA: the new job
    if not nxt.endswith('.CAR'):
        return False, '; '.join(errs + [f'next season: {nxt}'])
    d = open(nxt, 'rb').read()[56192:56192 + 684 + 38 * 16]   # (the .CAR's careerTeam + its 16 more slots)
    name = d[5:22].split(b'\0')[0].decode('latin1')
    got = [x for x in (d[684 + 38 * i + 3:684 + 38 * i + 26].split(b'\0')[0].decode('latin1') for i in range(16)) if x]
    check(name == club and all(x in got for x in extras), f'next season: careerTeam {name!r}, slots 16.. {got}', errs)
    info.append(f'next season: {name} with {sum(x in got for x in extras)}/{len(extras)} extras in slots 16.. ({len(got)} named)')
    return not errs, '; '.join(errs + info)


def home_market_sites():
    """obj2 offsets of numHomeMarketPlayers / homeMarketPlayers (AddPlayerToCareerContest) in the original IT exe."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import sacups
    from le import LE
    d1 = LE(open(os.path.join(ROOT, 'orig', 'ITALIAN.EXE'), 'rb').read()).obj_bytes(1)
    a1 = sacups.regs(d1)['A1']
    m = re.search(rb'\x66\x83\x3d(....)\x19\x74.\xc7\x05' + re.escape(struct.pack('<I', a1)) + rb'(....)', d1, re.S)
    return struct.unpack('<I', m.group(1))[0], struct.unpack('<I', m.group(2))[0]


def xtra_buy_first(s):
    """Career menu -> TRASFERIMENTI > ACQUISTA GIOCATORE > VISUAL. MERCATO NAZIONALE > ELENCA, the first row, the offer
    raised until accepted (xtra_market's way); back to the career menu. Returns the answer screen's texts."""
    walk(s, 'TRASFERIMENTI', 3)
    walk(s, 2, 3)
    scr = s.screen()
    walk(s, next(e[0] for e in scr.entries if e[1] and 'VISUAL. MERCATO NAZIONALE' in e[1]), 3)
    walk(s, 7, 3)
    scr = s.screen()
    s.shot('list')
    row = next(e[0] for e in scr.entries if 10 <= e[0] < 20 and not e[2])
    for k in (scr.path(row) or []):
        s.send(k + ' dump:0.5')
    s.send('fire dump:4')
    raise_n = 10
    for _ in range(10):
        scr = s.screen()
        tx = scr.texts()
        if "FAI UN'OFFERTA" in tx:
            s.send(' '.join(['fire+right'] * raise_n) + ' dump:1')
            walk(s, s.screen().find('CONFERMA OFFERTA', exact=True), 3)
            raise_n = 0
            continue
        more = next((re.search(r'AUMENTI DI L([\d,]+)M', x) for x in tx if 'AUMENTI DI' in x), None)
        if "OFFRI DI PIU'" in tx:
            raise_n = (int(more.group(1).replace(',', '')) // 100000 + 1) if more else 5
            walk(s, scr.find("OFFRI DI PIU'", exact=True), 3)
            continue
        break
    tx = s.screen().texts()
    for _ in range(8):
        if 'PROSS. PARTITA' in s.screen().texts():
            break
        press(s, s.screen(), 'CONTINUA', 3) or press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')
    return tx


def xleft_lists(s, exe):
    """[(team, index)] of the build's 'XTRA players who left' lists in memory: xtra's XS (+ xleft's XL when built)."""
    import lepatch
    p = lepatch.LEPatch(os.path.join(exe, 'ITALIAN.EXE'))
    r = s.result
    xs = r.read(r.base1 + xtra_xsold(p), 2 + 3 * 128)
    out = [struct.unpack_from('<HB', xs, 2 + 3 * i) for i in range(min(struct.unpack('<H', xs[:2])[0], 128))]
    xl = b''
    if len(p.le.objs) > 2:
        d3 = p.le.obj_bytes(3)
        k = d3.find(b'XLFT')
        if k >= 0 and r.base3 is not None:
            xl = r.read(r.base3 + k + 4, 5 + 3 * 32)
            if xl[0]:
                out += [struct.unpack_from('<HB', xl, 5 + 3 * i) for i in range(min(struct.unpack('<H', xl[1:3])[0], 32))]
    return out, xs[:2 + 3 * 4].hex() + ('/' + xl[:5 + 3 * 2].hex() if xl else '/no XL')


def bteam_vars(exe):
    """bteam in a built exe: the obj3 mailbox (BTRQ, BTEAM_FORCE builds) and BU list (BTBU) offsets, careerTeam & co
    (xtra.sites), the wage table, the change list (xleft.sites), the world's BAGE rows {parent word: (B word, ages)}."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import lepatch
    import sacups
    import xleft
    import xtra
    p = lepatch.LEPatch(os.path.join(exe, 'ITALIAN.EXE'))
    d3 = bytes(p.get(3, 0, 0x1000 * p.le.obj(3).npages))
    _, cnp, ct, cmp, sel = xtra.sites(p)
    orig = lepatch.LEPatch(os.path.join(ROOT, 'orig', UI_ORIG))
    xtra.LABELS.setdefault('SITES', xtra.sites(orig))     # (xleft.sites reads it: set by xtra.patch in a build)
    xs = xleft.sites(orig, sacups.regs(orig.le.obj_bytes(1)))
    d = open(os.path.join(exe, 'DATA', 'BAGE.005'), 'rb').read()
    rows, o = {}, 4
    for _ in range(d[3]):
        bw, pw, ri, k = struct.unpack_from('<HHBB', d, o)
        rows[pw] = (bw, list(d[o + 6:o + 6 + k]), ri)
        o += 6 + k
    mb = d3.find(b'BTRQ')
    return {'mb': (3, mb + 4) if mb >= 0 else None, 'bu': (3, d3.index(b'BTBU') + 4), 'cnp': cnp, 'ct': ct, 'cmp': cmp,
            'sel': sel, 'wage': xtra.wage_table(p), 'nfm2': xs['nfm2'], 'cfmp': xs['cfmp'], 'rows': rows}


def bteam_names(exe, word):
    """The B team's player names: record places 1..16 (TMW5.nnn) + its XTRA block (XTW5.nnn)."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import xtra
    f, o = word & 0xFF, word >> 8
    d = open(os.path.join(exe, 'DATA', 'TMW5.%03d' % f), 'rb').read()
    r = d[2 + o * 684:2 + (o + 1) * 684]
    out = [r[76 + i * 38 + 3:76 + i * 38 + 25].split(b'\0')[0].decode('latin1') for i in range(16)]
    xf = os.path.join(exe, 'DATA', 'XTW5.%03d' % f)
    if os.path.exists(xf):
        out += [x[3:25].split(b'\0')[0].decode('latin1') for x in xtra.read(open(xf, 'rb').read()).get(o, [])]
    return out


def bteam_state(s, v):
    """(careerNumPlayers, [names of the squad order], {slot: (name, byte 26, wage)}, BU entries [(kind, idx, word)])"""
    r = s.result
    n = struct.unpack('<H', bytes(r.obj2(v['cnp'], 2)))[0]
    order = list(r.obj2(v['cmp'], n))
    slots = {}
    for k in order:
        b = bytes(r.obj2(v['ct'] + 76 + k * 38, 38))
        slots[k] = (b[3:25].split(b'\0')[0].decode('latin1'), b[0x1A], struct.unpack('<I', bytes(r.obj2(v['wage'] + 4 * k, 4)))[0])
    bu = r.read(r.lin(v['bu']), 84)
    ents = [(bu[4 + 8 * i], bu[5 + 8 * i], struct.unpack_from('<H', bu, 6 + 8 * i)[0]) for i in range(min(bu[0], 10))]
    return n, [slots[k][0] for k in order], slots, ents


@scenario
def bteam_rt():
    """4.0.6 B-team call-ups, M2 runtime (BTEAM_FORCE release-recipe build, SWOSTEST_BUILD): a World 2026-27 career at
    ATALANTA (B team ATALANTA U23); at the first squad screen the harness's mailbox calls up 4 for one match (record
    places 1-3 + an XTRA place), a 5th (refused: max 4), one again (already called), 2 for the season (a record
    place: its generated replacement in the change list; an XTRA place), an index past the squad (no such player).
    PASS: the codes; each called-up player in careerTeam + the squad order with the 'generated' bit, wage 0 for one
    match, > 0 for the season; after the match played the one-match ones gone (squad = before + the season ones), BU =
    the 2 season entries; the same after SALVA CARRIERA + CARICA (BU saved in the engine block)."""
    exe = builds()['it']
    v = bteam_vars(exe)
    if v['mb'] is None:
        return False, f'{exe}: no BTRQ mailbox (not a BTEAM_FORCE build)'
    b = nop_league_int3('bteam_rt', exe)
    t1, t2, g1 = cc_sites(b)[1:4]
    me = os.environ.get('BT_CLUB', 'ATALANTA')
    path = ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', 'EUROPA', 'ITALIA', 'SERIE A', me]
    errs, info = [], []

    def leave(s):
        for _ in range(8):
            if 'PROSS. PARTITA' in s.screen().texts():
                break
            press(s, s.screen(), 'CONTINUA', 3) or press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')

    def to_squad(s):
        for _ in range(10):
            texts = s.screen().texts()
            if 'MOD. TATTICA' in texts:
                return True
            if 'TRASFERIMENTI' in texts and 'PARTITA' in texts:
                press(s, s.screen(), 'PARTITA', 2) or s.send('fire dump:2')
            elif '- PARTITA -' in texts:
                press(s, s.screen(), '- PARTITA -', 2) or s.send('fire dump:2')
            else:
                s.send('fire dump:2')
        return False

    with Session('bteam_rt', b, {}, 'dump:2', 1500, match=True) as s:
        s.wait()
        if not pick_career(s, path):
            return False, 'new career: ' + str(s.screen().texts()[:8])
        s.send('fire dump:3')
        leave(s)
        r = s.result
        selw = struct.unpack('<H', bytes(r.obj2(v['sel'], 2)))[0]
        if selw not in v['rows']:
            return False, f'{me} ({selw:#x}): no B team in BAGE {[hex(k) for k in v["rows"]]}'
        bw, ages, ri = v['rows'][selw]
        bn = bteam_names(exe, bw)
        n0, order0, _, _ = bteam_state(s, v)
        info.append(f'{me} {selw:#x}: B {bw:#x} ({len(bn)} players, rules {ri}), squad {n0}')
        x = 16 if len(bn) > 16 else 3
        reqs = [(1, 0), (1, 1), (1, x), (1, 2), (1, 4), (1, 0), (2, 5), (2, x + 1 if x == 16 else 6)]
        want, inbu, n, k1 = [], set(), n0, 0             # (bt_can's order: index, already called, squad full, kind)
        for k, i in reqs:
            c = 8 if i >= len(ages) or not bn[i] else 6 if i in inbu else 4 if n >= 30 else 1 if k == 1 and k1 >= 4 else 0
            want.append(c)
            if c == 0:
                inbu.add(i)
                n += 1
                k1 += k == 1
        s.poke(r.lin(v['mb']) + 1, b''.join(bytes(q) for q in reqs) + b'\xff' * 8)
        s.poke(r.lin(v['mb']), bytes([len(reqs)]))
        if not to_squad(s):
            return False, f'no squad screen: {s.screen().texts()[:12]}'
        r = s.result
        mb = r.read(r.lin(v['mb']), 26)
        res = list(mb[17:25])
        check(mb[0] == 0 and mb[25] == 1, f'mailbox not done once: count {mb[0]}, runs {mb[25]}', errs)
        check(res == want, f'codes {res} (want {want})', errs)
        n1, order1, slots1, bu1 = bteam_state(s, v)
        s.shot('squad_called')
        called = [bn[i] for (k, i), c in zip(reqs, res) if c == 0]
        info.append(f'codes {res}; squad {n0} -> {n1}; BU {bu1}')
        check(n1 == n0 + len(called), f'squad {n0} -> {n1}, want +{len(called)}', errs)
        for (k, i), c in zip(reqs, res):
            if c:
                continue
            sl = [q for q, (nm, f, w) in slots1.items() if nm == bn[i]]
            if not sl:
                errs.append(f'{bn[i]} ({k}, {i}) not in the squad order')
                continue
            nm, f, w = slots1[sl[0]]
            check(f & 2, f'{nm}: byte 26 {f:#x} without the generated bit', errs)
            check((w == 0) if k == 1 else (w > 0), f'{nm} (kind {k}): wage {w}', errs)
        nf = struct.unpack('<H', bytes(r.obj2(v['nfm2'], 2)))[0]
        cl = [struct.unpack_from('<HB', bytes(r.obj2(v['cfmp'] + 42 * j, 3))) for j in range(nf)]
        check((bw, 5) in cl, f'change list without ({bw:#x}, 5): {[(hex(a), b_) for a, b_ in cl[-4:]]}', errs)
        info.append(f'change list {nf}: last {[(hex(a), b_) for a, b_ in cl[-3:]]}')
        try:
            cc_match(s, t1, t2, g1, 'bt1')
        except AssertionError as e:
            errs.append(str(e))
            return False, '; '.join(errs + info)
        for _ in range(12):                             # to the career menu itself (the calendar advance: after the
            t = s.screen().texts()                      # day's results screens)
            s.log.append('[bt] after: ' + ' | '.join(t)[:200])
            if 'TRASFERIMENTI' in t and 'PARTITA' in t:
                break
            press(s, s.screen(), 'CONTINUA', 3) or press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')
        n2, order2, slots2, bu2 = bteam_state(s, v)
        season = [bn[i] for (k, i), c in zip(reqs, res) if k == 2 and c == 0]
        gone = [bn[i] for (k, i), c in zip(reqs, res) if k == 1 and c == 0]
        info.append(f'after the match: squad {n2}, BU {bu2}')
        check(n2 == n0 + len(season), f'after the match: squad {n2}, want {n0 + len(season)}', errs)
        check(not any(g in order2 for g in gone), f'one-match players still in: {[g for g in gone if g in order2]}', errs)
        check(all(g in order2 for g in season), f'season players gone: {[g for g in season if g not in order2]}', errs)
        check(len(bu2) == len(season) and all(e[0] & 3 == 2 for e in bu2), f'BU after the match {bu2} (before {bu1})', errs)
        for _ in range(6):                              # career menu -> ESCI -> main menu: save, load
            if s.screen().find('SALVA CARRIERA', exact=True) is not None:
                break
            press(s, s.screen(), 'ESCI', 3) or press(s, s.screen(), 'ABBANDONA', 3)
        walk(s, 'SALVA CARRIERA', 2)
        s.send(name_entry('BTRT') + ' dump:3')
        car = os.path.join(s.run, 'SWOS', 'BTRT.CAR')
        bteam_rt.car = (car, bw, [bn[i] for (k, i), c in zip(reqs, res) if k == 2 and c == 0])
    if not os.path.exists(car):
        return False, '; '.join(errs + info + ['no BTRT.CAR'])
    with Session('bteam_rt_load', b, {'BTRT.CAR': car}, 'dump:2', 600) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        leave(s)
        n3, order3, _, bu3 = bteam_state(s, v)
        check((n3, order3, bu3) == (n2, order2, bu2), f'after the load: squad {n3}, BU {bu3} (saved {n2}, {bu2})', errs)
        info.append(f'loaded: squad {n3}, BU {bu3}')
    return not errs, '; '.join(errs + info)


@scenario
def bteam_ui():
    """4.0.6 B-team call-ups, M3 UI (a build with bteam's UI, SWOSTEST_BUILD): a World 2026-27 career at ATALANTA,
    SQUADRA: the SQ. B button left of ESCI; fire: the B team's squad (ShowSquad); the selected row picked: the call-up
    page with his name; SOLO PROSSIMA PARTITA -> CONVOCATO PER LA PROSSIMA PARTITA, again -> GIA' CONVOCATO; ESCI: the
    squad screen with him in it (+1, BU kind 1). Then SQ. B, PAG. SUCC., the first extra, PER LA STAGIONE (the summer
    window): CONVOCATO PER LA STAGIONE, squad +1, BU kind 2 on index >= 16. Shots squad_btn, bsquad, page, page_ok,
    bsquad2, squad_after."""
    exe = builds()['it']
    v = bteam_vars(exe)
    me = os.environ.get('BT_CLUB', 'ATALANTA')
    path = ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', 'EUROPA', 'ITALIA', 'SERIE A', me]
    import bteam
    import finance
    import lepatch
    if UI != 'it':                                      # (SWOSTEST_UI: bteam's own texts read back as the Italian ones)
        for k, t in bteam.TEXTS[UI].items():
            for x, y in zip(t if isinstance(t, (list, tuple)) else [t], bteam.TEXTS['it'][k] if isinstance(t, (list, tuple)) else [bteam.TEXTS['it'][k]]):
                if x:
                    UI_MAP.setdefault(x, y)
    nbo = finance.find(lepatch.LEPatch(os.path.join(MAIN, 'orig', UI_ORIG)))['NEWBAL'][1]
    bank = lambda: struct.unpack('<i', bytes(s.result.obj2(nbo, 4)))[0]     # newBalance: no money for a call-up
    errs, info = [], []
    with Session('bteam_ui', exe, {}, 'dump:2', 900) as s:
        s.wait()
        if not pick_career(s, path):
            return False, 'new career: ' + str(s.screen().texts()[:8])
        s.send('fire dump:3')
        for _ in range(8):
            if 'PROSS. PARTITA' in s.screen().texts():
                break
            press(s, s.screen(), 'CONTINUA', 3) or press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')
        r = s.result
        selw = struct.unpack('<H', bytes(r.obj2(v['sel'], 2)))[0]
        if selw not in v['rows']:
            return False, f'{me} ({selw:#x}): no B team in BAGE'
        bw = v['rows'][selw][0]
        bn = bteam_names(exe, bw)
        if not sq_open(s):
            return False, f'no squad screen: {s.screen()}'
        n0, _, _, bu0 = bteam_state(s, v)
        b0 = bank()
        import complist                                 # a long coach name: shown cut at SQ. B (Davide 02/11 (a))
        scr = s.screen()
        cn = next((t for i, t, inv, _ in scr.entries if i == 5), '')
        ctb = bytes(s.result.obj2(v['ct'], 76))
        long_name = os.environ.get('BT_COACH', 'ALEXANDER MACPHERSON-SMYTHE')[:22]
        if cn and cn.encode('latin-1') + b'\0' in ctb:
            s.poke(s.result.lin((2, v['ct'] + ctb.index(cn.encode('latin-1') + b'\0'))), long_name.encode() + b'\0')
            walk(s, 'ESCI', 3)
            sq_open(s)
            scr = s.screen()
            shown = next((t for i, t, inv, _ in scr.entries if i == 5), '')
            g = {x[0]: scr.geom[j] for j, x in enumerate(scr.entries)}
            free = g[64][0] - g[5][0] - 2 if 64 in g else 999
            check(long_name.startswith(shown) and 0 < complist.px(shown) <= free,
                  f'coach {long_name!r} shown {shown!r} ({complist.px(shown)} px, free {free})', errs)
            info.append(f'coach {long_name!r} shown {shown!r} ({complist.px(shown)} px of {free})')
        else:
            errs.append(f'coach name {cn!r} not in careerTeam')
        scr = s.screen()
        s.shot('squad_btn')
        check(scr.find('SQ. B', exact=True) is not None, f'no SQ. B on the squad screen: {scr}', errs)
        info.append(f'squad {n0}, BU {bu0}')

        def page(kind_text, extra):
            r = press(s, s.screen(), 'SQ. B', 3)
            if r is None:
                return f'SQ. B not reachable: {s.screen()}'
            s.shot('bsquad2' if extra else 'bsquad')
            if extra:                                   # (xbrowse's label as read back: DE WEITER -> CONTINUA)
                import xbrowse
                press(s, s.screen(), ui_it(xbrowse.TEXTS[UI][0].decode('latin-1')), 2)
            info.append(f'B squad: {str(s.screen())[:300]}')
            if extra:
                for _ in range(3):                      # (PAG. PREC. -> the 16th row -> the 14th: the last extra)
                    s.send('up dump:0.5')
                q = s.screen()
                s.shot('page2_sel')
                info.append(f'page 2 selected {q.selected}, links {q.nav[3][0] if len(q.nav) > 3 else None}')
                info.append(f'page 2: {str(s.screen())[:300]}')
            s.send('fire dump:3')
            s.shot('picked')
            r = s.result
            info.append(f'menu ptr {struct.unpack("<I", r.read(r.base2 + s.info["menu"], 4))[0]:#x}')
            try:
                scr = s.screen()
            except RuntimeError as x:
                return f'after the pick: {x}'
            info.append(f'page: {scr}')
            if scr.find(kind_text, exact=True) is None:
                return f'no call-up page: {scr}'
            s.shot('page2' if extra else 'page')
            info.append(f'bank at the page {bank()}')
            press(s, scr, kind_text, 2)
            s.screen()
            info.append(f'bank after {kind_text} {bank()}')
            return None

        e = page('SOLO PROSSIMA PARTITA', False)
        if e:
            return False, e + '; ' + '; '.join(info)
        t = s.screen().texts()
        check('CONVOCATO PER LA PROSSIMA PARTITA' in t, f'after the call-up: {t}', errs)
        press(s, s.screen(), 'SOLO PROSSIMA PARTITA', 2)
        t = s.screen().texts()
        check("GIA' CONVOCATO" in t, f'the same again: {t}', errs)
        s.shot('page_ok')
        press(s, s.screen(), 'ESCI', 3)
        n1, _, _, bu1 = bteam_state(s, v)
        b1 = bank()
        check(b1 == b0, f'one match: bank {b0} -> {b1}', errs)
        check(n1 == n0 + 1 and len(bu1) == len(bu0) + 1 and bu1[-1][0] & 0x7F == 1, f'squad {n0} -> {n1}, BU {bu1}', errs)
        check(s.screen().find('SQ. B', exact=True) is not None, f'back: no SQ. B ({s.screen()})', errs)
        s.shot('squad_after')
        info.append(f'one match: squad {n1}, BU {bu1}')
        if len(bn) > 16:
            e = page('PER LA STAGIONE', True)
            if e:
                errs.append(e)
            else:
                t = s.screen().texts()
                check('CONVOCATO PER LA STAGIONE' in t, f'after the season call-up: {t}', errs)
                press(s, s.screen(), 'ESCI', 3)
                n2, _, _, bu2 = bteam_state(s, v)
                b2 = bank()
                check(b2 == b1, f'season: bank {b1} -> {b2} (wages only, no fee)', errs)
                check(n2 == n1 + 1 and bu2 and bu2[-1][1] >= 16, f'season extra: squad {n1} -> {n2}, BU {bu2}', errs)
                info.append(f'season: squad {n2}, BU {bu2}')
                s.shot('squad_after2')
    return not errs, '; '.join(errs + info)


@scenario
def bteam_rules():
    """4.0.6 B-team call-ups, M4 rules (BTEAM_FORCE build, SWOSTEST_BUILD): a World 2026-27 career at an A-League club
    (BT_RULES_CLUB, default BRISBANE ROAR: B team BRISBANE ROAR 2, AUS rules = no over-age player at all, the keeper
    included, season windows 24/6-15/9 and 12/1-8/2). At the first squad screen the harness's mailbox asks: an U23
    for one match (ok), an over-age outfield player (over-age cap), an over-age keeper (over-age cap: AUS has no keeper
    exception), an U23 for the season with the calendar's week poked to 1/11 for the run (window closed). PASS: the codes
    as bteam's rules give them from BAGE's ages; squad +1; the bank unchanged."""
    sys.path.insert(0, os.path.join(ROOT, 'tools'))
    import bteam
    import finance
    import lepatch
    exe = builds()['it']
    v = bteam_vars(exe)
    if v['mb'] is None:
        return False, f'{exe}: no BTRQ mailbox (not a BTEAM_FORCE build)'
    me = os.environ.get('BT_RULES_CLUB', 'BRISBANE ROAR')
    path = ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', 'ASIA', 'AUSTRALIA', 'A-LEAGUE MEN', me]
    nbo = finance.find(lepatch.LEPatch(os.path.join(MAIN, 'orig', UI_ORIG)))['NEWBAL'][1]
    errs, info = [], []
    b = nop_league_int3('bteam_rules', exe)             # (the '- PARTITA -' screen's int 3, as bteam_rt)
    with Session('bteam_rules', b, {}, 'dump:2', 900) as s:
        s.wait()
        if not pick_career(s, path):
            return False, 'new career: ' + str(s.screen().texts()[:8])
        s.send('fire dump:3')
        for _ in range(8):
            if 'PROSS. PARTITA' in s.screen().texts():
                break
            press(s, s.screen(), 'CONTINUA', 3) or press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')
        r = s.result
        selw = struct.unpack('<H', bytes(r.obj2(v['sel'], 2)))[0]
        if selw not in v['rows']:
            return False, f'{me} ({selw:#x}): no B team in BAGE'
        bw, ages, ri = v['rows'][selw]
        cap, u23, gk_any, _ = bteam.RULES[bteam.RULE_IDS[ri]]
        bn = bteam_names(exe, bw)
        d = open(os.path.join(exe, 'DATA', 'TMW5.%03d' % (bw & 0xFF)), 'rb').read()[2 + (bw >> 8) * 684:]
        gk = [d[76 + i * 38 + 0x1A] >> 5 == 0 for i in range(16)]
        y0 = 126                                         # (the 2026-27 season: born 2003 on = U23, age code 103)
        young = [a == 0 or a >= y0 - u23 for a in ages]
        pick = lambda want_young, want_gk: next((i for i in range(16) if bn[i] and young[i] == want_young
                                                 and gk[i] == want_gk), None)
        cases = [('U23', 1, pick(True, False), 0), ('over-age', 1, pick(False, False), 2),
                 ('over-age keeper', 1, pick(False, True), 0 if gk_any else 2), ('U23 season', 2, None, 3)]
        used = {c[2] for c in cases if c[2] is not None}
        cases[3] = cases[3][:2] + (next(i for i in range(16) if bn[i] and young[i] and i not in used), 3)
        if any(c[2] is None for c in cases):
            return False, f'{me}: B team {bw:#x} lacks a case {[(c[0], c[2]) for c in cases]} (ages {ages})'
        info.append(f'{me} {selw:#x}: B {bw:#x} rules {bteam.RULE_IDS[ri]} (cap {cap}, U{u23}, keeper any age {gk_any})')
        n0, _, _, _ = bteam_state(s, v)
        b0 = struct.unpack('<i', bytes(s.result.obj2(nbo, 4)))[0]
        reqs = [(k, i) for _, k, i, _ in cases]
        import split                                    # the week forced out of the windows (1/11) for the mailbox run
        d3 = bytes(lepatch.LEPatch(os.path.join(exe, 'ITALIAN.EXE')).get(3, 0, v['mb'][1]))
        bw_at = [m.start() for m in re.finditer(rb'\x0f\xb7\x05....\x0f\xb6\x80....\xc3', d3, re.S)]
        check(len(bw_at) >= 1, 'bt_week not found', errs)
        q = r.read(r.lin((3, bw_at[-1])), 14)
        cur_lin, cal1_lin = struct.unpack_from('<I', q, 3)[0], struct.unpack_from('<I', q, 10)[0]
        wk_lin = cal1_lin + struct.unpack('<H', bytes(r.read(cur_lin, 2)))[0]
        wk0, closed = r.read(wk_lin, 1)[0], split.week_of('1/11')
        info.append(f'week {wk0} -> {closed} for the requests')
        s.poke(wk_lin, bytes([closed]))
        s.poke(r.lin(v['mb']) + 1, b''.join(bytes(q) for q in reqs) + b'\xff' * (16 - 2 * len(reqs)))
        s.poke(r.lin(v['mb']), bytes([len(reqs)]))
        for _ in range(10):                             # PARTITA: ShowPlayMatchMenu (cseg_52588) runs the mailbox
            texts = s.screen().texts()
            if 'MOD. TATTICA' in texts:
                break
            if 'TRASFERIMENTI' in texts and 'PARTITA' in texts:
                press(s, s.screen(), 'PARTITA', 2) or s.send('fire dump:2')
            elif '- PARTITA -' in texts:
                press(s, s.screen(), '- PARTITA -', 2) or s.send('fire dump:2')
            else:
                s.send('fire dump:2')
        else:
            return False, f'no play-match screen: {s.screen().texts()[:12]}'
        s.poke(wk_lin, bytes([wk0]))
        r = s.result
        mb = r.read(r.lin(v['mb']), 26)
        res = list(mb[17:17 + len(reqs)])
        check(mb[0] == 0, f'mailbox not run: count {mb[0]}', errs)
        for (what, k, i, want), c in zip(cases, res):
            info.append(f'{what} {bn[i]} (idx {i}, age {ages[i]}, kind {k}): {bteam.CODES[c] if c < len(bteam.CODES) else c}')
            check(c == want, f'{what} {bn[i]}: code {c} (want {want} {bteam.CODES[want]})', errs)
        n1, _, _, bu1 = bteam_state(s, v)
        b1 = struct.unpack('<i', bytes(r.obj2(nbo, 4)))[0]
        check(n1 == n0 + sum(1 for c in res if c == 0), f'squad {n0} -> {n1}', errs)
        check(b1 == b0, f'bank {b0} -> {b1}', errs)
        info.append(f'squad {n0} -> {n1}, BU {bu1}')
        s.shot('rules_squad')
    return not errs, '; '.join(errs + info)


@scenario
def bteam_season():
    """4.0.6 B-team call-ups, M2 return (2): bteam_rt's save (ATALANTA, players called up for the season) played to
    the season's end (world8485: W8485_FROM, saved before CONTINUA), CONTINUA CARRIERA, the next season saved and
    loaded. PASS: the season players out of ATALANTA's squad, BU empty, the B team's change-list entry for each
    (when the list still holds one) back to his own name; reported: the squad sizes"""
    exe = builds()['it']
    v = bteam_vars(exe)
    errs, info = [], []
    if not getattr(bteam_rt, 'car', None):
        ok, msg = bteam_rt()
        if not getattr(bteam_rt, 'car', None):
            return False, f'bteam_rt: {msg[:300]}'
    car, bw, season = bteam_rt.car
    if not season:
        return False, 'bteam_rt called nobody up for the season'
    keys = ('W8485_BUILD', 'W8485_FROM', 'W8485_NOSACK', 'W8485_SAVE_END', 'SWOSTEST_SCENARIO')
    keep = {k: os.environ.get(k) for k in keys}
    try:
        os.environ.update(W8485_BUILD=exe, W8485_FROM=car, W8485_NOSACK='1', W8485_SAVE_END='BTSE',
                          SWOSTEST_SCENARIO='bteam_season_run')
        ok, msg = world8485()
    finally:
        for k, x in keep.items():
            if x is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = x
    if 'saved ' not in msg:
        return False, f'season: {msg[:300]}'
    end = msg.split('saved ', 1)[1].strip()
    with Session('bteam_season_end', exe, {'BTSE.CAR': end}, 'dump:2', 900) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        n, order, _, bu = bteam_state(s, v)
        info.append(f'season end: squad {n}, BU {bu}')
        check(all(g in order for g in season), f'season players gone before the end: {season}', errs)
        nxt = next_season_save(s, 'BTNS')
    if not nxt.endswith('.CAR'):
        return False, '; '.join(errs + info + [f'next season: {nxt}'])
    with Session('bteam_season_next', exe, {'BTNS.CAR': nxt}, 'dump:2', 600) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        for _ in range(8):
            if 'PROSS. PARTITA' in s.screen().texts():
                break
            press(s, s.screen(), 'CONTINUA', 3) or press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')
        r = s.result
        n, order, _, bu = bteam_state(s, v)
        info.append(f'next season: squad {n}, BU {bu}')
        check(not bu, f'next season: BU {bu}', errs)
        check(not any(g in order for g in season), f'next season: still in the squad {[g for g in season if g in order]}', errs)
        nf = struct.unpack('<H', bytes(r.obj2(v['nfm2'], 2)))[0]
        ents = [bytes(r.obj2(v['cfmp'] + 42 * j, 42)) for j in range(nf)]
        mine = [(e[2], e[7:29].split(b'\0')[0].decode('latin1')) for e in ents if struct.unpack_from('<H', e)[0] == bw]
        info.append(f'change list {nf}: B entries {mine}')
        bn = bteam_names(exe, bw)
        for i, nm in mine:
            if i < len(bn) and bn[i] in season:
                check(nm == bn[i], f'change list ({bw:#x}, {i}): {nm!r}, want {bn[i]!r} back', errs)
    return not errs, '; '.join(errs + info)


@scenario
def xleft_job():
    """4.0.6 (Enzo's duplicate): an XTRA player who left his club never comes back with it. World 2026-27 career at
    ATALANTA (release recipe, SWOSTEST_BUILD); the home market poked with KUPS KUOPIO's first XTRA player (index 16),
    bought; one of ATALANTA's own extras moved into the first 16 of the squad order (he is written back into its record at
    the job change); KUPS's job offer forced (world_job_squad's way), the season played, ACCETTA, the next season saved.
    PASS: KUPS's careerTeam without the bought player (base 4.0.5: he is in slots 16.. again = the duplicate), with its
    other extras; ATALANTA's moved extra in the list (xl_job); the list the same after a reload. XLEFT_FULL=1: xtra's XS
    list poked full (128) first, so the purchase goes to xleft's XL (the overflow list, its market blanking)."""
    import lepatch
    exe = builds()['it']
    club, me = os.environ.get('JOB_CLUB', 'KUPS KUOPIO'), 'ATALANTA'
    full = bool(os.environ.get('XLEFT_FULL'))
    nojob = bool(os.environ.get('XLEFT_NOJOB'))         # (bisect: no job offer, the season end at ATALANTA)
    seller = os.environ.get('XLEFT_SELLER', club)       # (bisect: buy another club's extra)
    blk, mine = xtra_club_block(exe, seller), xtra_club_block(exe, me)
    if not blk or not mine:
        return False, f'no XTRA block: {seller} {bool(blk)}, {me} {bool(mine)}'
    word, extras = blk
    jword = xtra_club_block(exe, club)[0]
    myword, myx = mine
    bought = extras[0]
    p = lepatch.LEPatch(os.path.join(exe, 'ITALIAN.EXE'))
    import xtra
    _, cnp, ct, cmp, sel = xtra.sites(p)
    nh, hm = home_market_sites()
    num, offers = job_offer_sites(exe)
    path = ['CARRIERA', 'SCEGLI SQUADRA', 'CARR. STORICHE', 'MONDO 2026-27', 'EUROPA', 'ITALIA', 'SERIE A', me]
    errs, info = [], []
    names = lambda r: [r.obj2(ct + 76 + j * 38 + 3, 23).split(b'\0')[0].decode('latin1') for j in range(32)]

    def leave(s):
        for _ in range(8):
            if 'PROSS. PARTITA' in s.screen().texts():
                break
            press(s, s.screen(), 'CONTINUA', 3) or press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')

    def consider(s, i):                                 # OFFERTE LAVORO -> the letter -> CONSIDERA (world_job_squad's
        walk(s, i, 3)                                   # way: without it the new club is not cached at the season end,
        letter = s.screen()                             # FindTeamInCache's int 3 at obj1+0x17064)
        if letter.find('CONSIDERA', exact=True) is None:
            rows = [j for j, g in enumerate(letter.geom) if g[0] == 8 and g[2] == 304 and not letter.entries[j][2]
                    and not letter.entries[j][3]]
            if rows:
                walk(s, rows[0], 3)
        press(s, s.screen(), 'CONSIDERA', 3)
        for _ in range(6):
            if 'TRASFERIMENTI' in s.screen().texts():
                break
            press(s, s.screen(), 'CONTINUA', 3) or press(s, s.screen(), 'ESCI', 3) or s.send('fire dump:2')

    with Session('xleft_job', exe, {}, 'dump:2', 600) as s:
        s.wait()
        if not pick_career(s, path):
            return False, 'new career: ' + str(s.screen().texts()[:8])
        s.send('fire dump:3')
        leave(s)
        r = s.result
        nobuy, noswap = bool(os.environ.get('XLEFT_NOBUY')), bool(os.environ.get('XLEFT_NOSWAP'))   # (bisect switches)
        if full:                                        # XS counted full: its zero entries (team 0, index 0) never match
            s.poke(r.base1 + xtra_xsold(p), struct.pack('<H', 128))     # an XTRA index (16..). (A 386-byte poke stalled the
                                                                         # debugger on the next SM, twice: keep pokes short)
        bidx = int(os.environ.get('XLEFT_IDX', 16))     # (bisect: a record player instead, index < 16)
        s.poke(r.base2 + hm, struct.pack('<HBB', word, bidx, 0))
        s.poke(r.base2 + nh, struct.pack('<H', 1))
        n0, nm0 = struct.unpack('<H', s.result.obj2(cnp, 2))[0], names(s.result)
        ans = xtra_buy_first(s) if not nobuy else []
        r = s.result
        n1, nm1 = struct.unpack('<H', r.obj2(cnp, 2))[0], names(r)
        if bidx < 16:
            bought = next((x for x in nm1[:n1] if x not in nm0), bought)
        if bought not in nm1[:n1] and not nobuy:
            return False, f'purchase of {bought} failed: squad {n0} -> {n1}, answer {ans[:6]}'
        lst, raw = xleft_lists(s, exe)
        info.append(f'bought {bought} ({club} 16): lists {raw}')
        check((word, 16) in lst, f'after the purchase: ({word:#x}, 16) not listed {raw}', errs)
        # one of ATALANTA's extras (slot 16.., an XTRA name) to squad position 15: written back at the job change
        order = list(r.obj2(cmp, n1))
        q = next((j for j in range(16, n1) if nm1[j] in myx), None)
        if q is None:
            return False, f'{me}: no extra in slots 16.. {nm1[16:n1]}'
        qi, qn = order.index(q), nm1[q]
        order[qi], order[15] = order[15], order[qi]
        if not noswap:
            s.poke(r.base2 + cmp, bytes(order))
        idx_q = 16 + myx.index(qn)
        if not nojob:
            s.poke(r.base2 + offers, struct.pack('<H', jword) + b'\xff' + bytes(17) + struct.pack('<I', 500000) + bytes(2))
            s.poke(r.base2 + num, struct.pack('<H', 1))
            walk(s, s.screen().find('VISUAL. COMPETIZ.', exact=True), 3)    # (back: ContestMenuOnReturn -> CheckJobOffers)
            press(s, s.screen(), 'ESCI', 3)
            leave(s)
        i = None if nojob else next((e[0] for e in s.screen().entries if e[1] and ('LAVORO' in e[1]) and not e[2] and not e[3]), None)
        if i is None and not nojob:
            return False, f'no job offer entry: {s.screen().texts()[:20]}'
        if not nojob:
            consider(s, i)
        for _ in range(6):                              # career menu -> ESCI -> main menu: save
            if s.screen().find('SALVA CARRIERA', exact=True) is not None:
                break
            press(s, s.screen(), 'ESCI', 3) or press(s, s.screen(), 'ABBANDONA', 3)
        walk(s, 'SALVA CARRIERA', 2)
        s.send(name_entry('XLJB') + ' dump:3')
        car = os.path.join(s.run, 'SWOS', 'XLJB.CAR')
    if not os.path.exists(car):
        return False, '; '.join(errs + ['no XLJB.CAR'])
    keys = ('W8485_BUILD', 'W8485_FROM', 'W8485_NOSACK', 'W8485_SAVE_END', 'SWOSTEST_SCENARIO')
    keep = {k: os.environ.get(k) for k in keys}
    try:                                                # the season to its end (saved before CONTINUA)
        os.environ.update(W8485_BUILD=exe, W8485_FROM=car, W8485_NOSACK='1', W8485_SAVE_END='XLJE',
                          SWOSTEST_SCENARIO='xleft_job_season')
        ok, msg = world8485()
    finally:
        for k, v in keep.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    if 'saved ' not in msg:
        return False, '; '.join(errs + [f'season: {msg[:200]}'])
    end = msg.split('saved ', 1)[1].strip()
    with Session('xleft_job_next', exe, {'XLJE.CAR': end}, 'dump:2', 600) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        if nojob:                                       # (bisect: the next season at ATALANTA)
            nxt = next_season_save(s, 'XLJN')
            return nxt.endswith('.CAR'), f'no job, next season: {nxt}'
        if press(s, s.screen(), 'OFFERTE LAVORO', 3) is None:
            return False, '; '.join(errs + [f'season end: no OFFERTE LAVORO {s.screen().texts()[:14]}'])
        scr = s.screen()
        row = next((e[0] for e in scr.entries if e[1] and club in e[1] and not e[2] and not e[3]), None)
        if row is None:
            return False, '; '.join(errs + [f'season end: no offer of {club}: {scr.texts()[:10]}'])
        rows = [j for j, g in enumerate(scr.geom) if g[0] == 8 and g[2] == 304 and not scr.entries[j][2]
                and not scr.entries[j][3]]
        walk(s, next((j for j in rows if abs(scr.geom[j][1] - scr.geom[row][1]) <= 4), rows[-1] if rows else row), 3)
        if press(s, s.screen(), 'ACCETTA', 3) is None:
            return False, '; '.join(errs + [f'season end: no ACCETTA {s.screen().texts()[:14]}'])
        nxt = next_season_save(s, 'XLJN')               # CONTINUA CARRIERA: the new job
        if nxt.endswith('.CAR'):
            lst2, raw2 = xleft_lists(s, exe)
    if not nxt.endswith('.CAR'):
        return False, '; '.join(errs + [f'next season: {nxt}'])
    d = open(nxt, 'rb').read()[56192:56192 + 684 + 38 * 16]
    name = d[5:22].split(b'\0')[0].decode('latin1')
    rec = [d[76 + 38 * i + 3:76 + 38 * i + 26].split(b'\0')[0].decode('latin1') for i in range(16)]
    got = [x for x in (d[684 + 38 * i + 3:684 + 38 * i + 26].split(b'\0')[0].decode('latin1') for i in range(16)) if x]
    check(name == club, f'next season: careerTeam {name!r}', errs)
    check(bought not in got and bought not in rec, f'DUPLICATE: {bought} (bought by {me}) back at {club}: slots 16.. {got}', errs)
    check(all(x in got for x in extras[1:]), f'{club} extras missing: {[x for x in extras[1:] if x not in got]}', errs)
    check((myword, idx_q) in lst2, f'{me} extra {qn} ({idx_q}) written back at the job change, not listed: {raw2}', errs)
    check((word, 16) in lst2, f'the bought one ({word:#x}, 16) no longer listed: {raw2}', errs)
    info.append(f'next season: {name}, slots 16.. {len(got)} named, {bought} absent: {bought not in got}; lists {raw2}')
    with Session('xleft_job_reload', exe, {'XLJN.CAR': nxt}, 'dump:2', 600) as s:
        s.wait()
        s.send(LOAD1 + ' dump:3')
        lst3, raw3 = xleft_lists(s, exe)
        check(lst3 == lst2, f'after a reload: lists {raw3} != {raw2}', errs)
    return not errs, '; '.join(errs + info)


